window.BP_QUESTIONS = [{"rule": "AND-001", "prompt": "You're reviewing this change in a `ChromeActivity` subclass. The method runs from a delayed callback scheduled during startup:\n```java\nprivate void maybeRequestDefaultBrowser() {\n    showDefaultBrowserDialog();\n}\n```\nWhat should the reviewer ask for?", "choices": ["Add `if (isActivityFinishingOrDestroyed()) return;` before showing the dialog", "Wrap `showDefaultBrowserDialog()` in a try/catch for `WindowManager.BadTokenException`", "Post the dialog with `PostTask.postTask()` so it runs on the UI thread", "Nothing — dialogs are safe to show from any callback once `onCreate()` has run"], "answer": 0, "explain": "Activities can be destroyed between when a callback is scheduled and when it runs. Guard UI work in async callbacks, animation listeners, and lambdas with `isActivityFinishingOrDestroyed()`."}, {"rule": "AND-002", "prompt": "A Fragment receives a Mojo response and updates its views:\n```java\nvoid onServiceResult(Result result) {\n    updateUI(result);\n}\n```\nWhich guard follows the Brave Android standard?", "choices": ["`if (getView() == null) return;` is sufficient, since a detached fragment has no view", "`if (!isAdded() || isDetached()) return;`, then bail if `getActivity()` is null/finishing", "`if (result == null) return;` — fragment state doesn't matter for Mojo responses on the UI thread", "Check `isResumed()` and queue the update until `onResume()` otherwise"], "answer": 1, "explain": "Fragments can be detached or their Activity destroyed while async work runs. Verify `isAdded()`/`!isDetached()` and that the host Activity is non-null and not finishing before touching UI."}, {"rule": "AND-003", "prompt": "A preference triggers an async network call:\n```java\npreference.setOnPreferenceClickListener(pref -> {\n    accountService.resendConfirmationEmail(callback);\n    return true;\n});\n```\nWhat's the recommended fix?", "choices": ["Debounce clicks with a 500 ms timer stored in a static field on the fragment", "Return `false` from the listener so the preference ignores subsequent clicks until done", "Call `preference.setEnabled(false)` before the request; re-enable it in the callback", "Show a toast telling the user the email is being sent"], "answer": 2, "explain": "Disable interactive UI while an async operation is in flight to prevent double-clicks, then re-enable it when the callback completes."}, {"rule": "AND-004", "prompt": "```java\nprivate void showSplash() {\n    if (mSplashContainer != null) {\n        mSplashContainer.setVisibility(View.VISIBLE);\n    }\n}\nprivate void hideSplash() {\n    mSplashContainer.setVisibility(View.GONE);\n}\n```\nWhat should a reviewer flag?", "choices": ["The null check in `showSplash()` is redundant and should be removed for consistency with `hideSplash()`", "`mSplashContainer` should be made `static` so it is never null", "Nothing — `View.GONE` on a null view is a no-op", "Add the same null check to `hideSplash()`; the field is treated as nullable elsewhere"], "answer": 3, "explain": "If a member field is null-checked in some code paths, check it in all paths that use it. Inconsistent checks suggest some paths can crash."}, {"rule": "AND-005", "prompt": "A JNI bridge forwards calls to a keyed service:\n```cpp\nvoid NTPBackgroundImagesBridge::GetCurrentWallpaperForDisplay() {\n  view_counter_service_->GetCurrentWallpaperForDisplay();\n}\n```\nUpstream logic \"should\" never call this in incognito. What's the best review comment?", "choices": ["Add an explicit `if (!view_counter_service_) return;`; it may be null in incognito", "Leave it; upstream guarantees the call never happens in incognito", "Replace it with `CHECK(view_counter_service_)` so a null service in incognito crashes loudly", "Create the service on demand for the incognito profile inside the bridge"], "answer": 0, "explain": "Services reached through bridges or native code may be null for incognito profiles. Add explicit null checks at the point of use, even if upstream theoretically handles it."}, {"rule": "AND-006", "prompt": "You need a thread-safe singleton for `BraveAccountServiceFactory`. Which implementation follows the standard?", "choices": ["A `static final Object sLock` with a `synchronized (sLock)` null-check in `getInstance()`", "A private static `LazyHolder` nested class with a `static final INSTANCE` field", "A `volatile` static field with double-checked locking", "Initialize the instance in `Application.onCreate()` and expose it via a public static field"], "answer": 1, "explain": "Use the LazyHolder idiom for singleton factories instead of explicit `synchronized` lock blocks. It's compact and thread-safe thanks to Java's class-loading guarantees."}, {"rule": "AND-007", "prompt": "A custom `Preference` stores `mTextColor = resolveThemeColor(context, R.attr.textColor)` in its constructor. Users report the title stays dark after switching to dark theme. What's the fix?", "choices": ["Cache the color in a static field shared by all instances of the preference", "Hardcode the color with `Color.parseColor()` in the constructor", "Resolve the theme color in `onBindViewHolder()` and apply it there", "Recreate the whole settings Activity whenever the theme changes"], "answer": 2, "explain": "Resolve theme colors at bind time (`onBindViewHolder` or equivalent), not during construction, so they update correctly on light/dark switches without recreating the view."}, {"rule": "AND-008", "prompt": "A preference in `brave_main_preferences.xml` is removed in Java when a feature flag is off. QA notices it briefly flashes on screen before disappearing. What should you add to the XML?", "choices": ["`android:enabled=\"false\"` on the preference", "`android:visibility=\"gone\"` on the preference's layout", "`app:singleLineTitle=\"false\"` on the preference", "`app:isPreferenceVisible=\"false\"` on the preference"], "answer": 3, "explain": "For preferences that are hidden or removed programmatically based on a flag, set `app:isPreferenceVisible=\"false\"` in XML to avoid the brief visual flash."}, {"rule": "AND-009", "prompt": "```java\nif (contractAddress == null || contractAddress.length() < MIN_LENGTH) {\n    Log.e(TAG, \"Invalid contract address\");\n    return \"\";\n}\n```\nWhat improvement does the Brave Android guide recommend?", "choices": ["Add an `assert` with the same condition above the guard, keeping the fallback", "Replace the guard with `throw new IllegalArgumentException()` to fail fast on bad input", "Upgrade `Log.e` to `Log.wtf` and remove the early return", "Remove the guard; invalid addresses should be impossible here"], "answer": 0, "explain": "Pair log-only defensive checks with `assert`: asserts surface problems immediately in debug builds, while the graceful handling still protects release builds."}, {"rule": "AND-010", "prompt": "`hasPipPermission()` queries `PackageManager` and `AppOpsManager`, and it's being called from a frequently-hit path. A teammate suggests caching it in a member during `onCreate()`. What's the right consideration?", "choices": ["Always cache system service results; they never change during an Activity's lifetime", "Cache expensive lookups, but not values that can change unnotified, like PiP availability", "Never cache system service results; Android already caches `PackageManager` lookups internally", "Move the lookup to a background thread instead of caching it"], "answer": 1, "explain": "Compute expensive system-service lookups once and store them instead of repeating them in a hot path. The exception is values that can change without notification in multi-window or config-change scenarios, such as PiP availability."}, {"rule": "AND-011", "prompt": "You're adding wallet address validation to an Android screen. iOS and desktop accept the same input. What should you do first?", "choices": ["Write a Java regex validator, since Android needs to validate before calling native", "Copy the iOS Swift validation logic into Kotlin for parity", "Check whether unified validation already exists on the core/native side and use it", "Skip validation on Android and rely on server errors"], "answer": 2, "explain": "Before writing validation in Android/Java, check for unified core/native-side validation. Preferring core-side logic avoids inconsistencies across Android, iOS, and desktop."}, {"rule": "AND-012", "prompt": "A Robolectric test crashes because the code under test calls `ChromeFeatureList.isEnabled(BraveFeatureList.SOME_FEATURE)`. What's the recommended pattern in the production code?", "choices": ["Wrap the call in `try { ... } catch (UnsatisfiedLinkError e) {}`", "Convert the test to an instrumentation test; Robolectric can't test this code", "Load the native library in the test with `System.loadLibrary()`", "Guard the call with `if (FeatureList.isNativeInitialized())`"], "answer": 3, "explain": "Robolectric has no native/JNI. Use conditional checks like `FeatureList.isNativeInitialized()` to handle the test environment gracefully (see `BraveDynamicColors.java`)."}, {"rule": "AND-013", "prompt": "Your bytecode class adapter for an upstream Java class keeps failing. The class has two constructors. What's the accepted approach?", "choices": ["Use a direct `.java.patch` file for that class instead", "Add a third constructor so the adapter can choose a unique one", "Copy the whole upstream class into `brave/` and redirect all imports", "Disable the adapter and use reflection to change the behavior at runtime"], "answer": 0, "explain": "Bytecode (class adapter) patching fails when a class has two constructors; use a direct `.java.patch` instead. Likewise, use direct `BUILD.gn` patches when circular deps prevent using `java_sources.gni`."}, {"rule": "AND-014", "prompt": "Presubmit flags `ProfileManager.getLastUsedRegularProfile()` in `QuickActionSearchAndBookmarkWidgetProvider`. As the reviewer, what do you say?", "choices": ["Block the PR until the profile comes from the hosting Activity's `getProfile()` instead", "Accept it: widget providers have no Activity or WebContents context, like upstream widgets", "Replace it with `ProfileManager.getOriginalProfile()`, which presubmit allows in widget code", "Pass the profile into the widget through an Intent extra"], "answer": 1, "explain": "Never flag `getLastUsedRegularProfile()` as a violation in Android widget providers, where no Activity/WebContents context exists. Upstream Chromium does the same in its widgets."}, {"rule": "AND-015", "prompt": "A PR adds this, but nothing implements or calls it:\n```java\npublic interface OnAnimationCompleteListener {\n    void onAnimationComplete();\n}\n```\nThe author says \"it might be useful later.\" Best response?", "choices": ["Keep it but mark it `@Deprecated` so nobody starts depending on it yet", "Keep it and add a TODO linking to the future issue that will use it", "Remove it before merging; unused interfaces shouldn't be left in the codebase", "Make it package-private so it can't leak into the public API until someone needs it"], "answer": 2, "explain": "Don't leave unused interfaces, listener patterns, or helper methods behind. If they were scaffolded during development and never used, remove them before merging."}, {"rule": "AND-016", "prompt": "```xml\n<FrameLayout\n    android:id=\"@+id/splash_animation_container\"\n    android:clickable=\"true\"\n    android:focusable=\"true\"\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"wrap_content\" />\n```\nThe container only hosts a display-only Lottie animation. What should the reviewer say?", "choices": ["Also add `android:contentDescription` so TalkBack can announce the animation", "Keep `focusable` but remove `clickable`, so keyboard users can reach it", "Fine as-is — it stops touches from passing through to the views below the splash", "Drop `clickable`/`focusable`; they hurt accessibility and touch handling here"], "answer": 3, "explain": "Don't set `android:clickable` or `android:focusable` on purely decorative or display-only views like animation containers; these attributes change accessibility and touch event handling."}, {"rule": "AND-017", "prompt": "Android and iOS both ship the exact same onboarding Lottie JSON file, each in its own directory. A designer updates the animation. What does the standard recommend?", "choices": ["Keep a single shared copy that both platforms reference", "Keep per-platform copies so each team can evolve them independently", "Generate the Android copy from the iOS one with a build step", "Convert the Android copy to an `AnimatedVectorDrawable`"], "answer": 0, "explain": "When Android and iOS use identical assets, reference a single shared copy instead of maintaining duplicates, so changes only need to be made once."}, {"rule": "AND-019", "prompt": "`brave_java_sources.gni` now lists dozens of `crypto_wallet` Java files mixed with everything else. What's the suggested improvement?", "choices": ["Sort the list alphabetically so the wallet files are grouped", "Consider moving the feature's sources into a separate build target", "Split `brave_java_sources.gni` into two `.gni` files of roughly equal size", "Nothing — all Brave Java sources should live in one list"], "answer": 1, "explain": "When feature-specific Java sources accumulate in `brave_java_sources.gni`, consider a separate build target for better build isolation and dependency tracking."}, {"rule": "AND-021", "prompt": "Which version of `handleState()` follows the Brave Android style?", "choices": ["`if (!isFinished) { if (hasData) { /* main logic */ } }`", "`if (!isFinished && hasData) { /* main logic */ } else { return; }`", "`if (isFinished) return;` and `if (!hasData) return;`, then the main logic", "Move the main logic to a helper and call it from inside both nested `if` blocks"], "answer": 2, "explain": "When a condition decides whether the rest of a method runs, return early instead of nesting `if` blocks; it reduces nesting depth and improves readability."}, {"rule": "AND-022", "prompt": "A PR modifies a class adapter in `build/android/bytecode/java/org/brave/bytecode/`. What else should it include?", "choices": ["A Robolectric unit test that instantiates the patched class and calls its methods", "A note in the PR description; bytecode adapters are verified at build time", "A ProGuard keep rule for every method the adapter touches", "`BytecodeTest.java` entries in `testClassesExist` and `testMethodsExist`"], "answer": 3, "explain": "Bytecode adapter changes need a matching bytecode test in `BytecodeTest.java` (class existence and method existence with return types), so upstream refactors fail at test time, not silently at runtime."}, {"rule": "AND-023", "prompt": "A new instrumentation test needs a class kept from shrinking. The author adds the `-keep` rule to `android/java/proguard.flags`. What's the right feedback?", "choices": ["Move it to `apk_for_test.flags`; `proguard.flags` is for runtime reflection only", "Correct — all keep rules belong in `proguard.flags`, test or production", "Add it to both `.flags` files to be safe, since test APKs merge them anyway", "Use `@Keep` on the class instead, which R8 only honors in test builds"], "answer": 0, "explain": "Keep rules for runtime reflection go in `proguard.flags`. Test-only rules go in `apk_for_test.flags`; putting them in `proguard.flags` grows the production APK by preventing shrinking."}, {"rule": "AND-024", "prompt": "Bytecode rewriting redirects `new UpstreamClass()` to `new BraveClass()`.\n```java\nclass BraveClass extends UpstreamClass {\n    private static final List<Entry> sEntries = List.of(new Entry());\n    BraveClass() {\n        Registry.register(sEntries);\n    }\n}\n```\nWhat's the risk, and the fix?", "choices": ["`List.of` is immutable, so `register()` will throw on insert; use `new ArrayList<>()`", "The constructor may run before `sEntries` is set; register in a `static {}` block after it", "`sEntries` should be `volatile` so other threads see it initialized", "There's no risk; Java always initializes a subclass's statics before its constructor runs"], "answer": 1, "explain": "A redirected allocation inside `UpstreamClass` static init can re-enter `BraveClass()` before `BraveClass`'s statics are initialized. Keep redirected constructors free of reads of their own static state; use a static block placed after the fields it uses."}, {"rule": "AND-025", "prompt": "You change a private method to package-private only so a test in the same package can call it. Which annotation should you add?", "choices": ["`@VisibleForTesting` with no arguments, since package-private is already the default", "`@SuppressWarnings(\"unused\")`", "`@VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)`", "No annotation; a `// for testing` comment is enough"], "answer": 2, "explain": "Annotate members made package-private solely for tests with `@VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)`. It documents intent and lets IDEs flag misuse from non-test code."}, {"rule": "AND-026", "prompt": "You need to add one Brave button to an upstream toolbar. A teammate proposes copying the whole upstream layout XML into Brave and adding the button there. Best response?", "choices": ["Good idea — XML replacement is the cleanest, most readable way to customize upstream UI", "Patch the upstream XML file in place with a `.patch` instead, which keeps the diff minimal", "Use reflection to inject the button into the toolbar after layout inflation", "Add it programmatically via `addView`; replace the XML only if that's equally invasive"], "answer": 3, "explain": "Replacing full upstream XML layouts creates maintenance burden during Chromium upgrades. Prefer programmatic `addView`, unless that requires extending final classes or is equally invasive; then document the trade-off."}, {"rule": "AND-027", "prompt": "You're adding a brand-new Brave-only drawable, `ic_brave_vpn_badge.xml`. Where should it go?", "choices": ["In a dedicated `brave-res` folder", "In the upstream `chrome/android/java/res/drawable/` directory next to similar icons", "In whichever upstream folder the consuming layout lives in", "In `res/raw/` so it isn't merged with upstream resources"], "answer": 0, "explain": "Brave-specific resources go in `brave-res`. Upstream resource directories are only for intentionally overriding an existing upstream resource; otherwise it's unclear whether a file is an addition or an override."}, {"rule": "AND-028", "prompt": "A PR removes an Android feature by deleting its Java classes and its settings XML. What should the reviewer check before approving?", "choices": ["That the deleted classes were marked `@Deprecated` for one release before removal", "That related bytecode adapters/tests, ProGuard rules, JNI, flags, and GN refs are removed", "Only that the build still compiles; any leftover references are harmless since R8 prunes them", "That the strings are kept in the `.grd` in case the feature returns later"], "answer": 1, "explain": "When removing a feature, audit all artifacts: bytecode adapters, ProGuard rules, bytecode test entries, Java sources, resources, JNI bindings, feature flags, and build references."}, {"rule": "AND-029", "prompt": "```java\nif (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {\n    requestPermissions(perms, REQUEST_CODE);\n}\n```\nBrave's minimum SDK is above API 23. What's the right review comment?", "choices": ["Keep it for safety in case the min SDK is ever lowered again", "Add an `else` branch that logs a warning for unsupported devices", "Remove the check; it's dead code given the min SDK", "Replace it with `BuildInfo.isAtLeastM()` for readability"], "answer": 2, "explain": "Remove Android version checks for API levels below the app's minimum SDK (e.g. Lollipop/Marshmallow); they're dead code."}, {"rule": "AND-031", "prompt": "You're writing a direct (non-`chromium_src`) patch to an upstream Java file. Which approach minimizes conflicts on Chromium upgrades?", "choices": ["Edit the existing upstream line in place so the diff stays as small as possible", "Reformat the surrounding block so the patch has clear anchors", "Comment out the upstream line and add your version below it", "Add entirely new lines rather than editing existing upstream lines"], "answer": 3, "explain": "In direct patches, prefer adding new lines over modifying existing ones. New lines have no upstream anchor that might change, reducing conflicts during upgrades."}, {"rule": "AND-032", "prompt": "You need to change behavior inside an anonymous inner class in upstream Chromium Java code, and the Brave override system can't handle it. What's acceptable?", "choices": ["Use a `.patch`, explain why in the PR, and link the override-support tracking issue", "Rewrite the whole upstream class as a Brave subclass and redirect it via bytecode", "Use reflection at runtime to swap out the anonymous class instance after construction", "Drop the change; anonymous inner classes can't be customized"], "answer": 0, "explain": "When the override system can't handle anonymous inner classes, a `.patch` file is the accepted fallback; document the reason and link to the tracking issue."}, {"rule": "AND-033", "prompt": "A PR tweaks a color in `brave_colors.xml` to fix the contrast on one new screen. What should the reviewer ask?", "choices": ["Why not hardcode the color in that one layout instead?", "Were other UIs using this resource checked for impact?", "Can the color be moved into upstream's `colors.xml` instead?", "Nothing — color tweaks are low risk"], "answer": 1, "explain": "Shared resource values (colors, dimensions, styles) can affect many screens. Cross-check every usage before modifying them."}, {"rule": "AND-034", "prompt": "A button looks wrong in dark mode. Which fix aligns with the standard?", "choices": ["Patch the upstream Java class to call `setTextColor()` based on the current night-mode flag", "Override `onConfigurationChanged()` and recolor the button manually", "Use baseline XML color resources for non-dynamic states; test with Dynamic Colors on/off", "Disable Dynamic Colors for this screen so the color is predictable"], "answer": 2, "explain": "For theming issues, follow upstream: baseline colors (XML resources) for non-dynamic states rather than patching Java to set colors. Always verify with the Dynamic Colors flag enabled and disabled."}, {"rule": "AND-035", "prompt": "You need a new Android string for a Brave feature. Where should it go?", "choices": ["In upstream `chrome_strings.grd`, next to related strings", "In the upstream `strings.xml` of the module that uses it, for locality", "Hardcoded in Java until translations are ready", "In `android_brave_strings.grd` or another Brave-owned resource"], "answer": 3, "explain": "Never modify upstream string resource files like `chrome_strings.grd`. Brave strings go in `android_brave_strings.grd` or a Brave-owned file to avoid patch conflicts."}, {"rule": "AND-036", "prompt": "The upstream method is annotated `@NullUnmarked`. Your Brave override looks like this:\n```java\n@Override\npublic void onResult(Profile profile) { ... }\n```\nWhat should you change?", "choices": ["Add `@NullUnmarked` to the override to match upstream", "Add `@NonNull` to `profile` to be stricter than upstream", "Add `@SuppressWarnings(\"NullAway\")` instead; it's equivalent", "Nothing — overrides inherit annotations automatically"], "answer": 0, "explain": "Match upstream nullability annotations (`@NullUnmarked`, `@Nullable`, `@NonNull`) on overrides. Mismatches cause NullAway build failures."}, {"rule": "AND-037", "prompt": "Which Log TAG declaration in `BraveVpnProfileController` follows the guideline?", "choices": ["`private static final String TAG = \"BraveVpnProfileController\";`", "`private static final String TAG = \"BraveVPN\";`", "`private static final String TAG = BraveVpnProfileController.class.getSimpleName();`", "`private static final String TAG = \"org.chromium.chrome.browser.vpn.BraveVpnProfileController\";`"], "answer": 1, "explain": "Log TAGs should be short and descriptive, not a repeat of the full class name when that adds no value."}, {"rule": "AND-038", "prompt": "Which XML follows the Brave Android layout guideline?", "choices": ["`<View android:paddingStart=\"16dp\" android:paddingEnd=\"16dp\" />`", "`<View android:paddingLeft=\"16dp\" android:paddingRight=\"16dp\" />`", "`<View android:paddingHorizontal=\"16dp\" />`", "`<View android:padding=\"16dp\" android:paddingTop=\"0dp\" android:paddingBottom=\"0dp\" />`"], "answer": 2, "explain": "Use shorthand attributes (`paddingHorizontal`, `marginHorizontal`, `paddingVertical`, `marginVertical`) instead of setting start/end or top/bottom separately."}, {"rule": "AND-039", "prompt": "With NullAway in JSpecify mode, which field declaration is correct?", "choices": ["`@Nullable` on its own line, then `private String mValue;` on the next", "`@Nullable private String mValue;`", "`private String @Nullable mValue;`", "`private @Nullable String mValue;`"], "answer": 3, "explain": "In JSpecify mode `@Nullable` is `TYPE_USE`, so it must go immediately before the type (e.g. `private @Nullable String`, or `Outer.@Nullable Inner`)."}, {"rule": "AND-039", "prompt": "With JSpecify-style `@Nullable`, which declaration is a **non-null list of nullable strings**?", "choices": ["`List<@Nullable String> mList;`", "`@Nullable List<String> mList;`", "`List<String> @Nullable mList;`", "`@Nullable List<@Nullable String> mList;`"], "answer": 0, "explain": "Position matters: the annotation applies to the type it precedes. `List<@Nullable String>` is a non-null list whose elements may be null."}, {"rule": "AND-040", "prompt": "```java\nprivate @Nullable String mNullableString;\n\nprivate void usesNullableString() {\n    if (mNullableString.isEmpty()) { ... }  // NullAway warns\n}\n```\nEvery caller of this private method checks the field is non-null first. What's the idiomatic fix?", "choices": ["Annotate the method with `@Initializer`", "Annotate the method with `@RequiresNonNull(\"mNullableString\")`", "Change the field to non-null and suppress the constructor warning", "Copy the field to a local `boolean isSet` and check that"], "answer": 1, "explain": "NullAway analyzes per method, so use `@RequiresNonNull`, `@EnsuresNonNull`, `@EnsuresNonNullIf`, and `@Contract` to carry nullness conditions across method boundaries. `@RequiresNonNull` only makes sense on private methods."}, {"rule": "AND-041", "prompt": "A field is null until `doThing()` first sets it, and is never set back to null. NullAway warns when it's used later inside a `PostTask` lambda. Which annotation fits best?", "choices": ["`@Nullable`, plus `assumeNonNull()` inside every lambda", "`@NullUnmarked` on the class", "`@MonotonicNonNull`", "`@Initializer` on `doThing()`"], "answer": 2, "explain": "For fields that start null but are never reset to null after initialization, use `@MonotonicNonNull`. NullAway then trusts the field stays non-null after assignment, even in lambdas."}, {"rule": "AND-042", "prompt": "`obj.getNullableString()` returns null only in a broken state, and a null would cause worse problems later if it slipped through. You want a crash even in production. Which do you use?", "choices": ["`assumeNonNull(ret)`", "`assert ret != null : \"broken\";`", "`assertNonNull(ret)`", "`Objects.requireNonNull(ret)`"], "answer": 3, "explain": "`Objects.requireNonNull()` crashes in production; use it when null would cause worse problems later. `assumeNonNull`, `assertNonNull`, and `assert` don't crash in prod (asserts only fire on Canary as dump-without-crashing)."}, {"rule": "AND-042", "prompt": "You need a non-null **expression** to assign a field from a map lookup, with assert semantics. Which is idiomatic?", "choices": ["`mNonNullField = assertNonNull(dict.get(\"key\"));` with `import static`", "`mNonNullField = NullUtil.assertNonNull(dict.get(\"key\"));` without a static import", "`assert dict.get(\"key\") != null; mNonNullField = dict.get(\"key\");`", "`mNonNullField = (String) dict.get(\"key\");`"], "answer": 0, "explain": "Use `assertNonNull()` when you need an assert as an expression, and always use `import static` for `assumeNonNull`/`assertNonNull`."}, {"rule": "AND-043", "prompt": "A class has a `destroy()` method that nulls out `mService`, which is otherwise always non-null. NullAway complains. What does the guide recommend?", "choices": ["Mark the whole class `@NullUnmarked`, since lifecycle nulling is outside NullAway's model", "Make it `@Nullable` with an `@EnsuresNonNullIf` guard, or suppress NullAway on `destroy()`", "Never null fields in `destroy()`; leave the references alive until GC collects the object", "Annotate `destroy()` with `@Initializer` so NullAway treats the field as reassigned there"], "answer": 1, "explain": "For destroy-nulled fields, choose one of two strategies: `@Nullable` fields guarded by an `@EnsuresNonNullIf` check (preferred for complex cases), or suppress warnings on `destroy()` (simpler cases)."}, {"rule": "AND-053", "prompt": "```java\nprivate @Nullable SomeService mService;\n\n@EnsuresNonNullIf(value = {\"mService\"}, result = false)\nprivate boolean isDestroyed() { return mService == null; }\n\npublic void doWork() {\n    if (isDestroyed()) return;\n    mService.execute();\n}\n```\nDoes NullAway warn on `mService.execute()`?", "choices": ["Yes — NullAway can't see through method calls, so an inline `mService != null` check is required", "Yes — `@EnsuresNonNullIf` only works when `result = true`", "No — `result = false` means `mService` is non-null whenever `isDestroyed()` is false", "No, but only because `doWork()` is public and NullAway skips public entry points"], "answer": 2, "explain": "Destruction strategy 1 (preferred for complex cases): keep the field `@Nullable` and guard uses with an `@EnsuresNonNullIf(..., result = false)` `isDestroyed()` helper, which NullAway trusts."}, {"rule": "AND-054", "prompt": "A simple class keeps `mService` non-null for its whole life except that `destroy()` sets it to null. What's the simple, recommended approach?", "choices": ["Mark `destroy()` `@NullUnmarked` so callers also skip null checks", "Make the field `@Nullable` and add `assumeNonNull(mService)` at every use", "Make the field `@MonotonicNonNull` so it may be set to null once", "Keep it non-null; add `@SuppressWarnings(\"NullAway\")` to `destroy()`"], "answer": 3, "explain": "Destruction strategy 2 (simpler cases): leave the field non-null and suppress NullAway warnings on `destroy()` only."}, {"rule": "AND-044", "prompt": "A RecyclerView binder sets `mField1`/`mField2` in `onBindViewHolder()`. To silence NullAway, the author adds `@Initializer` to `onBindViewHolder()`. What's the right feedback?", "choices": ["Don't; use an `@EnsuresNonNull` `assertBound()` helper, as binding isn't construction", "Good — `@Initializer` is exactly for binder methods that set fields before first use", "Use `@NullUnmarked` on the binder class instead, since RecyclerView controls binding", "Initialize both fields to empty placeholder views in the constructor so they're never null"], "answer": 0, "explain": "`onBindViewHolder()` isn't a real initializer. Add an `assertBound()` helper annotated `@EnsuresNonNull({...})` that asserts the fields, and call it in methods that need them."}, {"rule": "AND-045", "prompt": "NullAway warns about this `@NullMarked` data holder:\n```java\npublic class TabInfo {\n    public String title;\n    public String url;\n}\n```\nWhat's the recommended fix?", "choices": ["Annotate the class `@NullUnmarked`, since it's just a plain data struct with no logic to check", "Make the fields `final`, set them in a constructor, and use `/* title= */` at call sites", "Initialize both fields to `\"\"` at declaration so they're never null for readers", "Add `@MonotonicNonNull` to each field so they can be assigned after construction"], "answer": 1, "explain": "NullAway warns on non-primitive, non-`@Nullable` public fields not set by a constructor. Add a constructor that sets all fields, with `/* paramName= */` comments for readability."}, {"rule": "AND-046", "prompt": "`getTabById()` is `@Nullable`, but many callers know the tab exists and dislike the null checks. A teammate proposes changing its return type to non-null. Best response?", "choices": ["Agree — annotate it `@NonNull` since callers expect non-null", "Have callers wrap each call in `Objects.requireNonNull()`", "Keep it `@Nullable`; add `getTabByIdChecked()` returning `assertNonNull(getTabById(id))`", "Annotate the method `@NullUnmarked` so callers that know the tab exists stop getting warnings"], "answer": 2, "explain": "Don't mis-annotate `@Nullable` methods as non-null; it hides real nullability. For Chromium-authored code, add a \"Checked\" companion for callers that know the value exists."}, {"rule": "AND-047", "prompt": "You need to pass a `Supplier<@Nullable String>` to a method taking `Supplier<String>`, and you know it never returns null here. What's the idiomatic call?", "choices": ["`acceptsNonNullSupplier(nullableSupplier);` — the compiler handles variance", "`acceptsNonNullSupplier(() -> nullableSupplier.get());`", "Annotate the parameter `@NullUnmarked`", "`acceptsNonNullSupplier(SupplierUtils.asNonNull(nullableSupplier));`"], "answer": 3, "explain": "`Supplier<T>` and `Supplier<@Nullable T>` aren't assignment-compatible due to generics invariance. Use `SupplierUtils.asNonNull()` (or an explicit cast the other way), or change the parameter type if the value may really be null."}, {"rule": "AND-048", "prompt": "```java\npublic class MyComponent {\n    private SomeService mService;\n    public MyComponent() {}\n    public void initialize(SomeService service) { mService = service; }\n}\n```\nNullAway warns that `mService` isn't initialized in the constructor. What's the fix?", "choices": ["Annotate `initialize()` with `@Initializer`", "Annotate `mService` with `@MonotonicNonNull`", "Annotate the constructor with `@SuppressWarnings(\"NullAway\")`", "Split setup into several `@Initializer` setters, one per field"], "answer": 0, "explain": "For two-phase init, mark the second-phase method `@Initializer`. NullAway doesn't verify it's called, so prefer one `initialize()` over several setters (`onCreate()` is implicitly `@Initializer`)."}, {"rule": "AND-049", "prompt": "You need to silence a NullAway false positive inside one method of a migrated `@NullMarked` class, without weakening checks for its callers. Which annotation do you use?", "choices": ["`@NullUnmarked`", "`@SuppressWarnings(\"NullAway\")`", "`@Nullable` on the method's return type", "Either one; they behave identically"], "answer": 1, "explain": "Both suppress warnings in the body, but `@NullUnmarked` makes the signature's nullability unknown to callers. Prefer `@SuppressWarnings(\"NullAway\")`; reserve `@NullUnmarked` for code not yet migrated."}, {"rule": "AND-050", "prompt": "```java\nboolean isNull = thing == null;\nif (!isNull) {\n    thing.doWork();\n}\n```\nNullAway still warns on `thing.doWork()`. Why, and what's the fix?", "choices": ["`isNull` must be `final` for NullAway to trust it", "NullAway needs `assumeNonNull(thing)` after any boolean check", "NullAway can't track nullness through booleans; check `thing != null` directly", "The warning is a false positive here; add `@SuppressWarnings(\"NullAway\")` to the method"], "answer": 2, "explain": "NullAway can't follow nullness through intermediate boolean variables (NullAway#98). Put the null check directly in the `if` condition."}, {"rule": "AND-051", "prompt": "A `@NullMarked` Java class has both `@CalledByNative` methods and Java-to-native calls. Which statement is correct?", "choices": ["Both directions are fully checked by NullAway at compile time", "Neither direction is checked, so nullability annotations on native methods are pointless", "`@CalledByNative` methods are checked; Java-to-native calls are not", "`@CalledByNative` methods aren't null-checked; Java-to-native calls are, via asserts"], "answer": 3, "explain": "Nullness isn't checked for `@CalledByNative` methods, but Java-to-native calls are checked via `assert` when `@NullMarked` is present, so annotate native-bound parameters correctly."}, {"rule": "AND-052", "prompt": "Java code will be mirrored and built outside Chromium. How should nullability annotations be set up?", "choices": ["Use JSpecify (`org_jspecify_jspecify_java`) with `chromium_code = false` and `enable_errorprone = true`", "Use `org.chromium.build.annotations` as usual; mirrored builds can simply vendor the `build_java` target", "Use AndroidX `@Nullable` from `androidx.annotation`, which both builds already depend on", "Omit annotations in mirrored code and set `enable_errorprone = false` in its GN target"], "answer": 0, "explain": "For mirrored code, use JSpecify annotations instead of Chromium's copies, add the jspecify dep, set `chromium_code = false` to avoid the `build_java` dep, and keep `enable_errorprone = true`."}, {"rule": "AND-055", "prompt": "A PR adds `BraveToggleView extends FrameLayout`, a hand-drawn on/off switch for a settings screen. How should the reviewer flag it?", "choices": ["As a blocker: custom reimplementations of Material components aren't allowed in settings", "As a `nit:` asking why `MaterialSwitch` or a Brave subclass of it wasn't used", "Not at all; custom views give more control over theming", "Ask the author to subclass `SwitchCompat` instead"], "answer": 1, "explain": "Prefer Material components, which bring motion, accessibility, and theming. Flag custom reimplementations as `nit:` only, never as a blocker, and never flag Brave subclasses of Material components."}, {"rule": "AND-056", "prompt": "You're adding a new standalone `MyFeatureController.java` (no upstream subclassing) in brave-core. Where should it go?", "choices": ["In `android/java/org/chromium/chrome/browser/my_feature/`, appended to `brave_java_sources`", "In `chrome/browser/android/` since that's the shared Android home", "In `browser/my_feature/android/` as its own `android_library` in `brave_chrome_java_deps`", "In both a feature module and `brave_java_sources`, for compatibility"], "answer": 2, "explain": "New feature-specific Java goes in the feature's Android directory (`browser/<feature>/android/`), not the legacy tree. Consumers depend on the feature target; don't also list the files in `brave_java_sources`."}, {"rule": "AND-057", "prompt": "An icon sits next to a `TextView` showing the same \"Brave Shields\" title. How should the `ImageView` be declared?", "choices": ["`android:contentDescription=\"@string/brave_shields_title\"`", "`android:contentDescription=\"\"`", "Omit `contentDescription` entirely", "`android:contentDescription=\"@null\"`"], "answer": 3, "explain": "Decorative images should use `contentDescription=\"@null\"`, not an empty string or a missing attribute, so intent is explicit and TalkBack doesn't repeat the label. Meaningful images (clickable, icon-only buttons, QR codes) still need a real description."}, {"rule": "ARCH-059", "prompt": "A new `FooService` is only ever obtained through:\n\n```cpp\nFooService* FooServiceFactory::GetForProfile(Profile* profile) {\n  return static_cast<FooService*>(\n      GetInstance()->GetServiceForBrowserContext(profile, /*create=*/true));\n}\n```\n\nA bug reproduces in production but never in browser tests, which don't call `GetForProfile`. What should the reviewer suggest?", "choices": ["Call `GetForProfile()` in each test's `SetUpOnMainThread()` to force creation", "Pass `/*create=*/false` so the service is never created implicitly", "Override `ServiceIsCreatedWithBrowserContext()` to return `true`", "Create the service lazily from a static `NoDestructor` instead of the factory"], "answer": 2, "explain": "Features should be created eagerly with explicit lifetimes, not lazily on first use. Lazy creation gives tests and production different initialization orders, which makes bugs hard to reproduce."}, {"rule": "ARCH-060", "prompt": "You're reviewing:\n\n```cpp\nvoid FetchData(Callback cb) {\n  if (cache_.contains(key)) {\n    std::move(cb).Run(cache_[key]);\n    return;\n  }\n  network_->Fetch(key, std::move(cb));\n}\n```\n\nWhat is the problem, and the fix?", "choices": ["It's fine: running synchronously on a cache hit avoids a needless task hop", "The cache hit should post the callback so it's always async", "The network path should block until the fetch completes, so it's always sync", "Callers should be documented to check the cache first and handle the sync case"], "answer": 1, "explain": "A given callback must run either always synchronously or always asynchronously. Mixing the two means callers can't reason about when it runs; post the cached result with `PostTask` instead."}, {"rule": "ARCH-061", "prompt": "A reviewer flags this helper:\n\n```cpp\nvoid ProcessItem(int id) {\n  auto item = global_registry_->GetItem(id);\n  auto config = settings_manager_->GetConfig();\n  DoWork(item, config);\n}\n```\n\nWhat change best matches the guidance on control flow?", "choices": ["Cache `item` and `config` in members on first use to avoid repeated lookups", "Wrap the body in a `base::AutoReset` guard so re-entrant calls are ignored", "Look the values up once at startup and store them in a global struct", "Take `const Item&` and `const Config&` as parameters"], "answer": 3, "explain": "Keep control flow localized: pass the state a function needs as parameters instead of querying non-local state mid-execution. `AutoReset` guards are a last resort for unavoidable re-entrancy, not a substitute."}, {"rule": "ARCH-062", "prompt": "Which of these PRs should a reviewer ask to include an `InteractiveBrowserTest` Critical User Journey test?", "choices": ["A new toolbar button that opens a native Views bubble", "A new toggle on `brave://settings` wired directly to a pref", "A new tab helper that records page-load timings in the background", "A new `KeyedService` that syncs data with a backend server"], "answer": 0, "explain": "Features that add or modify user-visible native (Views) UI need at least one CUJ test. Don't require one for WebUI pages, trivial pref-wired toggles, or non-UI code like services and tab helpers."}, {"rule": "ARCH-062", "prompt": "A PR adds a new dialog and tests it like this:\n\n```cpp\nclass MyDialogTest : public BrowserWithTestWindowTest {};\n```\n\nThe production code now contains `if (!browser_view) return;` to make the test pass. What should the reviewer say?", "choices": ["Fine, as long as the null check carries a comment saying it's for tests", "Switch to `TestWithBrowserView` so `browser_view` is never null in the test", "Keep the test, but move the null check into a test-only `#if` block", "Use an `InteractiveBrowserTest` CUJ test instead"], "answer": 3, "explain": "`BrowserWithTestWindowTest` forces test-only `if (!browser_view)` checks into production code. UI features should be covered by an `InteractiveBrowserTest` CUJ test, or by tests with proper dependency injection."}, {"rule": "ARCH-063", "prompt": "A utility file adds:\n\n```cpp\n// static\nbool FooUtils::IsFeatureReady() {\n  auto* profile = ProfileManager::GetLastUsedProfile();\n  return FooServiceFactory::GetForProfile(profile)->IsReady();\n}\n```\n\nWhat should the reviewer request?", "choices": ["Use `GetActiveUserProfile()` so the result follows the focused window", "Take the `FooService*` as a parameter from the caller", "Null-check the profile and return `false` when none has been loaded yet", "Turn it into a member of a singleton so the profile lookup is cached"], "answer": 1, "explain": "Free functions and static methods must not reach into non-global state like profiles or windows. Have the caller pass in the profile- or window-specific dependency."}, {"rule": "ARCH-064", "prompt": "A new tab-scoped `ReaderModeFeature` must be queried by the toolbar button code to decide whether to show itself for a given tab. How should the feature be owned and exposed?", "choices": ["As a plain `unique_ptr` in `BraveTabFeatures`, with a getter on the tab", "As a `WebContentsUserData` helper fetched via `FromWebContents()`", "Via Unowned User Data, with a static `From(tab)` accessor", "As a global `std::map<TabInterface*, Feature*>` owned by the button"], "answer": 2, "explain": "Self-contained tab/window features can be a plain `unique_ptr` member. When external code needs to retrieve the feature, use the Unowned User Data pattern with a static `From()`, separating lifetime from retrieval."}, {"rule": "ARCH-065", "prompt": "You need a browser test where every tab gets a `MyTabFeatureMock` instead of the real Unowned User Data feature. What's the recommended approach?", "choices": ["Add a factory override for testing before the browser is created", "Use `BrowserWithTestWindowTest` and attach the mock to its fake tab strip", "After startup, delete each tab's real feature and construct the mock in its place", "Add a `--use-mock-tab-feature` switch checked inside `BraveTabFeatures::Init()`"], "answer": 0, "explain": "For integration tests, install a factory override via `GetUserDataFactoryForTesting().AddOverrideForTesting()` before the browser starts. For unit tests, attach the feature directly to a mock interface's `UnownedUserDataHost`."}, {"rule": "ARCH-067", "prompt": "You're reviewing:\n\n```cpp\nvoid FetchAll(const std::vector<Item>& items, DoneCallback done) {\n  auto barrier = base::BarrierCallback<Result>(\n      items.size(), std::move(done));\n  for (const auto& item : items) {\n    FetchAsync(item, barrier);\n  }\n}\n```\n\nWhat bug should you point out?", "choices": ["`barrier` is copied into each fetch, so `done` runs once per item", "With empty `items`, `done` never runs; handle that case first", "`done` must be bound with `base::Unretained` before being passed in", "`BarrierCallback` requires a fixed compile-time count, not a `size()`"], "answer": 1, "explain": "A `BarrierCallback` created with a count of zero never fires its done callback. Check for the empty case and run the callback (e.g. with `{}`) and return early."}, {"rule": "ARCH-068", "prompt": "Your PR adds two new P3A histograms reporting how often users open a new panel. Code review is approved and CI is green. What else must happen before merging?", "choices": ["Nothing; P3A is already privacy-preserving, so new metrics need no extra review", "Add the histograms to `histograms.xml` and get an OWNERS approval there", "Ship them behind a feature flag off by default until data has been reviewed", "Describe the metrics in the p3a Slack channel for privacy review"], "answer": 3, "explain": "New P3A metrics have strict privacy requirements. Post a brief description in the p3a Slack channel so the analytics team can do a privacy review before you merge."}, {"rule": "ARCH-069", "prompt": "During review you notice a new persisted pref:\n\n```cpp\ninline constexpr char kShowSidbarButton[] =\n    \"brave.sidbar.show_button\";\n```\n\nThe feature is landing behind a flag. What's the right call?", "choices": ["Leave it; the key can be renamed once the feature is enabled by default", "Fix only the C++ constant name; the stored string never matters to users", "Fix the key string now, before the first release ships it", "Leave it and file a follow-up to add a migration in a later release"], "answer": 2, "explain": "Persisted pref keys must be spelled correctly before the first release that includes them. Changing a key after it ships requires a migration to avoid losing user data."}, {"rule": "ARCH-070", "prompt": "While implementing a new Wallet setting, you notice an unrelated crash in the Rewards panel and also want to reorder methods in a file you aren't otherwise touching. What should you do?", "choices": ["Fix both in this PR so reviewers only need to load the context once", "Fix the crash here since it's urgent; defer only the reordering", "Include both, but mention each one clearly in the PR description", "Put the crash fix in its own PR and skip the reordering"], "answer": 3, "explain": "Each PR should have a single main purpose. Unrelated bug fixes and aesthetic reordering are ride-along changes; they make review, reverts, and bisecting harder."}, {"rule": "ARCH-071", "prompt": "A PR adds this to `components/playlist/core/common/DEPS`:\n\n```\ninclude_rules = [\n  \"+components/prefs\",\n]\n```\n\nso that `common/utils.h` can declare `bool IsPlaylistEnabled(PrefService* prefs);`. What should the reviewer say?", "choices": ["Fine, since `PrefService` is a component rather than `//chrome` code", "Move the helper into `core/browser/`, where prefs are valid", "Forward-declare `PrefService` in the header instead of adding the DEPS rule", "Keep it in `common/` but guard the declaration with `#if !BUILDFLAG(IS_IOS)`"], "answer": 1, "explain": "`common/` is compiled into every process that links the component, so it can't depend on browser-only APIs like `PrefService`, `Profile`, or `g_browser_process`. A new `+components/prefs` in a `common/DEPS` usually means the code belongs in `browser/`."}, {"rule": "ARCH-072", "prompt": "You're reviewing:\n\n```cpp\nstd::unique_ptr<KeyedService>\nFooServiceFactory::BuildServiceInstanceForBrowserContext(\n    content::BrowserContext* context) const {\n  if (!UserPrefs::Get(context)->GetBoolean(kFooEnabledPref)) {\n    return nullptr;\n  }\n  return std::make_unique<FooService>(...);\n}\n```\n\n`kFooEnabledPref` is a user-facing toggle. What should change?", "choices": ["Always build the service and have it check the pref at runtime", "Move the pref check into the static `GetForProfile()` accessor", "Check `base::FeatureList` as well, so both must be enabled", "Observe the pref and call `BrowserContextShutdown()` when it flips"], "answer": 0, "explain": "A factory may return `nullptr` only on session-stable attributes: profile type, buildflags, or feature flags. Gating on a user-toggleable pref (in the builder or the accessor) forces a restart for the toggle to take effect."}, {"rule": "ARCH-073", "prompt": "A new window feature is written as:\n\n```cpp\nFooFeature::FooFeature(Browser* browser) : browser_(browser) {}\n\nvoid FooFeature::DoStuff() {\n  DoStuffWith(browser_->GetProfile()->GetPrefs());\n}\n```\n\nWhat's the preferred design?", "choices": ["Keep `Browser*` but store it as `raw_ref<Browser>` so it can't be null", "Fetch prefs from `ProfileManager::GetActiveUserProfile()` instead", "Take `BrowserWindowInterface*` instead, since it's the modern replacement", "Inject the `PrefService&` it actually uses via the constructor"], "answer": 3, "explain": "Features should take exactly the dependencies they need at construction. `Browser` is a god object and globals hide coupling; even a narrower lookup key is worse than injecting the specific resolved dependency."}, {"rule": "ARCH-074", "prompt": "A PR adds a new desktop tab-scoped feature, used only by normal browser tabs:\n\n```cpp\n// browser/brave_tab_helpers.cc\nFooTabHelper::MaybeCreateForWebContents(web_contents);\n```\n\nWhat should the reviewer ask for?", "choices": ["Move it to `AttachPrivacySensitiveTabHelpers()` so it skips incognito", "Own a plain class as a `unique_ptr` in `BraveTabFeatures::Init()`", "Keep it, but add the helper to the presubmit allowlist", "Call `CreateForWebContents()` from `brave_tab_features.cc` instead"], "answer": 1, "explain": "Tab-scoped features are plain classes owned by `BraveTabFeatures` and created in `Init()`. `AttachTabHelpers()` is only for helpers that must also attach to non-tab `WebContents`."}, {"rule": "ARCH-075", "prompt": "You're reviewing a desktop tab feature:\n\n```cpp\nclass FooTabFeature : public content::WebContentsObserver {\n public:\n  explicit FooTabFeature(tabs::TabInterface& tab)\n      : WebContentsObserver(tab.GetContents()) {}\n};\n```\n\nWhat's the problem?", "choices": ["Nothing; a tab feature and its `WebContents` share the same lifetime", "It should hold a `WeakPtr<WebContents>` so it can detect destruction", "Discarding swaps the contents; use `ContentsObservingTabFeature`", "Observers must be registered in `Init()`, not in the constructor"], "answer": 2, "explain": "On desktop, discarding a tab replaces its `WebContents`, so a cached observer or `WeakPtr` goes stale. Use `ContentsObservingTabFeature`, or hold the `TabInterface` and call `GetContents()` at the point of use."}, {"rule": "ARCH-001", "prompt": "A new helper in `brave/components/foo/` needs to know whether the user is signed in, and the quickest way is to `#include \"brave/browser/...\"`. Which statement about Chromium's layering explains the reviewer's objection?", "choices": ["It's fine as long as the include is guarded by a buildflag that's off on iOS builds", "Dependencies flow downward only; components can't depend on embedder code", "Components may depend on any layer except `//base`", "Only `//content` is off-limits to components; browser-layer includes are allowed"], "answer": 1, "explain": "Chromium layers (`//base` → core libs → `//content` → `//components` → embedders) allow dependencies **downward only**. `brave/browser/` is the embedder layer, so components can never reach up into it."}, {"rule": "ARCH-002", "prompt": "You're reviewing this change in `components/p3a/p3a_service.cc`:\n\n```cpp\nvoid P3AService::Init() {\n  url_loader_factory_ =\n      g_browser_process->shared_url_loader_factory();\n}\n```\n\nWhat should the reviewer ask for?", "choices": ["Inject the URL loader factory via `Init()` params instead", "Wrap the call in `#if !BUILDFLAG(IS_IOS)` so it compiles on every platform", "Cache `g_browser_process` in a member to avoid repeated global lookups", "Move the `g_browser_process` call into a lambda so it runs lazily on first use"], "answer": 0, "explain": "`components/` code must never use `g_browser_process` or depend on `brave/browser/` — that's a layering violation. Pass dependencies in via injection (constructor params, `Init()`, callbacks)."}, {"rule": "ARCH-002", "prompt": "A component class currently takes a `Profile*` just to read a couple of prefs. Which signature follows the components layering rules?", "choices": ["`void Init(Profile* profile);` plus an include of `chrome/browser/profiles/profile.h`", "`void Init();` calling `ProfileManager::GetLastUsedProfile()` inside", "`void Init(Browser* browser);` so it can reach the profile and window", "`void Init(PrefService* prefs);`"], "answer": 3, "explain": "Never use `Profile` in components — pass `PrefService` (via `user_prefs::UserPrefs::Get(browser_context)`) or `BrowserContext` instead, and never include `chrome/browser/` or `brave/browser/` from `components/`."}, {"rule": "ARCH-003", "prompt": "```cpp\nBraveExtensionService::BraveExtensionService(Profile* profile)\n    : profile_(profile) {}\n\nvoid BraveExtensionService::OnMalwareListUpdated() {\n  ExtensionSystem* extension_system = ExtensionSystem::Get(profile_);\n  // ...profile_ is only ever used to reach extension_system\n}\n```\n\nWhat's the best review feedback?", "choices": ["Fine as-is — `Profile*` is the standard handle for looking up services", "Store a `Browser*` instead so other services are reachable later", "Inject `ExtensionSystem*` directly; the class only needs that service", "Replace `profile_` with a `raw_ref<Profile>` for memory safety"], "answer": 2, "explain": "Pass the most specific dependency, not a \"bag of stuff\" object. If `Profile` is only a lookup handle for one service, inject that service instead."}, {"rule": "ARCH-004", "prompt": "A teammate wraps every caller like this:\n\n```cpp\n#if BUILDFLAG(BRAVE_REWARDS_ENABLED)\n  auto* rewards_service = RewardsServiceFactory::GetForProfile(profile);\n  rewards_service->DoSomething();\n#endif\n```\n\nWhat does the standard prefer?", "choices": ["Keep the `#if` guards — buildflags are always clearer than runtime checks", "Add a `CHECK(rewards_service)` inside the `#if` block to catch misconfiguration", "Let the factory return null when disabled; callers just null-check", "Move the guard into a macro like `IF_REWARDS(...)` for brevity"], "answer": 2, "explain": "Prefer internal feature guards: the factory/service returns null or no-ops when disabled. Scattered buildflags at call sites lead to missing deps and maintenance burden."}, {"rule": "ARCH-005", "prompt": "```cpp\nvoid Init(network::ResourceRequest& request) {\n  auto shared_request =\n      std::make_shared<network::ResourceRequest>(request);\n  // ...\n}\n```\n\nThe request is owned by another class. What's the right fix?", "choices": ["Keep `std::make_shared` but supply a no-op deleter so it never frees the request", "Use `std::unique_ptr` so ownership is exclusive", "Keep `shared_ptr` — shared ownership is allowed when there's a strong reason", "Take a `const network::ResourceRequest&` and use it directly"], "answer": 3, "explain": "Don't take ownership of memory you don't own; pass unowned resources by reference or raw pointer. `std::shared_ptr` is banned outright in Chromium — if shared ownership is truly unavoidable, use `scoped_refptr` with `base::RefCounted`, but prefer redesign."}, {"rule": "ARCH-006", "prompt": "A new code path calls into the ad-block service from a background task runner, and crash reports start appearing. What's the most relevant guideline?", "choices": ["Service methods are thread-safe by default, so the crash must be coming from elsewhere", "Check which thread the service method expects to be called on", "Wrap the call in a `base::Lock` and it can then run on any thread", "Switch to `base::ThreadPool` so the service runs on more threads"], "answer": 1, "explain": "Calling service methods from the wrong thread causes crashes. Always check the thread a method expects — especially for ad-block and shields services."}, {"rule": "ARCH-007", "prompt": "Which include should a reviewer accept in Rewards code that needs random utilities?", "choices": ["`#include \"brave/components/brave_rewards/core/engine/util/random_util.h\"`", "`#include \"brave/vendor/brave_base/random.h\"`", "`#include \"../../vendor/brave_base/random.h\"` (relative path avoids visibility checks)", "Either works as long as `gn check` passes"], "answer": 0, "explain": "Never `#include \"brave/vendor/...\"` to reach internal headers — they're not public API, and full paths shouldn't be used to bypass visibility. Use the component's public API header."}, {"rule": "ARCH-008", "prompt": "A PR adds a new `PrefObserver` interface with `OnPrefChanged(const std::string&)` so a class can react to `kMyPref` changing. What should the reviewer suggest?", "choices": ["Poll the pref on a repeating timer instead", "Use `pref_change_registrar_.Add(...)` (reusing the superclass's if it has one)", "Keep the custom interface but derive it from `base::CheckedObserver` for safety", "Observe the whole `PrefService` and filter by name in a switch"], "answer": 1, "explain": "Don't create custom observer interfaces for pref changes — use the existing `pref_change_registrar_` pattern. Also check whether the superclass already has a `pref_change_registrar_` before adding one."}, {"rule": "ARCH-009", "prompt": "```cpp\nbool is_opted_in_ = false;\nvoid OnPrefChanged() { is_opted_in_ = prefs_->GetBoolean(kOptedIn); }\nbool IsOptedIn() { return is_opted_in_; }\n```\n\nWhat's the reviewer's best suggestion?", "choices": ["Drop the member and read the pref at call time; don't duplicate pref storage", "Make `is_opted_in_` a `std::atomic<bool>` so reads are thread-safe", "Also initialize `is_opted_in_` from the pref in the constructor so it's never stale", "Keep it — caching prefs is a recommended performance optimization"], "answer": 0, "explain": "Don't duplicate pref storage. Caching a pref in a member just creates a second source of truth; read the pref when you need it."}, {"rule": "ARCH-011", "prompt": "`MyServiceFactory` builds a service that calls into `RewardsService` and `AdsService`. What must the factory constructor include?", "choices": ["Nothing — keyed services are always created in alphabetical order", "A `CHECK` in `BuildServiceInstanceFor` that the other two services already exist", "A `PostTask` that delays creation until the other services are ready", "`DependsOn(...)` calls for both factories' `GetInstance()`"], "answer": 3, "explain": "If your `KeyedServiceFactory` depends on other services, declare them with `DependsOn` so initialization (and shutdown) order is correct."}, {"rule": "ARCH-012", "prompt": "A service should never be active for incognito profiles. A teammate proposes overriding `GetBrowserContextToUse` to redirect incognito to the original profile. What's the preferred approach?", "choices": ["Override `GetBrowserContextToUse` to redirect incognito to the original profile", "Create the service anyway and early-return in each method when off-the-record", "Return null from `GetForProfile` for incognito instead of redirecting", "Put a `NOTREACHED()` in the service constructor for incognito profiles"], "answer": 2, "explain": "If a service shouldn't be active in incognito, the factory should give back null for that profile rather than overriding `GetBrowserContextToUse` to hand back another context."}, {"rule": "ARCH-013", "prompt": "A new component needs to download data files via the component updater. A teammate starts writing a `FooComponentManager` class. What's the standard?", "choices": ["Write the manager — each component should have its own to isolate updates", "Extend `BraveComponentUpdater` with a new subclass per component", "Use a component installer policy — a per-component manager isn't needed", "Download the files directly with a `SimpleURLLoader` instead"], "answer": 2, "explain": "Components don't need their own component manager — use a component installer policy instead."}, {"rule": "ARCH-014", "prompt": "Code in `components/omnibox` needs to ask the browser layer whether autocomplete is enabled, but including browser headers would be a layering violation. What's the recommended design?", "choices": ["An abstract class in components, implemented in browser", "Include the browser header but whitelist it in `DEPS` `specific_include_rules`", "Use `g_browser_process` to fetch the client at runtime", "Move the entire omnibox component into `brave/browser/`"], "answer": 0, "explain": "When components need browser-layer behavior, define an abstract base class in components and implement it in browser; components then use the abstract type without a layering violation."}, {"rule": "ARCH-015", "prompt": "```cpp\ncontent::BrowserContext* GetBrowserContextToUse(\n    content::BrowserContext* context) const override {\n  return context;\n}\n```\n\nThis is in the Rewards service factory. What's wrong?", "choices": ["Nothing — returning the context unchanged is the correct default", "It creates services for incognito; return `nullptr` if off-the-record", "It should return `GetOriginalProfile()` so incognito shares the service", "It must be marked `final` to prevent subclasses overriding it"], "answer": 1, "explain": "Never initialize services for profile types they shouldn't support (e.g. Rewards in incognito). `GetBrowserContextToUse` must return null for unsupported profile types."}, {"rule": "ARCH-016", "prompt": "A PR adds `brave_news::LocaleUtil`, a new singleton that determines the user's locale. `brave_ads::LocaleHelper` already exists. What should the reviewer say?", "choices": ["Fine — each feature should own its own locale logic so teams aren't coupled", "Make the new singleton a `KeyedService` instead", "Copy `LocaleHelper` into `brave_news` so the two can evolve independently", "Reuse the existing `LocaleHelper` rather than duplicating it"], "answer": 3, "explain": "Check for existing services and singletons before creating new ones — don't duplicate singletons for the same purpose. Prefer observers over adding direct cross-service calls for decoupled notifications."}, {"rule": "ARCH-017", "prompt": "Several callers delete Tor's executable like this:\n\n```cpp\nauto path = tor_client_updater()->GetExecutablePath();\nbase::DeleteFile(path);\n```\n\nWhat's the better design?", "choices": ["Add a `Cleanup()` method on the updater and call that", "Add a shared free function `DeleteTorExecutable(path)` in a utils file", "Keep it — each caller knows best when and how its files should be deleted", "Post the `DeleteFile` to a background thread at each call site"], "answer": 0, "explain": "Cleanup logic belongs in the class that owns the resource. Don't spread cleanup details across multiple callers."}, {"rule": "ARCH-018", "prompt": "Where should a new Android-only Rewards native worker file go?", "choices": ["`brave/browser/android/rewards/brave_rewards_native_worker.cc`", "`brave/android/browser/rewards/native/brave_rewards_native_worker_android.cc`", "`brave/browser/android/brave_rewards_native_worker.cc`", "`brave/browser/brave_rewards/android/brave_rewards_native_worker.cc`"], "answer": 3, "explain": "Group files by component, not by platform: `brave_rewards/android/` beats `android/rewards/`. This keeps related code together, like Chromium's `chrome/browser/history/android/`."}, {"rule": "ARCH-019", "prompt": "```gn\nsource_set(\"wallet_api\") {\n  sources = [ \"wallet_api.cc\" ]  # empty stubs when wallet is disabled\n}\n```\n\nWhat does the standard prefer when `brave_wallet_enabled` is false?", "choices": ["Keep it built and have each stub hit `NOTREACHED()` so misuse is caught at runtime", "Wrap the whole target in `if (brave_wallet_enabled) { ... }`", "Keep the declarations but delete the `.cc` from `sources`", "Add a runtime `base::Feature` check inside each stub"], "answer": 1, "explain": "When a feature is disabled via buildflag, exclude the entire API from the build — don't leave API declarations with no (or empty) implementation."}, {"rule": "ARCH-020", "prompt": "A test needs to call `InternalMethod()`, which is private. A PR moves it to `public:`. What should the reviewer suggest?", "choices": ["Make it `protected` and subclass the class inside the test file to reach it", "Make it public but add a `// Visible for testing` comment", "Keep it private and add a `friend` declaration for the test class", "Duplicate the method's logic inside the test"], "answer": 2, "explain": "Use `friend` declarations instead of making methods public or protected for convenience. (`*ForTesting()` accessors are an accepted Chromium convention and aren't flagged under this rule.)"}, {"rule": "ARCH-021", "prompt": "```cpp\nvoid RewardsService::GetRecurringDonations() {\n  ledger->GetRecurringDonations([this](auto list) {\n    for (auto& observer : observers_)\n      observer.OnRecurringDonationsList(list);\n  });\n}\n```\n\nWhat's the issue?", "choices": ["Observers should be notified in reverse registration order", "The lambda should capture a `WeakPtr` instead of `this` — otherwise it's fine as written", "It should notify observers both before and after the query", "Queries should return via a callback; observers are for state changes"], "answer": 3, "explain": "Callbacks for queries, observers for state changes. A Get/Fetch should return its result via a callback; observers fire only when something is Set, Created, or Deleted."}, {"rule": "ARCH-022", "prompt": "A public Rewards header adds:\n\n```cpp\n#include \"brave/components/brave_rewards/core/engine/database/database_publisher_info.h\"\nvoid DoSomething(internal::database::DatabasePublisherInfo info);\n```\n\nWhat should it use instead?", "choices": ["The public Mojo type: `mojom::PublisherInfoPtr`", "A forward declaration of `DatabasePublisherInfo` to avoid the include", "A `void*`, so no internal header needs to be included", "A `std::string` containing serialized JSON of the publisher info"], "answer": 0, "explain": "Never expose internal implementation types in public component headers; use the component's public API types (e.g. Mojo types)."}, {"rule": "ARCH-023", "prompt": "In `brave/components/brave_referrals/BUILD.gn`, which target naming follows the standard?", "choices": ["`source_set(\"referrals\")`, referenced as `//brave/components/brave_referrals:referrals`", "`source_set(\"brave_referrals_lib\")` to make the target name globally unique", "Name it after its directory, e.g. `source_set(\"browser\")` in `browser/`", "Any name, as long as it's listed in `visibility`"], "answer": 2, "explain": "GN `source_set` names should match their directory name, so paths are predictable (e.g. `//brave/components/brave_referrals/browser`)."}, {"rule": "ARCH-024", "prompt": "The rewriter service is never null in production but is null in some unit-test configurations. Which snippet follows the standard?", "choices": ["`if (!service) return;`", "`if (!service) { CHECK_IS_TEST(); return; }`", "`CHECK(service);`", "`if (!service) { LOG(ERROR) << \"null in tests\"; return; }`"], "answer": 1, "explain": "Use `CHECK_IS_TEST()` before a null early-return when null should only happen in tests. It documents that null isn't a valid production state, unlike an ambiguous bare null check."}, {"rule": "ARCH-025", "prompt": "```cpp\nvoid BraveVpnServiceFactory::BuildServiceInstanceFor(...) {\n  auto* manager = BraveVPNConnectionManager::GetInstance();\n  manager->SetInstallSystemServiceCallback(base::BindRepeating(...));\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Call the setter earlier, in `main()`, to avoid initialization-order issues", "Store the callback in a global so any factory can set it", "Pass the callback into the manager's constructor instead of a setter", "Add a `DCHECK` that the callback was set before it's first used"], "answer": 2, "explain": "Pass dependencies via constructors, not setter callbacks. Constructor injection makes dependencies explicit and avoids confusing initialization ordering."}, {"rule": "ARCH-026", "prompt": "A `KeyedService` depends on local state that some unit tests don't provide, and the PR adds `if (!local_state_) return;` to several methods. What's cleaner?", "choices": ["Keep the null checks and add a comment that they're only for tests", "Override `ServiceIsNULLWhileTesting()` to return `true`", "Create a fake local state in production so it's never null", "Override `ServiceIsCreatedWithBrowserContext()` to return `false` in the factory"], "answer": 1, "explain": "When a keyed service shouldn't be created in unit tests lacking its dependencies, let the factory control it via `ServiceIsNULLWhileTesting()` returning `true` — cleaner than scattered null checks."}, {"rule": "ARCH-027", "prompt": "Your service factory returns null for incognito, but a feature wants to work there too:\n\n```cpp\nauto* profile =\n    Profile::FromBrowserContext(context)->GetOriginalProfile();\nauto* service = MyServiceFactory::GetForProfile(profile);\n```\n\nWhat should the reviewer say?", "choices": ["Don't bypass the factory; call it with the real profile and handle null", "Good workaround — the original profile always has the service", "Use `GetPrimaryOTRProfile()` instead of `GetOriginalProfile()`", "Add a comment explaining why the bypass is needed, then it's fine to merge"], "answer": 0, "explain": "Never call `GetOriginalProfile()` (or similar) to circumvent factory profile checks. If the factory returns null for a profile type, that profile isn't supposed to use the service."}, {"rule": "ARCH-028", "prompt": "A helper must attach to the `WebContents` itself (it also runs on non-tab WebContents), but should be skipped for non-regular profiles and when `kFoo` is disabled. Which approach is recommended?", "choices": ["Always call `CreateForWebContents()` and have every method check the guards", "Make it a `BraveTabFeatures` member, even though it also runs on non-tab contents", "Attach it unconditionally and destroy it in `DidFinishNavigation` if disabled", "A static `MaybeCreateForWebContents()` with the guards"], "answer": 3, "explain": "For helpers that must live on the `WebContents`, use a static `MaybeCreateForWebContents` with the guards rather than always creating and checking internally. (Pure tab-scoped features go in `BraveTabFeatures` instead.)"}, {"rule": "ARCH-029", "prompt": "You're adding a new keyed service factory for desktop. Which base class should it inherit from?", "choices": ["`ProfileKeyedServiceFactory`", "`BrowserContextKeyedServiceFactory`", "`RefcountedBrowserContextKeyedServiceFactory`", "`base::NoDestructor<KeyedServiceFactory>`"], "answer": 0, "explain": "New desktop keyed service factories should inherit from `ProfileKeyedServiceFactory` rather than the older `BrowserContextKeyedServiceFactory`."}, {"rule": "ARCH-030", "prompt": "Which change most clearly warrants a `base::Feature` guard?", "choices": ["A one-line fix for an off-by-one bug in an existing, already-shipped feature", "Renaming a private helper function", "Fixing a typo in a log message", "A large, experimental new service that may need rollback"], "answer": 3, "explain": "Guard significant or experimental functionality behind `base::Feature` so it can be remotely disabled via Griffin. Use judgment — small, self-contained changes and simple bug fixes typically don't need a flag."}, {"rule": "ARCH-031", "prompt": "A feature has `DesktopDelegate` (using `BrowserList`) and `AndroidDelegate` (using `TabModel`) with otherwise identical logic. What's the recommended refactor?", "choices": ["Keep both delegates; platform code should always be fully separate", "One unified delegate; only tab access is platform-specific", "Merge them into one file with `#if BUILDFLAG(IS_ANDROID)` around every method", "Move all the logic to Java and call it from desktop via JNI"], "answer": 1, "explain": "Unify platform-specific delegates: keep shared logic in one place and extract only the platform-specific bits (like tab access) into the delegate interface."}, {"rule": "ARCH-032", "prompt": "```cpp\nFileType GetFileType(const std::string& mime) {\n  if (mime == \"application/pdf\") return FileType::kPDF;\n  return FileType::kImage;\n}\n```\n\nWhat's the reviewer's concern?", "choices": ["It should use a `switch` statement instead of chained `if`s", "`kImage` is a reasonable default since most uploaded files are images anyway", "Unknown types silently become images; return `std::nullopt`", "It should `CHECK` that `mime` is non-empty — otherwise fine"], "answer": 2, "explain": "Don't silently fall back on unknown types — silent fallbacks mask bugs. Return an explicit error (e.g. `std::nullopt`) and let the caller handle unknown types."}, {"rule": "ARCH-033", "prompt": "A Mojo `BookmarksListener` has a single `Changed(BookmarksChange)` event that fires both when the model finishes loading and when bookmarks actually change. Which design follows the standard?", "choices": ["Keep `Changed` and add a `bool is_initial_load` field to the change struct", "Separate `OnBookmarksReady()` and `OnBookmarksChanged()` events", "Fire `Changed` on listener registration too so clients always get data", "Remove the load signal; clients should poll until data appears"], "answer": 1, "explain": "A Mojo `Changed` event should fire only on actual data changes. Don't conflate lifecycle events (model load, listener registration) with mutations — provide separate events."}, {"rule": "ARCH-034", "prompt": "You need to fetch from three services in parallel and run `OnAllComplete` with all results. Which approach does the standard recommend?", "choices": ["A `pending_count_` member that each callback decrements, running `OnAllComplete` at 0", "Chain the fetches sequentially so the last callback has everything", "`base::BarrierCallback<Result>(3, done)` passed to each fetch", "A `base::RepeatingTimer` that polls until all results arrive"], "answer": 2, "explain": "Use `base::BarrierCallback` to aggregate parallel async results rather than manually tracking completion counts."}, {"rule": "ARCH-035", "prompt": "This mojom is used by a component that also targets iOS:\n\n```mojom\nstruct ModelConfig {\n  enum Category { kChat = 0, kCompletion = 1 };\n  Category category;\n};\n```\n\nWhat's the problem?", "choices": ["Enum values must start at 1 in mojom", "Mojom doesn't allow enums inside structs on any platform, so it won't compile", "Nothing — nesting enums is preferred because it scopes the names", "Nested enums break iOS codegen; move the enum to top level"], "answer": 3, "explain": "Mojom enums must be top-level when the target includes iOS; nested enums produce invalid Objective-C++ (`*.mojom.objc.mm` build failure)."}, {"rule": "ARCH-036", "prompt": "`brave_wallet` must build for iOS. A PR adds a method taking `content::WebContents*` to a wallet service. What should the reviewer request?", "choices": ["Pass specific deps like `PrefService*` instead of content types", "Wrap the method in `#if !BUILDFLAG(IS_IOS)` and keep using `content::WebContents*`", "Use `content::BrowserContext*` instead, which is available on iOS", "Add `//content` to the iOS deps of `brave_wallet`"], "answer": 0, "explain": "Components that build for iOS can't depend on content-layer types (`content::WebContents`, `content::BrowserContext`) because iOS uses WebKit. Pass specific dependencies instead."}, {"rule": "ARCH-037", "prompt": "`brave_shields` must work on iOS and on content-based platforms. In the layered structure, which statement is correct?", "choices": ["`core/` may depend on `content/` as long as the iOS build skips those files", "iOS builds pull in both `core/` and `content/`", "Put everything in `content/` and stub it out for iOS", "Business logic lives in `core/`, which has no `//content` deps"], "answer": 3, "explain": "Use a layered component: `core/` is iOS-compatible with no `//content` deps and holds business logic; `content/` depends on `core/` and `//content`. iOS only builds `core/`."}, {"rule": "ARCH-038", "prompt": "Component A depends on component B. A new PR makes B call into a class in A. What's the recommended fix?", "choices": ["Break the cycle with a delegate interface or observer", "Allow it, since GN permits the cycle via `allow_circular_includes_from`", "Merge A and B into a single component", "Use a forward declaration so B doesn't need A's header"], "answer": 0, "explain": "Component dependencies must form a strict tree — no direct or transitive cycles. Use delegate interfaces or observers to break cycles."}, {"rule": "ARCH-039", "prompt": "A new Mojo data decoder service is being added. Where should its implementation live?", "choices": ["In `components/<feature>/browser/` next to its callers", "In a `services/` directory", "In `components/<feature>/renderer/`", "In `brave/browser/<feature>/`"], "answer": 1, "explain": "Mojo service implementations and data decoders belong in `services/`, not `components/.../browser/`, following Chromium conventions."}, {"rule": "ARCH-040", "prompt": "```gn\n# components/services/brave_shields/BUILD.gn\ndeps = [\n  \"//brave/components/brave_shields/core/browser/adblock\",\n]\n```\n\nWhat's wrong, and how is it fixed?", "choices": ["Nothing; everything under `core/` is safe for all processes by definition", "Use `public_deps` instead of `deps`", "Utility code can't use browser code; move it to `common/`", "Move the service itself into `core/browser/`"], "answer": 2, "explain": "Code running in the utility process must never depend on browser-process code. Anything shared between processes belongs in `common/`, not `browser/`."}, {"rule": "ARCH-041", "prompt": "A model-list service holds data that's identical for all profiles and doesn't depend on profile state. A PR adds a `BrowserContextKeyedServiceFactory` for it. What's the preferred design?", "choices": ["Keep the KeyedService for consistency with the other services in the feature", "A `base::NoDestructor` singleton, since there's no per-profile state", "A global `ModelListService* g_model_list = new ModelListService;`", "Store it as user data on each `BrowserContext`"], "answer": 1, "explain": "When a service has no per-profile state or profile-specific data, use a static singleton with `base::NoDestructor` — a KeyedService adds unnecessary complexity."}, {"rule": "ARCH-042", "prompt": "A migration you're writing would clear several user preferences and wipe a local storage directory on upgrade. What should happen before implementation?", "choices": ["Flag the destructive operation for UX review", "Ship it behind a feature flag defaulted on and skip review", "Just log the deletion so it's debuggable later", "Ensure it runs on a background thread so it's unnoticed"], "answer": 0, "explain": "Operations that delete user data must be flagged for UX review before implementation — silent data deletion is a poor experience and may violate user expectations."}, {"rule": "ARCH-043", "prompt": "You fire N parallel async requests and need results in the original request order. Which approach does the standard recommend?", "choices": ["Insert into a `std::map<int, Result>` keyed by index, then copy it out at the end", "`push_back` in each callback, then sort by timestamp", "Pre-size a vector to N and assign each result at its request index", "Issue the requests serially to preserve order"], "answer": 2, "explain": "For ordered async aggregation, pre-allocate a vector and insert by index rather than using a map and sorting later."}, {"rule": "ARCH-044", "prompt": "`mojom::ToolConfig` already has `name` and `description`. A PR adds a C++ `struct ToolConfig { std::string name; std::string description; };` plus conversion code. What should the reviewer say?", "choices": ["Good — C++ business logic should never depend on generated mojom types", "Fine, but put the struct in a `common/` directory", "Add `static_assert`s to keep the two structs in sync", "Use `mojom::ToolConfigPtr` directly"], "answer": 3, "explain": "When mojom types already describe the data shape, use them in C++ instead of creating redundant structs — duplicates create sync burden and drift risk."}, {"rule": "ARCH-045", "prompt": "Which API signature follows the standard for a fetcher with internal caching?", "choices": ["`void FetchData(const std::string& url, Callback cb);`", "`void FetchData(const std::string& url, const std::string& cache_key, Callback cb);`", "`void FetchData(const std::string& url, int cache_slot, Callback cb);`", "`std::string FetchData(const std::string& url, Callback cb);` returning the key"], "answer": 0, "explain": "Don't expose cache keys in API interfaces. Auto-generate unique keys internally instead of making callers provide or manage them."}, {"rule": "ARCH-046", "prompt": "The WebUI wants pinned items shown first, grouped by category. A PR changes the core service to return items in that display order. What's the better approach?", "choices": ["Sort in the core layer so every client automatically gets the same UI ordering", "Keep canonical order in the backend; reorder in the UI", "Add a `display_order` field computed by the backend", "Have the service return two lists: canonical and UI-ordered"], "answer": 1, "explain": "Data reordering for UI presentation belongs in the client/UI layer. The backend returns data in its canonical order; the frontend transforms it for display."}, {"rule": "ARCH-047", "prompt": "A history mojom interface will be consumed by WebUI and native iOS UI. Which name fits the standard?", "choices": ["`interface HistoryPageHandler`", "`interface HistoryWebUIHandler`", "`interface HistoryUIHandler`", "`interface HistoryWebPageBridge`"], "answer": 2, "explain": "Mojom interfaces that may be used by different UI frameworks should use framework-agnostic names like \"UIHandler\", not web-specific ones like \"PageHandler\"."}, {"rule": "ARCH-048", "prompt": "A trusted WebUI page needs to exchange data with an untrusted `chrome-untrusted://` frame it embeds (which doesn't intentionally run untrusted code). What's the recommended channel?", "choices": ["`window.postMessage` with origin checks", "A shared `localStorage` key both frames poll", "URL fragment changes on the iframe", "A mojo interface between the frames"], "answer": 3, "explain": "Use a mojo interface for trusted/untrusted WebUI communication; Chromium advises against `postMessage` across trust boundaries. Only avoid mojo when the frame intentionally runs untrusted code and minimizing API surface is a deliberate security choice."}, {"rule": "ARCH-049", "prompt": "```cpp\nbool IsZCashShieldedTransactionsEnabled() {\n  return IsZCashEnabled() && kShieldedEnabled.Get() &&\n         IsWalletWebUIEnabled();\n}\n```\n\nWhat's the reviewer's concern?", "choices": ["Cache `kShieldedEnabled.Get()` in a function-local static to avoid repeated lookups", "Drop the WebUI check here and gate it in the UI layer", "Reorder the checks so the cheapest runs first", "Also check `IsWalletWebUIEnabled()` in every caller"], "answer": 1, "explain": "Gate UI restrictions at the UI layer, not in core utility functions. Coupling core logic to UI state causes unexpected test failures and tight coupling."}, {"rule": "ARCH-050", "prompt": "An admin disables a feature via policy with ENFORCED enforcement. How should the settings UI behave?", "choices": ["Show the controls greyed out with a managed icon", "Show the controls enabled but ignore user changes", "Hide the feature's UI section entirely", "Show it normally — policy only affects the backend"], "answer": 2, "explain": "For ENFORCED policy-disabled features, hide the UI entirely rather than just disabling controls. RECOMMENDED policies keep the UI visible since users can override (and macOS `defaults write` creates RECOMMENDED policies)."}, {"rule": "ARCH-050", "prompt": "A tester sets a policy with `defaults write` on macOS to disable a feature, and the settings section is still visible. Is that a bug?", "choices": ["No — `defaults write` creates RECOMMENDED policies", "Yes — any managed policy, regardless of level, must hide the UI", "Yes — `defaults write` creates MANDATORY policies, so the section should be hidden", "No — macOS never supports enterprise policies"], "answer": 0, "explain": "Only ENFORCED policies hide the UI entirely. RECOMMENDED policies keep it visible since the user can override, and on macOS `defaults write` produces RECOMMENDED, not MANDATORY, policies."}, {"rule": "ARCH-051", "prompt": "```cpp\nvisual_content_used_percentage_ = new_value;\nOnStateForConversationEntriesChanged();\n```\n\nWhat should the reviewer request?", "choices": ["Notify before assigning so observers can see the old-to-new transition", "Post the notification asynchronously to batch updates", "Fine — observers should handle redundant notifications themselves", "Store the old value and notify observers only if the value changed"], "answer": 3, "explain": "Check that the value actually changed before firing state notifications to avoid unnecessary observer calls and re-renders."}, {"rule": "ARCH-053", "prompt": "A VPN feature needs a small helper that currently lives inside the Rewards module, and the PR imports the Rewards class directly. What's the recommended approach?", "choices": ["Import it — reusing existing code is always better than any duplication", "Copy the Rewards class into the VPN module", "Make Rewards depend on VPN as well to keep things symmetric", "Extract the helper into a shared utility or interface both can use"], "answer": 3, "explain": "Feature modules shouldn't import classes from unrelated feature modules. Extract shared functionality into a common utility or abstraction — cross-feature coupling makes features hard to change or remove independently."}, {"rule": "ARCH-054", "prompt": "Both Rewards and Wallet need the `gate3` service URL, with no single owner. Where should it live?", "choices": ["In the `brave_domains:urls` target", "As a `kGate3Url` constant duplicated in each component's `constants.h`", "In the legacy `brave_constants.h`", "In Rewards' constants, with Wallet adding a dependency on Rewards"], "answer": 0, "explain": "Shared URL constants with no clear owner go in `brave_domains:urls` — not duplicated per component and not in legacy `brave_constants.h`. Use `GetServicesDomain()` for environment-aware URLs."}, {"rule": "ARCH-055", "prompt": "```mojom\nstruct SearchResult {\n  array<string>? queries;\n};\n```\n\n`null` and `[]` both mean \"no queries\". What should the reviewer suggest?", "choices": ["Keep it optional, since optional arrays are cheaper to serialize over IPC", "Use `map<string, bool>?` instead", "A non-optional `array<string>`; empty means no items", "Add a separate `bool has_queries` field"], "answer": 2, "explain": "Prefer non-optional arrays in mojom (empty = no items). Only use `array<T>?` when null has a distinct meaning from empty."}, {"rule": "ARCH-056", "prompt": "A PR adds a new locale helper class under `brave/components/l10n/`. What's the reviewer's response?", "choices": ["Fine — `components/l10n/` is where all Brave locale-related code is meant to go", "It's deprecated; use Chromium's built-in localization", "Fine, as long as it has unit tests", "Move it to `components/l10n/common/` instead of `browser/`"], "answer": 1, "explain": "Don't add new code to the deprecated `components/l10n/`. Use Chromium's built-in localization; if no equivalent exists, discuss alternatives first."}, {"rule": "ARCH-057", "prompt": "A feature manages per-tab page-action state (e.g. find-in-page-like UI). Which owner is the right scope?", "choices": ["`BrowserWindowFeatures`", "A `BrowserContextKeyedServiceFactory` service", "`GlobalFeatures`", "`TabFeatures` (`BraveTabFeatures`)"], "answer": 3, "explain": "Every feature belongs to exactly one ownership primitive — Tab, Browser Window, Profile, or Global — and should use the narrowest scope that fits. Per-tab state belongs in `TabFeatures`."}, {"rule": "ARCH-057", "prompt": "A browser-window-scoped feature (e.g. a vertical tabs controller) wants to store a per-profile preference cache. What's the problem?", "choices": ["Multiple windows can share a profile; keep profile state out", "None; windows and profiles are always one-to-one", "It should be moved to `GlobalFeatures` so every window and profile can share the cache", "It should store the cache on each tab instead"], "answer": 0, "explain": "Browser-window features must not hold profile state (multiple windows share a profile), and tab features must not hold window state (tabs move between windows). Profile-scoped data belongs in a keyed service."}, {"rule": "ARCH-066", "prompt": "```cpp\nfor (auto& callback : pending_callbacks_) {\n  std::move(callback).Run();  // may add to pending_callbacks_\n}\npending_callbacks_.clear();\n```\n\nWhich fix follows the standard?", "choices": ["Iterate by index (`for (size_t i = 0; i < size(); ++i)`) so growth is safe", "Call `pending_callbacks_.clear()` before the loop", "`std::exchange` the queue into a local, then iterate the local copy", "Reserve extra capacity in `pending_callbacks_` before iterating"], "answer": 2, "explain": "Swap-and-process: move the queue into a local before iterating. Items added during processing won't corrupt the iteration or cause infinite loops."}, {"rule": "ARCH-058", "prompt": "```cpp\nclass FooTabFeature {\n  raw_ptr<Browser> browser_;\n};\n```\n\nWhat's the risk, and the fix?", "choices": ["None; a tab's `Browser` never changes over its lifetime", "Tabs can change windows; hold the `TabInterface` and ask it", "Use `raw_ref<Browser>` instead of `raw_ptr` to prevent nulls", "Store a `BrowserWindowInterface*` instead of `Browser*`, which is the modern API"], "answer": 1, "explain": "Tab-scoped features must never hold window-level objects (`Browser*` or `BrowserWindowInterface*`) — tabs can be dragged to other windows, causing use-after-free. Hold the tab and ask it for its current window."}, {"rule": "BS-001", "prompt": "A PR updates a dependency in `DEPS`:\n\n```python\n'src/brave/vendor/foo': 'https://github.com/brave/foo.git@v1.2.0',\n```\n\nWhat should the reviewer say?", "choices": ["Looks good — release tags are stable markers", "Use the `main` branch so fixes are picked up automatically", "Pin it to a commit hash instead of a tag", "Use a version range so patch releases are allowed"], "answer": 2, "explain": "DEPS entries must always use commit hashes, never branch names or tags. Hashes are immutable, so builds are reproducible."}, {"rule": "BS-003", "prompt": "A teammate adds a new GN arg `brave_android_keystore_path` for signing Android builds. Chromium already defines `android_keystore_path`. Best response?", "choices": ["Reuse the existing `android_keystore_path` arg rather than duplicating it", "Fine — the `brave_` prefix keeps it from clashing with upstream if Chromium changes theirs", "Rename it `enable_brave_android_keystore_path` to follow the buildflag naming convention", "Keep both, defaulting the new one to upstream's value"], "answer": 0, "explain": "Check for existing GN args before creating new ones. Duplicated config args confuse people and add maintenance burden."}, {"rule": "BS-004", "prompt": "You're reviewing a new build script:\n\n```python\nimport sys\n\ndef main():\n    out = sys.argv[1]\n    generate(out)\n\nmain()\n```\n\nWhich change brings it in line with the conventions?", "choices": ["Rewrite it in Node.js so it matches the frontend tooling and shares its npm deps", "Keep `sys.argv`, but add a length check and print usage before indexing", "Wrap `main()` in try/except and always exit 0 so a flaky step never breaks the build", "Use `argparse` and end with `if __name__ == '__main__': sys.exit(main())`"], "answer": 3, "explain": "Python build scripts should use `argparse` rather than raw `sys.argv`, and the standard `sys.exit(main())` entry point so they can return explicit exit codes."}, {"rule": "BS-005", "prompt": "The root `source_set(\"browser\")` already has ~200 sources and ~100 deps. A PR adds 4 new branded-wallpaper files to its `sources` and 2 deps to its `deps`. What should the reviewer ask for?", "choices": ["Just keep the new sources in order and the deps sorted alphabetically within the lists", "Move the feature into its own target with grouped `sources` and `deps`", "Move all of the target's deps into a separate `deps.gni` file to shrink `BUILD.gn`", "Nothing — it's fine as long as `gn check` passes"], "answer": 1, "explain": "Always group `sources` and `deps` in the same block. Split files into feature-specific targets/BUILD.gn files so it's clear which deps belong to which sources."}, {"rule": "BS-006", "prompt": "A single GN target contains three separate `if (enable_brave_vpn) { ... }` blocks, scattered between other sources and deps. What's the right feedback?", "choices": ["Fine — each block keeps its sources close to their related deps", "Replace them with `if (is_win || is_mac)` blocks", "Move the VPN-only sources into a `sources.gni` file", "Consolidate them into a single `if (enable_brave_vpn)` block"], "answer": 3, "explain": "A BUILD.gn target should almost never contain more than one of the same guard. If you're repeating the same `if (enable_foo)` block, consolidate."}, {"rule": "BS-007", "prompt": "Which GN snippet follows the standard for adding Tor launcher sources?", "choices": ["`if (is_linux) { sources += [ \"tor_launcher_linux.cc\" ] }`", "`if (enable_tor) { sources += [ \"tor_launcher.cc\" ] }`", "`if (is_linux || is_win) { sources += [ \"tor_launcher.cc\" ] }`", "`if (!is_android && !is_ios) { sources += [ \"tor_launcher.cc\" ] }`"], "answer": 1, "explain": "Feature-specific code is guarded by buildflags like `enable_tor`, not OS platform guards. OS guards without buildflags are deprecated."}, {"rule": "BS-008", "prompt": "You're adding a compile-time flag for a top-level Brave feature, the perf predictor. It needs to be distinguishable from Chromium flags. Which name follows the convention?", "choices": ["`brave_perf_predictor_enabled`", "`use_perf_predictor`", "`enable_brave_perf_predictor`", "`perf_predictor_brave`"], "answer": 2, "explain": "Buildflags that need to be distinguished from Chromium flags, or that are top-level Brave features, are named `enable_brave_<feature>`."}, {"rule": "BS-008", "prompt": "In `components/ai_chat/core/common/buildflags/buildflags.gni`, a PR adds `enable_tab_management_tool = !is_android`. A reviewer insists it must be renamed `enable_brave_tab_management_tool`. Best response?", "choices": ["The prefix isn't needed: it's scoped to a Brave component's own buildflags file", "Agree — every Brave buildflag must start with `enable_brave_` to avoid upstream clashes", "Rename it `brave_tab_management_tool_enabled`, since suffix naming is the GN convention", "Move the flag into Chromium's buildflags via a patch so no prefix is needed"], "answer": 0, "explain": "The `enable_brave_` prefix is only needed to avoid ambiguity with Chromium. Flags that are clearly Brave-specific by context, such as one in a Brave component's own buildflags file, don't need it."}, {"rule": "BS-010", "prompt": "A PR vendors a small third-party library and copies Chromium's `LICENSE` file into the new directory, because the library uses the same license. What should the reviewer say?", "choices": ["Good practice — each vendored directory should carry its own license copy for audits", "Don't duplicate the license file; use a special case or a reference", "Rename it to `LICENSE.brave` so license tooling doesn't confuse it with upstream's", "Also copy it into `brave/LICENSES/` for completeness"], "answer": 1, "explain": "Never duplicate Chromium's (or other projects') license files. Use special cases or references instead."}, {"rule": "BS-011", "prompt": "A feature ships a `static_data.json` that is needed by both C++ and the WebUI. The PR reads it at runtime with `base::ReadFileToString()` from a path next to the binary. Better approach?", "choices": ["Embed the JSON as a C++ raw string literal in a header", "Fetch it from a Brave server at startup instead", "Keep reading from disk, but cache the file contents in memory", "Package it as a resource in a `.grd` file"], "answer": 3, "explain": "JSON data files should be packaged as `.grd` resources rather than loaded from disk. That way the same data can be used from both C++ and JS."}, {"rule": "BS-013", "prompt": "A Chromium target needs to pull in Brave code. A patch adds this to an upstream target:\n\n```gn\nvisibility += [ \"//brave/components/brave_rewards/browser\" ]\n```\n\nWhat should be done instead?", "choices": ["Depend on an existing high-level target with visibility, e.g. `//brave/utility`", "Fine — patching the `visibility` list is the minimal, most targeted change possible", "Remove the `visibility` list from the upstream target entirely via the patch", "Add `nogncheck` to the include so the visibility restriction isn't enforced"], "answer": 0, "explain": "Use high-level `//brave/` targets (like `//brave/utility`) instead of modifying Chromium visibility lists. Those lists exist precisely to prevent this kind of cross-boundary dependency."}, {"rule": "BS-015", "prompt": "You're writing a new Python script that is only invoked by a GN `action()` in `components/foo/resources/BUILD.gn`. Where should the script live?", "choices": ["In `brave/script/`, alongside the other build scripts, so they're easy to find", "In a new top-level `brave/tools/` directory", "In `components/foo/resources/`, next to the action that uses it", "In a separate scripts repo pulled in via DEPS, so other projects can reuse it"], "answer": 2, "explain": "Build and utility scripts should live near the target or config that uses them. Avoid adding new scripts to `brave/script`."}, {"rule": "BS-016", "prompt": "A team proposes creating a new standalone GitHub repository for a feature's core logic, then pulling it into the build through DEPS. Best response?", "choices": ["Good idea — a separate repo gives smaller, faster code reviews and its own independent CI", "Fine, as long as DEPS pins it to an exact commit hash rather than a branch", "Only if the repo is also mirrored to Chromium's infrastructure for the bots", "Keep it in brave-core; separate repos are harder to manage, review, and maintain"], "answer": 3, "explain": "Avoid creating separate repositories for Brave features. Prefer keeping the code within brave-core."}, {"rule": "BS-017", "prompt": "A PR adds a background request at startup to a new endpoint `https://foo.brave.com/config`. There is no user opt-in. What else does the PR need?", "choices": ["Nothing — the network audit only checks third-party domains, not `*.brave.com`", "Add the URL to the network audit allowlist in `brave_network_audit_allowed_lists.h`", "Gate the request behind a disabled-by-default `base::Feature` so the network audit skips it", "Only an allowlist entry if the endpoint isn't HTTPS; `https://` URLs pass the audit"], "answer": 1, "explain": "New endpoints that don't require user opt-in must be added to the network audit allowed list. Otherwise the network audit check fails."}, {"rule": "BS-017", "prompt": "A new endpoint is hit only when the user explicitly clicks a \"Check for updates\" button. A reviewer asks for it to be added to the network audit allowed list. Best response?", "choices": ["None needed: the request only happens on explicit user action", "Agree — every new URL must be added to the allowlist, regardless of how it's triggered", "Add it, and also disable the network audit for that test to avoid false positives", "Move the request to startup so the audit can catch it"], "answer": 0, "explain": "The network audit allowlist is for endpoints contacted without user opt-in. Never require an entry for requests made only on explicit user action, such as a button click."}, {"rule": "BS-018", "prompt": "Reviewing this GN change for Brave Wallet:\n\n```gn\nif (!is_android && !is_ios) {\n  sources += [ \"brave_wallet_utils.cc\" ]\n}\n```\n\nWhat should the reviewer say?", "choices": ["Fine — Wallet is desktop-only today, so the guard is equivalent", "Use `if (is_win || is_mac || is_linux)` to be explicit", "Guard it with the actual feature flag, `brave_wallet_enabled`", "Remove the guard and use a runtime feature check instead"], "answer": 2, "explain": "Don't use OS guards as a proxy for a feature guard. Use the real feature flag (`brave_wallet_enabled`), because OS guards can drift out of sync with the feature logic."}, {"rule": "BS-019", "prompt": "A target adds `content_helper.cc`, which depends on `//content/public/browser`. Which guard is correct?", "choices": ["`if (use_blink) { ... }` in GN and `#if BUILDFLAG(USE_BLINK)` in C++", "`if (!is_ios) { ... }` in GN and `#if !BUILDFLAG(IS_IOS)` in C++", "`if (!is_android && !is_ios) { ... }` in GN and the matching `#if` in C++", "No guard — `//content` is built on every platform, including iOS and Android"], "answer": 0, "explain": "Content-layer dependencies are guarded with `use_blink`, the flag that actually controls whether the content layer is built. `!is_ios` is only a proxy and may not always be equivalent."}, {"rule": "BS-020", "prompt": "A directory already has a `BUILD.gn`. A PR adds a `sources.gni` alongside it to list a few extra files. What's the feedback?", "choices": ["Fine — `sources.gni` exists precisely for listing extra files beside a `BUILD.gn`", "Have either a `BUILD.gn` (preferred) or a `sources.gni`, not both", "Rename it `extra_sources.gni` to make its purpose clear", "Delete the `BUILD.gn` and move everything into `sources.gni` for consistency"], "answer": 1, "explain": "Never have both `BUILD.gn` and `sources.gni` in the same directory: it's unclear which is authoritative. Prefer `BUILD.gn`."}, {"rule": "BS-053", "prompt": "A teammate puts a new feature's sources in a `sources.gni` that is inserted into an upstream Chromium target \"because it's easier\". There's no circular dependency involved. Best response?", "choices": ["Fine — `sources.gni` is the standard way to add Brave code to upstream targets", "Fine, as long as the `sources.gni` contents are guarded by the feature's buildflag", "Move it to a `chromium_src` override of the upstream target instead", "Use a normal `BUILD.gn` target; `sources.gni` is only for circular deps"], "answer": 3, "explain": "Only use `sources.gni` to insert files into upstream targets that have circular deps. Otherwise it hurts incremental builds, because changes rebuild large upstream targets."}, {"rule": "BS-021", "prompt": "You've written unit tests for `//brave/components/brave_vpn/browser/v2`. They don't need any `//chrome` or profile scaffolding. How should they be wired in?", "choices": ["Add the `_unittest.cc` file directly to the `brave_unit_tests` sources in `test/BUILD.gn`", "Give it a `:unit_tests` target and add that to `brave_unit_tests` in `test/BUILD.gn`", "Add a `:unit_tests` target to `brave_components_unittests` in `components/BUILD.gn`", "Create a new `test()` executable just for this component's unit tests"], "answer": 2, "explain": "Tests live in a `unit_tests` target in the component's own BUILD.gn. Component tests are aggregated into `brave_components_unittests`; use `brave_unit_tests` only if they truly need chrome/browser-layer support."}, {"rule": "BS-021", "prompt": "While reviewing an unrelated PR, you notice an existing dependency on `//brave/components/foo:unit_tests` inside `brave_unit_tests`. What should you do?", "choices": ["Block the PR until it's moved to `brave_components_unittests`", "Don't flag it as a violation; many are there for historical reasons", "Ask the author to move the test files into `//brave/browser` alongside the dep", "Request that the dep be wrapped in `nogncheck` to silence the layering check"], "answer": 1, "explain": "Many component `:unit_tests` targets live in `brave_unit_tests` for historical reasons. The rule describes the target state for new code; never flag an existing dependency solely for its location."}, {"rule": "BS-022", "prompt": "A `unit_tests` target lists `test/fake_dependency_service.{h,cc}` in its `sources`. Another team now wants to use the same fake in their tests. What's the right GN structure?", "choices": ["Move them into a `testonly` `test_support` target that `unit_tests` depends on", "Have the other team depend directly on this `:unit_tests` target to reuse the fakes", "Copy the fake files into the other team's `unit_tests` target so each can evolve freely", "Move the fakes into the production `source_set` so anyone can use them"], "answer": 0, "explain": "Reusable fakes and mocks go in a separate `test_support` target rather than being embedded in `unit_tests`, so test targets across the codebase can share them."}, {"rule": "BS-023", "prompt": "A new browser test should run on both desktop and Android:\n\n```cpp\nclass MyBrowserTest : public InProcessBrowserTest {};\n```\n\nWhat should change?", "choices": ["Nothing — `InProcessBrowserTest` already runs on Android", "Duplicate the test into an Android-only fixture", "Use `content::RenderViewHostTestHarness` instead", "Derive from `PlatformBrowserTest` instead"], "answer": 3, "explain": "Cross-platform browser tests (desktop + Android) use `PlatformBrowserTest` as the base class, not `InProcessBrowserTest`."}, {"rule": "BS-024", "prompt": "```gn\nsource_set(\"my_service\") {\n  sources = [ \"my_service.h\", \"my_service.cc\" ]\n  deps = [ \"//base\", \"//components/prefs\" ]\n}\n```\n\n`my_service.h` includes a prefs header; `//base` is only used in the `.cc`. What's the fix?", "choices": ["Move both deps to `public_deps`, since consumers will need both transitively", "Move `//components/prefs` to `public_deps`; keep `//base` in `deps`", "Keep both in `deps` and forward-declare the prefs types in the header", "Add `//components/prefs` to every consumer's `deps`"], "answer": 1, "explain": "A dependency whose headers are included from your header files goes in `public_deps`, so consumers get the include paths too. Deps used only in `.cc` files stay in `deps`."}, {"rule": "BS-026", "prompt": "A teammate wants to add a small helper script to brave-core that post-processes generated files. They have drafts in Bash and Node.js. Which do you recommend?", "choices": ["Bash — it has the fewest dependencies", "Node.js — the repo already uses npm", "Python, run with `vpython` from depot_tools", "Either is fine as long as it's referenced from DEPS"], "answer": 2, "explain": "Build and utility scripts are written in Python (`vpython`), not Node.js or shell. That follows Chromium convention, avoids extra runtime deps, and works on Windows."}, {"rule": "BS-027", "prompt": "```gn\nif (enable_brave_rewards) {\n  deps += [\n    \"//brave/components/brave_rewards/common/buildflags\",\n    \"//brave/components/brave_rewards/browser\",\n  ]\n}\n```\n\nThe `.cc` uses `#if BUILDFLAG(ENABLE_BRAVE_REWARDS)`. What's wrong?", "choices": ["Nothing — the buildflag header is only needed when Rewards is enabled at build time", "The `browser` dep should be listed before `buildflags` to keep deps sorted", "Both deps should move to `public_deps`, since the `.cc`'s header exposes them", "The `buildflags` dep must be unconditional, since the `#if` needs it even when off"], "answer": 3, "explain": "When `deps +=` sits inside an `if (enable_feature)` block, add the `buildflags` dep unconditionally outside it. The `#if BUILDFLAG()` check needs that header in both states. Verify with `gn check` with the flag disabled."}, {"rule": "BS-028", "prompt": "A component exposes its public API as `source_set(\"browser\")` and has a helper `source_set(\"internal_network\")` with no `visibility` set. What's the right setup?", "choices": ["Make the public one a `static_library`/`component`; give the internal one `visibility = [ \":*\" ]`", "Keep both as `source_set`, the default for components, and document which one is internal", "Turn both into `component()` targets with default public visibility so either can be linked", "Keep both, but move `internal_network` into a `sources.gni` included by `browser`"], "answer": 0, "explain": "Public component targets use `static_library` or `component`. `source_set` is only for internal deps, and those must have restricted visibility."}, {"rule": "BS-029", "prompt": "A Python build script writes a generated file:\n\n```python\nwith open(output_path, 'w') as f:\n    f.write(content)\n```\n\nWhat should the reviewer ask for?", "choices": ["Open it with `'wb'` and encode the content manually", "Add `newline='\\n'` to `open()` for consistent LF endings", "Call `content.replace('\\r\\n', '\\n')` before writing", "Nothing — Python normalizes line endings automatically"], "answer": 1, "explain": "Always pass `newline='\\n'` when writing files from Python, so line endings are LF on every platform, especially Windows."}, {"rule": "BS-030", "prompt": "In a DEPS file, a directory allows the same content_settings includes for every `.cc` file:\n\n```python\nspecific_include_rules = {\n  \".*\\.cc\": [\n    \"+brave/components/content_settings/core/common\",\n  ],\n}\n```\n\nBetter approach?", "choices": ["List each `.cc` file individually under `specific_include_rules` to be explicit", "Add `// nogncheck` to those includes instead, so no DEPS entry is needed", "Move it to `include_rules`; keep `specific_include_rules` for file-specific cases", "Duplicate the rule into a DEPS file in each subdirectory, so every rule sits next to its files"], "answer": 2, "explain": "Use `include_rules` for includes allowed across a directory. Reserve `specific_include_rules` for edge cases where only specific files may include something."}, {"rule": "BS-031", "prompt": "You're adding a new entry to `resource_ids.spec`. How far should you bump the next starting ID?", "choices": ["By 1, the smallest gap needed", "By 10, to align on round numbers", "By 100, to reserve a full block", "By 5, leaving room for additions"], "answer": 3, "explain": "Bump resource IDs in `resource_ids.spec` by 5, not 1. That leaves room for later additions without conflicting with adjacent entries."}, {"rule": "BS-032", "prompt": "A new Mojo service implementation is declared in BUILD.gn as `static_library(\"my_service\")`. What should the reviewer suggest?", "choices": ["Use `component(\"my_service\")` instead", "Use `source_set(\"my_service\")` for faster builds", "Use `shared_library(\"my_service\")` explicitly", "Keep `static_library`; it's correct for services"], "answer": 0, "explain": "Mojo service targets use `component()` rather than `static_library()`. Components support dynamic linking and are the correct type for service implementations."}, {"rule": "BS-033", "prompt": "Code in `components/ai_chat/content/browser/` needs content-layer support in its unit test, so the author puts `associated_link_content_unittest.cc` in `browser/ai_chat/`. Feedback?", "choices": ["Fine — unit tests that need the content layer belong under `//brave/browser`", "Move it into `//chrome/test`, where the content test harnesses already live", "Put the test next to the component, using `content::RenderViewHostTestHarness`", "Turn it into a browser test, which gets content support no matter where it lives"], "answer": 2, "explain": "Unit tests for `//brave/components` code must not live in `//brave/browser`. Keep them next to the code; `content::RenderViewHostTestHarness` provides content-layer support."}, {"rule": "BS-036", "prompt": "Source files include `brave/components/ai_chat/core/common/mojom/ai_chat.mojom.h`, but the DEPS file lists `\"+brave/components/ai_chat/common\"`. The PR passes locally. What's the issue?", "choices": ["None — DEPS paths are matched by prefix, so `ai_chat/common` is close enough", "DEPS must list the exact include path, or the check validates the wrong thing", "DEPS entries for generated headers should name the `.mojom` file, not the directory", "Use `-brave/components/ai_chat` so the rule covers all subpaths at once"], "answer": 1, "explain": "DEPS allowlist paths must exactly match the `#include` paths. A mismatch (like `common/` vs `core/common/`) means the DEPS check isn't validating the right file."}, {"rule": "BS-037", "prompt": "Every target in `components/brave_wallet/test/BUILD.gn` belongs to Wallet, and the whole file is wrapped in `if (enable_brave_wallet) { ... }`. What's the preferred form?", "choices": ["Keep the wrapper; it's the safest option, since nothing can build accidentally", "Wrap each target in its own `if (enable_brave_wallet)` so the guards are local", "Move the targets into a `sources.gni` included conditionally", "Put `assert(enable_brave_wallet)` at the top and drop the wrapper"], "answer": 3, "explain": "If an entire BUILD.gn file belongs to a feature, put `assert(enable_feature)` at the top instead of wrapping its blocks in conditionals."}, {"rule": "BS-038", "prompt": "```gn\nif (kLocalAIModels) {\n  deps += [ \"//brave/components/local_ai/resources\" ]\n}\n```\n\n`kLocalAIModels` is a `base::Feature`, and no `enable_local_ai` build flag exists yet. Best fix?", "choices": ["Create a GN arg named `kLocalAIModels` that mirrors the feature's default state", "Add the dep unconditionally; the runtime feature check handles enablement", "Wrap the dep in `if (!is_ios)` as an approximation of where the feature runs", "Read `base::FeatureList` state from a GN `exec_script` at configure time"], "answer": 1, "explain": "Runtime feature flags (`base::FeatureList`) can't gate build-time deps. Use a build flag if one exists; otherwise include the dep unconditionally rather than inventing one."}, {"rule": "BS-039", "prompt": "`gn check` fails on an include, so a PR changes it to:\n\n```cpp\n#include \"brave/components/foo/bar.h\"  // nogncheck\n```\n\nWhat should the reviewer say?", "choices": ["Fine — `nogncheck` exists for exactly this case of a conditional include", "Move the include into the `.h` file instead", "Remove `nogncheck` and fix the GN dep so it's correctly conditional", "Set `check_includes = false` on this target rather than per include"], "answer": 2, "explain": "Don't suppress gn check failures with `nogncheck`; it's a code smell that masks real dependency problems. Fix the underlying GN dep guard instead."}, {"rule": "BS-040", "prompt": "```gn\nif (is_mac) {\n  if (enable_tor) {\n    deps += [ \"//brave/components/tor\" ]\n  }\n}\n```\n\nThe C++ include is guarded by `#if BUILDFLAG(ENABLE_TOR)` only. What's the correct GN?", "choices": ["`if (enable_tor) { deps += [ \"//brave/components/tor\" ] }`", "Keep it as is; the extra platform guard is harmless", "`if (is_mac && enable_tor) { deps += [ \"//brave/components/tor\" ] }`", "Add `if (is_mac)` around the C++ include to match"], "answer": 0, "explain": "Within a target, add deps behind the relevant buildflag only, not nested inside platform guards. The GN guards and C++ guards should always match."}, {"rule": "BS-041", "prompt": "```gn\nif (use_blink) {\n  deps += [\n    \"//brave/components/foo/common\",\n    \"//content/public/browser\",\n  ]\n}\n```\n\n`foo/common` is a plain utility needed on every platform. What's the fix?", "choices": ["Nothing — keeping related deps grouped under one guard keeps the BUILD file tidy and readable", "Change the guard to `if (!is_ios)` so Android and desktop both get the two deps", "Move both deps into a `sources.gni` that's included on every platform", "Make `foo/common` unconditional; keep `//content/public/browser` under `use_blink`"], "answer": 3, "explain": "Put a dep inside a guard only if the dep itself is specific to that condition. Unrelated deps inside guards cause incorrect configurations and missing symbols where the guard is false."}, {"rule": "BS-042", "prompt": "Building with `enable_brave_rewards = false` fails because `rewards_service_unittest.cc` no longer compiles. A teammate adds an unconditional dep on `//brave/components/brave_rewards` \"just for tests\". Better fix?", "choices": ["Only add the test to `sources` under `if (enable_brave_rewards)`", "Keep the dep, but mark it `testonly` so it never reaches production builds", "Wrap the whole test file body in `#if BUILDFLAG(ENABLE_BRAVE_REWARDS)`", "Use `nogncheck` on the test's includes"], "answer": 0, "explain": "When a build flag disables a feature, exclude that feature's tests from the build with GN conditionals, rather than patching deps so disabled-feature tests still compile."}, {"rule": "BS-043", "prompt": "You've added a new build flag, defaulting to enabled. `gn_check`, unit tests, and browser tests pass on your default build. What else is required before landing?", "choices": ["Nothing — the default configuration is what ships, so it's what CI must cover", "Only re-run `gn_check` with the flag disabled; tests don't depend on GN args", "Run `gn_check`, unit, component, browser tests, and presubmit with it disabled", "Ask CI to run the full suite with the flag disabled in a follow-up job after merging"], "answer": 2, "explain": "Validate a new build flag in both states: run `gn_check`, unit, component, and browser tests, and presubmit with the flag enabled AND disabled. Issues often appear only when it's disabled."}, {"rule": "BS-044", "prompt": "A settings WebUI imports `SpeedreaderPage` unconditionally and hides it at runtime when `loadTimeData.getBoolean('isSpeedreaderEnabled')` is false. The feature also has a build flag. What should be added?", "choices": ["A second runtime check in the page's constructor, in case `loadTimeData` is stale", "Wrap the import in `// <if expr=\"enable_speedreader\">` ... `// </if>`", "A dynamic `import()` guarded by `loadTimeData` so the module isn't eagerly loaded", "A CSS rule hiding the page when `isSpeedreaderEnabled` is false"], "answer": 1, "explain": "Use Chromium's UI preprocessor (`<if expr=\"enable_feature\">`) in JS/HTML so feature code is removed from the build when the flag is off, rather than relying only on runtime `loadTimeData` checks."}, {"rule": "BS-046", "prompt": "Rewards depends on Wallet. A PR adds fallback code paths so Rewards can still build and run when `enable_brave_wallet = false`. Better approach?", "choices": ["Keep the fallbacks; supporting more build configurations makes Rewards more robust", "Silently force `enable_brave_wallet = true` in Rewards' BUILD.gn when Rewards is on", "Guard Rewards with `if (!is_ios)` to approximate Wallet support", "Add `assert(enable_brave_wallet, \"Rewards requires Wallet\")` in Rewards' BUILD.gn"], "answer": 3, "explain": "When Feature A depends on Feature B, assert B's build flag when A is enabled, rather than making A work in unsupported configurations."}, {"rule": "BS-048", "prompt": "`kOllamaEndpoint = \"http://localhost:11434\"` is defined as a `constexpr char[]` in `model_service.cc`, `ollama_model_fetcher.cc`, and `model_service_unittest.cc`. What's the fix?", "choices": ["Define it once as `inline constexpr` in a shared header", "Keep the copies, but add a comment linking them", "Move it into a pref so all three files read the same value at runtime", "Keep the production copies and delete only the test copy, which can drift"], "answer": 0, "explain": "Shared constants such as limits, URLs, and keys belong in a common header, so implementation, tests, and other files don't each carry their own copy."}, {"rule": "BS-050", "prompt": "A PR adds `kGate3OAuthUrl`, used only by Rewards, to `components/constants/brave_constants.h`. Where should it go?", "choices": ["It's fine there — `brave_constants.h` is where Brave-wide constants live", "In `//brave/browser/brave_constants.h`, next to the other service URLs", "In Rewards' own `common` target, e.g. `brave_rewards/common/constants.h`", "In the `.cc` file that uses it, as a file-local constant in an anonymous namespace"], "answer": 2, "explain": "`components/constants` is a deprecated dumping ground: never add constants, headers, targets, or deps there. Put constants in the owning component's `common` target."}, {"rule": "BS-050", "prompt": "A URL constant is shared by several components, and no single component clearly owns it. Where should it be defined?", "choices": ["In `components/constants`, since it's shared", "In a dedicated `brave_domains` target", "Duplicated in each component that uses it", "In `//chrome/common/url_constants.h` via a patch"], "answer": 1, "explain": "Never add to `components/constants`. A constant (especially a URL) shared across components with no clear owner goes in a `brave_domains` target."}, {"rule": "BS-052", "prompt": "A PR adds `enable_foo = is_nightly && !is_android && is_official_build`, so a feature ships only in Nightly desktop official builds. What's the concern?", "choices": ["None — a compound flag precisely targets the Nightly desktop rollout with no runtime cost", "It should also include `!is_ios`, since iOS isn't covered by `!is_android`", "It should be a runtime feature flag combined with `is_official_build` in C++", "Compound channel/platform/official flags break on branch migration; use separate flags"], "answer": 3, "explain": "Don't create buildflags that combine channel, platform, and official_build. They break as branches migrate (nightly → beta → release) and are nearly impossible to test locally."}, {"rule": "BS-055", "prompt": "`source_set(\"core\")` contains `local_ai_service.{h,cc}` and `internal_helper.{h,cc}`. Consumers should only include `local_ai_service.h`. How do you enforce that?", "choices": ["Move `internal_helper.h` into an `internal/` folder and trust the naming", "Add a comment in `internal_helper.h` saying \"do not include\"", "Add `public = [ \"local_ai_service.h\" ]` to the target", "Set `visibility = [ \":*\" ]` on the whole target"], "answer": 2, "explain": "List the exposed headers in `public = [...]`. GN then enforces that dependents can only `#include` those headers, keeping implementation details internal."}, {"rule": "BS-056", "prompt": "A PR adds a new Brave endpoint that is only contacted after the user opts in. Does it need to go in the HSTS pin list?", "choices": ["Yes — add it to both the pins and HSTS `entries` in `input_file_parsers.cc`", "No — only endpoints contacted without user opt-in need to be pinned", "Only to the HSTS `entries` list; pinning is optional for opt-in endpoints", "No — adding it to the network audit allowlist already covers HSTS and pinning"], "answer": 0, "explain": "Every new Brave endpoint goes in the HSTS pin list (both the pins and HSTS `entries` in `chromium_src/net/tools/transport_security_state_generator/input_file_parsers.cc`), whether or not it requires opt-in."}, {"rule": "BS-057", "prompt": "A PR adds `webui/history/brave_history_embeddings_page_handler.{h,cc}` to `sources` of `source_set(\"ui\")` in `brave/browser/ui/BUILD.gn`. What should the reviewer ask for?", "choices": ["Nothing — `source_set(\"ui\")` is the standard place for browser UI files", "Put them in a lower-level target, e.g. `brave/browser/ui/webui/history/BUILD.gn`", "Add them via a `sources.gni` into upstream `//chrome/browser/ui` instead", "Keep them in `ui`, but guard them with `if (!is_android)` since history is desktop-only"], "answer": 1, "explain": "Don't add new sources to `source_set(\"ui\")` in `brave/browser/ui/BUILD.gn`. `//chrome/browser/ui` is prone to circular deps, so use a more specific, lower-level target."}, {"rule": "BS-057", "prompt": "Moving your files into a new `webui/history` target causes a circular include error with `//chrome/browser/ui`. Which approach is preferred?", "choices": ["Set `check_includes = false` on the new target, since the cycle is only in headers", "Add `// nogncheck` to the offending includes; the link-time deps are still correct", "Move the files back into `source_set(\"ui\")`, where the cycle doesn't arise", "Interface/impl split: headers in the direct dep, impl in a higher-level target"], "answer": 3, "explain": "Break cycles with the interface/impl pattern, dependency inversion, or templated subclasses. `allow_circular_includes_from`/`sources.gni` is only a temporary last resort; never use `check_includes = false`."}, {"rule": "BS-058", "prompt": "A GN `action()` that runs on the build bots passes:\n\n```gn\nargs = [ \"--output=\" + rebase_path(output) ]\n```\n\nWhat's the correct form?", "choices": ["`rebase_path(output, \"/\")`", "`rebase_path(output, root_build_dir)`", "`get_path_info(output, \"abspath\")`", "It's fine as is — absolute paths are the most robust"], "answer": 1, "explain": "One-argument `rebase_path()` produces a system-absolute path that breaks remote execution and relocated checkouts. Pass the expected base (usually `root_build_dir`) as `new_base`."}, {"rule": "CSRC-001", "prompt": "You need to change some upstream Chromium behavior and can't do it purely within brave-core. In what order of preference should you reach for options?", "choices": ["A patch first, since it's the most explicit and reviewable, then chromium_src", "Brave-only code, then chromium_src, then a patch as last resort", "chromium_src and patches are equally fine; pick whichever is shorter", "Edit `src/` directly and skip generating patch files"], "answer": 1, "explain": "Avoid modifying Chromium whenever possible. When unavoidable, chromium_src overrides are strongly preferred; patches (generated with `pnpm run update_patches`) are the last resort and should be minimal."}, {"rule": "CSRC-002", "prompt": "An upstream test fails in Brave because of an intentional behavior change. A PR adds this to a chromium_src override:\n\n```cpp\n#define SomeUpstreamTest DISABLED_SomeUpstreamTest\n```\n\nWhat should the reviewer request?", "choices": ["Disable it via a `test/filters/` file and keep Brave's version in a Brave test target", "Fine — `#define`-renaming to `DISABLED_` is the standard way to disable upstream tests", "Keep the `#define` but add an `#undef` after the include so it doesn't leak", "Patch the upstream test file to add `DISABLED_` instead"], "answer": 0, "explain": "Never disable upstream tests via `#define ... DISABLED_...` in chromium_src. Use filter files in `test/filters/`, and move Brave-specific replacements into `brave_unit_tests`, `brave_browser_tests`, etc."}, {"rule": "CSRC-003", "prompt": "You need different color logic in `ChromeTypographyProvider::GetColor` only when `ShouldIgnoreHarmonySpec()` is false. Which override shape is preferred?", "choices": ["Copy the full 50-line upstream function and edit the 3 lines that differ", "Patch upstream `GetColor` with an `if` block that calls into Brave code", "Return `ChromiumImpl::GetColor(...)` unless the condition applies", "Replace the whole class with a dummy no-op implementation"], "answer": 2, "explain": "Minimize duplication in overrides: wrap only the changed section and fall back to `ChromiumImpl` for everything else."}, {"rule": "CSRC-004", "prompt": "An upstream `.cc` file needs to `#include \"brave/components/my_feature/my_header.h\"`. A PR does this by adding a one-line patch. What's preferred?", "choices": ["A one-line patch is ideal; keep it", "Add the header to the upstream target's `public_deps` via a GN arg", "Copy the upstream file into brave-core and include it there", "Add the include via a chromium_src override"], "answer": 3, "explain": "Always prefer a chromium_src override over a patch — patches are harder to maintain, conflict more, and are harder to review. Required headers should be added through chromium_src, not patches."}, {"rule": "CSRC-005", "prompt": "A chromium_src override reproduces an entire 60-line upstream method because 3 lines need to change. What's the standard?", "choices": ["Acceptable if the copied code has a comment marking the changed lines", "Copy the whole file instead, so the method stays consistent with its neighbors", "Acceptable as long as `check_chromium_src.py` passes", "Override only the changed part; call the original for the rest"], "answer": 3, "explain": "Never copy entire Chromium files or methods into chromium_src. Override only what needs to change and delegate to the superclass for everything else."}, {"rule": "CSRC-007", "prompt": "You need `TabStrip` to create a `BraveNewTabButton` instead of `NewTabButton`. Which approach follows the standard?", "choices": ["Patch `tab_strip.cc` to construct `BraveNewTabButton` directly", "Patch every method of `NewTabButton` that needs Brave behavior", "A chromium_src `#define NewTabButton BraveNewTabButton`", "Copy `tab_strip.cc` into chromium_src with the one-line change applied"], "answer": 2, "explain": "Prefer subclassing over patching, in both C++ and Java. Swapping in a Brave subclass via chromium_src (or one patch changing a superclass in Java) is easier to maintain than patching individual methods."}, {"rule": "CSRC-012", "prompt": "Inside a chromium_src override, which include is correct?", "choices": ["`#include \"brave/chromium_src/net/proxy_resolution/proxy_resolution_service.h\"`", "`#include \"net/proxy_resolution/proxy_resolution_service.h\"`", "`#include \"../../../net/proxy_resolution/proxy_resolution_service.h\"`", "`#include \"chromium_src/net/proxy_resolution/proxy_resolution_service.h\"`"], "answer": 1, "explain": "In chromium_src overrides, always include the original header path, never the chromium_src version."}, {"rule": "CSRC-014", "prompt": "Brave wants to fully disable `TranslateURLFetcher`. A PR adds two patches (one for the `.h`, one for the `.cc`). What's the preferred approach?", "choices": ["Dummy no-op `.h`/`.cc` replacements in chromium_src", "Keep the two patches but combine them into one", "Add `#define TranslateURLFetcher BraveTranslateURLFetcher` and subclass it", "Remove the class from the upstream BUILD.gn via a GN patch"], "answer": 0, "explain": "To disable or replace a Chromium class entirely, add minimal no-op dummy replacements in chromium_src for the `.h` and `.cc` — no patch needed and easier maintenance."}, {"rule": "CSRC-015", "prompt": "You need `SomeClass::SomeMethod` to be virtual so a Brave subclass can override it. Which approach is correct?", "choices": ["A plaster rewrite with `make_virtual`", "`#define SomeMethod virtual SomeMethod` around the upstream header include", "`#define final` around the upstream include", "Subclass and hide the method with a same-named non-virtual one"], "answer": 0, "explain": "Don't use `#define` to add `virtual` — it rewrites every `SomeMethod` in the translation unit. Use the `make_virtual` plaster rewriter, which also handles pointer/reference return types and destructors."}, {"rule": "CSRC-016", "prompt": "```cpp\n#define final\n#include \"src/chrome/browser/ui/views/side_panel/side_panel_coordinator.h\"\n#undef final\n```\n\nWhat's the reviewer's verdict?", "choices": ["Accept, since the `#undef` immediately limits the scope", "Accept if `final` appears only once in that header and nowhere in its includes", "Replace it with `#define final override`", "Reject: it's undefined behavior and viral"], "answer": 3, "explain": "Never `#define final` — it's undefined behavior per the C++ standard and can break unrelated code using `final`. Use a minimal patch to remove `final` or find another approach."}, {"rule": "CSRC-017", "prompt": "A new chromium_src override replaces `TabView::BuildContextMenu()`. A per-function comment already explains it adds Brave menu items because upstream isn't extensible there. A reviewer also asks for a file-level comment. Correct?", "choices": ["Yes — every override file needs a file-level header comment", "Yes — and each method injected via `#define` also needs its own doc comment", "No — per-function comments are enough", "No — chromium_src overrides should never have comments"], "answer": 2, "explain": "chromium_src overrides should explain why they're needed, but a file-level comment isn't required if per-function comments cover it. Don't ask for doc comments inside `#define` macro bodies either."}, {"rule": "CSRC-018", "prompt": "You add a new `#include` of a Brave header to a chromium_src override. How do you verify the dependency is wired up?", "choices": ["If it compiles locally, the dependency is fine", "Add the include to the upstream file temporarily and run `gn check`", "Run `check_chromium_src.py`, which validates GN deps for override includes", "Add the header to `brave/BUILD.gn` `public_deps` to be safe"], "answer": 1, "explain": "The override compiles as part of the upstream target, which may lack deps on your headers. Test by adding the include to the upstream file and running `gn check`; if it fails, the dep must be added."}, {"rule": "CSRC-019", "prompt": "A chromium_src override of `window_feature_controller.cc` includes `brave/browser/ui/views/tabs/vertical_tab_utils.h`, and a patch adds `//brave/browser/ui/views/tabs` to the upstream target's deps. What's the preferred design?", "choices": ["Keep the include but move the GN dependency into `sources.gni` instead of a patch", "Keep it; a single Brave include in an override is acceptable", "Forward-declare a hook in the override; implement it in a Brave target", "Copy `vertical_tab_utils.h` into chromium_src so no dep is needed"], "answer": 2, "explain": "chromium_src should avoid depending on `//brave/...` targets — that creates an upstream→Brave dep. Forward-declare a hook in the override, implement it in a dedicated Brave target, and have a top-level Brave target depend on it."}, {"rule": "CSRC-020", "prompt": "In a chromium_src override you see:\n\n```cpp\nprovider_ = nullptr;\n```\n\nwith no context. What should the reviewer ask for?", "choices": ["Replace it with `provider_.reset()` so the ownership is explicit", "Remove it — upstream code will null the pointer during shutdown anyway", "Wrap it in `DCHECK(provider_)` first", "A comment explaining why it's reset, e.g. to avoid a dangling pointer"], "answer": 3, "explain": "Add comments for non-obvious `nullptr` assignments in chromium_src — the override is out of context from the original file, so intent (like dangling-pointer prevention) isn't clear."}, {"rule": "CSRC-021", "prompt": "You add `constexpr int kBravePolicySource = 10;` after upstream's `POLICY_SOURCE_COUNT`. What protects against upstream adding values?", "choices": ["A `DCHECK` at startup comparing upstream's count with `kBravePolicySource`", "A `static_assert` that the upstream count is `<= kBravePolicySource`", "Choosing a large value like `1000` so clashes are unlikely", "A unit test that logs the enum count"], "answer": 1, "explain": "When appending custom values after an upstream enum, add a `static_assert` so the build fails if upstream grows the enum and values would clash."}, {"rule": "CSRC-022", "prompt": "You're adding a Brave-specific Blink runtime-enabled feature `BraveGlobalPrivacyControl`. Where does it go?", "choices": ["`runtime_enabled_features.override.json5`", "A patch to `runtime_enabled_features.json5`", "A chromium_src override of `runtime_enabled_features.cc`", "A new `base::Feature` in `brave/components/` only"], "answer": 0, "explain": "Add Brave Blink runtime-enabled features to `runtime_enabled_features.override.json5` — it's designed for downstream additions and avoids patch conflicts with `runtime_enabled_features.json5`."}, {"rule": "CSRC-023", "prompt": "You need to change `PrivateHelper()`, defined in an anonymous namespace in upstream `chrome/browser/feature.cc`. How?", "choices": ["Use a `.patch` file", "A chromium_src override that `#define`s `PrivateHelper` to a Brave function", "Subclass the file's class and override `PrivateHelper`", "Use `make_virtual` on `PrivateHelper`"], "answer": 0, "explain": "chromium_src overrides only work for symbols with external linkage. Static or anonymous-namespace functions in upstream `.cc` files aren't visible outside the TU, so use a patch."}, {"rule": "CSRC-024", "prompt": "Upstream calls `l10n_util::GetStringFUTF16(IDS_FOO, site_name)` (one `$1`). You `#define` `IDS_FOO` to `IDS_BRAVE_FOO`. What must be true of `IDS_BRAVE_FOO`?", "choices": ["It must have no placeholders at all", "Any placeholders are fine; extra ones are filled with empty strings", "Its placeholders must be compatible with the upstream caller's", "It must have at least two placeholders for flexibility"], "answer": 2, "explain": "Replacement strings must match the placeholders the upstream caller provides. Fewer are silently ignored; more or different ones can cause runtime errors."}, {"rule": "CSRC-025", "prompt": "You're reviewing a chromium_src override that swaps an upstream string:\n\n```cpp\n#undef IDS_PASSWORD_MANAGER_UI_EMPTY_STATE_SYNCING_USERS\n#define IDS_PASSWORD_MANAGER_UI_EMPTY_STATE_SYNCING_USERS \\\n  IDS_BRAVE_PASSWORD_MANAGER_UI_EMPTY_STATE\n```\n\nWhat should be added?", "choices": ["Nothing — `check_chromium_src.py` already makes any extra guard redundant", "An `#ifndef`/`#error` guard before the `#undef`", "Wrap the `#undef` in `#if defined(...)` so it's skipped if the ID disappears", "A runtime `DCHECK` that the string resource loads successfully"], "answer": 1, "explain": "Guard overridden string IDs with `#ifndef`/`#error` so a rebase that removes or renames the upstream ID fails at compile time — an extra safety net on top of `check_chromium_src.py`."}, {"rule": "CSRC-026", "prompt": "In a chromium_src override where the upstream class was renamed via `#define` to `ChromiumImpl`:\n\n```cpp\nSkColor BraveProvider::GetColor(int id) {\n  return ChromeTypographyProvider::GetColor(id);\n}\n```\n\nWhat's wrong?", "choices": ["Nothing — `ChromeTypographyProvider` is the upstream class, so it's correct", "It should call `BraveProvider::GetColor(id)` recursively", "It should use `Super::GetColor(id)`", "It should call `ChromiumImpl::GetColor(id)`"], "answer": 3, "explain": "Fallback methods must call the correct base class. With `#define` renames changing the hierarchy, the upstream implementation is `ChromiumImpl`, not the original class name."}, {"rule": "CSA-001", "prompt": "A PR adds a hand-written helper:\n\n```cpp\nstd::string ParseQueryParam(const std::string& url, const std::string& key) {\n  // 30 lines of custom '?', '&' and '=' splitting...\n}\n```\n\nWhat should the reviewer say?", "choices": ["Approve if unit tests cover the edge cases like empty values and fragments", "Move it to a shared `brave/` utils file so other components can reuse it", "Use an existing utility such as `net::QueryIterator`", "Rewrite it with `std::regex` so the parsing is more robust to odd inputs"], "answer": 2, "explain": "Check for existing well-tested Chromium/base utilities before writing custom code — e.g. `net::QueryIterator` for query strings."}, {"rule": "CSA-002", "prompt": "New code contains:\n\n```cpp\nbase::Callback<void(bool)> cb = base::Bind(&Foo::OnDone, weak_ptr);\nservice->Start(cb);\n```\n\n`Start` runs the callback exactly once. What's the right fix?", "choices": ["Use `base::BindOnce` but pass the callback by `const&` to avoid a move", "Nothing — `base::Bind` is fine as long as the callback runs only once", "`base::OnceCallback` + `base::BindOnce`, passed via `std::move(cb)`", "Replace it with a `std::function<void(bool)>` holding a lambda"], "answer": 2, "explain": "`base::Callback`/`base::Bind` are deprecated. Use `OnceCallback`/`BindOnce` (or the `Repeating` variants), and `std::move` a `OnceCallback` when passing or running it."}, {"rule": "CSA-003", "prompt": "```cpp\ntime_t now = std::time(nullptr);\nif (now - last_check_ > kOneDay) Refresh();\n```\n\nWhat should the reviewer request?", "choices": ["Use `base::Time` / `base::TimeDelta` instead", "Use `localtime()` from `<ctime>` so the comparison is in local time", "Keep `time_t` but store it in a `uint64_t` to avoid the year-2038 problem", "Fine — `std::time` is portable standard C++"], "answer": 0, "explain": "Never use C-style `std::time`, `ctime` or `time_t`; use `base::Time` and related classes, which are cross-platform and type-safe."}, {"rule": "CSA-004", "prompt": "```cpp\nconst auto* name = dict->FindStringKey(\"name\");\nconst auto age = dict->FindIntKey(\"age\");\nif (name) result.name = *name;\nif (age) result.age = *age;\n// ...repeated for 12 more fields\n```\n\nWhat's the preferred approach for turning this JSON into `MyType`?", "choices": ["Keep the manual lookups; they're the most explicit and easiest to debug", "Serialize with `JSONWriter` and pattern-match on the resulting string", "Register the fields with `base::JSONValueConverter<MyType>`", "Store the whole `base::Value::Dict` as a member instead of typed fields"], "answer": 2, "explain": "Prefer `base::JSONValueConverter` over manual key-by-key parsing, which is verbose, error-prone, and duplicates boilerplate."}, {"rule": "CSA-005", "prompt": "```cpp\nstd::unordered_map<std::string, double> feature_map_;\n```\n\nThis is a general-purpose, unordered map of a few hundred entries. What should it be?", "choices": ["`absl::btree_map<std::string, double>` for better cache behavior", "It's fine — `std::unordered_map` is standard C++ and well understood", "`std::map<std::string, double>`, since hash maps are banned in Chromium", "`absl::flat_hash_map<std::string, double>`"], "answer": 3, "explain": "`std::unordered_map`/`set` are banned. Default to `absl::flat_hash_map`/`set`; `base::flat_map` for sorted small/write-once, `std::map` for large frequently-mutated sorted data. `absl::btree_*` is banned too."}, {"rule": "CSA-005", "prompt": "You need a hash map where **pointers to keys** must stay valid while the map is mutated. Which container fits Chromium's guidelines?", "choices": ["`absl::node_hash_map`", "`base::flat_map`, wrapping each key in a `std::unique_ptr`", "`absl::btree_map`, because tree nodes never move after insertion", "`std::unordered_map`, since its nodes are separately allocated"], "answer": 0, "explain": "For key pointer stability use `absl::node_hash_map`/`node_hash_set`; for value stability, wrap values in `std::unique_ptr` inside an `absl::flat_hash_map`. `std::unordered_*` and `absl::btree_*` are banned."}, {"rule": "CSA-006", "prompt": "```cpp\nstd::string str;\nvalue->GetAsString(&str);\n```\n\nWhich replacement follows the standard?", "choices": ["`const std::string& str = value->GetString();`", "`base::JSONWriter::Write(*value, &str);`", "`std::string str = value->DebugString();`", "Keep it, but check the `bool` return value of `GetAsString()`"], "answer": 0, "explain": "`GetAsString()`, `GetAsInteger()` etc. on `base::Value` are deprecated. Use the direct accessors `GetString()`, `GetInt()`, `GetDouble()`."}, {"rule": "CSA-007", "prompt": "`value` comes from a server response and might not be a bool:\n\n```cpp\nif (value.GetBool()) {\n  EnableFeature();\n}\n```\n\nWhat's the safe pattern?", "choices": ["Use the older `value.GetAsBoolean(&b)` and check its return value", "It's fine — `GetBool()` simply returns `false` on a type mismatch", "`if (value.GetIfBool().value_or(false)) { ... }`", "Wrap the call in `try { ... } catch (...)` to handle bad input"], "answer": 2, "explain": "`Get*()` CHECK-fails (crashes) on a type mismatch. When the type may differ, use `GetIfBool`/`GetIfInt`/`GetIfString`, typically with `.value_or(...)`."}, {"rule": "CSA-008", "prompt": "```cpp\nstd::string port_str = std::to_string(port);\n```\n\nWhat should this be?", "choices": ["`base::NumberToString(port)`", "`base::StringPrintf(\"%d\", port)`", "Build it with a `std::ostringstream` and `<<`", "Leave it — `std::to_string` is only a problem for floating-point values"], "answer": 0, "explain": "`std::to_string` is on Chromium's deprecated list; use `base::NumberToString`."}, {"rule": "CSA-009", "prompt": "```cpp\ndouble ratio = (double)completed / total;  // both are int\n```\n\nWhat should the reviewer suggest?", "choices": ["Nothing — C-style casts are fine for plain arithmetic types", "`static_cast<double>(completed) / total`", "`reinterpret_cast<double>(completed) / total`", "Drop the cast; `completed / total` is promoted to double automatically"], "answer": 1, "explain": "Chromium prohibits C-style casts. Use explicit C++ casts like `static_cast`, which are safer and searchable."}, {"rule": "CSA-010", "prompt": "```cpp\nstd::vector<unsigned char> buffer = BuildData();\nstd::move(cb).Run(buffer, other_arg);\n// buffer is never used again\n```\n\nWhat's the issue?", "choices": ["It copies the whole vector; pass `std::move(buffer)`", "None — the compiler elides the copy because `buffer` is a local", "The callback should receive `buffer.data()` instead of the vector", "Pass a clone explicitly so the ownership transfer is obvious to readers"], "answer": 0, "explain": "Prefer `std::move` over copying/cloning when you no longer need the original — forgetting it in `.Run()` silently copies the entire buffer."}, {"rule": "CSA-011", "prompt": "A PR introduces:\n\n```cpp\nstruct MonthlyStatements {\n  std::vector<MonthlyStatement> statements;\n};\nMonthlyStatements GetMonthlyStatements();\n```\n\nBest review feedback?", "choices": ["Make it a class with a private vector and `begin()`/`end()` accessors", "Drop the wrapper and return `std::vector<MonthlyStatement>`", "Keep it, but add a `using MonthlyStatementList = MonthlyStatements;` alias", "Good — a named plural type documents intent better than a bare vector"], "answer": 1, "explain": "Don't create plural/container wrapper types when a vector of the singular type works — extra types add complexity without value."}, {"rule": "CSA-012", "prompt": "```cpp\nstd::string result;\nbase::JSONWriter::Write(root, &result);\nprefs->SetString(prefs::kMyPref, result);\n```\n\nHow should this structured data be stored?", "choices": ["Split each key into its own separate string pref", "As is — string prefs are the most portable and easiest to migrate", "`prefs->SetDict(prefs::kMyPref, std::move(dict))` (or `SetList`)", "Base64-encode the JSON first so special characters survive"], "answer": 2, "explain": "Don't serialize to JSON strings for prefs; use the native `SetDict`/`SetList` pref value types."}, {"rule": "CSA-013", "prompt": "A header adds:\n\n```cpp\n#define BRAVE_SYNC_URL \"https://sync.brave.com\"\n```\n\nThe value is not passed in from GN. What's preferred?", "choices": ["`#define` it in BUILD.gn `defines` instead of in the header", "`extern const char kBraveSyncUrl[];`, defined in the `.cc`", "Keep the `#define` — it's zero-cost and the prefix avoids collisions", "A global `const std::string kBraveSyncUrl` defined in the header"], "answer": 1, "explain": "Use `extern const char[]` instead of `#define` for string constants so they're namespaced. The exception is values that must come from GN."}, {"rule": "CSA-014", "prompt": "```cpp\n// type must be \"uphold\" or \"gemini\"\nvoid SetWalletType(const std::string& type);\n```\n\nWhat's the better API?", "choices": ["An `enum class WalletType` parameter (with string conversion)", "Add `kUphold`/`kGemini` string constants and keep the `std::string` param", "Keep the string but `DCHECK` that it's one of the allowed values", "Accept an `int` where 0 means Uphold and 1 means Gemini"], "answer": 0, "explain": "When a value has a fixed set of options, use an enum (with string conversion where needed) — the compiler checks switches and invalid values become impossible."}, {"rule": "CSA-015", "prompt": "You're integrating a third-party C++ library whose code uses `throw` and `try/catch` for error handling. What must you verify?", "choices": ["Nothing, as long as you enable `-fexceptions` only for that one target", "That it builds with exception support disabled", "That every call into it from Brave code is wrapped in `try/catch`", "That exceptions never propagate past the library's public API boundary"], "answer": 1, "explain": "C++ exceptions are disallowed in Chromium. Third-party libraries must build with exceptions disabled."}, {"rule": "CSA-016", "prompt": "`items` is a `base::flat_set<Entry>`:\n\n```cpp\nfor (auto it = items.begin(); it != items.end();) {\n  if (it->IsExpired()) it = items.erase(it);\n  else ++it;\n}\n```\n\nWhich replacement follows the standard?", "choices": ["Copy the non-expired entries into a new `flat_set` and swap", "`base::EraseIf(items, [](const auto& e) { return e.IsExpired(); });`", "Keep the loop — iterator-based erase is the most explicit form", "`items.erase(std::remove_if(items.begin(), items.end(), pred), items.end());`"], "answer": 1, "explain": "Prefer `base::EraseIf` for `base::flat_*` containers (and `std::erase_if` for std containers) over manual erase loops."}, {"rule": "CSA-017", "prompt": "```cpp\nvoid ProcessBuffer(const std::vector<uint8_t>& data);  // read-only\n```\n\nCallers hold data in `std::vector`, `base::HeapArray`, and static arrays. Best signature?", "choices": ["`void ProcessBuffer(const uint8_t* data, size_t size);`", "`template <typename C> void ProcessBuffer(const C& data);`", "Keep `const std::vector<uint8_t>&` and convert at each call site", "`void ProcessBuffer(base::span<const uint8_t> data);`"], "answer": 3, "explain": "Use `base::span<const T>` for read-only parameters — a lightweight non-owning view that accepts any contiguous container."}, {"rule": "CSA-018", "prompt": "```cpp\nstd::vector<int> scores(num_players);  // num_players known at runtime\n// scores is filled in but never resized\n```\n\nWhat container best communicates the intent?", "choices": ["`std::array<int, kMaxPlayers>` sized to the largest possible value", "`base::FixedArray<int> scores(num_players);`", "`std::list<int>` so elements never need reallocation", "`std::vector<int>` with a `reserve(num_players)` call"], "answer": 1, "explain": "When size is known at creation but not at compile time, `base::FixedArray` communicates the fixed size and avoids heap allocation for small sizes."}, {"rule": "CSA-019", "prompt": "```cpp\nstd::vector<unsigned char> dat_buffer(size);\nProcessBuffer(dat_buffer.data(), dat_buffer.size());\n```\n\nThis is an owned byte buffer that's never resized. Which version follows the standard?", "choices": ["`auto buf = base::HeapArray<uint8_t>::WithSize(size); ProcessBuffer(buf.as_span());`", "`auto buf = std::make_unique<uint8_t[]>(size); ProcessBuffer(buf.get(), size);`", "`std::vector<uint8_t> buf; buf.reserve(size); ProcessBuffer(buf.data(), size);`", "`std::string buf(size, '\\0'); ProcessBuffer(buf.data(), buf.size());`"], "answer": 0, "explain": "Use `base::HeapArray<uint8_t>` for fixed-size owned byte buffers: fixed-size semantics, bounds-checked indexing, easy `base::span` conversion. `Uninit(size)` skips zero-init on hot paths."}, {"rule": "CSA-020", "prompt": "```cpp\nstd::vector<std::string> names;\nnames.reserve(items.size());\nfor (const auto& item : items) names.push_back(item.name);\n```\n\nWhat's the idiomatic replacement?", "choices": ["`std::vector<std::string> names(items.begin(), items.end());`", "Keep it — the `reserve()` already makes it optimal", "`std::transform` into `std::back_inserter(names)` after `reserve()`", "`auto names = base::ToVector(items, &Item::name);`"], "answer": 3, "explain": "Use `base::ToVector(range)` (optionally with a projection) for range-to-vector conversions; it handles `reserve()` and iteration for you."}, {"rule": "CSA-021", "prompt": "A class stores `std::list<Entry> entries_;`. Entries are appended once, then only iterated front-to-back. What should the reviewer suggest?", "choices": ["Keep `std::list` — linked lists are ideal for sequential traversal", "Use `std::vector<Entry>` (with `reserve()` if the size is known)", "Use `std::set<Entry>` so iteration order is deterministic", "Switch to `std::forward_list` to save one pointer per node"], "answer": 1, "explain": "Never use `std::list` for pure traversal — poor cache locality. Reserve it for stable iterators or frequent mid-container insert/remove; prefer `std::vector`."}, {"rule": "CSA-022", "prompt": "```cpp\n// Pass \"\" to clear the custom title.\nvoid SetCustomTitle(const std::string& title);\n```\n\nWhat's the better API?", "choices": ["Use a reserved value like `\"__unset__\"` so empty titles are allowed", "Keep `\"\"` but define `constexpr char kNoTitle[] = \"\";` for clarity", "`void SetCustomTitle(std::optional<std::string> title);`", "`void SetCustomTitle(const std::string& title, bool has_title);`"], "answer": 2, "explain": "Never use `\"\"`, `-1` or other magic values as \"no value\" sentinels — use `std::optional<T>` and `nullopt`."}, {"rule": "CSA-023", "prompt": "```cpp\nstd::optional<base::ElapsedTimer> elapsed_timer_;\n// ... starting the timer:\nelapsed_timer_ = base::ElapsedTimer();\n```\n\nWhich form is preferred for engaging the optional?", "choices": ["`elapsed_timer_.reset();`", "`elapsed_timer_ = std::optional<base::ElapsedTimer>(base::ElapsedTimer());`", "`elapsed_timer_ = std::make_optional<base::ElapsedTimer>();`", "`elapsed_timer_.emplace();`"], "answer": 3, "explain": "Prefer `.emplace()` when engaging a `std::optional` member — it states the intent explicitly."}, {"rule": "CSA-024", "prompt": "```cpp\nbool GetHistorySize(int* out_size);\n```\n\nHow should this be modernized?", "choices": ["`std::optional<int> GetHistorySize();`", "`std::pair<bool, int> GetHistorySize();`", "`bool GetHistorySize(int& out_size);` to avoid null pointers", "`int GetHistorySize();` returning `-1` when unavailable"], "answer": 0, "explain": "Return `std::optional<T>` instead of `bool` + out parameter when a value may or may not exist."}, {"rule": "CSA-025", "prompt": "In `brave_stats.cc`, which constant definition follows the standard?", "choices": ["`namespace brave_stats { namespace { constexpr int kMaxRetries = 3; } }`", "`namespace brave_stats { namespace { const int kMaxRetries = 3; } }`", "`#define kMaxRetries 3` near the top of the file", "`namespace { constexpr int kMaxRetries = 3; }` above `namespace brave_stats`"], "answer": 0, "explain": "Compile-time constants in anonymous namespaces should be `constexpr`, not `const`, and live inside the component's namespace."}, {"rule": "CSA-026", "prompt": "```cpp\nconst char kScript[] =\n    \"(function() {\\n\"\n    \"  let x = 1;\\n\"\n    \"  return x;\\n\"\n    \"})();\";\n```\n\nWhat should the reviewer suggest?", "choices": ["Concatenate the lines with `base::StrCat` instead of adjacent literals", "Build it at runtime by joining a `std::vector<std::string>` of lines", "Use a raw string literal: `R\"( ... )\"`", "Keep it — explicit `\\n` makes the line breaks obvious to reviewers"], "answer": 2, "explain": "Embed multiline JS, SQL etc. with raw string literals (`R\"()\"`) instead of escaping each line."}, {"rule": "CSA-027", "prompt": "```cpp\nvoid ProcessItem(const int& id, const bool& enabled, Foo* const& foo);\n```\n\nWhat should the signature be?", "choices": ["`void ProcessItem(int&& id, bool&& enabled, Foo*&& foo);`", "`void ProcessItem(int id, bool enabled, Foo* foo);`", "`void ProcessItem(const int* id, const bool* enabled, Foo* foo);`", "Keep it — `const&` avoids copying the arguments"], "answer": 1, "explain": "Pass primitives (`int`, `bool`, `float`, pointers) by value; `const&` only adds indirection."}, {"rule": "CSA-028", "prompt": "A new class ends with:\n\n```cpp\n private:\n  DISALLOW_COPY_AND_ASSIGN(MyClass);\n```\n\nWhat's the preferred replacement?", "choices": ["Delete only the copy constructor; assignment then fails automatically", "Keep the macro for consistency with nearby older classes", "Declare the copy constructor private and leave it undefined", "`= delete` the copy constructor and copy assignment"], "answer": 3, "explain": "`DISALLOW_COPY_AND_ASSIGN` is deprecated. Write `MyClass(const MyClass&) = delete;` and `MyClass& operator=(const MyClass&) = delete;`."}, {"rule": "CSA-029", "prompt": "```cpp\nstruct Topic {\n  Topic(Topic&&) = default;\n  Topic& operator=(Topic&&) = default;\n  // ...\n};\nstd::vector<Topic> topics_;\n```\n\nWhat should be added?", "choices": ["Delete the move operations so the vector always copies predictably", "Nothing; just call `topics_.reserve()` so reallocation never happens", "`noexcept` on both move operations", "`explicit` on the move constructor"], "answer": 2, "explain": "Declare custom move operations `noexcept` for types stored in `std::vector` — otherwise the vector falls back to copying during reallocation."}, {"rule": "CSA-031", "prompt": "A function reads an optional string but never stores it. Which parameter type is preferred?", "choices": ["`base::optional_ref<const std::string> value`", "`std::optional<std::reference_wrapper<const std::string>> value`", "`std::optional<std::string>& value`", "`const std::optional<std::string>& value`"], "answer": 0, "explain": "Never take `std::optional<T>&` — it's confusing and can hide copies. Take `std::optional<T>` by value if storing, or `base::optional_ref<T>` for non-owning access."}, {"rule": "CSA-032", "prompt": "```cpp\nbool ShouldDebounce(const GURL& url) {\n  // ...expensive rule matching on url...\n}\n```\n\nIt's called for every navigation, including `chrome://`, `file://` and `data:` URLs. What should be added first?", "choices": ["A cache of results keyed by full URL to amortize the cost", "`DCHECK(url.SchemeIsHTTPOrHTTPS());` to document the assumption", "`if (!url.SchemeIsHTTPOrHTTPS()) return false;`", "`if (!url.is_valid()) return false;` — scheme doesn't matter"], "answer": 2, "explain": "In URL processing code (shields, debouncing, content settings), short-circuit early on non-HTTP(S) URLs to save work and avoid edge cases."}, {"rule": "CSA-033", "prompt": "```cpp\nclass Transaction {\n  uint64_t invalid_after_ = 0;\n public:\n  void set_invalid_after(uint32_t value) { invalid_after_ = value; }\n};\n```\n\nWhat's the reviewer's concern?", "choices": ["The field should be `int64_t` so negative values can be detected", "The setter should `static_cast<uint64_t>(value)` explicitly", "None — widening `uint32_t` to `uint64_t` inside the setter is lossless", "Silent truncation at call sites; make the param `uint64_t`"], "answer": 3, "explain": "Setter/parameter types must match the field type. A narrower parameter silently truncates at the call site — especially dangerous in wallet/crypto code."}, {"rule": "CSA-034", "prompt": "A feature is removed, and its pref `kOldFeatureEnabled` was stored in user profiles. The PR deletes the pref registration and all uses in one go. What should happen instead?", "choices": ["Nothing — unregistered prefs are simply ignored, so deleting is safe", "Register it for clearing for a release, then remove it", "Rename the pref to a new key in the same CL so old values are orphaned", "Keep the pref registered forever in case the feature returns"], "answer": 1, "explain": "Deprecate prefs before removing them: register the old pref for clearing in one release so stored values are wiped from existing profiles, then fully remove it."}, {"rule": "CSA-035", "prompt": "Which of these should a reviewer flag as \"production code modified solely for tests\"?", "choices": ["A thin `GetFeatureForTesting()` accessor exposing an internalized `base::Feature`", "A `Reset()` method that's also used by the production shutdown path", "An early return in production code when the input list is empty", "`if (CHECK_IS_TEST()) { SkipDnsLookup(); }` inside the production resolver"], "answer": 3, "explain": "Never let test workarounds change production behavior — use test infra like `kHostResolverRules` in `SetUpCommandLine`. Only flag clear signals (`CHECK_IS_TEST()`, `UNIT_TEST`, `_for_testing`); thin `ForTesting()` accessors and defensive logic are fine."}, {"rule": "CSA-036", "prompt": "```cpp\nstd::string url = scheme + \"://\" + host + path;\n```\n\nWhich version follows Chromium conventions?", "choices": ["`base::StringPrintf(\"%s://%s%s\", scheme.c_str(), host.c_str(), path.c_str())`", "`base::StrCat({scheme, \"://\", host, path})`", "`base::JoinString({url::kHttpsScheme, host, path}, url::kStandardSchemeSeparator)`", "`base::StrCat({url::kHttpsScheme, url::kStandardSchemeSeparator, host, path})`"], "answer": 3, "explain": "Use `url::kStandardSchemeSeparator` instead of hardcoding `\"://\"` when constructing URLs."}, {"rule": "CSA-037", "prompt": "```cpp\nservice->DoAsync([](const std::string&) {});\n```\n\nThe caller genuinely doesn't care about the result. What's idiomatic?", "choices": ["`service->DoAsync(base::NullCallback());`", "`service->DoAsync(base::BindOnce([](const std::string&) {}));`", "`service->DoAsync(base::DoNothing());`", "Add an `OnIgnored(const std::string&)` member and bind it with `BindOnce`"], "answer": 2, "explain": "Use `base::DoNothing()` for no-op callbacks instead of empty lambdas — it's the Chromium idiom and reads clearly."}, {"rule": "CSA-038", "prompt": "```cpp\nresult += base::StrCat({kOpenTag, \"\\n\", \"=== METADATA ===\\n\"});\n```\n\nWhat's the better form?", "choices": ["`result = base::StrCat({result, kOpenTag, \"\\n\", \"=== METADATA ===\\n\"});`", "`base::StrAppend(&result, {kOpenTag, \"\\n\", \"=== METADATA ===\\n\"});`", "`result.append(base::StrCat({kOpenTag, \"\\n\", \"=== METADATA ===\\n\"}));`", "`result += absl::StrFormat(\"%s\\n=== METADATA ===\\n\", kOpenTag);`"], "answer": 1, "explain": "`StrCat` builds a temporary string that is then copied; `base::StrAppend(&str, {...})` appends directly into the target."}, {"rule": "CSA-039", "prompt": "```cpp\nfor (auto it = history.crbegin(); it != history.crend(); ++it) {\n  ProcessEntry(*it);\n}\n```\n\nWhich rewrite follows the standard?", "choices": ["Copy `history`, call `std::reverse` on the copy, then loop forward", "Keep the reverse iterators but add a comment explaining the order", "`std::views::reverse(history)` in a range-for, plus a why-comment", "An index loop from `history.size() - 1` down to `0`"], "answer": 2, "explain": "Prefer `std::views::reverse()` with a range-based for loop over explicit reverse iterators, and always comment why reverse order is needed."}, {"rule": "CSA-040", "prompt": "```cpp\nstd::string msg = base::StringPrintf(\"Error %d: %s\", code, desc.c_str());\n```\n\nWhat should it be?", "choices": ["`base::StrCat({\"Error \", std::to_string(code), \": \", desc})`", "Stream `code` and `desc` into a `std::ostringstream`", "Keep `base::StringPrintf` — it's the Chromium-native formatter", "`absl::StrFormat(\"Error %d: %s\", code, desc)`"], "answer": 3, "explain": "`base::StringPrintf` is being deprecated in favor of `absl::StrFormat` (which also accepts `std::string` directly)."}, {"rule": "CSA-041", "prompt": "```cpp\nstd::optional<int64_t> value = GetCount();\nuint64_t result = 0;\nif (value.has_value()) {\n  result = static_cast<uint64_t>(*value);\n}\n```\n\nWhich is the preferred concise and safe form?", "choices": ["`result = base::ClampedNumeric<uint64_t>(*value).RawValue();`", "`result = static_cast<uint64_t>(value.value_or(0));`", "`result = base::saturated_cast<uint64_t>(value.value_or(0));`", "`result = base::checked_cast<uint64_t>(value.value_or(0));`"], "answer": 2, "explain": "Combine `base::saturated_cast<T>()` with `.value_or(default)` for safe numeric conversion. Use `checked_cast` only when out-of-range is an invariant violation (it CHECK-fails)."}, {"rule": "CSA-041", "prompt": "`count` and `item_size` come from untrusted input. Which computes the total safely?", "choices": ["`size_t total = count * item_size; if (total / count != item_size) return std::nullopt;`", "`base::CheckedNumeric<size_t> total = count * item_size; if (!total.IsValid()) return {};`", "`size_t total = base::checked_cast<size_t>(count * item_size);`", "`if (!base::CheckMul(count, item_size).AssignIfValid(&total)) return std::nullopt;`"], "answer": 3, "explain": "Casting after the fact doesn't help — the naked `count * item_size` overflows first. Use non-member helpers like `base::CheckMul` so every checked operation is explicit."}, {"rule": "CSA-042", "prompt": "```cpp\nbool found = false;\nfor (const auto& item : items) {\n  if (item.IsExpired()) { found = true; break; }\n}\n```\n\nWhich replacement is preferred?", "choices": ["`std::ranges::all_of(items, [](const auto& i) { return i.IsExpired(); })`", "`std::ranges::any_of(items, [](const auto& i) { return i.IsExpired(); })`", "`std::count_if(items.begin(), items.end(), pred) > 0`", "Keep the loop; the early `break` already makes it efficient"], "answer": 1, "explain": "Prefer C++20 `std::ranges::any_of` / `all_of` / `find_if` over manual loops with break conditions."}, {"rule": "CSA-043", "prompt": "```cpp\nstd::string truncated = content.substr(0, max_length);\n```\n\nMost `content` strings are already shorter than `max_length`. What's the improvement?", "choices": ["Call `content.reserve(max_length)` before `substr()`", "Use `content.resize(max_length)` on a copy instead", "Only `substr()` when `content.size() > max_length`", "Nothing — `substr()` is a no-op when the string is already short"], "answer": 2, "explain": "Guard `substr()` with a size check: it always allocates and copies, so for content within the limit, use the original string."}, {"rule": "CSA-044", "prompt": "```cpp\nstd::optional<Result> Parse(const std::string& input, std::string* error);\n```\n\nCallers need both the result and the error message on failure. Better signature?", "choices": ["`base::expected<Result, std::string> Parse(const std::string& input);`", "`bool Parse(const std::string& input, Result* out, std::string* error);`", "`Result Parse(const std::string& input);` that throws on failure", "`std::pair<std::optional<Result>, std::string> Parse(const std::string& input);`"], "answer": 0, "explain": "When a function can fail with error details, return `base::expected<T, E>` — success and error bundled in one value, no out-parameter."}, {"rule": "CSA-045", "prompt": "```cpp\nconst std::map<ActionType, std::string> kActionNames = {\n    {ActionType::kSummarize, \"summarize\"},\n    {ActionType::kRewrite, \"rewrite\"},\n};\n```\n\nWhat's the preferred form for this static enum-to-string mapping?", "choices": ["`constexpr auto kActionNames = base::MakeFixedFlatMap<ActionType, std::string_view>({...});`", "`const absl::flat_hash_map<ActionType, std::string_view> kActionNames = {...};` at file scope", "`constexpr auto kActionNames = base::MakeFlatMap<ActionType, std::string_view>({...});`", "`static const base::NoDestructor<std::map<ActionType, std::string>> kActionNames(...)`"], "answer": 0, "explain": "For compile-time constant enum↔string mappings, use `base::MakeFixedFlatMap` — compile-time verified and more maintainable than runtime maps or switches."}, {"rule": "CSA-046", "prompt": "```cpp\nauto value = base::JSONReader::Read(json_str);\nif (!value || !value->is_dict()) return;\nauto& dict = value->GetDict();\n```\n\nThe JSON is always expected to be an object. Better form?", "choices": ["`auto dict = base::test::ParseJsonDict(json_str);`", "`auto* dict = base::JSONReader::Read(json_str)->GetIfDict(); if (!dict) return;`", "`auto dict = base::JSONReader::ReadDict(json_str); if (!dict) return;`", "`auto& dict = base::JSONReader::Read(json_str)->GetDict();`"], "answer": 2, "explain": "When a JSON string should be a dictionary, use `base::JSONReader::ReadDict()`, which returns `std::optional<base::Value::Dict>` directly."}, {"rule": "CSA-047", "prompt": "```cpp\nvoid SetName(std::string&& name) { name_ = std::move(name); }\n```\n\nWhat does the Google style guide prefer for this sink parameter?", "choices": ["`void SetName(const std::string& name) { name_ = name; }`", "Provide both a `const std::string&` and a `std::string&&` overload", "`void SetName(std::string& name) { name_.swap(name); }`", "`void SetName(std::string name) { name_ = std::move(name); }`"], "answer": 3, "explain": "For parameters moved into the callee, pass by value instead of `T&&` — callers `std::move()` either way and the API is simpler."}, {"rule": "CSA-048", "prompt": "A migration function gains:\n\n```cpp\nprofile_prefs->ClearPref(kOldFeaturePref);\n```\n\nWhat should the reviewer ask for?", "choices": ["Nothing — `ClearPref` on a missing pref is a harmless no-op", "A comment with the date it was added, e.g. `// Added 2025-01`", "Guard the call behind a feature flag so it can be turned off", "A `TODO(yourname)` comment so people know who to ask"], "answer": 1, "explain": "Annotate obsolete-pref migration entries with the date they were added (e.g. \"safe to remove after ~3 releases\") so old migrations are easy to clean up."}, {"rule": "CSA-049", "prompt": "```cpp\nauto it = metric_configs_.find(metric_name);\nif (it == metric_configs_.end()) {\n  return nullptr;\n}\nreturn &it->second;\n```\n\nWhat's the concise replacement?", "choices": ["`return metric_configs_.contains(metric_name) ? &metric_configs_.at(metric_name) : nullptr;`", "`return &metric_configs_[metric_name];`", "`return &metric_configs_.at(metric_name);`", "`return base::FindOrNull(metric_configs_, metric_name);`"], "answer": 3, "explain": "Use `base::FindOrNull()` instead of the manual find-and-check-end pattern for map lookups."}, {"rule": "CSA-050", "prompt": "```cpp\naccelerator_list.insert(accelerator_list.end(),\n                        brave_accelerators.begin(),\n                        brave_accelerators.end());\n```\n\nWhat's preferred?", "choices": ["A range-based `for` loop calling `push_back()` on each element", "`std::copy(brave_accelerators.begin(), brave_accelerators.end(), std::back_inserter(accelerator_list));`", "`base::Extend(accelerator_list, brave_accelerators);`", "`accelerator_list = base::ToVector(brave_accelerators);`"], "answer": 2, "explain": "Use `base::Extend(target, source)` to append one collection to another instead of `insert(end, begin, end)`."}, {"rule": "CSA-051", "prompt": "In a unit test:\n\n```cpp\nauto value = base::JSONReader::Read(json_str);\nASSERT_TRUE(value);\nASSERT_TRUE(value->is_dict());\nauto* name = value->GetDict().FindString(\"name\");\nASSERT_TRUE(name);\nEXPECT_EQ(*name, \"test\");\n```\n\nWhat's the preferred style?", "choices": ["`EXPECT_THAT(ParseJsonDict(json_str), DictHasValue(\"name\", \"test\"));`", "Parse into a struct with `base::JSONValueConverter` and compare fields", "`EXPECT_EQ(json_str, R\"({\"name\":\"test\"})\");` — compare the raw JSON text directly", "Keep the asserts — each `ASSERT_TRUE` pinpoints the exact failure"], "answer": 0, "explain": "In tests, use `base::test::ParseJson*()` and the matchers in `base/test/values_test_util.h` — more readable, with better failure messages."}, {"rule": "CSA-052", "prompt": "A new entry in `about_flags.cc` should be available everywhere:\n\n```cpp\n{\"brave-my-feature\", ..., kOsDesktop | kOsAndroid}\n```\n\nWhat should the platform mask be?", "choices": ["Leave it as is — iOS doesn't use `about_flags.cc`", "`kOsDesktop | kOsAndroid | kOsIos`, listed explicitly for clarity", "`kOsAll`", "`kOsDesktop`, with Android registered in a separate entry"], "answer": 2, "explain": "Use `kOsAll` for cross-platform feature flags instead of OR-ing individual platform constants."}, {"rule": "CSA-053", "prompt": "```cpp\n// HACK: skip validation for now\nif (ShouldSkipValidation()) return;\n```\n\nThis works around an upstream race condition and should go away later. What should the reviewer require?", "choices": ["Nothing — the `HACK:` prefix already marks it as temporary", "A `TODO(<brave-browser issue URL>)` explaining its removal", "A `TODO(username)` so people know who owns the hack", "Delete the comment so the code doesn't advertise the workaround"], "answer": 1, "explain": "Temporary workarounds must reference a tracking issue via `TODO(https://github.com/brave/brave-browser/issues/<id>)`, explaining when/why to remove them — otherwise they become permanent debt."}, {"rule": "CSA-053", "prompt": "```cpp\n// FooApi::Connect() relies on the receiver sending Ack messages,\n// but the JS bindings don't implement this protocol. Use an explicit\n// timer instead.\nbase::OneShotTimer idle_timer_;\n```\n\nThis is the intended long-term design. Does it need a tracking-issue TODO?", "choices": ["No — it's a permanent design rationale", "No — but it must be reworded to start with `HACK:`", "Yes — but a `TODO(username)` is enough instead of an issue URL", "Yes — any comment mentioning a limitation needs a tracking issue"], "answer": 0, "explain": "Never require a tracking issue for permanent design decisions. A comment explaining why an alternative wasn't used, when the current code is the long-term solution, is rationale, not a workaround."}, {"rule": "CSA-054", "prompt": "```cpp\nauto* name = dict.FindString(\"display_name\");\nauto* url = dict.FindString(\"endpoint_url\");\n// the same keys are read again in two other functions\n```\n\nWhat should the reviewer suggest?", "choices": ["Named constants like `constexpr char kDisplayName[]`", "`#define DISPLAY_NAME_KEY \"display_name\"` at the top of the file", "Global `const std::string kDisplayName = \"display_name\";` in the header", "Nothing — inline literals keep the key visible right where it's used"], "answer": 0, "explain": "Use named constants for JSON property keys rather than inline literals — prevents typos and eases refactoring."}, {"rule": "CSA-055", "prompt": "```cpp\nstd::string_view BuildUrl(std::string_view host) {\n  std::string url = base::StrCat({\"https://\", host, \"/api\"});\n  return url;\n}\n```\n\nWhat's wrong, and what's the fix?", "choices": ["The view dangles once `url` is destroyed; return `std::string`", "Make `url` a `static` local so the buffer outlives the call", "Nothing — `std::string` converts to `std::string_view` safely", "Return `url.c_str()` so the pointer stays valid after return"], "answer": 0, "explain": "Never return `std::string_view` from a function that builds a string — it points into a destroyed temporary. Return `std::string` (or `std::optional<std::string>`)."}, {"rule": "CSA-056", "prompt": "```cpp\nenum { kBravePolicySource = 10 };\n```\n\nWhat's preferred?", "choices": ["`enum class PolicySource { kBrave = 10 };`", "`#define BRAVE_POLICY_SOURCE 10`", "`const int kBravePolicySource = 10;` declared in the header", "`constexpr int kBravePolicySource = 10;`"], "answer": 3, "explain": "For a single numeric constant, use `constexpr int` — enums are for sets of related values."}, {"rule": "CSA-057", "prompt": "```cpp\nstd::string GetProfileId(const std::string& profile_path);\n```\n\nHow should the parameter be typed?", "choices": ["`std::string_view profile_path`", "`const std::u16string& profile_path` for Windows compatibility", "`const GURL& profile_path` using a `file://` URL", "`const base::FilePath& profile_path`"], "answer": 3, "explain": "File system paths should be `base::FilePath`, not `std::string` — type-safe, simpler call sites, self-documenting."}, {"rule": "CSA-058", "prompt": "```cpp\nenum class SidebarItem {\n  kBookmarks,\n#if BUILDFLAG(ENABLE_BRAVE_TALK)\n  kTalk,\n#endif\n  kHistory,\n};\n```\n\nThese values are persisted to prefs. What's the fix?", "choices": ["Add a `kMaxValue = kHistory` entry at the end of the enum", "Nothing — enum values are resolved at compile time per build", "Change `enum class` to a plain `enum` so values are stable", "Explicit values: `kBookmarks = 0`, `kTalk = 1`, `kHistory = 2`"], "answer": 3, "explain": "When enum members are conditionally compiled out, assign explicit values to the rest so they don't shift and break serialization, persistence or IPC."}, {"rule": "CSA-059", "prompt": "A header declares:\n\n```cpp\nvoid OnSubmitSignedExtrinsic(std::optional<std::string>,\n                             std::optional<std::string>);\n```\n\nWhat should the reviewer request?", "choices": ["Replace the second parameter with an out-parameter to disambiguate", "Name both parameters, matching the `.cc`", "Nothing — the `.cc` definition already names them", "Add a comment above the declaration describing the two arguments"], "answer": 1, "explain": "Always name parameters in header declarations, matching the `.cc` — especially when the types alone are ambiguous."}, {"rule": "CSA-060", "prompt": "```cpp\nstruct ContentSite {\n  std::string name_;\n  int percentage_ = 0;\n};\n```\n\nWhat naming should the fields use?", "choices": ["`m_name` and `m_percentage`", "`name` and `percentage`", "Keep `name_` and `percentage_` — all members use trailing underscores", "`name_` but expose it through a `name()` getter"], "answer": 1, "explain": "Trailing underscores are for class member variables, not plain struct fields."}, {"rule": "CSA-062", "prompt": "New code uses `uint32_t hash = base::Hash(str);`. You think `base::Hash` is deprecated. What's the correct reviewer process?", "choices": ["Flag it — you remember it being deprecated years ago", "Approve if it compiles; deprecated APIs still work until they're removed", "Approve — existing callers use it, so one more use is consistent", "Confirm the notice in its header, then request the replacement"], "answer": 3, "explain": "Never introduce new uses of deprecated APIs — but verify the deprecation notice in the actual header first; never flag based on memory (here, replace with `base::FastHash(base::as_byte_span(str))`)."}, {"rule": "CSA-063", "prompt": "In a header:\n\n```cpp\nstruct TopicArticle {\n  int id;\n  double score;\n  std::string title;\n};\n```\n\nWhat should change?", "choices": ["`int id = 0;` and `double score = 0.0;`", "Wrap `id` and `score` in `std::optional` to mark them unset", "Nothing — callers always set every field before reading it", "Add a constructor that zeroes the struct with `memset`"], "answer": 0, "explain": "POD members in header-declared structs/classes must be explicitly default-initialized; reading an uninitialized POD is undefined behavior."}, {"rule": "CSA-064", "prompt": "```cpp\nstd::string_view GetDomain(const char* env_from_switch);\n```\n\nCallers pass `std::string`s and literals. Best parameter type?", "choices": ["`std::string_view env_from_switch`", "Keep `const char*` and add a `size_t len` parameter", "`std::string env_from_switch` by value", "`const std::string& env_from_switch`"], "answer": 0, "explain": "Prefer `std::string_view` over `const char*` for string parameters — it accepts `std::string`, `const char*` and literals, and carries the size."}, {"rule": "CSA-065", "prompt": "Which `std::string_view` **class member** is safe and should NOT be flagged as a lifetime bug?", "choices": ["`std::string_view host_;` in a long-lived service, set from `url.host()` of a local GURL", "`std::string_view pref_path_;` initialized from `prefs::kMyPref` (`inline constexpr char[]`)", "`std::string_view name_;` in a singleton, set from a `GetUserName()` `std::string` return", "`Config(std::string_view name) : name_(name) {}` where callers may pass temporaries"], "answer": 1, "explain": "`string_view` members are dangerous in general, but those initialized from static-lifetime data (pref-key constants, string literals, `kFeatureName`) are safe. Check the initializer before flagging."}, {"rule": "CSA-066", "prompt": "```cpp\nstd::deque<Request> pending_;\nstd::stack<Frame> history_;\n```\n\nWhat should these be?", "choices": ["`std::vector<Request>` (erasing from the front) and `std::stack<Frame>`", "`std::list<Request>` and `std::vector<Frame>`", "`base::circular_deque<Request>` and `base::stack<Frame>`", "Keep them — they're standard containers with well-known behavior"], "answer": 2, "explain": "Use `base::circular_deque` / `base::queue` / `base::stack` instead of the std versions — consistent memory use across platforms and smaller code size."}, {"rule": "CSA-067", "prompt": "```cpp\nint count = static_cast<int>(vec.size());\nfor (int i = 0; i < static_cast<int>(vec.size()); ++i) { ... }\n```\n\nWhat type should `count` and `i` be?", "choices": ["Keep `int`, but use `base::checked_cast<int>` instead of `static_cast`", "`size_t`", "`int64_t`, to avoid any overflow", "`uint32_t`, which is enough and smaller"], "answer": 1, "explain": "Use `size_t` for sizes, counts, offsets and indices — it avoids needless casts against STL APIs. Public APIs use `size_t` even if internals use `uint32_t`."}, {"rule": "CSA-068", "prompt": "```cpp\nbase::flat_map<std::string, int> map;\n// hot path:\nint val = map[\"key\"];\n```\n\nHow should the lookup be written?", "choices": ["Switch to `std::map` so lookups don't allocate", "`auto it = map.find(\"key\");`", "`int val = map.at(std::string(\"key\"));`", "`static const std::string kKey = \"key\"; int val = map[kKey];`"], "answer": 1, "explain": "`base::flat_map`/`flat_set` support transparent comparison: `find()` with `std::string_view` or `const char*` avoids building a temporary `std::string`; `operator[]` doesn't."}, {"rule": "CSA-069", "prompt": "```cpp\nstd::vector<uint8_t> data = GetBytes();\nbase::ReadUnicodeCharacter(\n    reinterpret_cast<const char*>(data.data()), &i, &code_point);\n```\n\n`ReadUnicodeCharacter` now takes a `std::string_view`. What's the issue?", "choices": ["None — `data.data()` is contiguous, so the conversion is safe", "Use `static_cast` instead of `reinterpret_cast` for the pointer", "Hidden `strlen()` on non-null-terminated data; use `base::as_string_view(data)`", "`std::string_view(reinterpret_cast<const char*>(data.data()))` makes it explicit"], "answer": 2, "explain": "When building a `string_view` from byte buffers, always pass the size: implicit `const char*` conversion runs `strlen()`, which is UB on non-null-terminated data."}, {"rule": "CSA-070", "prompt": "A Rust → C++ cxx bridge for logging:\n\n```rust\nunsafe extern \"C++\" {\n    fn log_event(name: &CxxString);\n}\n```\n\nC++ only reads the name for logging. Better type?", "choices": ["`fn log_event(name: Box<Vec<u8>>);` for zero-copy", "Keep `&CxxString` — it's the native C++ string type", "`fn log_event(name: String);` so C++ owns the text", "`fn log_event(name: &str);` (maps to `rust::Str`)"], "answer": 3, "explain": "For read-only text across FFI, use `&str` / `rust::Str` — a zero-copy borrow. `&CxxString` forces C++ container overhead for a mere borrow."}, {"rule": "CSA-070", "prompt": "```cpp\nclass Reporter {\n  rust::String last_report_;\n};\nvoid Reporter::Refresh() { last_report_ = ffi::build_report(); }\n```\n\nWhat should the reviewer request?", "choices": ["Deep-copy into a `std::string` member at the boundary", "Store a `rust::Str` view instead to avoid any copies", "Switch `build_report()` to return `&str` so C++ can keep the reference", "Nothing — `rust::String` is a fine member type for owned text"], "answer": 0, "explain": "Never store `rust::String` as a class member — it ties the class to Rust's allocator and bridge layout. Deep-copy into `std::string` to keep text past the FFI call."}, {"rule": "CSA-071", "prompt": "Cross-platform UI code:\n\n```cpp\nstd::wstring title = L\"Brave\";\n```\n\nWhat should it be?", "choices": ["Fine — `wchar_t` is 16-bit, which matches Chromium's UTF-16", "`std::u16string title = u\"Brave\";`", "`std::basic_string<uint16_t> title = {'B','r','a','v','e'};`", "`std::wstring title = u\"Brave\";` with the UTF-16 literal prefix"], "answer": 1, "explain": "Chromium uses UTF-16 via `std::u16string`/`char16_t*` and `u\"...\"` literals. `std::wstring`/`wchar_t*` are only for Windows-only code."}, {"rule": "CSA-071", "prompt": "You need a bullet character (U+2022) in a `std::u16string`. Which literal is correct?", "choices": ["`u\"\\U2022\"`", "`u\"\\xe2\\x80\\xa2\"`", "`base::UTF8ToUTF16(\"\\xe2\\x80\\xa2\")` stored alongside the UTF-8 form", "`u\"\\u2022\"`"], "answer": 3, "explain": "For non-ASCII in UTF-16 literals use the literal character or a `\\uXXXX`/`\\UXXXXXXXX` escape — never `\\xXX` byte escapes, which silently produce wrong code units."}, {"rule": "BS-014", "prompt": "You're reviewing a header where a 6-line block is guarded like this:\n\n```cpp\n#if BUILDFLAG(ENABLE_SPELLCHECK)\n#include \"components/spellcheck/common/spellcheck_features.h\"\n// ... five more lines ...\n#endif\n```\n\nWhat should the closing line look like?", "choices": ["`#endif  // end of block`", "`#endif  // BUILDFLAG(ENABLE_SPELLCHECK)`", "`#endif` with no comment — the matching `#if` is easy to find", "`#endif ENABLE_SPELLCHECK`"], "answer": 1, "explain": "Annotate `#endif` with the condition it closes, e.g. `#endif  // BUILDFLAG(ENABLE_SPELLCHECK)`, so readers know what's ending."}, {"rule": "BS-034", "prompt": "A PR adds this to a `.cc` file:\n\n```cpp\n#include \"content/public/browser/web_contents.h\"\n// ...\n#if BUILDFLAG(ENABLE_AI_CHAT)\n  SearchTabsByContent(web_contents);\n#endif\n```\n\nA reviewer asks for the `web_contents.h` include to be moved inside the `#if`. What's the right call?", "choices": ["Leave it unconditional: `web_contents.h` is always built", "Move it inside the guard: an include should always sit next to the code that uses it", "Move it inside a new `#if BUILDFLAG(ENABLE_WEB_CONTENTS)` guard", "Replace the include with a forward declaration inside the guard"], "answer": 0, "explain": "Guard an include only when the header itself is GN-gated. Always-built headers like `web_contents.h` stay unconditional even if only used inside a guard, and never invent buildflag names."}, {"rule": "BS-034", "prompt": "```cpp\n#include \"chrome/browser/extensions/extension_web_ui.h\"\n// ...\n#if BUILDFLAG(ENABLE_EXTENSIONS)\n  IsChromeURLOverridden(...);\n#endif\n```\n\n`extension_web_ui.h` is only in GN `sources` when `enable_extensions` is set. What happens and what's the fix?", "choices": ["It breaks builds with extensions off; move the include inside the `#if`", "Wrap the include in `#ifdef ENABLE_EXTENSIONS`", "Add a forward declaration of `IsChromeURLOverridden` instead", "Nothing — an unused include is harmless in any build configuration, so leave it"], "answer": 0, "explain": "When a header is gated in GN, it doesn't exist in the disabled config, so its include must sit inside the same `#if BUILDFLAG(...)` block."}, {"rule": "BS-035", "prompt": "Right after the regular includes of a file you see:\n\n```cpp\n#if BUILDFLAG(ENABLE_BRAVE_REWARDS)\n#include \"brave/components/brave_rewards/core/buildflags/buildflags.h\"\n#endif\n\n#if BUILDFLAG(ENABLE_BRAVE_REWARDS)\nnamespace rewards { ... }\n#endif\n```\n\nThis is the only guarded block in the file. What should the reviewer suggest?", "choices": ["Convert the second guard to a runtime `base::FeatureList` check", "Remove the guard around the include and keep the one around the namespace", "Merge them into a single `#if BUILDFLAG(ENABLE_BRAVE_REWARDS)` block", "Keep both: includes and code must always have separate guards"], "answer": 2, "explain": "Consecutive regions with the same `#if BUILDFLAG(...)` condition should be one guard block — allowed for an include when it's the single guarded block right after the regular includes."}, {"rule": "BS-035", "prompt": "A file has guarded code for two different flags, each needing its own guarded include. Which layout is correct?", "choices": ["Rewards include + code in one block, then Ads include + code in a second block", "Guarded includes grouped at the top; each code block in its own guard below", "One block per flag, but put the Ads block first so its include comes earlier", "A single `#if BUILDFLAG(ENABLE_BRAVE_REWARDS) && BUILDFLAG(ENABLE_BRAVE_ADS)` around everything"], "answer": 1, "explain": "Includes always come first. Merging each include into its code block would put the second include after code (e.g. after a `namespace {...}`), so keep guarded includes grouped at the top."}, {"rule": "BS-045", "prompt": "In which situation is it acceptable to **omit** the `#endif  // BUILDFLAG(...)` comment?", "choices": ["A 1–2 line, unambiguous block in a file that doesn't use them", "A short block nested inside another `#if` block", "A 5-line block that is obvious from context", "A 2-line block in a file where every other `#endif` is commented"], "answer": 0, "explain": "Always comment `#endif` for blocks longer than 3 lines, nested blocks, or when surrounding code already does; only short (1–2 line), unambiguous blocks may skip it."}, {"rule": "BS-049", "prompt": "You're introducing `enable_brave_wallet` as a build flag. What should go into the public header `brave/components/brave_wallet/browser/brave_wallet_service.h`?", "choices": ["Add `#error` in every `.cc` that includes the header", "Wrap the whole header body in `#if BUILDFLAG(ENABLE_BRAVE_WALLET)` ... `#endif`", "Nothing — the GN `sources` gating already keeps the header out of other builds", "`static_assert(BUILDFLAG(ENABLE_BRAVE_WALLET));` with the buildflags include"], "answer": 3, "explain": "A `static_assert(BUILDFLAG(...))` in public headers catches accidental inclusion when the feature is disabled."}, {"rule": "BS-051", "prompt": "```cpp\n#if BUILDFLAG(ENABLE_BRAVE_AI_CHAT)\n#include \"brave/browser/ai_chat/tools/history_tool.h\"\n#endif\n\nclass HistoryTool;  // used only in AI-chat code below\n```\n\nA reviewer asks to wrap `class HistoryTool;` in the same buildflag guard. Best response?", "choices": ["Agreed — every symbol tied to the feature must be guarded, including declarations", "Replace the forward declaration with an unconditional include instead", "Move the forward declaration inside the guarded include block", "Not needed: only includes and actual usages need guards"], "answer": 3, "explain": "Never require `BUILDFLAG` guards for forward declarations — they pull in no dependencies. Guard the `#include` and the actual usage."}, {"rule": "BS-054", "prompt": "`brave/components/foo/foo_impl.cc` is only in `sources` inside `if (enable_foo)` in BUILD.gn. It contains:\n\n```cpp\n#include \"brave/components/foo/common/buildflags/buildflags.h\"\n\n#if BUILDFLAG(ENABLE_FOO)\nvoid DoFoo() { ... }\n#endif\n```\n\nWhat should the reviewer say?", "choices": ["Fine — double-checking the flag is a cheap safety net", "Replace the `#if` with `static_assert(BUILDFLAG(ENABLE_FOO));` in this `.cc`", "Drop the buildflag include and the `#if`; they're redundant", "Also remove the `if (enable_foo)` gating in BUILD.gn so the guard does the work"], "answer": 2, "explain": "A file already gated in BUILD.gn shouldn't re-check its own enable flag — it's redundant and misleading. `static_assert` safety nets are for public headers, not implementation files."}, {"rule": "BS-054", "prompt": "`foo_service.cc` is only compiled when `enable_foo = true`. It includes `foo/common/buildflags/buildflags.h` solely to read `BUILDFLAG(FOO_API_ENDPOINT)`, a URL passed in from GN. Is that include OK?", "choices": ["Only if it also wraps the usage in `#if BUILDFLAG(ENABLE_FOO)` to be safe", "Yes — reading other GN-passed values is a valid reason", "No — hardcode the URL instead since the file is already gated", "No — conditionally compiled files must never include buildflag headers"], "answer": 1, "explain": "The no-include rule covers only re-checking the enable/disable flag that already gates the file. Including the buildflag header to read other parameters is expected."}, {"rule": "CSM-003", "prompt": "You're reviewing this initialization code:\n\n```cpp\nvoid MyService::Init() {\n  predictor_ = new BandwidthSavingsPredictor(extractor_);\n}\nMyService::~MyService() { delete predictor_; }\n```\n\nWhat should the reviewer ask for?", "choices": ["Keep it — the destructor already deletes the pointer, so nothing leaks", "Wrap it in a `std::shared_ptr` so ownership stays safe if the service is ever copied", "Use a `std::unique_ptr` (via `std::make_unique`) instead of manual new/delete", "Store it as a `raw_ptr<>` so any dangling use is detected at runtime"], "answer": 2, "explain": "Avoid manual `new`/`delete`. Use `std::unique_ptr`, stack variables, or member initializer lists like `predictor_(std::make_unique<...>(extractor))`."}, {"rule": "CSM-004", "prompt": "A class receives a `PrefService*` from its factory; the `PrefService` is owned by the profile. A teammate stores it as `std::unique_ptr<PrefService> prefs_` \"to be safe\". What's the right review comment?", "choices": ["Don't wrap an unowned resource in an ownership type; it will double free", "Fine, as long as `prefs_` is declared last so it's destroyed first", "Use `std::shared_ptr` instead so the profile and the class can share it", "Fine, but call `prefs_.release()` in the destructor to avoid a double delete"], "answer": 0, "explain": "If a class doesn't own a resource, don't create ownership wrappers for it — doing so is a common source of crashes."}, {"rule": "CSM-005", "prompt": "Two objects need to share ownership of a cache. A teammate writes:\n\n```cpp\nstd::shared_ptr<Cache> cache_;\n```\n\nWhat's the best response?", "choices": ["Approve; `std::shared_ptr` is the standard C++ tool for shared ownership of a cache", "Approve only if `std::make_shared` constructs it, so the control block is co-allocated", "Replace with `std::weak_ptr` on both sides so neither object keeps the cache alive", "`std::shared_ptr` is banned; use unique ownership, or `scoped_refptr` if truly needed"], "answer": 3, "explain": "`std::shared_ptr` is on Chromium's banned features list. Prefer unique ownership; use `base::RefCounted` / `scoped_refptr` only when shared ownership is truly needed."}, {"rule": "CSM-006", "prompt": "Which `Shutdown()` implementation follows the standard for a class with a `weak_factory_` and pending async callbacks?", "choices": ["```cpp\nvoid MyClass::Shutdown() {\n  CleanupResources();\n}\n```", "```cpp\nvoid MyClass::Shutdown() {\n  weak_factory_.InvalidateWeakPtrs();\n  CleanupResources();\n}\n```", "```cpp\nvoid MyClass::Shutdown() {\n  CleanupResources();\n  weak_factory_.InvalidateWeakPtrs();\n}\n```", "Nothing is needed; the `WeakPtrFactory` destructor handles it"], "answer": 1, "explain": "Call `weak_factory_.InvalidateWeakPtrs()` at the *start* of shutdown, otherwise pending callbacks can fire on a partially-destroyed object."}, {"rule": "CSM-007", "prompt": "An async completion handler looks like this, where `request_` is a `base::WeakPtr<Request>`:\n\n```cpp\nvoid OnCallback() {\n  request_->Complete(result);\n}\n```\n\nWhat should the reviewer request?", "choices": ["Replace the WeakPtr with `base::Unretained`, since the request outlives the callback", "Nothing; WeakPtr dereferences are automatically no-ops when invalidated", "Add `DCHECK_CALLED_ON_VALID_SEQUENCE` and an early `if (!request_) return;`", "Wrap the call in a try/catch so an invalid pointer can't crash the process"], "answer": 2, "explain": "Always check a `base::WeakPtr` is valid before dereferencing, especially after async operations, and add thread checkers to methods using WeakPtrs."}, {"rule": "CSM-008", "prompt": "A new class needs to hand out weak pointers to itself. Which declaration follows the standard?", "choices": ["`class MyClass : public base::SupportsWeakPtr<MyClass> {};`", "`class MyClass { std::weak_ptr<MyClass> self_; };`", "`class MyClass { base::WeakPtrFactory<MyClass> weak_factory_{this}; };` as the first member", "`class MyClass { base::WeakPtrFactory<MyClass> weak_factory_{this}; };` as the last member"], "answer": 3, "explain": "Use a `base::WeakPtrFactory<T>` member (declared last) instead of inheriting `base::SupportsWeakPtr<T>`; the factory performs more safety checks."}, {"rule": "CSM-009", "prompt": "Reviewing this async call:\n\n```cpp\nauto weak_this = weak_ptr_factory_.GetWeakPtr();\nrpc_->GetNetworkName(base::BindOnce(\n    [](base::WeakPtr<MyService> self, Callback cb,\n       const std::string& name) {\n      if (!self) return;\n      std::move(cb).Run(name);\n    }, weak_this, std::move(callback)));\n```\n\nWhat's the preferred fix?", "choices": ["Bind a member method directly: `BindOnce(&MyService::OnGetNetworkName, weak_this, ...)`", "Capture `this` in the lambda instead of a WeakPtr, since the service owns `rpc_`", "Keep it — the lambda's `if (!self)` check already makes it safe and readable", "Bind `base::Unretained(this)` into the lambda instead, saving the null check entirely"], "answer": 0, "explain": "With WeakPtrs in async callbacks, bind to a member function so the call is auto-cancelled if the WeakPtr is invalid; don't capture the WeakPtr in a lambda."}, {"rule": "CSM-010", "prompt": "A teammate needs to run a blocking file read and then update UI state:\n\n```cpp\nbase::ThreadPool::PostTask(\n    FROM_HERE,\n    base::BindOnce(&MyClass::ReadAndUpdate, base::Unretained(this)));\n```\n\nWhat should the reviewer suggest?", "choices": ["Switch to `base::BindRepeating` so the task can be retried if the read fails", "Keep `Unretained` but add a `SEQUENCE_CHECKER` to `ReadAndUpdate` to catch misuse", "Capture a raw `this` in a lambda instead, since `Unretained` is just a wrapper for it", "Post a static blocking function with `PostTaskAndReplyWithResult`; reply via a WeakPtr"], "answer": 3, "explain": "Never use `base::Unretained` when posting to thread pools — it leads to use-after-free. Run the blocking work on the pool and handle the result on the main thread via `PostTaskAndReplyWithResult` with a WeakPtr."}, {"rule": "CSM-011", "prompt": "A class owns a `base::RepeatingTimer timer_` and starts it like this:\n\n```cpp\ntimer_.Start(FROM_HERE, delay,\n    base::BindRepeating(&MyClass::OnTimer,\n                        weak_factory_.GetWeakPtr()));\n```\n\nA reviewer is deciding what to comment. What's appropriate?", "choices": ["Flag it as a bug: owned timers must use `base::Unretained(this)`, never a WeakPtr", "At most a nit that `Unretained(this)` is preferred for an owned timer; not a bug", "Flag it as a bug: owned timers can fire after destruction, so add `InvalidateWeakPtrs()`", "Require `base::ThreadPool::PostDelayedTask` instead, so the timer isn't needed"], "answer": 1, "explain": "For a self-owned timer, `base::Unretained(this)` is preferred because the timer dies with the class. Using a WeakPtr is just overhead — a style preference, never a correctness bug, and never insist on changing it."}, {"rule": "CSM-012", "prompt": "A class owns `mojo::Remote<mojom::Foo> remote_` and sets:\n\n```cpp\nremote_.set_disconnect_handler(\n    base::BindOnce(&MyClass::OnDisconnect,\n                   base::Unretained(this)));\n```\n\nAn automated review bot flags `base::Unretained` here as a potential UaF. Your call?", "choices": ["Agree; Mojo disconnect handlers must always bind a WeakPtr, even when owned", "Agree; bind `base::DoNothing()` and poll `is_connected()` instead", "Disagree; `this` owns the endpoint, so it can't fire after destruction", "Agree; move the remote into a `std::unique_ptr` so its lifetime is explicit"], "answer": 2, "explain": "`base::Unretained(this)` in disconnect/error handlers is safe when the class owns the `mojo::Remote`/`Receiver`/`AssociatedRemote` — the endpoint is destroyed with the class."}, {"rule": "CSM-013", "prompt": "Which member ordering follows the standard?", "choices": ["```cpp\nclass MyService {\n  raw_ptr<PrefService> prefs_;\n  std::unique_ptr<Fetcher> fetcher_;\n  raw_ptr<ProfileManager> profile_manager_;\n};\n```", "```cpp\nclass MyService {\n  raw_ptr<PrefService> prefs_;\n  raw_ptr<ProfileManager> profile_manager_;\n  std::unique_ptr<Fetcher> fetcher_;\n};\n```", "Ordering doesn't matter as long as members are alphabetized", "```cpp\nclass MyService {\n  std::unique_ptr<Fetcher> fetcher_;\n  raw_ptr<PrefService> prefs_;\n  raw_ptr<ProfileManager> profile_manager_;\n};\n```"], "answer": 3, "explain": "Place owning members (like `std::unique_ptr<>`) first and unowned `raw_ptr<>` members after them; it follows Chromium convention and makes ownership visually clear."}, {"rule": "CSM-014", "prompt": "You need to act on a set of tabs after an async fetch completes. You currently have `std::vector<raw_ptr<Tab>> tabs`. What should you bind into the callback?", "choices": ["`std::move(tabs)` — `raw_ptr` detects dangling pointers, so binding it is safe", "A `std::vector<base::WeakPtr<Tab>>` built from each tab's `GetWeakPtr()`", "A `std::vector<Tab*>`, avoiding `raw_ptr` overhead inside the callback", "A `base::span<raw_ptr<Tab>>` over the vector, so nothing is copied"], "answer": 1, "explain": "Never capture `std::vector<raw_ptr<T>>` in async callbacks — the pointers may dangle by the time it runs. Bind a `std::vector<base::WeakPtr<T>>` instead."}, {"rule": "CSM-015", "prompt": "A single-threaded class has a `SEQUENCE_CHECKER(sequence_checker_)`, but only 2 of its 10 methods call `DCHECK_CALLED_ON_VALID_SEQUENCE`. Best review comment?", "choices": ["Apply the check to all methods or drop the checker; partial checking misleads", "Fine; only the methods that touch shared state need the sequence check", "Replace the checker with a `base::Lock` so every method is protected, not just two", "Move the two checked methods into a separate class with its own checker"], "answer": 0, "explain": "Use `SEQUENCE_CHECKER` consistently — all methods or none. Partial checking is misleading and makes correct code look unsafe."}, {"rule": "CSM-016", "prompt": "A `KeyedService` owns a fetcher and a database handle, and releases them only in its destructor. What's the guidance?", "choices": ["That's correct; the destructor is the idiomatic RAII place for this cleanup", "Move cleanup to a static `atexit` handler so it runs after all services", "Release them in `Shutdown()` too, for orderly service-graph teardown", "Release them lazily on first use after shutdown has been signalled"], "answer": 2, "explain": "For `KeyedService`s, clean up owned resources in `Shutdown()`, not just the destructor — the service graph has dependencies that require orderly teardown."}, {"rule": "CSM-017", "prompt": "A `KeyedService` observes prefs via a `PrefChangeRegistrar` member and another source via `base::ScopedObservation`. Its `Shutdown()` is empty. A teammate says \"ScopedObservation unsubscribes automatically, so we're fine.\" Response?", "choices": ["Agreed; ScopedObservation and the registrar both clean up in the destructor, which is enough", "Agreed, but add a DCHECK in the destructor that no observers remain registered", "Replace ScopedObservation with manual `AddObserver` calls in the constructor only", "Call `pref_change_registrar_.RemoveAll()` and `observation_.Reset()` in `Shutdown()`"], "answer": 3, "explain": "`ScopedObservation` can still lead to UaF: other services can trigger callbacks during their shutdown after yours. Always explicitly unsubscribe observers and pref registrars in `KeyedService::Shutdown()`."}, {"rule": "CSM-018", "prompt": "You're adding a service under `components/` that needs prefs and network access. Which constructor follows the standard?", "choices": ["`MyFeatureService(content::BrowserContext* context, scoped_refptr<network::SharedURLLoaderFactory> factory);`", "`MyFeatureService(PrefService* prefs, scoped_refptr<network::SharedURLLoaderFactory> factory);`", "`MyFeatureService(Profile* profile, scoped_refptr<network::SharedURLLoaderFactory> factory);`", "`MyFeatureService(content::WebContents* web_contents, PrefService* prefs);`"], "answer": 1, "explain": "Component services should take specific dependencies like `PrefService*` and a URL loader factory, not `BrowserContext` — that prevents iOS reuse and adds content-layer dependencies."}, {"rule": "CSM-019", "prompt": "A method `OnDataLoaded()` is only ever invoked via `base::BindOnce(&MyClass::OnDataLoaded, weak_factory_.GetWeakPtr())`. What should it contain to follow the standard?", "choices": ["A `DCHECK_CALLED_ON_VALID_SEQUENCE(sequence_checker_)` at the top", "A `base::AutoLock` around the whole body, since callbacks may run concurrently", "Nothing extra; `BindOnce` with a WeakPtr already guarantees the right sequence", "A `CHECK(this)` at the top to catch an invalidated WeakPtr"], "answer": 0, "explain": "Methods used as `base::BindOnce` / `base::BindRepeating` targets should include `DCHECK_CALLED_ON_VALID_SEQUENCE` to ensure they run on the correct thread."}, {"rule": "CSM-020", "prompt": "A teammate adds this at file scope:\n\n```cpp\nstatic const std::map<std::string, int> kMyLookup = {\n    {\"foo\", 1}, {\"bar\", 2}};\n```\n\nWhat's the right fix?", "choices": ["Make it `inline` instead of `static` so there's one copy across TUs", "It's fine because it's `const`, so it's initialized at compile time", "Return a function-local `static const base::NoDestructor<std::map<...>>`", "Allocate it with `new` and never delete it, avoiding exit-time destructors"], "answer": 2, "explain": "Chromium prohibits globals with non-trivial destructors. Use `base::NoDestructor` as a function-local static (or `constexpr` for simple arrays/values)."}, {"rule": "CSM-021", "prompt": "`ContentScraper::Process()` does blocking work and is used from the UI thread. Callers currently each post manually to the thread pool and bind weak pointers. What does the standard suggest?", "choices": ["Make `Process()` run synchronously on the UI thread with `ScopedAllowBlocking`", "Make `ContentScraper` ref-counted (`RefCountedThreadSafe`) so it can be shared across threads", "Use `base::Unretained` for all the posted tasks, since the scraper outlives them", "Hold a `base::SequenceBound<ContentScraper>` and use `AsyncCall(&ContentScraper::Process)`"], "answer": 3, "explain": "For blocking/IO classes accessed asynchronously from the UI thread, use `base::SequenceBound<T>`: it binds the object to a task runner and posts all calls there automatically."}, {"rule": "CSM-022", "prompt": "Which thread-pool post follows the standard for non-urgent work that can safely be abandoned at shutdown?", "choices": ["`base::ThreadPool::PostTask(FROM_HERE, {base::MayBlock(), base::TaskPriority::BEST_EFFORT}, task);`", "`base::ThreadPool::PostTask(FROM_HERE, {base::MayBlock(), base::TaskPriority::BEST_EFFORT, base::TaskShutdownBehavior::SKIP_ON_SHUTDOWN}, task);`", "`base::ThreadPool::PostTask(FROM_HERE, {base::MayBlock(), base::TaskPriority::BEST_EFFORT, base::TaskShutdownBehavior::BLOCK_SHUTDOWN}, task);`", "`base::ThreadPool::PostTask(FROM_HERE, {base::MayBlock(), base::TaskPriority::USER_BLOCKING, base::TaskShutdownBehavior::SKIP_ON_SHUTDOWN}, task);`"], "answer": 1, "explain": "Explicitly specify `base::TaskPriority` and shutdown behavior instead of relying on defaults — `BEST_EFFORT` for non-urgent work, `SKIP_ON_SHUTDOWN` when it can be abandoned."}, {"rule": "CSM-023", "prompt": "New code needs to encrypt a token before storing it. A teammate writes `OSCrypt::EncryptString(plaintext, &ciphertext);`. What's the review feedback?", "choices": ["Fine, as long as it's called off the UI thread, since it may block on the keychain", "Use the async OSCrypt interface (`os_crypt_async`); the sync one is deprecated", "Wrap it in `base::ThreadPool::PostTask` so encryption never blocks the UI", "Store the token in plain prefs instead; prefs are already protected by the OS"], "answer": 1, "explain": "New code must use the async OSCrypt interface; the legacy synchronous `OSCrypt` interface is deprecated."}, {"rule": "CSM-024", "prompt": "A component-level `DefaultBrowserMonitor` needs platform-specific \"is default browser?\" logic. Which design does the standard prefer?", "choices": ["Store a `base::RepeatingCallback<bool()> is_default_browser_callback_` passed in by the platform layer", "Add `#if BUILDFLAG(IS_WIN)` / `IS_MAC` blocks directly in the component class", "A nested `Delegate` interface (`virtual bool IsDefaultBrowser() = 0;`) owned via `std::unique_ptr`", "Have the component include the browser-layer shell-integration header directly"], "answer": 2, "explain": "For cross-layer platform behavior, use a dedicated delegate class rather than raw callbacks — cleaner interfaces, safer lifetimes, and better testability."}, {"rule": "CSM-025", "prompt": "Reviewing:\n\n```cpp\nremote_.set_disconnect_handler(\n    base::BindOnce(&MyClass::OnDisconnect,\n                   base::Unretained(this)));\nvoid MyClass::OnDisconnect() { remote_.reset(); }\n```\n\nWhat's the best suggestion?", "choices": ["Replace with `remote_.reset_on_disconnect();`", "Replace `base::Unretained(this)` with a WeakPtr — it's a UaF", "Call `remote_.reset()` in the destructor too", "No change; this is the idiomatic pattern"], "answer": 0, "explain": "When the disconnect handler only resets the remote, use the built-in `remote.reset_on_disconnect()` instead of a manual handler."}, {"rule": "CSM-026", "prompt": "A feature needs to remember a list of tabs to close later. Which member type is preferred?", "choices": ["`std::vector<content::WebContents*> tabs_to_close_;`", "`std::vector<raw_ptr<content::WebContents>> tabs_to_close_;`", "`std::vector<std::string> tabs_to_close_;` holding each tab's URL", "`std::vector<tabs::TabHandle> tabs_to_close_;`"], "answer": 3, "explain": "Store `tabs::TabHandle`s (integer IDs) rather than `WebContents*`; raw pointers can dangle and be reused for a different allocation, but handles can't accidentally point to a different tab."}, {"rule": "CSM-027", "prompt": "A new mojom method lets the renderer-hosted WebUI ask the browser to fetch data: `FetchResource(url.mojom.Url url)`. The browser only ever needs to fetch from three known endpoints. What should the reviewer suggest?", "choices": ["Add a doc comment stating that the URL must be validated by the browser", "Restrict the input to an enum/allowlist of the known endpoints", "Accept the URL as a `string` instead of `url.mojom.Url` and parse it browser-side", "Nothing; the browser process is trusted, so fetching any URL is fine"], "answer": 1, "explain": "Mojom interfaces taking URLs from less-privileged processes should consider an allowlist or enum — an unrestricted URL lets the renderer send requests to any endpoint."}, {"rule": "CSM-027", "prompt": "A mojom method accepts a URL from the renderer, and the browser-side implementation already filters it against an allowlist downstream. Nearby similar methods have no URL-validation comments. Should the reviewer request a doc comment about URL validation?", "choices": ["Yes; every URL parameter in a mojom interface must document its validation", "Yes, and also require a second validation step in the mojom traits", "No; it's validated downstream and nearby code has no such comments", "No, but require converting the parameter to a string to avoid parsing bugs"], "answer": 2, "explain": "Never request URL-validation doc comments if the implementation already validates downstream; check surrounding code first, or you introduce inconsistency and verbosity."}, {"rule": "CSM-028", "prompt": "`service->ForEach()` takes a `base::FunctionRef<void(Item&)>`. A test just wants to iterate without doing anything. Which compiles and follows the standard?", "choices": ["`service->ForEach(base::DoNothing());`", "`service->ForEach([](Item&) {});`", "`service->ForEach(base::NullCallback());`", "`service->ForEach(nullptr);`"], "answer": 1, "explain": "`base::DoNothing()` doesn't match `base::FunctionRef<void(T&)>` signatures; use an explicit no-op lambda instead."}, {"rule": "CSM-029", "prompt": "Reviewing:\n\n```cpp\nif (!task_id_.is_null()) {\n  actor_service_->GetTask(task_id_)->Pause(false);\n}\n```\n\nWhat should the reviewer say?", "choices": ["Fine — a non-null ID guarantees the task still exists in the service", "Wrap `actor_service_` in a WeakPtr, since the service may be destroyed first", "Add `DCHECK(task_id_)` before the call to document the invariant", "Null-check `GetTask()`'s result before calling `Pause()`; it may be gone"], "answer": 3, "explain": "Always null-check return values from methods that can return nullptr — a valid ID doesn't guarantee the lookup succeeds. When chaining `a->GetB()->DoC()`, store and check the intermediate."}, {"rule": "CSM-030", "prompt": "Reviewing:\n\n```cpp\nif (auto result = ParseEvent(params, std::move(model_key))) {\n  callback.Run(std::move(*result));\n}\n// ... later in the same function ...\ncallback.Run(GenerationResultData(std::move(event), model_key));\n```\n\nWhat's the problem?", "choices": ["`model_key` is used after move; don't move it (pass by const ref)", "Nothing — the move is inside an `if`, so it only matters on one branch", "`std::move(*result)` should be `result.value()` to avoid UB on empty optionals", "`callback` should be `std::move`d into `Run()` to avoid a copy"], "answer": 0, "explain": "Never use a variable after `std::move()` — it's in a valid but unspecified state. This applies even when the move is inside a branch."}, {"rule": "CSM-031", "prompt": "Which signature follows the standard for a function that inspects a `Foo` without changing ownership and that requires a non-null value?", "choices": ["`void Process(const std::unique_ptr<Foo>& foo);`", "`void Process(const scoped_refptr<Foo>& foo);`", "`void Process(Foo& foo);`", "`void Process(std::unique_ptr<Foo> foo);`"], "answer": 2, "explain": "Don't pass smart pointers by const reference — it forces heap allocation and couples callers to an ownership model. Use `T*` or `T&` (when non-null is required)."}, {"rule": "CSM-032", "prompt": "A teammate makes a class `base::RefCountedThreadSafe` because it's accessed from two threads and they're unsure who should delete it. What's the guidance?", "choices": ["Good choice; thread-safe refcounting removes lifetime concerns across both threads", "Use `std::shared_ptr` instead; its atomic refcount is the standard C++ equivalent", "Redesign for single ownership; if refcounting is truly needed, keep it on one sequence", "Make it a leaky global singleton (`base::NoDestructor`) so it's never deleted mid-use"], "answer": 2, "explain": "Refcounting makes ownership and destruction order hard to reason about, especially across threads. Prefer a redesign with single ownership; otherwise pin to one sequence, proxy via `PostTask()`, and use `WeakPtr` binds."}, {"rule": "CSM-033", "prompt": "A class caches a pref dict for later use:\n\n```cpp\ndict_ = &pref_service_->GetDict(kMyPref);  // const base::Value::Dict*\n```\n\nWhat should it do instead?", "choices": ["Store it as a `raw_ptr<const base::Value::Dict>` for UaF detection", "Store a `.Clone()` of the dict by value, or read it inline when needed", "Store it as a `const base::Value::Dict&` member bound in the constructor", "It's fine — the `PrefService` outlives this class, so the pointer stays valid"], "answer": 1, "explain": "Never hold pointers to a `base::Value` returned from `PrefService` — it dangles when the pref updates or the service is destroyed. Clone it for longer-lived use, or use it inline."}, {"rule": "CSM-034", "prompt": "`map_` holds `std::string_view` keys pointing into strings stored in `strings_`. Which declaration order is safe?", "choices": ["```cpp\nclass NameTable {\n  std::deque<std::string> strings_;\n  base::flat_map<std::string_view, NameId> map_;\n};\n```", "```cpp\nclass NameTable {\n  base::flat_map<std::string_view, NameId> map_;\n  std::deque<std::string> strings_;\n};\n```", "Either; destruction order of members is unspecified", "Either, as long as the destructor calls `map_.clear()` first"], "answer": 0, "explain": "Members are destroyed in reverse declaration order, so declare the depended-upon member (`strings_`) first; it is then destroyed last."}, {"rule": "CSM-035", "prompt": "Sequence-aware code needs per-sequence cached state. A teammate adds `thread_local std::string cache;`. What's the guidance?", "choices": ["Fine — `thread_local` is the C++ standard tool, and a sequence maps to one thread", "Wrap it in `base::NoDestructor` and keep `thread_local`, which avoids exit-time destructors", "Use `thread_local raw_ptr<std::string>`, since a pointer is trivially destructible", "Use `base::SequenceLocalStorageSlot`; `thread_local` needs trivially destructible types"], "answer": 3, "explain": "Prefer `base::SequenceLocalStorageSlot` for sequence-aware code. `thread_local` requires trivially destructible types (not `raw_ptr`), no `COMPONENT_EXPORT`, and `ABSL_CONST_INIT` at namespace/class scope."}, {"rule": "CSM-036", "prompt": "A class must always hold a valid, never-changing reference to its `BrowserWindowInterface`, passed into the constructor as `BrowserWindowInterface&`. Which field declaration is preferred?", "choices": ["`BrowserWindowInterface& window_;`", "`raw_ptr<BrowserWindowInterface> window_;`", "`const raw_ref<BrowserWindowInterface> window_;`", "`raw_ref<BrowserWindowInterface> window_;`"], "answer": 2, "explain": "Use `const raw_ref<T>` for fields that must never be null (the `const` prevents rebinding, like `T&`); `raw_ptr<T>` is the default for nullable/reassignable non-owning fields."}, {"rule": "CSM-036", "prompt": "A constructor stores `browser->GetProfile()` (which effectively never returns null) into a field, and the author wraps it in `CHECK_DEREF(...)`. When is `CHECK_DEREF` appropriate?", "choices": ["Always — every pointer-to-reference conversion into a `raw_ref` needs `CHECK_DEREF`", "Only when the pointer could really be null; here it's a redundant check", "Never — plain `*ptr` is equivalent, since a null deref crashes anyway", "Only inside tests, where a crash message is more useful than a deref"], "answer": 1, "explain": "`CHECK_DEREF` asserts non-null and is safer than `*ptr`, but don't use it reflexively: reserve it for pointers that could really be null, not ones like `GetProfile()` that upstream doesn't check."}, {"rule": "CSM-037", "prompt": "Reviewing:\n\n```cpp\nvoid Schedule(std::string_view name) {\n  task_runner_->PostTask(FROM_HERE,\n      base::BindOnce(&MyClass::OnReady,\n                     weak_factory_.GetWeakPtr(), name));\n}\n```\n\nWhat should the reviewer say?", "choices": ["Fine — `BindOnce` copies bound arguments, so the string data is safe", "Fine — the WeakPtr cancels the task if anything is destroyed", "Use `base::Unretained(this)` instead, since the WeakPtr is what can dangle", "Bind an owning `std::string(name)`; copying a view copies only the pointer"], "answer": 3, "explain": "`base::Bind*` doesn't catch view types like `std::string_view`/`base::span`. Bind an owning copy (`std::string`, `std::vector`), unless using `base::raw_span` or the storage is static."}, {"rule": "CSM-037", "prompt": "Which of these bound view arguments is acceptable per the standard?", "choices": ["A naked `base::span<const uint8_t>` over a local `std::vector` in a posted task", "A `base::span` over a `constexpr` static array", "A `std::string_view` of a `std::string` parameter", "A `base::span` over a member vector bound with `base::Unretained`"], "answer": 1, "explain": "Binding a view is OK only with `base::raw_span<T>` (dangling protection) or when the backing storage is static, like a `constexpr` array or a string literal."}, {"rule": "CSM-038", "prompt": "A class holds a `PrefChangeRegistrar` member and registers:\n\n```cpp\npref_change_registrar_.Add(kSomePref,\n    base::BindRepeating(&MyClass::OnPrefChanged,\n                        base::Unretained(this)));\n```\n\nA linter flags every `base::Unretained(this)`. What's correct?", "choices": ["Safe — the registrar is a member destroyed with `this`; don't flag it", "Flag it — `PrefChangeRegistrar` callbacks can run after `this` and need a WeakPtr", "Flag it only if the registrar observes `local_state`, which outlives profiles", "Flag it — bind `base::DoNothing()` instead and read the pref on demand"], "answer": 0, "explain": "`base::Unretained(this)` is safe when the callback is owned by `this` or a member destroyed with it (registrars, timers, owned Mojo endpoints, `CallbackListSubscription`). Only flag it when the callback can outlive `this`."}, {"rule": "CSM-039", "prompt": "Which signature correctly expresses that `SetDelegate` takes ownership of the delegate?", "choices": ["`void SetDelegate(Delegate* delegate);` with `delegate_.reset(delegate)` inside", "`void SetDelegate(Delegate& delegate);`", "`void SetDelegate(std::unique_ptr<Delegate> delegate);`", "`void SetDelegate(const std::unique_ptr<Delegate>& delegate);`"], "answer": 2, "explain": "Pointer types in signatures are the ownership contract: `std::unique_ptr<T>` means the function takes ownership. A function must never take ownership of a `T*` parameter."}, {"rule": "CSM-039", "prompt": "A function builds a local `std::unique_ptr<Foo> foo` and returns it. A teammate writes `return std::move(foo);`. Also, a separate function returns a plain moveable value type wrapped in `std::unique_ptr`. What's the guidance?", "choices": ["Both are correct; explicit `std::move` makes the transfer of ownership clear", "Use `return foo;` (`std::move` blocks elision) and return moveable types by value", "Keep `return std::move(foo);`, but return value types as raw `T*` to avoid copies", "Use `std::shared_ptr` for both returns so callers can share the result freely"], "answer": 1, "explain": "Don't `std::move()` a local on return — it suppresses copy elision. And a smart pointer isn't the default way to move a value: take or return moveable types by value."}, {"rule": "CSM-040", "prompt": "Reviewing Windows code:\n\n```cpp\nHANDLE file = ::CreateFile(...);\nif (!IsValid(file)) {\n  return false;\n}\n::CloseHandle(file);\n```\n\nWhat should the reviewer suggest?", "choices": ["Add `::CloseHandle(file)` before every early return to avoid the leak", "Wrap it in `std::unique_ptr<HANDLE>` so it's freed automatically", "Use `base::win::ScopedHandle` so it's closed on destruction", "Use `base::mac::ScopedCFTypeRef` so the same code is portable"], "answer": 2, "explain": "Don't manage OS handles by hand; use platform scopers such as `base::win::ScopedHandle` and `base::apple::ScopedCFTypeRef<T>`, which release on destruction."}, {"rule": "CS-001", "prompt": "Reviewing a new header:\n\n```cpp\n// foo_service.h\n#include \"base/memory/ref_counted.h\"\n\nclass FooService {\n  std::string name_;\n};\n```\n\nIt compiles because `ref_counted.h` happens to pull in `<string>`. What should you say?", "choices": ["Fine — it compiles, and `ref_counted.h` is a stable base header", "Forward-declare `std::string` to keep the header lean", "Move the `std::string` member into a pimpl in the `.cc` file", "Add `#include <string>` directly to `foo_service.h` itself"], "answer": 3, "explain": "Include what you use. Transitive includes can change at any time and break your code. Also remove includes you don't actually use."}, {"rule": "CS-001", "prompt": "A unit test uses `net::MockHostResolver` and includes `net/dns/mock_host_resolver.h`, but not `net/dns/host_resolver.h`, which is private to `//net/dns:host_resolver` in GN. A review bot flags a missing include for `host_resolver.h`. Is the flag correct?", "choices": ["Yes — include what you use means a header for every type you touch", "No — the exported mock header is the right include here", "Yes — add the test target to the `friend` list so the include is allowed", "No — test files are exempt from include-what-you-use entirely"], "answer": 1, "explain": "GN-private headers are an exception: include the header the owner exports for that purpose, such as `mock_*.h` or `*_test_util.h`. Never flag the missing private include in review."}, {"rule": "CS-003", "prompt": "You're adding a pref and an accessor that control whether Tor is available. Which pair should you choose?", "choices": ["`kTorEnabled` / `IsTorEnabled()`", "`kTorDisabled` / `IsTorDisabled()`", "`kTorDisabled` / `IsTorEnabled()`", "`kDisableTor` / `ShouldDisableTor()`"], "answer": 0, "explain": "Use the positive form (\"Enabled\", not \"Disabled\") for booleans, prefs and methods. Negatives make conditions like `!IsTorDisabled()` harder to read."}, {"rule": "CS-004", "prompt": "C++ exposes `IsTorDisabledManaged()` while the settings JS calls `getTorManaged()` for the same concept. Best fix?", "choices": ["Keep both — each layer follows its own conventions", "`IsTorDisabledManaged()` in C++ and `isTorDisabledManaged()` in JS", "`IsTorManaged()` in C++ and `isTorManaged()` in JS", "`GetTorManaged()` in C++ and `getTorManaged()` in JS"], "answer": 2, "explain": "Use one name for a concept everywhere: C++, JS, prefs and UI. `IsTorManaged` / `isTorManaged` is consistent and also uses the positive form."}, {"rule": "CS-005", "prompt": "You're adding a bool query for whether to show the branded wallpaper, plus a function that records a P3A histogram for daily savings. Which declarations follow the conventional prefixes?", "choices": ["`bool GetShouldShowBrandedWallpaper();` and `void SendSavingsDaily();`", "`bool ShouldShowBrandedWallpaper();` and `void RecordSavingsDaily();`", "`bool IsShowBrandedWallpaper();` and `void ReportSavingsDaily();`", "`bool GetShowBrandedWallpaper();` and `void RecordSavingsDaily();`"], "answer": 1, "explain": "Use `Should*` for bool queries (not `Get*`), `Record*` for histogram/P3A recording, and `Load*`/`Save*` pairs for persistence."}, {"rule": "CS-006", "prompt": "`bool IsBraveCommandIds(int id);` checks whether a single command id belongs to Brave. Your review?", "choices": ["Fine — it's checked against a set of ids, so the plural fits", "Rename to `AreBraveCommandIds(int id)`", "Rename to `CheckBraveCommandIds(int id)`", "Rename to `IsBraveCommandId(int id)`"], "answer": 3, "explain": "Names should be grammatically correct. A function that takes one id and asks \"is it a Brave command id?\" is `IsBraveCommandId`."}, {"rule": "CS-007", "prompt": "You're creating a brand-new, Brave-only service for webcompat reports. It doesn't subclass anything from Chromium. What name and file should it get?", "choices": ["`WebcompatReporterService` in `webcompat_reporter_service.h`", "`BraveWebcompatReporterService` in `brave_webcompat_reporter_service.h`", "`BraveWebcompatReporterService` in `webcompat_reporter_service.h`", "`WebcompatReporterService` in `brave_webcompat_reporter.h`"], "answer": 0, "explain": "Only use the `Brave*` prefix when overriding or subclassing a Chromium class, like `BraveOmniboxClientImpl`. The filename should match the class name."}, {"rule": "CS-008", "prompt": "A function shows the first-launch notification only if it hasn't been shown before and a pref allows it. Best name?", "choices": ["`ShowFirstLaunchNotification()`", "`ShouldShowFirstLaunchNotification()`", "`MaybeShowFirstLaunchNotification()`", "`FirstLaunchNotification()`"], "answer": 2, "explain": "Use the `Maybe*` prefix for functions that conditionally perform an action. `Show*` sounds unconditional, and `Should*` is a query, not an action."}, {"rule": "CS-009", "prompt": "```cpp\nbool isTorDisabled = false;\nstd::string userName;\n```\n\nWhat should these C++ variables be called?", "choices": ["Leave them — camelCase is fine for locals; snake_case is only for members", "`is_tor_disabled` and `user_name`", "`IsTorDisabled` and `UserName`", "`kIsTorDisabled` and `kUserName`"], "answer": 1, "explain": "C++ variables use snake_case. CamelCase is reserved for class and method names."}, {"rule": "CS-010", "prompt": "In review you notice a `.cc` file's `#include` lines aren't in canonical order. What should you do?", "choices": ["Request a reorder before approving, since order can affect builds", "Leave a `nit:` asking for canonical order, without blocking", "Ask the author to put Brave includes before Chromium includes", "Don't comment on it — formatting tooling handles include order"], "answer": 3, "explain": "Never enforce include order in code review, because tooling handles it. For the rest of the basic style: opening braces go on the previous line (K&R), and continuation lines are indented 4 spaces."}, {"rule": "CS-011", "prompt": "You copy `chrome/browser/foo/bar.cc` (`Copyright 2019 The Chromium Authors`) into brave-core and modify it. What should the copyright header be?", "choices": ["Keep the Chromium copyright notice with its original 2019 year", "Replace it with the Brave copyright header and the current year", "Keep the Chromium notice but bump the year to the current year", "Switch to the Brave header once more than half the lines have changed"], "answer": 0, "explain": "Never put Brave's copyright on copied or derived Chromium code; keep their notice. Don't bump existing copyright years."}, {"rule": "CS-012", "prompt": "An AI assistant creates a new file and copies the header from a neighbor: `Copyright (c) 2023 The Brave Authors`. The PR is being written today. What should the year be?", "choices": ["Keep 2023 — matching the neighbor keeps headers consistent", "The year the feature work started, per the tracking issue", "The current year, taken from the system date at creation", "A range such as `2023-present`, covering both years"], "answer": 2, "explain": "New files use the current year. Get it from the system date, not from memory or training data, and never copy old years from other files."}, {"rule": "CS-013", "prompt": "Which of these member functions may stay defined inline in a header?", "choices": ["`static bool HandleURL(const GURL& url) { return url.scheme() == \"rewards\"; }`", "`bool is_enabled() const { return is_enabled_; }`", "`virtual bool IsEnabled() const { return enabled_; }`", "`void Shutdown() { observers_.Clear(); prefs_ = nullptr; }`"], "answer": 1, "explain": "Move method definitions to `.cc` files. Simple `snake_case()` accessors are the exception and can stay inline. Never declare a `virtual` function inline."}, {"rule": "CS-014", "prompt": "```cpp\n// my_class.h\n#include \"components/foo/bar.h\"\n\nclass MyClass {\n  raw_ptr<foo::Bar> bar_;\n};\n```\n\n`foo::Bar` is only used as a pointer here. What should the reviewer suggest?", "choices": ["Nothing — including it in the header guarantees the type is complete everywhere", "Swap to a smaller header that transitively provides `Bar`", "Change the member to `std::unique_ptr<foo::Bar>` so the include can be dropped", "Forward-declare `foo::Bar` in the header; include `bar.h` in the `.cc`"], "answer": 3, "explain": "In headers, forward-declare types used only as pointers or references, and move the full `#include` to the `.cc` file."}, {"rule": "CS-014", "prompt": "A WebUI controller header includes `ui/webui/mojo_web_ui_controller.h` (its base class) and takes a `content::WebUI*` in its constructor. `content::WebUI` comes in transitively through that base header. A reviewer suggests adding `namespace content { class WebUI; }`. Is that worth it?", "choices": ["No — it already arrives via the required base-class header", "Yes — every pointer-only type should be forward-declared, no exceptions", "Yes — and forward-declare the base class too, so its include can go", "Yes — and also add an explicit `web_ui.h` include for include-what-you-use"], "answer": 0, "explain": "Never suggest forward declarations for types that come transitively through a required base-class header, or for base classes themselves, which can't be forward-declared."}, {"rule": "CS-015", "prompt": "```cpp\nclass MyClass {\n private:\n  int value_ = 0;\n  friend class MyClassTest;\n};\n```\n\nWhere should the `friend` declaration go?", "choices": ["At the very top of the class, before `public:`, so it's visible", "At the end of the `private:` section, after all members", "Immediately after `private:`, before any member declarations", "In its own `protected:` section at the bottom of the class"], "answer": 2, "explain": "`friend` statements go immediately after the `private:` access specifier, not buried among members."}, {"rule": "CS-016", "prompt": "```cpp\n// foo.cc\nnamespace {\nstatic constexpr int kMaxRetries = 3;\n}  // namespace\n\nstatic void InternalHelper() { ... }\n```\n\nWhat should change?", "choices": ["Nothing — both already have internal linkage, which is all that matters", "Drop `static` in the namespace; move `InternalHelper` into it", "Move both into the header so unit tests can reach them", "Keep `static` on both and remove the redundant anonymous namespace"], "answer": 1, "explain": "Put code that's internal to a `.cc` file in an anonymous namespace, not `static`. Inside that namespace `static` is redundant, so write plain `constexpr`."}, {"rule": "CS-017", "prompt": "A header declares `Init()`, `Shutdown()` and `OnPrefChanged()` in that order, and the class overrides methods from both `KeyedService` and `PrefObserver`. Which layout matches the standard?", "choices": ["Define the methods alphabetically in the `.cc`, and group overrides by return type in the header", "Define them in any order in the `.cc`, and list all overrides in one unlabeled block", "Define overrides first in the `.cc`, then the rest in declaration order", "Follow `.h` order in the `.cc`; label override groups per parent class"], "answer": 3, "explain": "Definitions in the `.cc` follow the declaration order in the `.h`. In the header, group overrides within each access section, with one labeled group per parent class."}, {"rule": "CS-018", "prompt": "You need five new P3A recording methods. The natural home is `RewardsServiceImpl`, which is already about 5000 lines. Best approach?", "choices": ["Put them in a focused helper file that the service calls into", "Add them to `RewardsServiceImpl` next to related code so they're easy to find", "Add them at the end of `RewardsServiceImpl` under a `// P3A` banner comment", "Add them as lambdas inside the existing methods that trigger them"], "answer": 0, "explain": "Don't keep dumping code into already-large files. Smaller focused helper files and targets read better, cause fewer rebase conflicts and make dependencies easier to track."}, {"rule": "CS-019", "prompt": "```cpp\n// Previously this used a raw pointer, now using unique_ptr.\n// Changed from std::map to base::flat_map per review feedback.\nbase::flat_map<std::string, int> lookup_;\n```\n\nWhat should the reviewer say?", "choices": ["Fine — it records why the code looks this way for future readers", "Move these notes into the header so they're more visible", "Remove the history; describe only what the current code does", "Add the PR number so readers can find the review discussion"], "answer": 2, "explain": "Comments must make sense to someone reading the code fresh. Comments are not a changelog, so never reference removed code, prior behavior or the change itself."}, {"rule": "CS-021", "prompt": "```cpp\nif (!parent_hash) return std::nullopt;\nif (!state_root) return std::nullopt;\nif (!number) return std::nullopt;\n```\n\nThe reasons for each check aren't obvious. What should the author do?", "choices": ["Collapse them into one `if (!a || !b || !c)` with no comments", "Comment each branch briefly with what it guards", "Replace each check with a `CHECK`, since they shouldn't happen", "Add one summary comment at the top, e.g. `// Validate inputs.`"], "answer": 1, "explain": "When a function has several non-obvious early-return failure branches, put a brief comment before each one saying what it guards, e.g. \"State root validates the block's state trie.\""}, {"rule": "CS-022", "prompt": "Where should the comment describing what `kBraveWorkaroundNewWindowFlash` does live?", "choices": ["In `my_features.h`, above `BASE_DECLARE_FEATURE`", "In both the `.h` and the `.cc`, kept in sync", "Only in the `about:flags` description string", "In `my_features.cc`, above `BASE_FEATURE`"], "answer": 3, "explain": "Comments explaining a `base::Feature` go in the `.cc` file where the feature is defined, not in the header."}, {"rule": "CS-023", "prompt": "You add `if (!x) return;` to work around an upstream Chromium bug. What else should you do?", "choices": ["Link the crbug in a comment and file details on the upstream bug", "Add a `// HACK(username)` comment so it's greppable during cleanup", "Describe the bug in a comment, but don't link external trackers because links rot", "Nothing — a null check is self-explanatory and needs no comment"], "answer": 0, "explain": "Link the upstream issue in a code comment and file details upstream. Then the workaround can be removed when the fix lands."}, {"rule": "CS-024", "prompt": "A filter file entry reads:\n\n```\n# Same root cause as the test above\n-BrowserTest.SomeOtherTest\n```\n\nWhat should change?", "choices": ["Nothing — the entries are adjacent, so the reference is clear", "Change it to `as the previous entry` to be less ambiguous", "Name the related test explicitly, e.g. `BrowserTest.FirstTest`", "Change it to `as the test below` and reorder the entries"], "answer": 2, "explain": "Don't use positional words like \"above\" or \"below\" in comments, because someone may insert code in between. Refer to the item by name."}, {"rule": "CS-025", "prompt": "```cpp\nDCHECK(g_browser_process);\nDCHECK(browser_context);  // can never be null here\n```\n\nWhat's the right change?", "choices": ["Both are fine — `DCHECK` documents invariants at no release cost", "Drop the `g_browser_process` one; make the other a `CHECK`", "Turn both into `CHECK`s so release builds enforce them", "Replace both with `if (!x) return;` to fail gracefully"], "answer": 1, "explain": "Use `CHECK`, not `DCHECK`, for conditions that should never happen in any build. Skip pointless checks like `g_browser_process`, because the browser couldn't run without it."}, {"rule": "CS-026", "prompt": "The `type` string comes from parsed server data:\n\n```cpp\nmojom::AdType ToMojomAdType(const std::string& type) {\n  if (type == \"inline\") return mojom::AdType::kInline;\n  if (type == \"popup\") return mojom::AdType::kPopup;\n  NOTREACHED();\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Nothing — `NOTREACHED()` documents the unexpected case", "Use `DCHECK(false)` so release builds don't crash", "Keep `NOTREACHED()` and add a fallback `return mojom::AdType::kUndefined;` after it", "Return `std::optional<mojom::AdType>` and `std::nullopt` for unknown values"], "answer": 3, "explain": "`NOTREACHED()` crashes the browser, so use it only for real invariants. For bad data, return `std::nullopt` or a default value. `NOTREACHED()` is fatal and the code after it is dead, so a fallback return there is pointless."}, {"rule": "CS-027", "prompt": "```cpp\nstd::optional<std::string> db_value = LoadFromDatabase(key);\nCHECK(db_value.has_value());\n```\n\nWhat should the reviewer suggest?", "choices": ["Log the failure and return `std::nullopt` to the caller", "Fine — a missing value means corruption, so crashing is safest", "Downgrade to `DCHECK` so only developers crash", "Use `CHECK(db_value.has_value(), base::NotFatalUntil::M140)` permanently"], "answer": 0, "explain": "`CHECK` only conditions fully within the code's control. Data from databases, user input or other external sources needs graceful error handling, because a `CHECK` failure crashes the user's browser."}, {"rule": "CS-028", "prompt": "`bool ImportBookmarks(const base::FilePath& path);` can fail because the file is missing, malformed or too large, and callers want to show a different message for each. Best signature change?", "choices": ["Keep `bool` and log the reason internally", "Keep `bool` and add a `std::string* error_out` parameter", "Return an enum result code describing the outcome", "Throw an exception carrying the reason"], "answer": 2, "explain": "Return result codes (enums) rather than `bool` from operations that can fail. They carry extra error information and are more future-proof."}, {"rule": "CS-029", "prompt": "A class has this member:\n\n```cpp\nbase::expected<ChainMetadata, std::string> chain_metadata_;\n```\n\nThe error string is never shown anywhere. What should change?", "choices": ["Nothing — keeping the error around may help future debugging", "Handle the error where it occurs; keep `std::optional<ChainMetadata>`", "Use `std::variant<ChainMetadata, std::string>` to make both states explicit", "Store the error in a separate `last_error_` member for diagnostics"], "answer": 1, "explain": "Don't store error state. Handle or log the error at the point of failure, and keep only the success type."}, {"rule": "CS-030", "prompt": "```cpp\nclass MyObserver : public TabStripModelObserver {\n  void OnTabStripModelChanged(...) override {}\n  void OnTabGroupChanged(...) override { Update(); }\n};\n```\n\nWhat should happen to `OnTabStripModelChanged`?", "choices": ["Add an `// Intentionally empty.` comment to the body", "Add `NOTREACHED()` to the body", "Keep it so readers can see the event was considered", "Remove the override entirely"], "answer": 3, "explain": "If an override doesn't implement any behavior, don't define it at all."}, {"rule": "CS-031", "prompt": "A Chromium patch adds:\n\n```diff\n+SignBinaries(params);\n+CopyPreSignedBinaries(params);\n```\n\nThese two calls always happen together. What should the reviewer suggest?", "choices": ["Combine them into one method so the patch is one line", "Fine — two explicit calls are clearer than a wrapper", "Put both calls on one line, separated by `;`, to shrink the diff", "Add a comment in the patch reminding callers to call both"], "answer": 0, "explain": "Combine methods that are always called in sequence. That shrinks patches and stops callers from forgetting one of the calls."}, {"rule": "CS-032", "prompt": "```cpp\nvoid RewardsService::SavePendingContribution(...) {\n  SaveToDB(...);\n  GetPendingContributionsTotal();  // refresh the UI\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — the service owns the data, so it should push totals to the UI", "Have the service call the WebUI handler directly to skip a round trip", "Notify observers and let the UI query the total itself", "Have the UI poll the total on a short timer to stay current"], "answer": 2, "explain": "The service layer shouldn't make queries to update UI. Fire observer notifications and let the UI layer respond."}, {"rule": "CS-033", "prompt": "`MyClass::GetDefaultPath()` has a completely different implementation on Android, currently written as a 40-line `#if BUILDFLAG(IS_ANDROID)` block in `my_class.cc`. What should the reviewer suggest?", "choices": ["Fine — keeping every platform in one file makes it easier to find", "Move the Android implementation into `my_class_android.cc`", "Move the Android branch into a lambda to shorten the method", "Replace it with a runtime `if (IsAndroid())` check"], "answer": 1, "explain": "When an implementation is completely different on one platform, put it in a separate file such as `my_class_android.cc` instead of large `#if` blocks."}, {"rule": "CS-033", "prompt": "Which preprocessor check should guard Windows-only code?", "choices": ["`#if defined(WIN32)`, set by the Windows SDK headers", "`#if defined(OS_WIN)`, from `build/build_config.h`", "`#ifdef _MSC_VER`, since Windows builds use MSVC", "`#if BUILDFLAG(IS_WIN)` from `build/build_config.h`"], "answer": 3, "explain": "Always use the `BUILDFLAG(IS_*)` flags from `build/build_config.h`. Never use compiler macros like `WIN32` or `__APPLE__`, or the removed `defined(OS_*)` form."}, {"rule": "CS-034", "prompt": "```cpp\n#if BUILDFLAG(IS_ANDROID)\n  // Don't show notifications\n#endif\n```\n\nThe real reason for suppressing notifications is the user's Do Not Disturb setting, not the platform. What should the reviewer suggest?", "choices": ["Use a feature check such as `if (IsDoNotDisturbEnabled())`", "Extend it to `#if BUILDFLAG(IS_ANDROID) || BUILDFLAG(IS_IOS)`", "Move the block into `notifications_android.cc`", "Fine — Android is where Do Not Disturb is used most"], "answer": 0, "explain": "When behavior depends on a feature rather than the platform, use a feature check instead of a platform check."}, {"rule": "CS-035", "prompt": "```cpp\nvoid OnTabContextMenuAction(int action) {\n  if (!base::FeatureList::IsEnabled(kRenamingTabs)) return;\n  model->SetCustomTitle(...);\n}\nvoid TabStripModel::SetCustomTitle(...) {  // private, one caller\n  CHECK(base::FeatureList::IsEnabled(kRenamingTabs));\n  ...\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — a defensive `CHECK` in every helper catches future misuse", "Change the helper's check to `DCHECK` to save the release cost", "Drop the helper's `CHECK`; note the precondition in a comment", "Remove the entry-point check and rely on the helper's `CHECK` instead"], "answer": 2, "explain": "Check feature flags at entry points only, and comment private helpers. Public APIs called from many places are entry points themselves and keep their own checks."}, {"rule": "CS-036", "prompt": "A PR stores whether a feature is enabled for the current profile in a file-level `static bool g_feature_enabled_for_profile;`. Your review?", "choices": ["Fine, as long as every access is guarded by a lock", "Use a profile-keyed service or `UserData` for per-profile state", "Make it `thread_local` so each thread sees its own value", "Wrap it in `base::NoDestructor<bool>` to avoid exit-time destructors"], "answer": 1, "explain": "Never use static variables for per-profile settings, because static state is shared across every profile and breaks multi-profile scenarios."}, {"rule": "CS-037", "prompt": "```cpp\nstd::string api_url = std::getenv(\"BRAVE_API_URL\");\n```\n\nHow should this configuration be provided instead?", "choices": ["Keep `getenv`, but only in `#if !defined(NDEBUG)` builds", "Read it once at startup and cache it in a global", "A local-state pref that developers set by hand", "A GN arg, plus a command-line switch for overrides"], "answer": 3, "explain": "Configuration comes from GN args, not environment variables. Use command-line switches for runtime overrides."}, {"rule": "CS-040", "prompt": "A WebUI file contains `const AdType = { kInline: 0, kPopup: 1 }`, mirroring an enum already defined in a `.mojom` file. Your review?", "choices": ["Use the generated Mojo JS bindings for the enum instead", "Fine — add a `// Keep in sync with ads.mojom` comment", "Add a unit test asserting the JS and mojom values match", "Move the values to a shared JSON file loaded by both C++ and JS"], "answer": 0, "explain": "When values are defined in Mojo, use the generated bindings in C++, Java and JS. Hand-copied constants drift out of sync."}, {"rule": "CS-041", "prompt": "A PR pulls in rapidjson to parse a component's JSON config, citing speed. Your review?", "choices": ["Fine, if a benchmark shows it's faster", "Use `nlohmann::json` instead, for its nicer API", "Use `base::JSONReader` and `JSONWriter`", "Parse it by hand with `std::string::find`"], "answer": 2, "explain": "Don't use rapidjson. `base::JSONReader` and `base::JSONWriter` are the Chromium standard."}, {"rule": "CS-042", "prompt": "```cpp\nif (VLOG_IS_ON(2)) {\n  VLOG(2) << \"Rules: \" << DumpRules();\n}\n```\n\nWhat should the reviewer say?", "choices": ["Keep it — otherwise `DumpRules()` runs even when logging is off", "Remove the guard; `VLOG` already checks the level", "Change the guard to `if (DCHECK_IS_ON())` to skip release builds", "Change it to `LOG(INFO)` so it always prints"], "answer": 1, "explain": "`VLOG` does its own level check and won't evaluate inline expressions when the level is disabled, so `VLOG_IS_ON` is redundant. Also make sure each VLOG has a real purpose and isn't left over from debugging."}, {"rule": "CS-043", "prompt": "Code in `brave/components/brave_policy/` tags its VLOG messages with a component name. Which name should it use?", "choices": ["A generic `Brave` tag shared by all components", "A descriptive alias such as `AdminSettings`", "The class name, e.g. `BravePolicyServiceImpl`", "The component directory name, `brave_policy`"], "answer": 3, "explain": "The component name used in VLOG messages should match the component's directory name."}, {"rule": "CS-044", "prompt": "```cpp\nif (!ParseFilterList(user_supplied_list)) {\n  LOG(ERROR) << \"Failed to parse filter list\";\n}\n```\n\nA bad user-supplied list is expected now and then and isn't serious. What should the log be?", "choices": ["`VLOG(1)`, or `LOG(WARNING)` if noteworthy", "Keep `LOG(ERROR)` — any parse failure is an error", "A `CHECK` so the bad list gets noticed", "No log at all — silently ignore the failure"], "answer": 0, "explain": "`LOG(ERROR)` is for truly unexpected, serious failures. For expected or non-critical cases, use `VLOG` for debug info or `LOG(WARNING)` for noteworthy issues."}, {"rule": "CS-044", "prompt": "A keyed service has `LOG(ERROR) << \"Failed to load model file\";`. From the diff alone it looks non-critical to you, but you haven't confirmed that. What should you do?", "choices": ["Ask for `VLOG(1)`, since it looks non-critical in the diff", "Ask for `DLOG(ERROR)` so release logs stay clean", "Leave it — you haven't confirmed it's non-critical", "Ask for `LOG(WARNING)` as a middle ground"], "answer": 2, "explain": "Never suggest lowering log severity for failures you haven't confirmed are non-critical. The developer knows better than a reviewer whether the failure matters to their service."}, {"rule": "CS-045", "prompt": "An optional metadata field fails to parse. The feature works fine without it, and the message only helps developers debugging locally. Which log statement fits?", "choices": ["`LOG(ERROR) << \"Failed to parse optional field\";`", "`CHECK(parsed) << \"Failed to parse optional field\";`", "`NOTREACHED() << \"Failed to parse optional field\";`", "`DLOG(ERROR) << \"Failed to parse optional field\";`"], "answer": 3, "explain": "Use `DLOG(ERROR)` for errors that aren't critical in release builds, so release logs aren't polluted with non-actionable errors."}, {"rule": "CS-046", "prompt": "You're adding `GetUrlCosmeticResourcesOnUI()`, which processes filter data on the UI thread and could be slow on large pages. What should you add?", "choices": ["A `VLOG(1)` printing the elapsed time from `base::TimeTicks::Now()`", "A `SCOPED_UMA_HISTOGRAM_TIMER` at the top of the function", "A `base::ElapsedTimer` with a `LOG(INFO)` of the result", "Nothing — profile it locally once before landing"], "answer": 1, "explain": "Code that processes data on the UI thread or may be slow should use `SCOPED_UMA_HISTOGRAM_TIMER`, so its performance is measured in the field."}, {"rule": "CS-047", "prompt": "Three different click handlers each call:\n\n```cpp\nbase::UmaHistogramExactLinear(\"Brave.NTP.CustomizeUsage\", N, 7);\n```\n\nwith a different `N`. What should the reviewer suggest?", "choices": ["Fine — each call site records its own bucket value", "Give each handler its own histogram name for clarity", "Wrap it in one `RecordNTPCustomizeUsage()` helper", "Switch each site to the `UMA_HISTOGRAM_ENUMERATION` macro"], "answer": 2, "explain": "Emit each histogram from a single location. Wrap it in a helper instead of duplicating the emission across call sites."}, {"rule": "CS-048", "prompt": "```cpp\nVLOG(1) << \"Sync seed: \" << sync_seed;\n```\n\nWhat's the right fix?", "choices": ["Don't log the seed; log only that it was set", "Fine — VLOG is off by default in release builds", "Switch to `DVLOG(1)` so it only appears in debug builds", "Log only the first 8 characters of the seed"], "answer": 0, "explain": "Never log sensitive data such as sync seeds, private keys, tokens or credentials. Even VLOG-level logging can expose it."}, {"rule": "CS-049", "prompt": "```cpp\nstruct TestData {\n public:\n  std::string name;\n  int value;\n};\n```\n\nWhat should the reviewer say?", "choices": ["Fine — an explicit `public:` documents intent for readers", "Add a `private:` section for `value` to encapsulate it", "Change `public:` to `protected:` for test-only structs", "Remove `public:`, or use `class` for access control"], "answer": 3, "explain": "Struct members are public by default, so `public:` in a struct is redundant. Remove it, or switch to `class` if you need access control."}, {"rule": "CS-050", "prompt": "```cpp\nBraveOriginService* BraveOriginService::GetInstance() {\n  static base::NoDestructor<BraveOriginService> instance;\n  return instance.get();\n}\n```\n\nWhat should the reviewer suggest for this global service?", "choices": ["Fine — `NoDestructor` is the approved Chromium singleton", "Register it in `GlobalFeatures` so tests can reset it", "Use a plain function-local `static BraveOriginService instance;`", "Make it a `KeyedService` attached to the first profile"], "answer": 1, "explain": "Prefer `GlobalFeatures`, the replacement for `BrowserProcessImpl`, over `base::NoDestructor` for global services. A `NoDestructor` instance can't be reset between tests."}, {"rule": "CS-051", "prompt": "`used` is 30 and `total` is 120, both `int`. Which expression gives the correct percentage?", "choices": ["`int pct = (used / total) * 100;`", "`int pct = used / (total * 100);`", "`int pct = (used * 100) / total;`", "`int pct = static_cast<int>(used / total) * 100;`"], "answer": 2, "explain": "With integer arithmetic, multiply by 100 before dividing. `(used / total) * 100` truncates to 0 whenever `used < total`."}, {"rule": "CS-052", "prompt": "```cpp\nDoSomething(base::BindOnce([](int a, int b, int c) {\n  // 20 lines of complex logic...\n}));\n```\n\nWhat should the reviewer suggest?", "choices": ["Move it into a named function in the anonymous namespace", "Fine — lambdas keep the logic close to the call site", "Split the lambda into two smaller nested lambdas", "Store the lambda in a named local `auto` variable first"], "answer": 0, "explain": "When a lambda is complex enough to make the surrounding code hard to read, move it into a named free function in the anonymous namespace."}, {"rule": "CS-053", "prompt": "```cpp\nauto elapsed = timer.Elapsed();\nauto weights_opt = base::ReadFileToBytes(weights_path);\n```\n\n`ReadFileToBytes` returns `std::optional<std::vector<uint8_t>>`. What's the right review comment?", "choices": ["Require both to spell out their types before approving", "Both are fine; `auto` is acceptable whenever the initializer is a call", "Flag only `weights_opt`, because complex types must be explicit", "`nit:` spell out `base::TimeDelta`; leave `weights_opt` as `auto`"], "answer": 3, "explain": "Spell out short, descriptive types like `base::TimeDelta` instead of using `auto` just to save typing. `auto` is fine for verbose types. This is a preference: prefix it with `nit:` and never insist."}, {"rule": "CS-054", "prompt": "```cpp\nclass TreeTabNode {\n public:\n  explicit TreeTabNode(TabInterface* tab) : current_tab_(tab) {}\n private:\n  raw_ptr<TabInterface> current_tab_ = nullptr;\n};\n```\n\nThis is the only constructor. What should the reviewer say?", "choices": ["Fine — default member initializers are always required", "Drop the `= nullptr`; the constructor always sets it", "Remove the constructor initializer and keep the default", "Keep both, so the member is safe if a constructor is added"], "answer": 1, "explain": "Initialize members in their declarations unless every constructor sets them explicitly. Then a default like `= nullptr` suggests a state that never happens."}, {"rule": "CS-055", "prompt": "```cpp\nvoid ApiFetch(const std::string& verb, const std::string& url,\n              const base::Value& body_value, Callback cb);\n```\n\n`body_value` is silently ignored for GET and HEAD. Best redesign?", "choices": ["Make `body_value` a `std::optional<base::Value>` defaulting to `std::nullopt`", "Take a `std::variant<GetRequest, PostRequest>` parameter", "Use overloads, e.g. `ApiFetch(url, cb)` and `ApiFetch(url, body, cb)`", "Document in the header that `body_value` is ignored for GET/HEAD"], "answer": 2, "explain": "Don't make callers pass parameters that are silently ignored. Use overloads, which are also preferred over `std::variant` for distinct call patterns."}, {"rule": "CS-056", "prompt": "```cpp\nfor (auto& observer : observers_) {\n  observer.OnPoliciesChanged();\n}\n```\n\nWhat's the preferred form?", "choices": ["`observers_.Notify(&Observer::OnPoliciesChanged);`", "`for (Observer& o : observers_) o.OnPoliciesChanged();`", "`std::ranges::for_each(observers_, &Observer::OnPoliciesChanged);`"], "answer": 0, "explain": "Use the `observers_.Notify(&Observer::Method)` helper instead of manually iterating observer lists."}, {"rule": "CS-057", "prompt": "```cpp\nstd::string script = \"const selectors = [`\" + selector + \"`];\";\nExecuteScript(script);\n```\n\n`selector` comes from page-derived data. What should the reviewer suggest?", "choices": ["Fine — the template-literal backticks quote it safely", "Escape backticks in `selector` before concatenating", "Build the string with `base::StringPrintf` instead of `+`", "Serialize the data with `base::JSONWriter` and embed that"], "answer": 3, "explain": "When building JavaScript from C++ data, encode it with JSON serialization (`base::JSONWriter`). String concatenation invites injection."}, {"rule": "CS-058", "prompt": "A browser test has:\n\n```cpp\nbool result;\nASSERT_TRUE(content::ExecuteScriptAndExtractBool(\n    web_contents, \"domAutomationController.send(someCheck())\", &result));\n```\n\nWhat should it become?", "choices": ["`ExecJs`, reading the result back from `domAutomationController`", "`EXPECT_EQ(true, EvalJs(web_contents, \"someCheck()\"));`", "`ExecuteScriptAndExtractString`, comparing against `\"true\"`", "`ExecuteScript`, then poll a DOM attribute for the result"], "answer": 1, "explain": "`ExecuteScriptAndExtract*` is deprecated. Use `EvalJs` when you need a result and `ExecJs` when you don't."}, {"rule": "CS-059", "prompt": "You have a `content::BrowserContext* browser_context` and need a `Profile*`. Which is correct?", "choices": ["`static_cast<Profile*>(browser_context)`", "`dynamic_cast<Profile*>(browser_context)`, null-checked", "`Profile::FromBrowserContext(browser_context)`", "`reinterpret_cast<Profile*>(browser_context)`"], "answer": 2, "explain": "Use `Profile::FromBrowserContext()` to convert. Unlike a cast, it includes safety checks."}, {"rule": "CS-060", "prompt": "```cpp\nGURL url(user_input);\nloader->DownloadUrl(url);\n```\n\nWhat should the reviewer ask for?", "choices": ["Check `url.is_valid()` and return early if not", "Nothing — `GURL` normalizes and sanitizes any input", "Check `!url.is_empty()` and return early if empty", "Add `CHECK(url.is_valid())` before the download"], "answer": 0, "explain": "Always check `GURL::is_valid()` before using a constructed URL. Malformed URLs can cause crashes or odd behavior. `CHECK` is wrong for user input."}, {"rule": "CS-061", "prompt": "```cpp\nusing MyFeatureTest = testing::Test;\nTEST_F(MyFeatureTest, CrashesOnNull) {\n  EXPECT_DEATH(Process(nullptr), \"\");\n}\n```\n\nWhat should change?", "choices": ["Nothing", "Rename the test case to `DeathCrashesOnNull`", "Use `ASSERT_DEATH` instead of `EXPECT_DEATH`", "Rename the suite to `MyFeatureDeathTest`"], "answer": 3, "explain": "Death test suite names must end in `DeathTest`. GoogleTest uses that suffix to apply the threading behavior death tests need to work reliably."}, {"rule": "CS-063", "prompt": "```cpp\nconst base::TimeDelta kAnimationDuration = base::Milliseconds(200);\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — `const` already makes it a compile-time constant", "Make it `constexpr base::TimeDelta`", "Store `int kAnimationDurationMs = 200` and convert at each use", "Make it a `static const` inside the function that uses it"], "answer": 1, "explain": "`base::Milliseconds()`, `base::Seconds()` and similar are constexpr-capable, so declare time constants `constexpr base::TimeDelta` to compute them at compile time."}, {"rule": "CS-066", "prompt": "A PR leaves this behind \"in case we need it later\":\n\n```cpp\n// #include \"brave/components/old_feature/old_header.h\"\n// void OldMethod() { ... }\n```\n\nYour review?", "choices": ["Fine, with a `TODO` explaining when to restore it", "Wrap it in `#if 0` so editors grey it out clearly", "Delete it — version control history already keeps it", "Move it into an unbuilt `_deprecated.cc` file for reference"], "answer": 2, "explain": "Don't commit commented-out code, dead includes or development leftovers. They add noise and never get cleaned up, and the history lives in version control."}, {"rule": "CS-065", "prompt": "You're removing the AI models `chat-old-model-1` and `chat-old-model-2`. Some users have one of them selected in the `kDefaultModelKey` pref. What else should the PR do?", "choices": ["Add a migration that resets the pref to a sensible default", "Nothing — the UI will just show a blank selection", "Keep the old model entries hidden forever so the prefs stay valid", "Add a `CHECK` that the stored model still exists"], "answer": 0, "explain": "When removing or renaming a feature, model or pref value that users may have selected, add a migration that resets the pref to a sensible default. Otherwise users are left with a stale, broken value."}, {"rule": "CS-068", "prompt": "A PR removes a feature flag and its checks, but leaves behind the helper functions only that feature used, its `.grdp` strings and related constants. Your review?", "choices": ["Fine — unused leftovers are harmless and cost nothing", "Mark the leftovers `[[deprecated]]` for a follow-up PR", "Remove only the strings; the helpers might be reused", "Ask for all of that dead code to be removed in this PR"], "answer": 3, "explain": "When removing a feature, remove all of its dead code: helpers, orphaned UI strings in `.grdp` files, constants and utilities only the removed code used."}, {"rule": "CS-069", "prompt": "A new class inherits from two concrete implementation classes to reuse code from both. What should the reviewer suggest?", "choices": ["Fine — multiple inheritance is allowed in Chromium", "Prefer composition over inheriting from both concrete classes", "Use virtual inheritance to avoid diamond problems", "Ban multiple inheritance entirely, including observer interfaces"], "answer": 1, "explain": "Chromium permits multiple inheritance but discourages it beyond interface-style patterns. Explore composition before inheriting from several concrete classes."}, {"rule": "CS-067", "prompt": "You're investigating a rare crash and want the current `state` string attached to crash reports. What should you use?", "choices": ["`LOG(ERROR) << \"Unexpected state: \" << state;`", "`DVLOG(1) << \"Processing state: \" << state;`", "A `base::debug::ScopedCrashKeyString` for `state`", "`CHECK(false) << state;` so the report includes it"], "answer": 2, "explain": "For crash diagnostics, use `base::debug::ScopedCrashKeyString`, which attaches data to crash reports without polluting logs. Remove other logging before check-in, and if some must stay, use `DVLOG(1)`."}, {"rule": "CS-070", "prompt": "```cpp\n// prefs_registration.h\n#include \"brave/components/containers/core/mojom/containers.mojom.h\"\n\nvoid RegisterProfilePrefs(\n    user_prefs::PrefRegistrySyncable* registry,\n    const std::vector<mojom::ContainerPtr>& default_containers);\n```\n\nWhat should the reviewer suggest?", "choices": ["Include `containers.mojom-forward.h` in the header instead", "Nothing — generated mojom types can't be forward-declared", "Hand-write `namespace mojom { class Container; }` in the header", "Move the declaration into the `.mojom` file as an interface method"], "answer": 0, "explain": "Every mojom target auto-generates a `*.mojom-forward.h`. Use it in headers that only need declarations, which cuts compile time and transitive dependencies, and include the full bindings in the `.cc`."}, {"rule": "CS-071", "prompt": "Code that decides whether to grant a capability to a frame does:\n\n```cpp\nurl::Origin origin =\n    url::Origin::Create(render_frame_host->GetLastCommittedURL());\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — it's equivalent to the frame's origin", "Use `url::SchemeHostPort(url)` instead", "Compare `GetLastCommittedURL().host()` against an allowlist", "Use `render_frame_host->GetLastCommittedOrigin()`"], "answer": 3, "explain": "Make security decisions from `url::Origin`, never a raw `GURL`, and read it from the exact frame with `GetLastCommittedOrigin()`. Converting a `GURL` to an origin often gives the wrong origin."}, {"rule": "CS-071", "prompt": "Your shields logic must decide whether to farble in a frame loaded from a `blob:` URL that `https://a.com` embeds. What should the decision be based on?", "choices": ["The origin parsed out of the `blob:` URL string", "`GetLastCommittedOrigin()` on the embedded frame itself", "The top-level frame's last committed URL", "Nothing — `blob:` frames are always exempt from farbling"], "answer": 1, "explain": "`blob:`, `about:blank` and `about:srcdoc` inherit the embedder's origin, and `GetLastCommittedOrigin()` returns it. Ignoring this let any embedder of a `blob:` URL bypass farbling."}, {"rule": "CS-072", "prompt": "Which header guard is correct for `brave/components/foo/bar.h`?", "choices": ["`#pragma once`", "`#ifndef COMPONENTS_FOO_BAR_H_`", "`#ifndef BRAVE_COMPONENTS_FOO_BAR_H_`", "`#ifndef SRC_BRAVE_COMPONENTS_FOO_BAR_H_`"], "answer": 2, "explain": "`#pragma once` isn't allowed. The guard is the full path from the source root, uppercased, with `/` and `.` replaced by `_`, plus a trailing `_`."}, {"rule": "CS-073", "prompt": "You're writing `if (!service) return;` in new code, and you also notice an unbraced single-statement `for` loop in a teammate's PR. What's right?", "choices": ["Brace your own; don't flag the teammate's unbraced loop", "Unbraced single statements are fine everywhere", "Brace yours, and request braces in the teammate's PR", "Only loops need braces; an `if` with a lone `return` doesn't"], "answer": 0, "explain": "Always brace `if`/`else`/`for`/`while` bodies, even single statements, so an added line can't fall outside the conditional. Never flag missing braces in review, because tooling handles them."}, {"rule": "CS-074", "prompt": "A null `profile` here would be a programming bug:\n\n```cpp\nif (!profile) {\n  NOTREACHED();\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — `NOTREACHED()` already states the intent clearly", "Replace it with `DCHECK(profile);` to avoid release cost", "Add a `return;` after `NOTREACHED()` for safety", "Replace it with an unconditional `CHECK(profile);`"], "answer": 3, "explain": "Prefer an unconditional `CHECK()` over an `if` that conditionally hits `NOTREACHED()`. It's shorter and states the invariant directly."}, {"rule": "CS-074", "prompt": "An entry is sometimes missing in the wild and you don't yet know why. You want reports from the field without crashing users. Which code fits?", "choices": ["`CHECK(entry_was_found)` to capture a crash dump", "`base::debug::DumpWithoutCrashing()`, then return", "`base::ImmediateCrash()` when the entry is missing", "`ADD_FAILURE()` when the entry is missing"], "answer": 1, "explain": "`DumpWithoutCrashing()` uploads a report and keeps running, which suits a failure you're still investigating. `CHECK` is for invariants, `ImmediateCrash` is for when the process must die, and `ADD_FAILURE` belongs in tests."}, {"rule": "DOC-006", "prompt": "You're writing the README for `browser/brave_rewards/`. It already states the directory's purpose. Which section should come next to orient a new developer?", "choices": ["A full list of every file in the directory, sorted alphabetically", "A changelog of recent PRs that touched the directory", "Key files, each with a one-line description of its role", "A copy of the class comments from each header file"], "answer": 2, "explain": "An orienting README names the key files and their roles (e.g. `rewards_service_impl.cc` is the main implementation, `rewards_service_factory.cc` the profile-keyed factory) rather than dumping everything."}, {"rule": "DOC-007", "prompt": "A draft README for the Rewards browser integration has a purpose statement and a key-files list. A reviewer says it's still missing something a newcomer needs. What is most likely missing?", "choices": ["A Usage section showing how to obtain the service", "A full API reference duplicated from the service headers", "A history of why the service was originally designed this way", "Build instructions copied from the main brave-core README"], "answer": 0, "explain": "A good README covers purpose, key files, how to use the main APIs, and who maintains it. Start with the simplest use case, such as how to obtain the service."}, {"rule": "DOC-009", "prompt": "A PR adds this to a Brave component README:\n\n```markdown\n## How to Add a Feature Flag\n\n1. Create a feature in features.h...\n2. Register in about_flags.cc...\n3. Add a histogram entry in enums.xml...\n```\n\nThe steps are copied from Chromium's docs. What should the reviewer say?", "choices": ["Fine, as long as a comment notes which Chromium revision it was copied from", "Fine; having the steps inline saves readers a click to another site", "Move the copied steps into a separate `FEATURE_FLAGS.md` file instead", "Link to the upstream guide instead; a copy will go stale"], "answer": 3, "explain": "Don't duplicate documentation: copies inevitably drift out of sync. Link to the canonical source instead. (Entries in `docs/best-practices/` are the exception and must be self-contained.)"}, {"rule": "DOC-010", "prompt": "In a general project README, which version of a \"How to Add a Feature Flag\" section follows Brave's documentation guidance?", "choices": ["A full step-by-step copy of the Chromium guide, with Brave notes added inline", "A link to the Chromium guide plus the Brave-specific `about_flags.cc` step", "Just a bare link to the Chromium guide, with no other text at all", "A note telling readers to search the Chromium docs for \"feature flag\""], "answer": 1, "explain": "Link to the canonical source with context: point to Chromium's feature flag guide and add only the Brave-specific note, which is to also register in `brave/browser/about_flags.cc`."}, {"rule": "DOC-001", "prompt": "A PR refactors the `RewardsService` API. The author says: \"I'll update the README and method comments in a follow-up CL.\" Best response?", "choices": ["Fine — docs reviews should be separate so code review stays focused", "Only the header comments must change now; READMEs can follow later", "Fine, as long as a follow-up issue is filed and linked from the PR", "Ask for the README and method docs to be updated in this same CL"], "answer": 3, "explain": "Docs changes belong in the same changelist as the code — separate doc CLs get forgotten and lose context, and reviewers benefit from seeing both together."}, {"rule": "DOC-002", "prompt": "While editing a component you find a README section describing a sync flow you're fairly sure no longer exists, but nobody can confirm. What's the recommended move?", "choices": ["Delete it — when in doubt, default toward removal", "Leave it alone since you're not 100% certain", "Rewrite it from your best guess of how it works now", "Leave it but add a \"may be outdated\" warning banner"], "answer": 0, "explain": "Dead documentation misleads and erodes trust. Remove content you know is wrong, and when in doubt default toward removal."}, {"rule": "DOC-004", "prompt": "Which header comment best documents this method?\n\n```cpp\nstd::optional<PublisherInfo> GetPublisherInfo(const std::string& id);\n```", "choices": ["`// Returns nullopt if |id| isn't in the local DB. No network fetch; UI thread only.`", "`// See https://github.com/brave/brave-core/pull/1234 for the design and details.`", "`// Looks up |id| in publisher_map_, then calls ConvertRow() on the result.`", "`// Gets the publisher info.`"], "answer": 0, "explain": "Method docs should describe the contract — behavior, params, return values, gotchas and restrictions (e.g. threading, staleness) — not restate the name or narrate the implementation."}, {"rule": "DOC-005", "prompt": "You're creating a new major directory, `brave/browser/brave_rewards/`. What should its README.md contain?", "choices": ["A full class-by-class design doc covering every edge case", "Purpose, key files, main API usage, and maintainers", "Just a title for now; it'll be filled in once the code stabilizes", "Nothing — header comments are enough documentation"], "answer": 1, "explain": "A README orients newcomers: purpose, key files, main API usage, and maintainers — starting with the simplest use case and building up."}, {"rule": "DOC-008", "prompt": "A Brave doc on adding feature flags copies Chromium's step-by-step instructions verbatim. How should it be written?", "choices": ["Keep the copy so readers don't have to leave the Brave docs", "Copy the instructions but add a \"last synced\" date", "Link to the Chromium guide plus a short Brave-specific note", "Delete the doc entirely; Brave devs should know upstream docs exist"], "answer": 2, "explain": "Duplicated docs drift out of sync. Link to the canonical source and add only the project-specific context (e.g. also register in `brave/browser/about_flags.cc`)."}, {"rule": "DOC-008", "prompt": "You're adding a new entry to `docs/best-practices/coding-standards.md`. A reviewer suggests ending it with \"See PR #4567 and the Chromium style guide for details.\" Best response?", "choices": ["Accept — linking beats duplicating, as for all docs", "Decline: best-practice entries must be self-contained", "Accept, but link only to the PR, not external docs", "Copy the entire Chromium style guide section into the entry instead"], "answer": 1, "explain": "Best-practice entries are the exception to \"link, don't duplicate\": distill the relevant rule, rationale, caveats and examples directly, with no links to PRs, other entries or external docs."}, {"rule": "DOC-011", "prompt": "Your team proposes a 40-page comprehensive design doc for a feature, but nobody is assigned to keep it updated. Best advice?", "choices": ["Skip docs entirely and rely on code comments", "Write the full doc now; even partly stale, comprehensive beats minimal", "Write a small, accurate doc you'll actually maintain", "Write the full doc and mark it \"historical\" when it goes stale"], "answer": 2, "explain": "A little fresh documentation beats lots of stale documentation. Treat docs like a bonsai: alive but frequently trimmed, focused on what saves the most developer time."}, {"rule": "FE-001", "prompt": "A test helper looks like this:\n```tsx\nasync function renderMyComponent(...args: Parameters<typeof render>) {\n  let result\n  await act(async () => { result = render(...args) })\n  return result!\n}\n```\nWhat should the reviewer request?", "choices": ["Take explicit `ui: React.ReactElement, options?: RenderOptions` params, not `...args`", "Nothing; spreading `Parameters<typeof render>` already keeps the helper fully type-safe", "Remove the `act()` wrapper; `render` already wraps itself in `act` internally", "Spread the args into a single props object before forwarding them to `render`"], "answer": 0, "explain": "Don't spread arbitrary `...args` into `render()`, component props, or other React APIs; it can inject unexpected attributes (an XSS risk). Pass explicit parameters."}, {"rule": "FE-002", "prompt": "```tsx\n{items.map((item) => (\n  <AttachmentItem key={item.id}>\n    <div key={item.id}>{item.name}</div>\n  </AttachmentItem>\n))}\n```\nWhat should change?", "choices": ["Remove `key` from `AttachmentItem` and keep it on the `<div>`", "Remove `key` from the inner `<div>`; the list element already has it", "Use the array index as the inner key so it differs from the outer one", "Nothing; keys on both levels make reconciliation more robust"], "answer": 1, "explain": "Keys belong on the list element. When the parent already sets `key`, redundant keys on inner elements show a misunderstanding of React's reconciliation boundary."}, {"rule": "FE-003", "prompt": "A PR adds a pure `groupConversationsByDate()` helper to `conversation_context.tsx`, the file that holds React context state. Best review comment?", "choices": ["Wrap it in `useCallback` so it isn't recreated on every render of the provider", "Export it from the context value so consumers can call it", "Move it to a utility module such as `utils/conversation_history_utils.ts`", "Fine as-is; keeping related logic in the context file aids discoverability"], "answer": 2, "explain": "Pure utility functions belong in dedicated utility modules. Context files should focus on state management, not data transformation."}, {"rule": "FE-004", "prompt": "The attachment UI has `<AttachmentImageItem />`, and you need PDF support. What does the standard suggest?", "choices": ["Add a parallel `<AttachmentDocumentItem />` so each file type stays simple", "Subclass `AttachmentImageItem` for documents", "Render PDFs as images so the existing component works", "Merge them into one generic `<AttachmentUploadItem type={file.type} />`"], "answer": 3, "explain": "When adding a new file type to upload/attachment UI, merge similar components into a single generic one rather than creating parallel components."}, {"rule": "FE-005", "prompt": "A test file starts with:\n```ts\nenum FileType {\n  kImage = 0,\n  kDocument = 1,\n}\n```\n`FileType` is defined in `ai_chat.mojom`. What should the reviewer say?", "choices": ["Import `FileType` from the generated `ai_chat.mojom-webui.js` bindings", "Use a `const` object instead of an enum so it tree-shakes better", "Add a comment noting the values must stay in sync with the mojom", "Move the enum into a shared `test_utils.ts` so other tests can reuse it"], "answer": 0, "explain": "Don't redefine or duplicate types from generated Mojo bindings in tests; import them from the generated bindings or source files."}, {"rule": "FE-006", "prompt": "Which line follows the front-end guidance?", "choices": ["`const count = useMemo(() => items.length, [items])`", "`const count = items.length`", "`const count = useMemo(() => items.length, [items.length])`", "`const count = useCallback(() => items.length, [items])()`"], "answer": 1, "explain": "Don't wrap trivial property access like `array.length` or `obj.property` in `useMemo`; direct access is cheaper than memoization overhead."}, {"rule": "FE-007", "prompt": "```tsx\nfunction UserInfo({ user }: Props) {\n  return <div className='user-info'>{user ? user.name : ''}</div>\n}\n```\nWhat's the preferred rewrite?", "choices": ["Render `<div className='user-info' hidden={!user}>` instead", "Render a `<Placeholder />` when `user` is missing", "`if (!user) return null` before rendering the `<div>`", "Use `{user?.name ?? ''}` to shorten the expression"], "answer": 2, "explain": "Return `null` early when there's no data, instead of rendering empty containers or placeholder markup that add unnecessary DOM nodes."}, {"rule": "FE-008", "prompt": "You're exposing a new Mojo API to React components and need a context plus provider. What should you use?", "choices": ["A hand-written `React.createContext` plus a custom Provider for this API", "A global singleton module that components import directly", "Redux, with the Mojo remote stored in the store", "The `generateReactContext` helper from `$web-common/api/react_api`"], "answer": 3, "explain": "Use `generateReactContext` from `$web-common/api/react_api` for Mojo API context/provider pairs rather than custom boilerplate per API."}, {"rule": "FE-009", "prompt": "Which state update follows the front-end guidance?", "choices": ["`setPartialState({ isLoading: true })`", "`setState({ ...state, isLoading: true })`", "`setState(Object.assign({}, state, { isLoading: true }))`", "`state.isLoading = true; setState(state)`"], "answer": 0, "explain": "Prefer partial update functions over spreading the whole state object and overriding one field; it's more efficient and less error-prone."}, {"rule": "FE-010", "prompt": "Which CSS follows the Leo design system guidance?", "choices": ["`color: var(--leo-color-text-primary, #000);`", "`color: var(--leo-color-text-primary);`", "`color: var(--leo-color-text-primary, inherit);`", "`color: #000; color: var(--leo-color-text-primary);`"], "answer": 1, "explain": "Never give fallback values for Leo CSS variables. They're guaranteed to be set, and defaults can mask theming bugs."}, {"rule": "FE-012", "prompt": "A PR adds a new panel with several tightly-coupled sub-components and one Storybook story that exercises the full panel in its main states. A reviewer wants a story per sub-component. What does the guidance say?", "choices": ["Every new component, including sub-components, needs its own story before merging", "Stories are only required for components in the shared component library", "One integrated story covering the main states is enough; don't insist on more", "Replace the story with snapshot tests, which cover the same states more cheaply"], "answer": 2, "explain": "New UI should have Storybook stories for its primary visual states, but a single integrated story can suffice. It's a preference, not a requirement; never insist on more stories."}, {"rule": "FE-013", "prompt": "```ts\nif (value instanceof mojom.ConversationTurn) {\n  handleTurn(value)\n}\n```\nWhy is this a bug in WebUI code?", "choices": ["`instanceof` is slow on mojom structs; use `typeof value === 'object'` instead", "It works, but mojom types should be compared with `===`", "`ConversationTurn` must be imported from a `.mojom-lite.js` file for `instanceof` to work", "Mojom TS bindings generate interfaces, not classes; use a type guard instead"], "answer": 3, "explain": "TypeScript WebUI mojom bindings generate interfaces, not classes, so `instanceof` checks don't work. Use type guards or discriminated unions."}, {"rule": "FE-014", "prompt": "A new WebUI at `brave://rewards-panel` can't find its resources at runtime. What's the most likely cause?", "choices": ["The files aren't in a top-level `resources/` directory named after the WebUI host", "The resources need a `?v=` cache-busting query string to be served at runtime", "WebUI resources must be inlined into the HTML file by the `grit` build step", "The resources are TypeScript instead of the transpiled JavaScript the loader expects"], "answer": 0, "explain": "WebUI resource files must be in the top-level directory under `resources/` that matches the WebUI host name; misplaced resources won't be found at runtime."}, {"rule": "FE-015", "prompt": "A plain HTML element's only job is to open a help article URL. No design-system component is involved. Which is preferred?", "choices": ["`<button onClick={() => window.open(url)}>Visit</button>`", "`<a href={url} target=\"_blank\" rel=\"noopener\">Visit</a>`", "`<div role=\"link\" onClick={() => location.assign(url)}>Visit</div>`", "`<span onClick={() => window.open(url)}>Visit</span>`"], "answer": 1, "explain": "Use a real `<a>` link when the only action is navigation; it's semantic and shows the destination on hover. Exception: a Nala/Leo design-system button takes precedence for consistency."}, {"rule": "FE-016", "prompt": "```tsx\nconst { rerender } = render(<Counter count={1} />)\nrerender(<Counter count={2} />)\nawait waitFor(() => expect(screen.getByText('2')).toBeInTheDocument())\n```\nWhat should the reviewer suggest?", "choices": ["Increase the `waitFor` timeout so the assertion doesn't flake on CI", "Wrap `rerender` in `setTimeout` before `waitFor`", "Drop `waitFor`; `rerender` is synchronous, so assert directly", "Replace `rerender` with a fresh `render` call"], "answer": 2, "explain": "`rerender` is synchronous (and `act()` applies pending updates), so `waitFor` isn't needed. Unnecessary `waitFor` slows tests and can mask timing bugs."}, {"rule": "FE-017", "prompt": "A rich-text editor component reads `window.getSelection()` to find the caret. The page may show two editors at once. What should the reviewer raise?", "choices": ["Nothing; `window.getSelection()` always refers to the currently focused editor", "Cache the selection in a module-level variable shared by both editors", "Render only one editor per page so the global selection is unambiguous", "Pass a ref to the specific editor rather than reading the global selection"], "answer": 3, "explain": "For component-scoped operations, consider multiple instances on the page. Pass a ref to the specific instance rather than relying on global state."}, {"rule": "FE-018", "prompt": "A component exports this type for consumers:\n```ts\nexport type AttachmentSource =\n  | { kind: 'tab', tabId: number }\n  | { kind: 'file', file: File }\n```\nWhat does the guide require?", "choices": ["A documentation comment explaining the type's purpose", "Converting it to an `interface` so consumers can extend it", "Moving it to a `.d.ts` file", "Nothing; union types are self-documenting"], "answer": 0, "explain": "Exported TypeScript types meant for use outside the component must have doc comments, especially complex unions and data shapes used as component APIs."}, {"rule": "FE-022", "prompt": "A README contains this usage example:\n```tsx\n<div>Hello</div>\n<button onClick={api.reset()}>Reset</button>\n```\nWhat should the reviewer say?", "choices": ["It's illustrative pseudo-code, so validity doesn't matter", "Wrap the siblings in a fragment and use `onClick={() => api.reset()}`", "Only the fragment is missing; `onClick={api.reset()}` is valid JSX as written", "Convert it to plain text so readers don't copy-paste it"], "answer": 1, "explain": "Documentation code examples must be valid and compilable, because developers copy-paste them. Sibling elements need a fragment, and `onClick={fn()}` invokes immediately."}, {"rule": "FE-023", "prompt": "A WebUI page needs a small bit of extra JavaScript. A teammate adds an inline `<script>` tag to the HTML. Best response?", "choices": ["Inline scripts are fine for fewer than 20 lines", "Move it into a separate `.js` file loaded via `<script src>` from the same origin", "Add a TypeScript entry point (e.g. `patches.ts`) to the GN `entry_points`", "Put the code in an `onload` attribute on `<body>`"], "answer": 2, "explain": "Use compiled TypeScript entry points instead of inline `<script>` tags. You get type checking, code analysis, and consistent bundling; add entry points in the GN build config."}, {"rule": "FE-024", "prompt": "A PR adds a new `class SettingsCard extends React.Component` that holds an `isExpanded` state flag. What should the reviewer request?", "choices": ["Convert it to `React.PureComponent` for performance", "Nothing; class components are still fine for simple stateful UI like this", "Move the state into the parent and keep the class", "Rewrite it as a function component with hooks like `useState`"], "answer": 3, "explain": "Write React components as functions with hooks. The only valid class exception is an error boundary (`componentDidCatch` has no hook equivalent)."}, {"rule": "FE-025", "prompt": "A refactor changes `isDirty |= updateFileTimestamps(file)` to a boolean form. `updateFileTimestamps` writes to disk. Which version is correct?", "choices": ["`isDirty = updateFileTimestamps(file) || isDirty`", "`isDirty ||= updateFileTimestamps(file)`", "`isDirty = isDirty || updateFileTimestamps(file)`", "`isDirty = Boolean(isDirty || updateFileTimestamps(file))`"], "answer": 0, "explain": "`||` short-circuits: once `isDirty` is true, the right side never runs. Put the side-effecting call on the left so it always executes."}, {"rule": "FE-026", "prompt": "A WebUI HTML file has:\n```html\n<style>\n  body { background: #111114; }\n</style>\n```\nA PR changes it to `var(--leo-color-container-background)` \"for consistency.\" What should the reviewer say?", "choices": ["Approve; design tokens should always replace hardcoded colors for theming", "Keep the hardcoded value; Leo tokens load async, so the change causes a FOUC", "Approve, but add `#111114` as the `var()` fallback so it never flashes", "Move the style into the TypeScript entry point so it applies with the tokens"], "answer": 1, "explain": "Keep hardcoded initial body/root colors in WebUI HTML. Tokens like `--leo-color-container-background` load via JavaScript, so using them at first paint causes a flash of unstyled content."}, {"rule": "FE-030", "prompt": "A component parses a server-provided config with `useMemo(() => JSON.parse(rawData), [rawData])`. What's the concern?", "choices": ["`useMemo` shouldn't be used for parsing; use `useEffect`", "`JSON.parse` is too slow for render paths; parse the config once on the server", "Malformed JSON throws and crashes the tree; wrap it in `try/catch` with a fallback", "No concern; a React error boundary will catch it and retry the parse on next render"], "answer": 2, "explain": "`JSON.parse` on external or server data in render paths (including `useMemo`) must be wrapped in `try/catch`; an uncaught `SyntaxError` crashes the whole tree."}, {"rule": "FE-027", "prompt": "```tsx\nit('renders', () => {\n  expect(render(<MyComponent />)).toBeTruthy()\n})\n```\nWhat's wrong with this test?", "choices": ["It should use `toBeDefined()` instead, since `toBeTruthy()` coerces the value", "It needs `await`, because `render()` returns a promise in React 18 tests", "Nothing; it's a valid smoke test that catches render-time exceptions", "`render()` always returns a truthy object; assert on rendered content instead"], "answer": 3, "explain": "`expect(render(...)).toBeTruthy()` tests nothing because `render()` always returns a truthy object. Assert on actual rendered content instead."}, {"rule": "FE-028", "prompt": "A news card receives article summaries containing HTML from a third-party feed. A PR renders them with `dangerouslySetInnerHTML`. Best response?", "choices": ["Build known-safe React elements; if raw HTML is unavoidable, sanitize it and get a security review", "Fine, as long as the feed is served over HTTPS from a trusted, contractually vetted partner domain", "Strip `<script>` tags and `on*` attributes with a regex, then use `dangerouslySetInnerHTML`", "Render it inside a sandboxed `<iframe srcdoc>` so any injected script runs isolated from the page"], "answer": 0, "explain": "Don't use `dangerouslySetInnerHTML` for external or untrusted HTML. Render known-safe elements via React components; if raw HTML is unavoidable, sanitize it and request a security review."}, {"rule": "FE-029", "prompt": "```tsx\nuseEffect(() => {\n  fetchData().then(setData)\n}, [])\n```\nWhat does the front-end guide want here?", "choices": ["Add `setData` to the dependency array so the linter's exhaustive-deps rule passes", "Return a cleanup that cancels the request, e.g. via `AbortController.abort()`", "Make the effect callback `async` and `await` the fetch so errors propagate", "Move the fetch into `useMemo` so it runs during render"], "answer": 1, "explain": "Async work started in `useEffect` must be cleaned up to avoid state updates on unmounted components. Use an `AbortController` or a ref-based cancellation flag."}, {"rule": "IOS-001", "prompt": "Which of these closures should be changed to capture `[weak self]`?\n\n```swift\n// A\ndataSource.onUpdate = { self.reloadData() }\n// B\nTask { await self.fetchData() }\n```", "choices": ["Both A and B — any closure referencing `self` can form a cycle", "Only A — it's stored; the fire-and-forget Task creates no cycle", "Only B — every `Task` must capture `[weak self]` to be safe", "Neither — Swift's ARC breaks closure cycles like these automatically"], "answer": 1, "explain": "Capture `[weak self]` in closures that outlive the scope (stored closures, callbacks). Fire-and-forget `Task {}` blocks that aren't stored don't create a retain cycle, so don't require it there."}, {"rule": "IOS-001", "prompt": "A view controller stores a task:\n\n```swift\nfetchTask = Task {\n  await self.fetchData()\n}\n```\n\nWhat should the reviewer say?", "choices": ["Fine — Tasks release their captures on completion, so no cycle can form", "Use `[weak self]` and `self?.fetchData()` since the Task is stored", "Use `Task.detached` so the closure doesn't implicitly capture `self`", "Add `[weak self]` to the inner `fetchData` call only, not the Task itself"], "answer": 1, "explain": "A Task stored as a property that strongly captures `self` is a retain cycle. Apply `[weak self]` to the root/outermost closure."}, {"rule": "IOS-002", "prompt": "You're adding a new SwiftUI view model that publishes a list of items. Which declaration follows the standard?", "choices": ["`class ViewModel: ObservableObject { @Published var items: [Item] = [] }`", "`struct ViewModel { @State var items: [Item] = [] }`", "`class ViewModel: ObservableObject { var items: [Item] = [] { willSet { objectWillChange.send() } } }`", "`@Observable class ViewModel { var items: [Item] = [] }`"], "answer": 3, "explain": "Prefer the `@Observable` macro (Observation framework) over Combine's `ObservableObject`/`@Published` — less boilerplate and better SwiftUI integration."}, {"rule": "IOS-003", "prompt": "```swift\n@MainActor\nclass MyViewController: UIViewController {\n  func refresh() {\n    Task { @MainActor in\n      tableView.reloadData()\n    }\n  }\n}\n```\n\nWhat should the reviewer note?", "choices": ["The Task needs `Task.detached { @MainActor in ... }` to avoid inheriting context", "`reloadData()` must be wrapped in `DispatchQueue.main.async` inside the Task", "The Task's `@MainActor` is redundant — it inherits isolation from the class", "Remove `@MainActor` from the class and keep it only on the Task where it's needed"], "answer": 2, "explain": "Tasks inherit actor isolation from their enclosing context, so `@MainActor` on a Task inside a `@MainActor` type is redundant. Mark UI methods/types `@MainActor` so async callers must await them."}, {"rule": "IOS-004", "prompt": "A PR gates a new API like this:\n\n```swift\nif ProcessInfo.processInfo.operatingSystemVersion.majorVersion >= 17 {\n  useNewAPI()\n}\n```\n\nBest review comment?", "choices": ["Use `if #available(iOS 17, *)` so the compiler enforces availability", "Fine, as long as there's a comment explaining which API needs iOS 17", "Use `UIDevice.current.systemVersion` string comparison for minor versions too", "Wrap it in `@available(iOS 17, *)` on the whole file so callers are gated"], "answer": 0, "explain": "Use `#available` rather than manual version comparisons — the compiler enforces correctness and warns when deployment targets change."}, {"rule": "IOS-005", "prompt": "Which snippet follows the preferred Swift idioms?", "choices": ["`let newest = items.sorted(by: { $0.date > $1.date }).first`", "`for item in items { guard item.isEnabled else { continue }; process(item) }`", "`guard let a = optionalA else { return }` followed by `guard let b = optionalB else { return }`", "`for item in items where item.isEnabled { process(item) }`"], "answer": 3, "explain": "Prefer concise Swift idioms: `for … where`, `max(by:)`/`min(by:)` instead of `sorted().first`, combined guard conditions, and expression-level `switch`."}, {"rule": "IOS-006", "prompt": "```swift\nlet allowedTypes: [String] = [\"image\", \"video\", \"audio\"]\nif allowedTypes.contains(type) { ... }\n```\n\nThis is only ever used for `contains`. What should change?", "choices": ["Declare it as `Set<String>` for O(1) membership testing", "Nothing — arrays are faster for small collections", "Use `allowedTypes.first(where:)` instead of `contains`", "Convert it to an enum with a `rawValue` lookup"], "answer": 0, "explain": "When the primary operation is membership testing, use `Set` — `Set.contains` is O(1) vs Array's O(n)."}, {"rule": "IOS-007", "prompt": "A new framework class is declared `open class TabsBarView`. Nothing outside the module subclasses it. Reviewer feedback?", "choices": ["Keep `open` so future modules can subclass it without a breaking change", "Make it `public` — `open` is only for types external modules subclass", "Make it `internal`; framework types should never be exposed as public API", "Mark it `final open` to allow external use while preventing overrides"], "answer": 1, "explain": "Default to `public`. `open` is only for when external modules must subclass or override — otherwise it needlessly exposes implementation details."}, {"rule": "IOS-008", "prompt": "Which way of creating a `TabType` from a Bool follows the standard?", "choices": ["`static func from(isPrivate: Bool) -> TabType` factory in an extension", "A global function `makeTabType(isPrivate:)` next to the enum definition", "`init(isPrivate: Bool)` assigning `self` in an extension on `TabType`", "`static let make: (Bool) -> TabType` closure property on the enum"], "answer": 2, "explain": "Prefer convenience initializers on enums over static factory methods — more idiomatic Swift."}, {"rule": "IOS-009", "prompt": "```swift\ninit(profile: ProfileIOS, isPrivate: Bool = false) { ... }\n```\n\nEvery caller must consciously decide whether the tab is private. What should the reviewer say?", "choices": ["Remove the default so callers must pass `isPrivate` explicitly", "Fine — defaults reduce boilerplate, and most tabs aren't private anyway", "Change the default to `true` so a forgotten argument is privacy-safe", "Make `isPrivate` an implicitly unwrapped optional so nil means \"unset\""], "answer": 0, "explain": "Don't provide default values for parameters callers should always specify — it prevents accidental use of an incorrect default."}, {"rule": "IOS-010", "prompt": "In a review you see two `var`s that are assigned once and never mutated: one is a stored property on a `final class`, the other is a property on a `struct`. What should you flag?", "choices": ["Both — always use `let` when a value isn't mutated, wherever it's declared", "Neither — `var` is the Swift default for stored properties on any type", "Only the class property; struct mutability is set at the usage site", "Only the struct property; class properties have reference semantics anyway"], "answer": 2, "explain": "Use `let` for single-assignment properties, but never flag `var` properties on structs — callers control struct mutability with `let`/`var` at the usage site."}, {"rule": "IOS-011", "prompt": "```swift\nclass SettingsViewController: UIViewController {\n  var tableView: UITableView!\n  override func viewDidLoad() {\n    super.viewDidLoad()\n    tableView = UITableView()\n  }\n}\n```\n\nWhat's the recommended fix?", "choices": ["Use `lazy var tableView = UITableView()` or init it in the initializer", "Keep it — `viewDidLoad` always runs before any access to `tableView`", "Change it to `weak var tableView: UITableView!` so the view owns it", "Use `unowned var tableView: UITableView` to avoid the optional entirely"], "answer": 0, "explain": "Avoid implicitly unwrapped optionals for properties set in `viewDidLoad` — they crash if accessed early. Use lazy properties, safe optionals, or initializer setup (use `lazy` when deferring work or needing `self`)."}, {"rule": "IOS-012", "prompt": "You're wrapping a callback-based `request.start { result in ... }` API as `async throws`. The request supports `cancel()`. What's the correct structure?", "choices": ["`withCheckedThrowingContinuation` alone — Swift propagates cancellation to the request", "Poll `Task.isCancelled` in a loop while the request runs, calling `request.cancel()`", "Wrap the request in `Task.detached` and cancel that Task from the caller when needed", "Wrap the continuation in `withTaskCancellationHandler`, calling `request.cancel()`"], "answer": 3, "explain": "When bridging callbacks with `withCheckedContinuation`, use `withTaskCancellationHandler` so Task cancellation propagates to the underlying request."}, {"rule": "IOS-013", "prompt": "```swift\nfunc fetchData(from url: URL, _ completionHandler: @escaping () -> Void) {\n  if url.scheme != \"https\" { return }\n  // ... eventually calls completionHandler()\n}\n```\n\nWhat's wrong?", "choices": ["The early return never calls `completionHandler`, so callers hang", "The handler should be `@Sendable` since it escapes to another thread", "Nothing — callers shouldn't be notified about invalid input", "It should throw instead of returning, since non-HTTPS is an error"], "answer": 0, "explain": "Always call completion handlers on every code path, including error and early returns — otherwise resources leak and callers may wait forever."}, {"rule": "IOS-014", "prompt": "A PR injects a script into a tab's web view with `webView.callAsyncJavaScript(...)`. What should the reviewer request?", "choices": ["Switch to `webView.evaluateJavaScript(...)` — it's simpler", "Wrap the call in `DispatchQueue.main.async`", "Use the `evaluateSafeJavaScript` wrapper instead", "Nothing — `callAsyncJavaScript` is the safe API"], "answer": 2, "explain": "Use `evaluateSafeJavaScript` rather than calling `callAsyncJavaScript` or `evaluateJavaScript` directly — the wrapper provides proper error handling and security checks."}, {"rule": "IOS-015", "prompt": "Which error model follows the standard?", "choices": ["`enum FetchError: Int { case networkError = 1; case parseError = 2 }` mapped to codes", "`let kFetchNetworkError = 1` constants returned from the function alongside the result", "`enum FetchError: Error { case networkFailure(URLError); case parseFailure(DecodingError) }`", "Return `nil` from the function and log the error code with `Logger` for debugging"], "answer": 2, "explain": "Model error states as Swift `Error` types, not integer codes — you get type safety, exhaustive switches, and better debugging."}, {"rule": "IOS-016", "prompt": "A new delegate protocol is proposed:\n\n```swift\nprotocol DownloadDelegate: AnyObject {\n  func downloadDidFinish(_ download: Download?)\n}\n```\n\nReviewer feedback?", "choices": ["Make it an implicitly unwrapped `Download!` so delegates can skip the nil check", "Fine — optional parameters are more flexible for future call sites", "Make the parameter non-optional; delegates shouldn't have to handle nil", "Change the protocol to `@objc optional` methods so conformers can opt out"], "answer": 2, "explain": "Delegate method parameters should be non-optional; the delegate should not need to handle nil values from the delegating object."}, {"rule": "IOS-017", "prompt": "The compiler warns \"variable was written to, but never read\" for a value you intentionally keep only for its side effect. What's the preferred fix?", "choices": ["Add `// swiftlint:disable` above it to silence the warning locally", "Assign it to `_` explicitly, e.g. `_ = variable`", "Add a dummy `print(variable)` so the value counts as read", "Mark the variable `@discardableResult` to suppress the warning"], "answer": 1, "explain": "Use `_ = variable` (assign to `_`) for intentionally unused values — it signals intent and silences the warning."}, {"rule": "IOS-018", "prompt": "Which SwiftUI snippet should replace `Text(\"Hello\").cornerRadius(8)`?", "choices": ["`Text(\"Hello\").clipShape(.rect(cornerRadius: 8))`", "`Text(\"Hello\").mask(RoundedRectangle(cornerRadius: 8))`", "`Text(\"Hello\").border(.clear, width: 8)`", "Nothing — `.cornerRadius()` is fine"], "answer": 0, "explain": "`.cornerRadius()` is deprecated; use `.clipShape(.rect(cornerRadius:))`."}, {"rule": "IOS-019", "prompt": "```swift\nText(\"Hello\")\n  .background(Color.blue)\n  .clipShape(RoundedRectangle(cornerRadius: 8))\n```\n\nThe goal is a rounded blue background. Best suggestion?", "choices": ["Use `.cornerRadius(8)` instead of `.clipShape`", "Swap the order of the two modifiers", "Use `.background(.blue, in: .rect(cornerRadius: 8))`", "Wrap it in a `ZStack` with a `RoundedRectangle` behind it"], "answer": 2, "explain": "Use `.background(_:in:)` with a shape parameter instead of layering `.background()` and `.clipShape()`."}, {"rule": "IOS-020", "prompt": "```swift\nVStack {\n  Text(\"Title\").padding(.bottom, 8)\n  Text(\"Subtitle\").padding(.bottom, 8)\n  Text(\"Body\")\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Use `VStack(spacing: 8)` and drop the per-child padding", "Use `Spacer().frame(height: 8)` between each child view", "Move the `.padding(.bottom, 8)` onto the `VStack` itself", "Nothing — per-child padding is more explicit and easier to tweak"], "answer": 0, "explain": "Use the `spacing` parameter on `VStack`/`HStack` instead of padding each child — cleaner and more maintainable."}, {"rule": "IOS-021", "prompt": "A SwiftUI `body` contains a 25-line inline `HStack { ... }` builder for a row header, nested inside a `List`. Reviewer feedback?", "choices": ["Fine as long as the `body` still type-checks quickly", "Extract it into a named `View` struct or computed property", "Wrap it in `AnyView` to help the compiler's type-checking", "Convert it into a `UIViewRepresentable` for better performance"], "answer": 1, "explain": "When an inline SwiftUI builder block exceeds a few lines, extract it into a named `View` struct or computed property for readability and reuse."}, {"rule": "IOS-022", "prompt": "You need to render a SwiftUI view inside a `UITableViewCell`. Which approach does the standard prefer?", "choices": ["Add a `UIHostingController`'s view as a subview of the cell and pin constraints", "Set `cell.contentConfiguration = UIHostingConfiguration { MySwiftUIView(...) }`", "Rewrite the row as a UIKit view, since SwiftUI can't live in table cells", "Wrap the SwiftUI view in a `UIViewRepresentable` and add it to the cell"], "answer": 1, "explain": "Use `UIHostingConfiguration` for SwiftUI in table/collection view cells instead of manually embedding a `UIHostingController`."}, {"rule": "IOS-023", "prompt": "```swift\noverride func layoutSubviews() {\n  super.layoutSubviews()\n  widthConstraint.constant = bounds.width / 2\n}\n```\n\nWhat's the problem?", "choices": ["`super.layoutSubviews()` must be called last, after constraints are updated", "Changing constraints in `layoutSubviews` risks layout loops; set them at setup", "It should call `layoutIfNeeded()` right after changing the constant", "Nothing — `layoutSubviews` is the right place for size-dependent constraints"], "answer": 1, "explain": "Never create or modify Auto Layout constraints in `layoutSubviews`; it causes infinite layout loops."}, {"rule": "IOS-024", "prompt": "After toggling a state that changes a constraint, a PR calls `setNeedsLayout()` followed by `layoutIfNeeded()`. What's the preferred call?", "choices": ["`setNeedsUpdateConstraints()`", "`setNeedsDisplay()`", "`invalidateIntrinsicContentSize()` then `layoutIfNeeded()`", "`view.layoutSubviews()` directly"], "answer": 0, "explain": "When constraints need to change, call `setNeedsUpdateConstraints()` — the constraint system handles the layout invalidation."}, {"rule": "IOS-025", "prompt": "A new screen must keep its bottom toolbar above the keyboard. The PR observes `keyboardWillShowNotification` and adjusts a bottom inset. Best review response?", "choices": ["Also observe `keyboardWillHideNotification` to reset the inset", "Constrain to `view.keyboardLayoutGuide.topAnchor` instead", "Use a fixed 300pt bottom inset when a text field is focused", "Wrap the screen in a `UIScrollView`"], "answer": 1, "explain": "Use `UIView.keyboardLayoutGuide` for keyboard-responsive layouts rather than manually observing keyboard notifications and adjusting insets."}, {"rule": "IOS-027", "prompt": "In a custom Brave panel (not a settings screen), which background color assignment is correct?", "choices": ["`UIColor(braveSystemName: .primary20)`", "`UIColor(red: 0.2, green: 0.4, blue: 0.8, alpha: 1)`", "`UIColor(hex: \"#3366CC\")`", "`.systemBlue`, since system colors support dark mode"], "answer": 0, "explain": "Use `UIColor(braveSystemName:)` instead of hard-coded colors for design-system consistency and dark mode. System colors are acceptable only in settings-like screens matching iOS default styling."}, {"rule": "IOS-028", "prompt": "A PR adds 60 lines of Brave Talk URL-handling logic directly inside `BVC+TabPolicyDecider.swift`. What should the reviewer request?", "choices": ["Move it into a `Tab` helper; keep the policy decider as thin delegation", "Move it into a separate `BVC+BraveTalk.swift` extension on BrowserViewController", "Put it in `TabState` so the Brave Talk handling travels with each tab", "It's fine — URL policy decisions belong in the policy decider file"], "answer": 0, "explain": "`BVC+TabObserver.swift` and `BVC+TabPolicyDecider.swift` should only contain thin delegation; feature-specific business logic belongs in `Tab` helpers."}, {"rule": "IOS-029", "prompt": "```swift\noverride func viewDidLoad() {\n  super.viewDidLoad()\n  setupTableView()       // reads self.dataSource\n  dataSource = makeDataSource()\n}\n```\n\nWhat should change?", "choices": ["Move `super.viewDidLoad()` to the end", "Set `dataSource` before calling `setupTableView()`", "Move `setupTableView()` to `viewDidAppear`", "Make `dataSource` an implicitly unwrapped optional"], "answer": 1, "explain": "In `viewDidLoad`, set properties before calling setup methods that depend on them — ordering bugs here are common and hard to debug."}, {"rule": "IOS-030", "prompt": "A new Objective-C header declares `- (void)loadURL:(NSURL *)url completion:(CompletionBlock)completion;` where completion may be nil. Which header shape follows the standard?", "choices": ["Annotate every pointer with `_Nonnull` individually; no macros", "Wrap in `NS_ASSUME_NONNULL_BEGIN/END` and mark `completion` as `nullable`", "Leave it unannotated — Swift will import pointers as implicitly unwrapped", "Mark the entire interface `nullable`"], "answer": 1, "explain": "All Obj-C headers should use `NS_ASSUME_NONNULL_BEGIN`/`NS_ASSUME_NONNULL_END` and explicitly annotate nullable parameters."}, {"rule": "IOS-031", "prompt": "`BraveUtils` exposes only class methods and should never be instantiated. How should its header prevent instantiation?", "choices": ["Declare `- (instancetype)init NS_UNAVAILABLE;`", "Declare both `init` and `+new` as `NS_UNAVAILABLE` — `new` is required", "Make `init` return `nil` in the implementation", "Add a comment saying not to instantiate it"], "answer": 0, "explain": "Mark `init` as `NS_UNAVAILABLE` for static-only Obj-C classes. Marking `new` isn't necessary since most usage is from Swift, which doesn't call `new`."}, {"rule": "IOS-032", "prompt": "A PR adds `OBJC_EXPORT` to a constant's declaration in the `.h` and again to its definition in the `.mm`. Reviewer feedback?", "choices": ["Correct — it must appear on both the declaration and definition", "Remove it from the header and keep it on the implementation", "Keep it only on the header declaration, not the implementation", "Replace it with `extern \"C\"` in both places for C++ linkage"], "answer": 2, "explain": "`OBJC_EXPORT` belongs only on the header declaration, not the implementation."}, {"rule": "IOS-033", "prompt": "An Obj-C factory method `+ (instancetype)walletServiceWithProfileIOS:(ProfileIOS *)p` imports into Swift with an awkward name. What's the recommended fix?", "choices": ["Add a Swift extension wrapper method with a nicer name", "Rename the Obj-C method itself using C-style naming", "Use `NS_REFINED_FOR_SWIFT` and leave the original hidden", "Annotate the declaration with `NS_SWIFT_NAME(...)`"], "answer": 3, "explain": "Use `NS_SWIFT_NAME` on Obj-C APIs to provide idiomatic Swift names — especially important for factory methods and C-style names."}, {"rule": "IOS-034", "prompt": "```objc\nif (string == @\"expected\") { ... }\n```\n\nWhat should the reviewer say?", "choices": ["Fine — string literals are interned, so `==` works for constant strings", "Use `[string compare:@\"expected\"] == 0`, which handles nil safely", "Use `isEqualToString:` — `==` compares pointer identity", "Cast both to `const char*` with `UTF8String` and compare via `strcmp`"], "answer": 2, "explain": "Never use `==`/`!=` for `NSString` comparison; use `isEqualToString:`. `==` compares pointers, not contents."}, {"rule": "IOS-035", "prompt": "Inside an `@implementation BraveWalletBridge` (an Obj-C class), how should a local variable holding the account count be named? And what about a member of a C++ class that holds an Obj-C type?", "choices": ["camelCase `accountCount` in Obj-C; `account_count_` in the C++ class", "`account_count` in both — Brave uses Chromium style for all native code", "`accountCount` in both — anything touching Obj-C types uses camelCase", "`kAccountCount` in the Obj-C class; `AccountCount` in the C++ class"], "answer": 0, "explain": "Use camelCase for Obj-C variables inside Obj-C classes/types; when Obj-C types are used inside C++ classes, follow C++ snake_case conventions."}, {"rule": "IOS-037", "prompt": "```objc\n__weak typeof(self) weakSelf = self;\ndispatch_async(queue, ^{\n  [weakSelf doWork];\n});\n```\n\nWhat should the reviewer ask for?", "choices": ["Capture `self` strongly — it's a one-shot block, so no cycle can persist", "Promote to a `__strong` `strongSelf` inside the block and bail if nil", "Use `__unsafe_unretained` instead of `__weak` to avoid the weak overhead", "Nothing — messaging a nil `weakSelf` is a safe no-op, so this is fine"], "answer": 1, "explain": "Do the weak/strong dance in posted tasks: convert `weakSelf` to a strong reference inside the block and bail if nil, so `self` can't vanish mid-use."}, {"rule": "IOS-038", "prompt": "A method returns an `NSArray *` property, but internally builds it as `NSMutableArray` and returns the mutable object directly. What's the guidance?", "choices": ["Return `[array copy]`; use `mutableCopy` only when mutability is needed", "Fine — `NSMutableArray` is a subclass of `NSArray`, so the type is honest", "Change the return type to `id` so callers don't assume immutability", "Always return `mutableCopy` so callers can safely modify their own copy"], "answer": 0, "explain": "Use `copy` for immutable and `mutableCopy` for mutable collections; passing a mutable collection where an immutable one is expected leads to subtle bugs."}, {"rule": "IOS-039", "prompt": "A new feature needs the rewards controller and does `let controller = BraveRewardsViewController.shared`. Best review response?", "choices": ["Fine — singletons are the standard way to share long-lived services", "Wrap `.shared` in a lazy property to defer access until first use", "Store `.shared` in a global constant to avoid repeated lookups", "Pass the controller in via the initializer instead"], "answer": 3, "explain": "No singletons for service access — pass dependencies through initializers, method parameters, or the `Tab`/`TabHelper` extension pattern."}, {"rule": "IOS-040", "prompt": "A feature needs to store per-tab data. Which approach is correct?", "choices": ["Add a stored property to `Tab` for each feature's data", "Use `objc_setAssociatedObject` to attach data to the tab", "Use a Tab Helper with the `TabDataValues` pattern", "Keep a global `[TabID: Data]` dictionary in the feature"], "answer": 2, "explain": "Tab-associated data should use the `TabDataValues` extension pattern, not stored properties or associated objects, for proper lifecycle management."}, {"rule": "IOS-041", "prompt": "A PR adds `var playlistItemCount: Int` to `TabState` so the Playlist feature can track it per tab. What should the reviewer say?", "choices": ["Fine — `TabState` is where per-tab data lives, so it belongs there", "Use a Tab Helper with `TabDataValues`; keep `TabState` minimal", "Make it optional so it doesn't affect other features using `TabState`", "Put it in `Preferences` keyed by tab ID so it survives app restarts"], "answer": 1, "explain": "Don't add feature data to `TabState` — it should remain a minimal model of core tab state. Use a Tab Helper with `TabDataValues`."}, {"rule": "IOS-042", "prompt": "A new `WalletViewModel` calls `BraveWallet.shared.keyringService` directly inside its methods. Reviewer feedback?", "choices": ["Fine — view models are the right layer to call SDK singletons", "Move the singleton call into the SwiftUI view to keep the model pure", "Inject the SDK dependency through the view model's initializer", "Cache the singleton in a `static let` to avoid repeated lookups"], "answer": 2, "explain": "View models must not import or reference SDK singletons directly; pass SDK dependencies through the initializer so they're testable."}, {"rule": "IOS-043", "prompt": "A closure registered at startup calls `GetApplicationContext()->...getLastUsedProfile()` each time it fires to get the profile. What's wrong?", "choices": ["The last-used profile can change; pass `ProfileIOS` in explicitly", "Nothing — it always returns the profile that registered the closure", "It should call `getLastUsedProfile()` once and cache it in a static", "It should use the original (non-incognito) profile instead"], "answer": 0, "explain": "Bind `ProfileIOS` directly into closures and initializers; don't call `getLastUsedProfile` at point of use because the last-used profile can change."}, {"rule": "IOS-044", "prompt": "Which approach follows the standard for a feature-flagged event handler?", "choices": ["Register the handler always; start `handle(event:)` with `guard FeatureFlags.isEnabled(.myFeature) else { return }`", "Check the flag in both registration and every handler call", "Read the flag once in `handle(event:)` and cache it", "Only register the handler `if FeatureFlags.isEnabled(.myFeature)`"], "answer": 3, "explain": "Feature flag checks should gate handler/observer registration, not runtime checks inside the handler — avoiding overhead when the feature is disabled."}, {"rule": "IOS-045", "prompt": "A PR adds `var isBraveSearchResultsPage: Bool` to a generic `extension URL` in a shared utilities file. Best response?", "choices": ["Fine — URL extensions are the natural home for URL classification checks", "Make it `fileprivate` in the generic extension to limit its visibility", "Move it into a feature-specific helper, not a generic URL extension", "Move it to the legacy `Shared` module next to the other URL helpers"], "answer": 2, "explain": "Feature-specific logic doesn't belong in generic utility extensions; create feature-specific helpers instead."}, {"rule": "IOS-046", "prompt": "A new iOS feature registers its prefs inside its service's `Init()` method. Where should pref registration go?", "choices": ["In the service's constructor, so it's close to usage", "In `AppDelegate.didFinishLaunching`", "In `browser_prefs.mm`", "In a Swift `Preferences` extension"], "answer": 2, "explain": "iOS preference registration goes in `browser_prefs.mm`, not arbitrary init methods."}, {"rule": "IOS-047", "prompt": "A metric needs the app's install date months after install. A PR reads `Preferences.DAU.installationDate`. What should the reviewer say?", "choices": ["Fine — `Preferences.DAU.installationDate` is the canonical install date", "Use `Preferences.P3A.installationDate`; the DAU one resets after 14 days", "Compute it from the app bundle's creation date via `FileManager`", "Store a new install-date pref in the caches directory on first launch"], "answer": 1, "explain": "`Preferences.DAU.installationDate` resets after 14 days; use `Preferences.P3A.installationDate` for a persistent installation date."}, {"rule": "IOS-048", "prompt": "A C++ observer fires correctly in unit tests, but the Swift UI never updates. The PR added the C++ observer and a Swift delegate protocol. What's the most likely gap?", "choices": ["The Swift delegate must be `@MainActor`, or callbacks are silently dropped", "C++ observers can't notify Swift directly; the UI needs to poll instead", "The bridge object between the C++ observer and Swift delegate isn't wired", "The Swift delegate must be a singleton so the C++ side can find it"], "answer": 2, "explain": "Wire the complete chain: C++ observer → bridge object → Obj-C/Swift delegate. Missing links are a common source of silent failures."}, {"rule": "IOS-049", "prompt": "A C++ class in `ios/browser` stores `ProfileIOS* profile_;`. Reviewer feedback?", "choices": ["Use `std::shared_ptr<ProfileIOS>`", "Use `ProfileIOS& profile_;` instead", "Use `raw_ptr<ProfileIOS> profile_;`", "Fine — raw pointers are allowed on iOS"], "answer": 2, "explain": "When a C++ class stores a pointer, use `raw_ptr<T>` instead of raw `T*` to enable Chromium's pointer safety checks."}, {"rule": "IOS-050", "prompt": "An iOS stub for a cross-platform interface method isn't implemented yet but may be called in practice. Which macro should it use?", "choices": ["`NOTREACHED()` — it documents the path is unsupported", "`CHECK(false)`", "`DCHECK(false)` only", "`NOTIMPLEMENTED()`"], "answer": 3, "explain": "`NOTREACHED()` crashes in release builds. Use `NOTIMPLEMENTED()` for paths that may be reached but aren't implemented yet; reserve `NOTREACHED()` for truly impossible paths."}, {"rule": "IOS-051", "prompt": "Which Mojo interface registration follows the standard?", "choices": ["`registry->Add(\"brave_wallet.mojom.JsonRpcService\", ...)`", "`registry->Add(kJsonRpcServiceName, ...)` with a local `constexpr char[]`", "`registry->Add(brave_wallet::mojom::JsonRpcService::Name_, ...)`", "`registry->Add(typeid(JsonRpcService).name(), ...)`"], "answer": 2, "explain": "Use the generated interface's `::Name_` constant when registering Mojo interfaces, not hard-coded strings."}, {"rule": "IOS-052", "prompt": "A feature saves a user's onboarding-completed state as a file under the app's Caches directory. What's the issue?", "choices": ["None — Caches is backed up to iCloud and persists across launches", "The system can purge Caches at any time, so the state may be lost", "Caches files are readable by other apps in the same app group", "It should use `/tmp` instead, which is cleared less aggressively"], "answer": 1, "explain": "Don't rely on the iOS caches directory for persistent state — the system can clear it at any time."}, {"rule": "IOS-053", "prompt": "A new feature adds user-facing strings to `SharedStrings.swift`. Reviewer feedback?", "choices": ["Fine — `SharedStrings.swift` is where all user-facing strings go", "Hard-code the English strings for now and localize them later", "Put them in the feature's own `Localizable.strings` without a Swift wrapper", "Add them to `BraveStrings`; `SharedStrings` is for legacy strings"], "answer": 3, "explain": "New user-facing strings go in `BraveStrings`, not `SharedStrings.swift`."}, {"rule": "IOS-054", "prompt": "You need a small helper shared by two new feature modules. A teammate suggests adding it to the `Shared` module since both already depend on it. Best response?", "choices": ["Create a new module; `Shared` is legacy and shouldn't grow", "Agree — a common dependency is exactly what `Shared` is for", "Copy the helper into both modules to avoid a new dependency", "Put it in `Shared` but mark it `@available(*, deprecated)`"], "answer": 0, "explain": "The `Shared` module is legacy — existing code can be used, but don't add new functionality. Create a new module for new shared code."}, {"rule": "IOS-055", "prompt": "You add tests for a class in `BraveCore/Wallet/`. Where should the test file live?", "choices": ["`BraveCoreTests/` root, alongside all other tests", "`BraveCore/Wallet/Tests/` next to the source", "`BraveCoreTests/Wallet/`", "`ClientTests/` since it's the main test target"], "answer": 2, "explain": "Test files should mirror the source module structure: `BraveCore/Wallet/` → `BraveCoreTests/Wallet/`."}, {"rule": "IOS-056", "prompt": "A new iOS feature needs to expose its pref names to Swift. A PR adds them to the shared `pref_names_bridge.h`. What should the reviewer suggest?", "choices": ["Hard-code the pref strings in Swift to avoid a bridge header", "Fine — keeping all pref names in one bridge header is simpler", "Move them to `SharedStrings.swift` alongside other shared constants", "Export them in a feature-specific header instead"], "answer": 3, "explain": "Export iOS pref constants in feature-specific headers, not a shared `pref_names_bridge.h`, to reduce coupling and make dependencies explicit."}, {"rule": "IOS-057", "prompt": "A new Obj-C wrapper around a mojom type is used by both browser and renderer-side code. Where should it go?", "choices": ["`ios/browser/`", "`ios/app/`", "`components/` next to the mojom", "`ios/common/`"], "answer": 3, "explain": "Mojom wrapper types belong in `ios/common/` because they're shared between processes; `ios/browser/` creates unnecessary layering constraints."}, {"rule": "IOS-058", "prompt": "You're adding (a) a plain Obj-C header that exposes a C++ type to Swift and (b) an iOS-specific implementation of a cross-platform interface. Which file names fit?", "choices": ["(a) `foo_ios.h`, (b) `foo_bridge.h`", "Both `foo_bridge.h`", "(a) `foo_swift.h`, (b) `foo_impl.h`", "(a) `foo_bridge.h`, (b) `foo_ios.h`"], "answer": 3, "explain": "Use `_bridge.h` for plain Obj-C wrapper headers exposing C++ to Swift, and `_ios.h` for iOS-specific implementations of cross-platform interfaces."}, {"rule": "IOS-059", "prompt": "What should the concrete iOS implementation of `BraveWalletService` be named?", "choices": ["`BraveWalletServiceImpl`", "`BraveWalletServiceIOS`", "`BraveWalletService_ios`", "`IOSBraveWalletService`"], "answer": 0, "explain": "Name concrete implementations with the `Impl` suffix, not a platform suffix like `_ios`."}, {"rule": "IOS-060", "prompt": "A PR is ready except it still contains `print(\"DEBUG tabs:\", tabs)` and a commented-out old implementation. One log line is genuinely useful. What should happen?", "choices": ["Remove the prints and dead code; use `Logger` for the useful line", "Leave them — they help future debugging and cost nothing at runtime", "Wrap the prints in `#if DEBUG` so they never ship in release builds", "Convert all of them to `NSLog` so they show up in device logs"], "answer": 0, "explain": "Remove debug `print` statements and dead code before submitting; use `Logger` instead of `print` for logging that should stay."}, {"rule": "IOS-061", "prompt": "A UI refactor replaces a `UIButton` (which had `accessibilityLabel = Strings.close`) with a new SwiftUI button. What should the reviewer verify?", "choices": ["Nothing — SwiftUI generates labels from the icon name automatically", "That accessibility labels are removed since SwiftUI handles it", "That the new button keeps an accessibility label for VoiceOver", "That the button has a tooltip"], "answer": 2, "explain": "Always set accessibility labels on interactive elements, and verify they're preserved when refactoring UI — VoiceOver users depend on them."}, {"rule": "IOS-063", "prompt": "You need small thumbnails of large tab screenshots. Which approach does the standard prefer?", "choices": ["Draw into a `UIGraphicsImageRenderer` at the target size", "Use `UIImage.prepareThumbnail(of:)`", "Set `UIImageView.contentMode` and let it scale", "Use Core Image's `CILanczosScaleTransform`"], "answer": 1, "explain": "Use `UIImage.prepareThumbnail(of:)` instead of manual `UIGraphicsImageRenderer` resizing — it's optimized for memory and performance."}, {"rule": "IOS-064", "prompt": "An injected web page (e.g. an internal error page) needs a dark mode. The PR toggles a `.dark` class via JavaScript when the app theme changes. Best suggestion?", "choices": ["Fine — JS toggling is more flexible", "Inject inline styles from Swift on each theme change", "Render two copies of the page and swap them", "Use CSS `@media (prefers-color-scheme: dark)`"], "answer": 3, "explain": "For injected web content, prefer CSS `@media (prefers-color-scheme: dark)` over toggling CSS classes via JavaScript."}, {"rule": "IOS-065", "prompt": "You want to call `.scrollBounceBehavior(_:)` (iOS 17+) on a codebase that still supports iOS 16, with a no-op fallback that disappears automatically once the deployment target is raised. How?", "choices": ["Wrap each call site in `if #available(iOS 17, *)` with an empty else branch", "A same-named `View` extension, `@_disfavoredOverload` and obsoleted in 17", "Add a differently named `braveScrollBounceBehavior` extension that forwards", "Mark a same-named fallback `@available(iOS, deprecated: 17.0)` as a reminder"], "answer": 1, "explain": "Backport with `@_disfavoredOverload` + `@available(iOS, obsoleted:)` to create a transparent fallback that vanishes automatically when the deployment target is raised."}, {"rule": "IOS-066", "prompt": "```swift\ntry await Task.sleep(nanoseconds: 500_000_000)\n```\n\nThis appears with no context in a PR. What should the reviewer ask for?", "choices": ["Replace it with `DispatchQueue.main.asyncAfter`", "Increase it to 1 second to be safe", "Nothing — short delays are harmless", "A comment explaining why the delay is necessary"], "answer": 3, "explain": "Artificial delays like `Task.sleep` must have a comment explaining why they're needed; unexplained delays are a code smell that may hide race conditions."}, {"rule": "IOS-067", "prompt": "A media player shows elapsed time using `String(format: \"%02d:%02d\", minutes, seconds)`. Reviewer suggestion?", "choices": ["Use a `DateFormatter` with the `\"mm:ss\"` format", "Use `Duration.formatted()` / `TimestampFormatStyle`", "Fine — `String(format:)` is the simplest approach", "Use string interpolation with zero-padding helpers"], "answer": 1, "explain": "Use `TimestampFormatStyle` or `Duration.formatted()` for durations instead of manual string formatting."}, {"rule": "IOS-068", "prompt": "A class adds `private var waitForReadyCancellable: AnyCancellable?` just to wait for a single value once during setup. Reviewer feedback?", "choices": ["Fine — cancellables must always be stored as properties", "Store it in a `Set<AnyCancellable>` instead", "Use `.sink` without keeping a cancellable at all", "Use a local variable for the short-lived cancellable"], "answer": 3, "explain": "For temporary Combine subscriptions (e.g. waiting for one value), prefer a local variable over a stored property to avoid accumulating dead subscriptions."}, {"rule": "IOS-069", "prompt": "```swift\nfunc requestPermission() async -> Bool {\n  await withCheckedContinuation { continuation in\n    pendingContinuation = continuation\n    delegate?.showPermissionPrompt()\n  }\n}\n```\n\nWhat's the risk, and the fix?", "choices": ["If `delegate` is nil it never resumes — check the delegate first", "The continuation may be resumed twice by the prompt; add a lock around it", "It must use `withCheckedThrowingContinuation` so a denial can throw", "It's missing `[weak self]`; add it to the closure to avoid a retain cycle"], "answer": 0, "explain": "When a continuation depends on a delegate callback, check the delegate is set before entering `withCheckedContinuation`, or the task can hang forever."}, {"rule": "IOS-070", "prompt": "A new primary button is styled as a full capsule, though the design doesn't call for it. What shape does the standard expect?", "choices": ["Capsule — it's the iOS default for primary buttons", "Rounded rectangle, consistent with Nala", "Sharp corners for a cleaner, more modern look", "Circle, so every button shares one shape"], "answer": 1, "explain": "Buttons should use rounded rectangle shapes consistent with Nala; avoid capsule or sharp-cornered buttons unless the design calls for it."}, {"rule": "IOS-071", "prompt": "To customize `ChromeViewController` via chromium_src on iOS, which approach is preferred?", "choices": ["`#define ChromeViewController BraveViewController` around an `#include`, then `#undef`", "Copy the upstream `.mm` into chromium_src and edit the copy so upstream stays untouched", "Patch the upstream file directly with a small, clearly commented `.patch` file", "Swizzle methods at runtime with `method_exchangeImplementations` in a Brave category"], "answer": 0, "explain": "Prefer subclassing over duplication using the `#define`/`#include`/`#undef` pattern to substitute a Brave subclass, with blank lines around the wrapped include."}, {"rule": "IOS-074", "prompt": "A feature should default to enabled on iOS but disabled elsewhere. A PR adds `#if BUILDFLAG(IS_IOS)` in the feature definition `.cc`. Preferred approach?", "choices": ["Keep the `#if` — it's the clearest way to express a platform default", "Toggle it at runtime from Swift on launch via the feature list", "Use a Griffin study only, so the default stays the same everywhere", "Use a GN build argument to set the platform-specific default"], "answer": 3, "explain": "Use GN build args (not C++ source) for platform-specific feature defaults — it allows build-time configuration and reduces `#ifdef` clutter."}, {"rule": "IOS-075", "prompt": "A PR adds a new iOS unit test target `brave_ios_rewards_unittests` but doesn't touch any aggregate target. What's the consequence?", "choices": ["None — CI discovers all `*_unittests` targets automatically", "The tests only run in release builds, not on debug bots", "The tests run but their results aren't reported to the PR", "They never run on CI; add it to `brave_all_unit_tests`"], "answer": 3, "explain": "Every new iOS test target must be included in `brave_all_unit_tests`; otherwise it never runs on CI."}, {"rule": "IOS-076", "prompt": "In an iOS bridge header, a flag is exposed as `kBraveNewsFeedV2` but the C++ `base::Feature` is named `kBraveNewsFeedUpdate`. Why does this matter?", "choices": ["It doesn't — the bridge name is cosmetic as long as it compiles", "It breaks the build, since the bridge macro expects matching names", "Mismatched names fail silently: the flag appears to work but doesn't", "Only the Swift name matters, because Griffin reads it from the bridge"], "answer": 2, "explain": "Feature flag names in iOS bridge headers must exactly match the C++ `base::Feature` names, or the flag silently fails to control the feature."}, {"rule": "IOS-077", "prompt": "A new `UIImageView` shows a downloaded favicon with no `contentMode` or size constraints, and some icons blow out the layout. What's the fix?", "choices": ["Resize every downloaded favicon to 24×24 before display", "Call `sizeToFit()` on the image view after setting the image", "Set an explicit `contentMode` or size constraints", "Use `withRenderingMode(.alwaysTemplate)` on the image"], "answer": 2, "explain": "Set explicit `contentMode` or size constraints on `UIImageView`/SwiftUI `Image` (e.g. `.resizable().frame(maxWidth:maxHeight:)`); otherwise images display at natural size."}, {"rule": "IOS-078", "prompt": "Which icon-only SwiftUI delete button follows the standard?", "choices": ["`Button { … } label: { Image(braveSystemName: \"leo.trash\") }`", "`Button { … } label: { Image(braveSystemName: \"leo.trash\").accessibilityHidden(true) }`", "`Button(\"\") { … }.overlay(Image(braveSystemName: \"leo.trash\")).accessibilityLabel(\"Delete\")`", "`Button { … } label: { Label(\"Delete\", braveSystemImage: \"leo.trash\") }.labelStyle(.iconOnly)`"], "answer": 3, "explain": "Use `Label` with `.labelStyle(.iconOnly)` for icon-only buttons so accessibility information is provided automatically."}, {"rule": "IOS-079", "prompt": "A new toolbar needs a trash icon. Which is correct?", "choices": ["`Image(systemName: \"trash\")`", "`Image(\"trash\")` from a bundled PNG", "`Image(uiImage: UIImage(systemName: \"trash\")!)`", "`Image(braveSystemName: \"leo.trash\")`"], "answer": 3, "explain": "Use Nala (Leo) icons via `Image(braveSystemName:)` instead of Apple's `Image(systemName:)` for design-system consistency."}, {"rule": "IOS-080", "prompt": "```swift\nImage(braveSystemName: \"leo.trash\")\n  .resizable()\n  .frame(width: 24, height: 24)\n```\n\nWhat should the reviewer suggest?", "choices": ["Add `.aspectRatio(contentMode: .fit)` so the glyph isn't distorted", "Use `.scaleEffect(1.5)` instead of `.frame` to keep it crisp", "Nothing — `.resizable().frame(...)` is the right way to size images", "Size it with a font, e.g. `.font(.title3)`, like an SF Symbol"], "answer": 3, "explain": "Nala icons are custom SF Symbols; treat them like font glyphs and size them with `.font()`, not `.resizable().frame()`."}, {"rule": "IOS-081", "prompt": "A design calls for a 15pt caption. Which implementation is acceptable?", "choices": ["A semantic style like `.subheadline`, or a `@ScaledMetric` size", "`.font(.system(size: 15))`, matching the design spec exactly", "`.font(.custom(\"SF Pro\", fixedSize: 15))` for a stable layout", "`UIFont.systemFont(ofSize: 15)` in UIKit, bridged into the view"], "answer": 0, "explain": "Don't use explicit font sizes — respect Dynamic Type with semantic styles. If a custom value is needed, use `@ScaledMetric` (SwiftUI) or `UIFontMetrics` (UIKit)."}, {"rule": "IOS-082", "prompt": "```swift\nstruct ContentView: View {\n  @State private var value: Int\n  init(value: Int) {\n    self._value = State(wrappedValue: value)\n  }\n  ...\n}\n```\n\nWhat should the reviewer say?", "choices": ["Fine — `State(wrappedValue:)` is the documented way to seed `@State`", "Don't seed `@State` in `init`; assign it in `.onAppear` or `.task`", "Change `@State` to `@Binding` so the parent owns the initial value", "Make `value` a `static var` so it's shared and survives view updates"], "answer": 1, "explain": "Assigning `@State` in `init` via `State(wrappedValue:)` can cause undefined behavior on later body computations. Pass the initial value and assign it in `onAppear` or `task`."}, {"rule": "IOS-083", "prompt": "```swift\nToggle(\"Setting\", isOn: Binding(\n  get: { isEnabled },\n  set: { isEnabled = $0; performSomeWork() }\n))\n```\n\nBest review suggestion?", "choices": ["Fine — a custom `Binding` is the idiomatic way to add side effects", "Use `$isEnabled` and do the work in `.onChange(of: isEnabled)`", "Wrap `performSomeWork()` in `DispatchQueue.main.async` inside `set`", "Use `Binding.constant(isEnabled)` and call the work from the toggle"], "answer": 1, "explain": "Avoid `Binding(get:set:)` for side effects or transforms — SwiftUI can't tell if the graph changed, causing unnecessary rebuilds. Use `onChange`/`didSet` for side effects, and helpers or subscripts on the type for transforms (e.g. `$value.isPresented`)."}, {"rule": "LOC-001", "prompt": "```xml\n<message name=\"IDS_FOO_TITLE\" desc=\"Title for the Foo settings section\"\n         translateable=\"true\">\n  Foo\n</message>\n```\n\nWhat should the reviewer say about this `.grdp` entry?", "choices": ["Good — always mark strings explicitly translateable so the tooling picks them up", "Change it to `translatable=\"true\"` (correct spelling)", "Remove it — `translateable=\"true\"` is the default", "Replace it with `translateable=\"false\"` for settings titles"], "answer": 2, "explain": "`translateable=\"true\"` is the default in GRD/GRDP files, so never add it explicitly. Only `translateable=\"false\"` is meaningful to the tooling."}, {"rule": "LOC-002", "prompt": "Which menu-item string follows Brave's UI text conventions?", "choices": ["`Save page as...`", "`Save page as . . .`", "`Save page as`", "`Save page as…`"], "answer": 3, "explain": "Use the proper Unicode ellipsis character `…` instead of three periods `...` in user-facing strings."}, {"rule": "LOC-003", "prompt": "Which `desc` best serves translators for a string whose text is just \"History\"?", "choices": ["`desc=\"History\"`", "`desc=\"Title for the browser visits history section of a URL picker\"`", "`desc=\"History text shown in the URL picker, translate as appropriate\"`", "`desc=\"\"` (left empty since the text is self-explanatory)"], "answer": 1, "explain": "Translators often see only the description, so add context: the UI element type and disambiguation (browser vs. conversation history). Never leave `desc` empty — though for truly self-evident strings like \"Cancel\", a brief description is fine."}, {"rule": "LOC-003", "prompt": "A reviewer insists a `Cancel` button string needs a three-sentence description. Another string uses the same copy-pasted `desc` as an unrelated tooltip. Which feedback is valid?", "choices": ["Only the copy-pasted `desc` needs fixing", "Both are fine; descriptions are optional as long as the string text is clear", "Both need fixing: every `desc` must be several sentences", "Only the `Cancel` one needs fixing; reusing descriptions is encouraged"], "answer": 0, "explain": "Each description must be unique to its purpose, specify the UI element type, and be proofread. But don't insist on verbose descriptions for strings that speak for themselves."}, {"rule": "LOC-004", "prompt": "In a new Lit-based WebUI component, how should localized strings be accessed?", "choices": ["Call `loadTimeData.getString()` directly in `render()`", "Hardcode English and let the build translate it", "Use `I18nMixinLit`", "Fetch strings over a mojo call at startup"], "answer": 2, "explain": "In Lit WebUI components, use `I18nMixinLit` instead of calling `loadTimeData.getString()` directly — it's the standard, consistent i18n approach."}, {"rule": "LOC-005", "prompt": "You need to change the wording of an upstream string defined in `app/generated_resources.grd`. What's the correct approach?", "choices": ["Edit the text directly in `app/generated_resources.grd`", "Patch `app/generated_resources.grd` and regenerate with `pnpm run update_patches`", "Edit each locale's `.xtb` file with the new translation", "Add a Brave string and redirect the upstream `IDS_` via chromium_src"], "answer": 3, "explain": "Never modify upstream GRD/GRDP files — they're replaced on every Chromium bump. Add the string to the Brave GRD/GRDP and redirect the upstream `IDS_` constant via a chromium_src `#undef`/`#define`."}, {"rule": "LOC-006", "prompt": "Brave needs a simple word substitution applied across many upstream strings in all locales. What's the recommended tool?", "choices": ["`grd_string_replacements.py` with `default_replacements`", "A chromium_src `#undef`/`#define` override for each affected `IDS_` constant", "Manually edit each upstream GRD file and all its `.xtb` translations", "A runtime string replace in `l10n_util::GetStringUTF16`"], "answer": 0, "explain": "For simple word/phrase substitutions across upstream strings, use `brave/script/lib/l10n/grd_string_replacements.py` with `default_replacements` and `pnpm run chromium_rebase_l10n` — it applies consistently across all locales."}, {"rule": "LOC-007", "prompt": "You add a string to the AI Chat WebUI GRDP file, whose WebUI component is `AiChat`. Which attribute is correct?", "choices": ["`formatter_data=\"webui=AIChat\"`", "`formatter_data=\"webui=AiChat\"`", "`formatter_data=\"webui=ai_chat\"`", "No `formatter_data` — the build infers it from the file path"], "answer": 1, "explain": "WebUI GRDP strings need `formatter_data=\"webui=ComponentName\"` that exactly matches the WebUI component identifier; a typo or mismatch means the string won't be in that bundle."}, {"rule": "LOC-008", "prompt": "Which placeholder follows the GRD/GRDP standard?", "choices": ["`<ph name=\"SITE_NAME\">$1<ex>example.com</ex></ph>`", "`<ph name=\"PH_1\">$1</ph>`", "`<ph name=\"siteName\">$1<ex>example.com</ex></ph>`", "`<ph name=\"SITE_NAME\">$1</ph>` (examples are optional)"], "answer": 0, "explain": "Placeholders need descriptive SCREAMING_SNAKE_CASE names and an `<ex>` example showing translators the runtime value. Use `LINK_BEGIN`/`LINK_END` for link placeholders."}, {"rule": "LOC-009", "prompt": "A settings group has two sibling toggle labels: \"Background Image\" and \"Brave backgrounds\". What's the reviewer's feedback?", "choices": ["Fine — each string can choose its own capitalization based on its own content", "Both should be all lowercase for a modern look", "Only the first word of a label may ever be capitalized", "Same level, mixed title and sentence case; make them consistent"], "answer": 3, "explain": "Strings within a feature or UI surface must use consistent capitalization. Title case is for page titles, section headers, buttons, and menu items; sentence case for descriptions, body text, tooltips, and helper text."}, {"rule": "LOC-010", "prompt": "Which string follows Brave's UI text conventions?", "choices": ["\"Sync bookmarks, passwords, etc. with Shields on\"", "\"Sync our bookmarks, passwords, and more with Shields on\"", "\"Sync bookmarks, passwords, and more with Shields up\"", "\"Sync bookmarks, passwords, etc. with Shields up\""], "answer": 2, "explain": "Use \"and more\" instead of \"etc.\", \"Brave's\" instead of \"our\", and match established feature vocabulary (Shields are \"up/down\", not \"on/off\")."}, {"rule": "LOC-010", "prompt": "Which description is better for a button that shares open tabs with the AI assistant?", "choices": ["\"Send your tabs' contents\"", "\"Send the content of your tabs to Brave AI\"", "\"Send your tabs\"", "\"Send our tabs' contents to our AI assistant\""], "answer": 1, "explain": "Be explicit about data-sharing actions (say where data goes), avoid possessive constructions like \"tabs' contents\" for translatability, and use \"Brave\" rather than \"our\"."}, {"rule": "LOC-011", "prompt": "A PR adds five new `IDS_` strings to a GRDP \"for an upcoming follow-up\", but none are referenced in code yet. What should the reviewer say?", "choices": ["Fine — adding strings early gives translators a head start before the feature lands", "Fine, as long as they're marked `translateable=\"true\"`", "Remove them until code references them; every string goes to translation", "Keep them but give them empty descriptions"], "answer": 2, "explain": "Only add GRD/GRDP strings that are actively referenced in the codebase, and remove strings that become unused. Reviewers should verify each `IDS_` constant is actually used."}, {"rule": "LOC-012", "prompt": "After a Chromium rebase, new upstream strings mention \"Google Pay\" and \"Gemini\". What's expected?", "choices": ["Review them and replace Google product names with Brave branding", "Leave them — upstream strings are never shown in Brave", "Replace \"Google Pay\" with \"Brave Wallet\" everywhere it appears in the new strings", "Wait for users to report the branding issue"], "answer": 0, "explain": "During rebases, review new upstream strings for Google product names and ensure correct Brave branding. Note \"Brave Wallet\" means the crypto wallet only — not general autofill/payment cards."}, {"rule": "LOC-013", "prompt": "```tsx\ngetLocale(`CHAT_UI_${model.key.toUpperCase().replaceAll('-', '_')}_SUBTITLE`)\n```\n\nWhat's the problem?", "choices": ["Template literals are slower than string concatenation", "It should use `toLowerCase()` to match key conventions", "Nothing, provided every model key has a matching string defined in the GRDP", "It defeats static analysis and dead-string detection"], "answer": 3, "explain": "Never construct `getLocale()` keys dynamically — it defeats static analysis, prevents dead string detection, and breaks if key formats change. Use explicit keys like `S.CHAT_UI_CLAUDE_SUBTITLE`, or have the data source provide the string."}, {"rule": "LOC-014", "prompt": "```cpp\nhtml_source->AddString(\n    \"sectionDescription\",\n    l10n_util::GetStringFUTF16(IDS_SECTION_DESCRIPTION, kLearnMoreURL));\n```\n\nWhat's the recommended alternative?", "choices": ["Embed the full `<a href>` markup into the GRD string itself so translators see it", "Pass the URL as a separate string; build the link in the UI", "Keep it, but escape the URL with `base::EscapeForHTML`", "Hardcode the URL into each locale's translation"], "answer": 1, "explain": "Build links in the UI, not in localized strings. Pass the URL separately (via `AddString` or a mojom constant) instead of formatting it into the localized string in C++."}, {"rule": "LOC-015", "prompt": "Which settings toggle description is punctuated correctly?", "choices": ["\"Block trackers on all sites.\" (single sentence, with period)", "\"Block trackers on all sites\" (single sentence, no period)", "\"Block trackers on all sites. This may break some sites\" (no final period)", "\"Block trackers on all sites!\" (exclamation)"], "answer": 1, "explain": "Single-sentence toggle descriptions don't end with a period; multi-sentence descriptions do end with a period on the last sentence."}, {"rule": "LOC-016", "prompt": "A string reviewer sees: \"Some extensions are non compatible on this page and\". What should they flag?", "choices": ["Nothing — translators will clean up the grammar in each language anyway", "Only that it should be in title case", "It's truncated, and \"non compatible\" needs a hyphen", "Only that it should end with an ellipsis"], "answer": 2, "explain": "Strings must be complete, grammatically correct, and properly punctuated — no truncated sentences, hyphenated compound adjectives, and appropriate prepositions — since translators use the English source as reference."}, {"rule": "LOC-017", "prompt": "Your PR adds three new user-facing strings to a dialog. What should you include for string review?", "choices": ["A screenshot attached as an inline code review comment", "Just the GRDP diff — it shows the exact text", "A link to the design mock instead of the real UI", "A screenshot of the rendered UI in the PR description"], "answer": 3, "explain": "When adding or modifying user-facing strings, include a screenshot of the actual rendered UI in the PR description (not inline comments) so reviewers can check truncation, capitalization, layout, and terminology."}, {"rule": "NA-001", "prompt": "A PR for a new feature adds a custom `my_feature_icon.svg` because no existing icon was a perfect fit. As the reviewer, you:", "choices": ["Approve — an optimized SVG under 1 KB adds negligible weight to the bundle", "Ask to move the SVG into a shared theme folder so every platform can reuse it", "Use or extend the Leo/Nala icon system and tag `@brave/nala-token-reviewers`", "Ask them to inline the SVG markup in the component so no new asset file is added"], "answer": 2, "explain": "Leo is the canonical icon source on every platform. Bypassing it leads to inconsistency and duplicates, so flag it and tag `@brave/nala-token-reviewers`."}, {"rule": "NA-009", "prompt": "An Android feature needs a new icon. Where does it go?", "choices": ["Add the icon entry to `android/nala/icons.gni`", "Create `android/java/res/drawable/ic_my_new_icon.xml`", "Add PNGs to each `drawable-*dpi` folder", "Add it to the `leo_icons` list in `components/vector_icons/BUILD.gn`"], "answer": 0, "explain": "On Android, add icons to the Nala list in `android/nala/icons.gni` instead of creating new drawable resources."}, {"rule": "NA-010", "prompt": "A WebUI page needs an icon that isn't wired up yet. What's the right approach?", "choices": ["Add `my_icon.svg` next to the page and reference it with `<img src=\"my_icon.svg\" />`", "Base64-encode the SVG into a CSS `background-image` on a styled `<span>` wrapper", "Add a new `.icon` file under `components/vector_icons/` and load it via a `chrome://resources` URL", "List it in `leo_icons` in `ui/webui/resources/BUILD.gn`; render `<leo-icon name=\"my-icon-name\">`"], "answer": 3, "explain": "For WebUI, add the icon name to the `leo_icons` array in `ui/webui/resources/BUILD.gn` and use `<leo-icon>`, not a raw `.svg` file."}, {"rule": "NA-011", "prompt": "A C++ Views toolbar button needs a new icon. How should it be added?", "choices": ["Create `components/vector_icons/my_new_icon.icon` containing the vector path commands", "Add `\"my-icon-name\"` to `leo_icons` in `components/vector_icons/BUILD.gn`", "Add `\"my-icon-name\"` to `leo_icons` in `ui/webui/resources/BUILD.gn`", "Rasterize it to PNG at 1x/2x and add it to the theme resources `.grd`"], "answer": 1, "explain": "For C++ browser UI, add the Leo icon name to `leo_icons` in `components/vector_icons/BUILD.gn` instead of creating a standalone `.icon` file."}, {"rule": "NA-002", "prompt": "An Android PR adds this to `res/values/colors.xml`:\n\n```xml\n<color name=\"my_custom_blue\">#1A73E8</color>\n```\n\nWhat should the reviewer say?", "choices": ["Fine, but add a matching night-mode variant in `res/values-night/colors.xml` too", "Rename it with a `brave_` prefix so it can't collide with upstream Chromium's color resource names", "Use a Nala/Leo token like `@color/leo_color_button_background` and tag the Nala token reviewers", "Move the hex value into a Java constant in `BraveColors` so it's defined in one place"], "answer": 2, "explain": "Don't define new Android color resources, because they bypass the design system and drift across themes and platforms. Reference an existing Nala/Leo token."}, {"rule": "NA-005", "prompt": "In a settings WebUI written in React, a teammate creates a `FancyCheckbox` component that wraps a styled `<input type=\"checkbox\">`. Your review?", "choices": ["Replace it with `Checkbox` from `@brave/leo/react/checkbox`", "Fine, as long as its CSS uses Leo color variables", "Fine, if they add the right `aria-*` attributes", "Move `FancyCheckbox` to a shared components folder so others can reuse it"], "answer": 0, "explain": "In WebUI React, use Leo components instead of native HTML or hand-rolled equivalents. They're themed, accessible and design-approved. Tag `@brave/nala-token-reviewers` when flagging this."}, {"rule": "NA-007", "prompt": "Convert this to follow the design system:\n\n```tsx\n<select value={value} onChange={(e) => setValue(e.target.value)}>\n  <option value='a'>Option A</option>\n  <option value='b'>Option B</option>\n</select>\n```", "choices": ["Keep the native `<select>` and style it with Leo CSS variables so it matches the theme", "`<Dropdown value={value} onChange={(e) => setValue(e.target.value)}>` keeping the `<option>` children", "A Leo `<Button>` that toggles a custom popup list of options when clicked", "`<Dropdown value={value} onChange={(e) => setValue(e.detail.value)}>` with `<leo-option>` children"], "answer": 3, "explain": "Use `Dropdown` from `@brave/leo/react/dropdown` instead of `<select>`. Its children are `<leo-option>` and its events carry the value in `e.detail.value`."}, {"rule": "NA-008", "prompt": "A PR adds this component:\n\n```tsx\nfunction Spinner() {\n  return <div className='spinner' aria-label='Loading...' />\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Fine — it has an `aria-label`, so it's accessible", "Use `ProgressRing` from `@brave/leo/react/progressRing`", "Use `Alert` from `@brave/leo/react/alert`", "Move the spinner CSS into a shared stylesheet so other pages can reuse it"], "answer": 1, "explain": "Check whether Leo already provides a component before building one. For loading indicators, that's `ProgressRing`. Custom versions add maintenance and are usually less accessible."}, {"rule": "NA-012", "prompt": "Reviewing a Views change:\n\n```cpp\n// brave_color_id.h\nBRAVE_COLOR_ID(kColorSidebarPanelBackground)\n// brave_color_mixer.cc\nmixer[kColorSidebarPanelBackground] = {nala::kColorContainerBackground};\n// side_panel_view.cc\nSetBackground(views::CreateThemedSolidBackground(\n    kColorSidebarPanelBackground));\n```", "choices": ["Fine — a Brave color ID decouples the view from Nala so tokens can be swapped later", "Rename it to `kColorBraveSidebarPanelBackground` so Brave-specific IDs are easy to spot", "Drop the intermediate ID; use `nala::kColorContainerBackground` directly at the call site", "Move the mixer assignment into `side_panel_view.cc` so the color lives next to its only use"], "answer": 2, "explain": "Don't create intermediate `kColor*` tokens that just map to a Nala token. Use the Nala token directly, because the extra indirection hides which token is in use."}, {"rule": "PATCH-001", "prompt": "You're reviewing a hand-written patch to an upstream Chromium file:\n\n```diff\n void Foo::Init() {\n+  // Brave: register our extra handlers.\n+  BRAVE_FOO_INIT\n+\n   RegisterHandlers();\n-  StartObserving();  \n+  StartObserving();\n```\n\nWhat should the reviewer ask for?", "choices": ["Nothing — a `// Brave:` comment helps resolve conflicts during rebases", "Keep only `BRAVE_FOO_INIT`; drop the comment, blank line and whitespace fix", "Keep the comment but revert the trailing-whitespace fix to shrink the hunk", "Move the comment above the function signature so it doesn't touch the body"], "answer": 1, "explain": "Patches contain only the minimal functional change — no comments, blank lines or whitespace fixes. Every extra line is more to review and more to conflict on Chromium upgrades."}, {"rule": "PATCH-004", "prompt": "You need to inject about 8 lines of Brave logic into the middle of an upstream `.cc` function. Which approach follows the patch guidelines?", "choices": ["A multiline patch inserting the 8 lines, wrapped in `// Brave start` / `// Brave end` markers", "Several small 2–3 line patches spread through the function so each hunk rebases easily", "Copy the upstream function's body into the patch as a replacement block", "Move the logic into a macro or `chromium_src` override and patch in one line"], "answer": 3, "explain": "Never create multiline hand-written patches. Move the logic into a `#define` or `chromium_src` override so the patch itself stays one line."}, {"rule": "PATCH-005", "prompt": "A patch adds three Brave entries to a list/block in an upstream file, and more Brave entries are expected later. How should the patch be written?", "choices": ["Patch in an `include` of a Brave-owned file that holds the entries", "Add all three entries inline and update the patch whenever new ones are needed", "Create one patch file per entry so each can be dropped independently", "Replace the upstream list entirely with a Brave-maintained copy of it"], "answer": 0, "explain": "When a patch adds to a list or block, use an `include` so future items are added in brave-core without touching the patch again."}, {"rule": "PATCH-006", "prompt": "You must make `PermissionControllerImpl::GetPermissionStatus` return early for a Brave-specific permission. Which patch line is preferred?", "choices": ["`+  if (permission == AUTOPLAY) return true;` as a single inline line", "`+  // Brave: AUTOPLAY early return` followed by the inline `if` check", "`+BRAVE_PERMISSION_CONTROLLER_IMPL_GET_PERMISSION_STATUS`, defined in brave-core", "`+#define BRAVE_HOOK if (permission == AUTOPLAY) return true;` written inside the patch"], "answer": 2, "explain": "Patches should reference a `#define` whose body lives in brave-core, so behavior can change without editing the patch. Name it `BRAVE_ALL_CAPS_ORIGINAL_METHOD_NAME`."}, {"rule": "PATCH-007", "prompt": "An upstream Android layout XML contains a `<LinearLayout>` block that Brave doesn't want. How should the patch get rid of it?", "choices": ["Delete the element's lines with `-` lines so the patch clearly shows what's removed", "Wrap the block in an XML comment: add a `<!--` line before and `-->` after", "Add `android:visibility=\"gone\"` to the opening tag so it never renders", "Delete it and re-add an empty `<LinearLayout/>` placeholder for ID lookups"], "answer": 1, "explain": "In XML patches, comment out with `<!-- -->` instead of deleting lines. That keeps the patch addition-only and minimizes the diff."}, {"rule": "PATCH-007", "prompt": "Your one-line patch to an upstream `.cc` file comes out at 104 characters. A reviewer points out the 80-column limit. Best response?", "choices": ["Split it over two lines, since patched files must pass the 80-column lint", "Shorten it by renaming the upstream variables it references to fit 80 columns", "Run `git cl format` on the upstream file so the line wraps automatically", "Keep it on one line; lint doesn't run on patches, and one-liners rebase better"], "answer": 3, "explain": "Keep patches to one line even if that breaks the line-length limit, because lint doesn't run on patched files. Also put additions on separate lines and match existing code exactly so the patch auto-resolves."}, {"rule": "PATCH-008", "prompt": "Brave needs to drop a dependency from an upstream target:\n\n```gn\n  public_deps += [ \":chrome_framework_widevine_signature\" ]\n```\n\nWhich patch is preferred?", "choices": ["Add a line: `public_deps -= [ \":chrome_framework_widevine_signature\" ]`", "Delete the original `public_deps +=` line with a `-` line in the patch", "Comment out the original line with `#` so it's easy to restore later", "Change the original line to `public_deps += []` to keep line numbers stable"], "answer": 0, "explain": "Use `-=` on a separate line to remove items from GN lists. The patch then only adds a line and never modifies the original one."}, {"rule": "PATCH-009", "prompt": "A patch to an upstream `BUILD.gn` target needs to add `//brave/browser/ui/views/location_bar` as a dep, and more Brave deps will likely follow. Which patch line is best?", "choices": ["`+  deps += [ \"//brave/browser/ui/views/location_bar\" ]`", "`+  deps += [ ... ]` listing every Brave dep you can foresee now", "`+  deps += brave_browser_window_deps`, defined in Brave code", "`+  public_deps = [ \"//brave/browser/ui\" ]`, replacing the upstream deps"], "answer": 2, "explain": "Define a variable in Brave code and patch only the reference to it. Deps can then be added or removed without touching the patch."}, {"rule": "PATCH-010", "prompt": "To change how upstream's `java_cpp_enum.py` generates a Java enum, a teammate adds a patch to the Python script. Your review?", "choices": ["Fine — Python scripts aren't compiled, so the patch is low risk", "Don't patch build scripts; patch the enum's header instead", "Fine, as long as the Python patch is a single, macro-style line", "Guard the patched code with an environment-variable check so it only runs for Brave"], "answer": 1, "explain": "Patching Python build scripts prevents correct incremental rebuilds and breaks remote `siso` actions. Prefer a `chromium_src` override or a `#define`. For enums processed by upstream scripts, a multiline header patch is acceptable."}, {"rule": "PLSTR-001", "prompt": "A plaster config needs to change the `return false;` inside `IsFeatureEnabled()` to `return true;`. The author wrote:\n\n```yaml\nre_pattern: 'return false;'\nreplace: 'return true;'\n```\n\nWhat should the reviewer say?", "choices": ["Fine — plaster only ever replaces the first match, so the literal is safe", "Switch to a `#define` in chromium_src so the override is compile-checked", "Add `re_flags: [DOTALL]` so the regex can match across lines", "Anchor the pattern on `IsFeatureEnabled()` and its surrounding context"], "answer": 3, "explain": "Plaster patterns should match method names or other relevant context to ensure a single, targeted match. A bare `return false;` can match many places and drift during Chromium updates; broad patterns are only for when you *intend* to replace every occurrence."}, {"rule": "PLSTR-001", "prompt": "You want to rename every use of `kOldConstant` in an upstream file to `kBraveConstant`. Which plaster pattern is appropriate?", "choices": ["A regex anchored on the first function using `kOldConstant`, to stay targeted", "`re_pattern: 'kOldConstant'` — simple is fine when every instance should match", "One substitution per call site, each anchored on its enclosing method", "A `#define kOldConstant kBraveConstant` in chromium_src, since it's just a rename"], "answer": 1, "explain": "Targeted context is the default, but simple patterns are correct when you intentionally want to replace all occurrences of something in the file."}, {"rule": "PLSTR-002", "prompt": "Which plaster substitution is fragile and should be rewritten?\n\n```yaml\n# A\npattern: 'kOldConstantName'\nreplace: 'kNewConstantName'\n# B\npattern: 'return NavigateWebAppUsingParams(nav_params);'\nreplace: 'return BraveNavigateWebAppUsingParams(&profile_.get(), *params_, nav_params);'\n# C\npattern: 'if (MyMethod() && my_bool) {'\nreplace: 'if (BraveMethod() && my_bool) {'\n```", "choices": ["A — bare symbol renames always need `re_pattern` with word boundaries", "B — whole statements are too long and brittle to use with `pattern`", "C — it drags in `&& my_bool` and the brace, which aren't replaced", "None of them; all three use `pattern` correctly for literal text"], "answer": 2, "explain": "The test isn't literal length but \"is every token part of what I'm changing?\" `&& my_bool` and the brace can change upstream without affecting the rewrite, so C needs `re_pattern`."}, {"rule": "PLSTR-002", "prompt": "An author writes this to swap a call that sits inside an indented block:\n\n```yaml\npattern: '    MyMethod()'\nreplace: '    BraveMethod()'\n```\n\nBest review feedback?", "choices": ["Good — including the indentation makes the match more specific and safer", "Use `re_pattern` with flexible whitespace, e.g. `'(^\\s+)(MyMethod\\(\\))'`", "Drop the plaster and patch the file directly, since it's a one-line change", "Wrap the literal in double quotes so YAML ignores the leading whitespace"], "answer": 1, "explain": "`pattern` requires an exact whitespace match, so leading indentation makes it break if upstream reindents. When the match needs to reach beyond the replaced text (like flexible whitespace), use `re_pattern`."}, {"rule": "PLSTR-003", "prompt": "A new PR adds this to `chromium_src/.../web_app_launch_process.cc`:\n\n```cpp\n#define NavigateWebAppUsingParams(nav_params) \\\n  NavigateWebAppInContainerUsingParams(&profile_.get(), *params_, nav_params)\n#include <chrome/browser/ui/web_applications/web_app_launch_process.cc>\n```\n\nWhat should the reviewer request?", "choices": ["Add an `#undef NavigateWebAppUsingParams` right after the include", "Reorder includes so the macro can't hit unrelated declarations", "Rename the upstream function to `NavigateWebAppUsingParams_ChromiumImpl` and wrap it", "Replace the macro with a plaster rewrite that redirects only the intended call"], "answer": 3, "explain": "New macros that edit upstream code are banned — a `#define` silently rewrites every occurrence in the TU. A plaster rewrite changes only the intended call, shows up in the generated patch, and `count` fails loudly if the premise breaks."}, {"rule": "PLSTR-003", "prompt": "You need `DownloadDisplayController::UpdateToolbarButtonState` to be overridable by a Brave subclass. In new code, what's the right approach?", "choices": ["A plaster `make_virtual` substitution (with `drop_final`/`add_friend` if needed)", "`#define UpdateToolbarButtonState virtual UpdateToolbarButtonState` in chromium_src", "Copy the whole header into chromium_src with the method made virtual", "Rename the upstream method to `UpdateToolbarButtonState_ChromiumImpl`"], "answer": 0, "explain": "Even decorating macros like `#define SomeMethod virtual SomeMethod` are banned in new code. Use the `make_virtual` rewriter (preferring AST rewriters over regex where one fits)."}, {"rule": "PLSTR-004", "prompt": "A plaster must append `public_deps += brave_web_applications_deps` to the `web_applications` source set. Which `re_pattern` is better?", "choices": ["`'(source_set\\(\"web_applications\"\\).*?\\bpublic_deps\\s*=\\s*\\[.*?\\])'` + `DOTALL`", "`'(public_deps = \\[ \"//chrome/browser:browser_public_dependencies\" \\])'` as a literal", "`'public_deps'` with no further context, so upstream reformatting can't break it", "A `pattern` containing the full, current text of the `source_set(\"web_applications\")` block"], "answer": 0, "explain": "Anchor on the thing being changed (the target) and let `.*?` absorb incidental content. Pinning the exact contents of the deps list breaks on any upstream addition for reasons unrelated to the rewrite."}, {"rule": "PLSTR-005", "prompt": "A plaster replaces a single literal statement:\n\n```yaml\nre_pattern: '\\n([^\\S\\n]*)return NavigateWebAppUsingParams\\(nav_params\\);'\nreplace: |-\n  \\n\\1return BraveNavigateWebAppUsingParams(&profile_.get(), *params_, nav_params);\n```\n\nWhat's the reviewer's best suggestion?", "choices": ["Keep it; capturing indentation with `([^\\S\\n]*)` is required for a correct patch", "Add `re_flags: [MULTILINE]` so `^` can replace the leading `\\n` in the regex", "Use a plain `pattern:` with the literal `return` statement — it's its own anchor", "Move the replacement into a chromium_src `#define` of `NavigateWebAppUsingParams`"], "answer": 2, "explain": "If the anchor is a single literal statement, use plain `pattern` — it escapes the string for you. Don't reach for `re_pattern` with escaped punctuation and capture groups just to reproduce whitespace."}, {"rule": "SG-001", "prompt": "After the user clears data, which confirmation string follows the Brave voice guidelines?", "choices": ["\"Brave cleared your browsing history.\"", "\"Your browsing history has been cleared by the system.\"", "\"Browsing history clearing has been completed successfully.\"", "\"Poof! Your history is gone for good!\""], "answer": 0, "explain": "Use active voice (say who did it), stay concise and simple, and be friendly but not jokey or whimsical."}, {"rule": "SG-002", "prompt": "Which warning text follows the Brave style guide?", "choices": ["\"You cannot undo this action.\"", "\"You can't undo this action.\"", "\"This action cannot be undone.\"", "\"This action is not able to be undone.\""], "answer": 1, "explain": "Use contractions where possible; they're more conversational and save space in UI strings."}, {"rule": "SG-003", "prompt": "An ad-reporting dialog needs a label for a flagged ad. Which is best?", "choices": ["\"This ad looks creepy\"", "\"This ad is basically sketchy\"", "\"This ad looks suspicious\"", "\"This ad seems fishy\""], "answer": 2, "explain": "Avoid colloquial language, idioms, slang, and filler words like \"basically\"; they can confuse, offend, or translate poorly."}, {"rule": "SG-004", "prompt": "A consent checkbox appears before account creation. Which label follows the perspective rules?", "choices": ["\"You've read the Brave terms of service\"", "\"The user has read the Brave terms of service\"", "\"We confirm you've read our terms of service\"", "\"I've read the Brave terms of service\""], "answer": 3, "explain": "Address readers in second person (you, your), but use first person (I, me, my) when the user takes an action or gives consent."}, {"rule": "SG-004", "prompt": "A privacy notice explains what search data is accessible. Which phrasing does the style guide prefer?", "choices": ["\"Brave can only access the following search data…\"", "\"We can only access the following search data…\"", "\"Our team can only access the following search data…\"", "\"The following search data can only be accessed…\""], "answer": 0, "explain": "For legal, security, or data privacy topics, say \"Brave\" or \"the Brave team\" instead of \"we\" to avoid implying staff can access user data."}, {"rule": "SG-005", "prompt": "You're writing a Shields-down confirmation dialog. Which version best follows the sentence-length guideline?", "choices": ["\"Are you sure you want to put Shields down for this page? Shields down may reduce your privacy.\"", "Title: \"Put Shields down?\" Body: \"Shields down may reduce your privacy on this site.\"", "\"Putting Shields down for this page, which you may want to do, may reduce your privacy and expose trackers.\"", "Title: \"Are you sure you want to put Shields down for this page right now?\""], "answer": 1, "explain": "Aim for 15 words or fewer per sentence. Break long sentences up (e.g. a short title plus body) and read them aloud to test."}, {"rule": "SG-006", "prompt": "Which help text uses the preferred tense?", "choices": ["\"Clicking 'Search default' will show a list of search options\"", "\"Once you click 'Search default,' you'll see a list of search options\"", "\"Click 'Search default' to see a list of search options\"", "\"You are clicking 'Search default' to be seeing search options\""], "answer": 2, "explain": "Default to simple present tense. If a verb follows was/were, has/have, is/are, or be, or ends in -ing, it isn't simple tense."}, {"rule": "SG-007", "prompt": "Which sentence follows the style guide's language guidance?", "choices": ["\"Ask the account owner to approve his request.\"", "\"Ask the account owner to approve his or her request.\"", "\"Ask the chairman of the account to approve the request.\"", "\"Ask the account owner to approve the request.\""], "answer": 3, "explain": "Rephrase to avoid gendered pronouns (defaulting to they/their if unavoidable) and avoid gender-latent words like \"chairman\" or \"policeman.\""}, {"rule": "SG-008", "prompt": "Which desktop settings section heading is correctly cased?", "choices": ["\"Clear browsing data\"", "\"Clear All Browsing Data\"", "\"CLEAR BROWSING DATA\"", "\"clear browsing data\""], "answer": 0, "explain": "Use sentence case for headlines, titles, and buttons; never ALL CAPS. Title case is only for branded product names (iOS is an exception, following Apple's rules)."}, {"rule": "SG-009", "prompt": "Which marketing line follows the style guide?", "choices": ["\"Keep your friends, Brendan and Brian, safe with Brave\"", "\"Keep your friends, Brendan, and Brian safe with Brave\"", "\"Keep your friends, Brendan & Brian safe with Brave\"", "\"Keep your friends; Brendan; and Brian, safe with Brave\""], "answer": 1, "explain": "Always use the Oxford (serial) comma before the last item in a list of 3 or more."}, {"rule": "SG-010", "prompt": "Which string follows Brave's punctuation rules?", "choices": ["\"Loading...\" using three standard periods", "\"Loading!!\" with doubled exclamation for emphasis", "\"Loading…\" with the Unicode ellipsis character", "\"Loading . . .\" with periods spaced per print style"], "answer": 2, "explain": "Use the Unicode ellipsis `…`, not three periods. Exclamation points are used sparingly, never more than one per view."}, {"rule": "SG-010", "prompt": "Which sentence uses hyphens and dashes correctly per the style guide?", "choices": ["\"Keep a browser that's up-to-date. Support is available Monday - Friday.\"", "\"Keep an up to date browser. Support is available Monday to-Friday.\"", "\"Keep an up-to-date browser — support is available Monday-Friday.\"", "\"Keep an up-to-date browser. Support is available Monday–Friday.\""], "answer": 3, "explain": "Hyphenate multi-word adjectives before a noun (\"up-to-date browser\"), not after. Use an en dash for spans replacing \"to,\" and em dashes have no surrounding spaces."}, {"rule": "SG-011", "prompt": "Which confirmation modal follows the UI copy guidelines?", "choices": ["Title \"Delete history?\", a body stating the consequence, button [Delete history]", "Title \"Would you like to delete your history now?\" with buttons [OK] and [Cancel]", "Title \"Delete history?\" with button [YES, DELETE THE HISTORY]", "Title \"Please confirm\", body \"Are you sure you want to continue?\", button [Continue]"], "answer": 0, "explain": "Confirmation modals: the title states the action as a question, the body states consequences, and the button repeats the action verb (≤3 words, sentence case, no articles)."}, {"rule": "SG-011", "prompt": "A page failed to load. Which error message meets the guidelines?", "choices": ["\"Whoopsie! Something went wrong. We're on it, hang tight!\"", "\"This page failed to load. Try reloading, or setting Shields down.\"", "\"Sorry, the server failed to fetch the page. Please try again later.\"", "\"Invalid response from server (error code 502). Reload to retry.\""], "answer": 1, "explain": "Error messages must say what happened and offer a solution; never a dead end. Avoid exclamations, apologies, \"please,\" blame, and jargon like server, fetch, or invalid."}, {"rule": "SG-012", "prompt": "Which email footer text follows the accessibility guidance?", "choices": ["\"To unsubscribe from these emails, click here.\" (with \"here\" as the link)", "\"Click the link below to unsubscribe from future emails.\"", "\"Want to stop getting these emails? Unsubscribe.\" (link on \"Unsubscribe\")", "\"Unsubscribe using the button to the right of this message.\""], "answer": 2, "explain": "Never use \"click here\" as link text; describe what happens. Also avoid directional language like \"to the right of\" or \"below.\""}, {"rule": "SG-013", "prompt": "Which UI string formats numbers and dates correctly?", "choices": ["\"Sync three devices by June 1st at 6:00 PM\"", "\"Sync 3 devices by 6/1/21 at 6:00pm\"", "\"Sync 3 devices by June 1st at 18:00\"", "\"Sync 3 devices by June 1 at 6:00 pm\""], "answer": 3, "explain": "In UI, use digits for 0–9. Dates have no ordinals or numeric formats, and times are lowercase with a space: \"6:00 pm.\""}, {"rule": "SG-013", "prompt": "Which storage and pricing string is formatted correctly?", "choices": ["\"Get 1 TB for HK$9.99, 50% off\"", "\"Get 1TB for $9.99 HKD, 50 % off\"", "\"Get one TB for HK$9.99, 50 percent off\"", "\"Get 1 TB for 9.99 HK$, 50% off\""], "answer": 0, "explain": "Put a space between a number and its unit (\"1 TB\"), no space before % (\"50%\"), and use the currency symbol with the country outside the US (\"HK$9.99\")."}, {"rule": "SG-014", "prompt": "Which sentence follows Brave's product naming conventions?", "choices": ["\"Download the Brave Browser and turn on shields.\"", "\"Download the Brave browser and turn on Shields.\"", "\"Download Brave and turn on shields.\"", "\"Be Brave: download the Brave Browser today and turn on Shields.\""], "answer": 1, "explain": "\"Brave browser\" always has a lowercase \"browser,\" and Shields is always capitalized, even in general usage. Never use \"Brave\" as an adjective."}, {"rule": "SG-015", "prompt": "Which settings toggle label follows the style guide's word choices?", "choices": ["\"Activate Brave Private Ads\"", "\"Enable Brave Private Ads\"", "\"Turn on Brave Private Ads\"", "\"Turn on Brave ads\""], "answer": 2, "explain": "Say \"turn on\"/\"turn off,\" not \"enable\"/\"disable,\" and use the branded names \"Brave Ads\" or \"Brave Private Ads.\""}, {"rule": "SG-015", "prompt": "Which Brave Rewards and Playlist copy uses the approved vocabulary?", "choices": ["\"Tip BAT to creators. Download videos to your playlist.\"", "\"Donate BAT to creators. Save videos to your playlist.\"", "\"Send BAT to creators. Watch saved videos in your playlist.\"", "\"Contribute BAT to creators. Add videos to your playlist.\""], "answer": 3, "explain": "Use \"contribute\"/\"support\" for BAT (not donate, tip, give, pay, or send), \"add\" for Playlist (not download/save), and \"view\" instead of \"watch.\""}, {"rule": "SG-016", "prompt": "Which privacy claim follows Brave's terminology rules?", "choices": ["\"Brave routes your request through a proxy, so the site can't see your IP address.\"", "\"Your browsing is 100% anonymous thanks to our anonymizing server network.\"", "\"Military-grade encryption keeps your browsing completely private from everyone.\"", "\"Brave's TOR windows make you totally secure and invisible to every site you visit.\""], "answer": 0, "explain": "Privacy claims must say specifically what's protected and how. Never use superlatives like \"100% anonymous\" or \"military-grade,\" prefer \"proxy server\" over \"anonymizing server,\" and never write \"TOR.\""}, {"rule": "SG-017", "prompt": "Which string is best for localization?", "choices": ["\"Be sure to clear this page's contents\"", "\"Clear the content of this page\"", "An \"Aa\" icon with no text label", "A button image with the text \"Clear\" baked into the PNG"], "answer": 1, "explain": "Write for translation: lead with the verb (not \"Be sure to…\"), avoid possessives, avoid letters in icons, label icons with text, and keep text out of images."}, {"rule": "SG-018", "prompt": "Which Rewards balance string follows the BAT guidelines?", "choices": ["\"$80 BAT\"", "\"80 BAT points\"", "\"80.000 BAT\"", "\"80.00 BAT (cryptocurrency)\""], "answer": 2, "explain": "Show BAT balances to three decimal places, never with a currency symbol. BAT is a \"token\" or \"crypto asset,\" never a point, currency, or cryptocurrency."}, {"rule": "SG-019", "prompt": "Which onboarding sentence describes devices correctly on first reference?", "choices": ["\"Sync bookmarks between your PC and your mobile device.\"", "\"Sync bookmarks between your laptop computer and your smartphone.\"", "\"Sync bookmarks between your desktop and your device.\"", "\"Sync bookmarks between your computer and your phone or tablet.\""], "answer": 3, "explain": "Use \"phone or tablet\" on first mobile reference (then \"your device\"), and \"computer\" for non-mobile machines; avoid laptop, PC, or desktop."}, {"rule": "SG-020", "prompt": "Which marketing line follows Brave's product messaging rules?", "choices": ["\"Brave Talk: free video calls for up to 4 people, with no time limit.\"", "\"Brave Talk: end-to-end encrypted video calls for everyone, totally free.\"", "\"Brave VPN: watch your favorite streaming sites from anywhere.\"", "\"The Brave browser blocks all ads and trackers, unlike Meta.\""], "answer": 0, "explain": "Talk can claim free calls for up to 4 people with no time limit, but never \"E2E\"/\"end-to-end.\" Don't pitch VPN for streaming, claim Brave blocks ALL ads/trackers, or call out companies like Meta."}, {"rule": "TA-002", "prompt": "A flaky browser test stops failing after the author adds one line just before the assertion:\n\n```cpp\nVLOG(1) << \"Checking distill state\";\nEXPECT_TRUE(IsDistilled());\n```\n\nCI has been green for 20 runs. What should the reviewer say?", "choices": ["Approve — 20 consecutive green CI runs are strong evidence the race is gone", "Approve, but change `VLOG` to `LOG(INFO)` so it also works in release builds", "Reject: it's a timing-based fake fix; synchronize on the real condition", "Ask for a `std::this_thread::yield()` too, so the other thread reliably gets scheduled"], "answer": 2, "explain": "Logging, dummy work, reordering, and yields only change timing; they hide the race instead of fixing it. Never use a timing-based fix; add proper synchronization."}, {"rule": "TA-003", "prompt": "A test sometimes checks `tab_helper()->PageDistillState()` before distillation finishes. Which fix addresses the root cause?", "choices": ["`ASSERT_TRUE(base::test::RunUntil([&] { return tab_helper()->PageDistillState() == kDistilled; }));`", "`base::PlatformThread::Sleep(base::Milliseconds(500));` before checking `PageDistillState()`", "`base::RunLoop().RunUntilIdle();` then `ASSERT_EQ(tab_helper()->PageDistillState(), DistillState::kDistilled);`", "`ASSERT_TRUE(content::NavigateToURL(web_contents, url));` again, then check `PageDistillState()`"], "answer": 0, "explain": "Proper root cause analysis means identifying what races and waiting on the actual condition you care about (`RunUntil`, `TestFuture`, observers), not on arbitrary time."}, {"rule": "TA-004", "prompt": "A teammate says: \"I extracted a helper method and the flake went away. If I inline it again, it flakes. Not sure why, but it works.\" How should you respond?", "choices": ["Ship it — the extracted helper is cleaner code, so the refactor is an improvement anyway", "Ship it, with a comment saying not to inline the helper", "It's not a fix: without explaining the synchronization, the race is still there", "Run it 100 times locally under load; if it never fails, the race is effectively fixed"], "answer": 2, "explain": "If removing your \"fix\" brings the flake back but you can't explain WHY it fixes the race, it's not a real fix. Real fixes are deterministic, explainable, and robust."}, {"rule": "TA-005", "prompt": "```cpp\nservice->StartSync();\nbase::RunLoop().RunUntilIdle();\nEXPECT_TRUE(service->IsSynced());\n```\n\nWhat's the problem with this test?", "choices": ["Nothing — `RunUntilIdle()` drains every pending task, so the sync result is deterministic", "It should call `RunUntilIdle()` twice, since sync may post a follow-up task", "It should use `ASSERT_TRUE` so a failed sync stops the test immediately", "`RunUntilIdle()` is forbidden: it can return early or time out; wait on the condition"], "answer": 3, "explain": "Chromium style forbids `RunLoop::RunUntilIdle()` for async tests. It can return too early when events depend on other task queues, or run too long, which makes tests flaky."}, {"rule": "TA-006", "prompt": "A browser test must wait until the Speedreader bubble appears, i.e. until `tab_helper()->speedreader_bubble_view()` is non-null. Which wait follows the standard?", "choices": ["Loop `NonBlockingDelay(base::Milliseconds(100))` until `speedreader_bubble_view()` is non-null", "`ASSERT_TRUE(base::test::RunUntil([this]() { return tab_helper()->speedreader_bubble_view(); }));`", "`base::RunLoop().RunUntilIdle();` then `ASSERT_TRUE(tab_helper()->speedreader_bubble_view());`", "`EXPECT_TRUE(content::EvalJs(web_contents, \"!!document.querySelector('#speedreader-bubble')\"))`"], "answer": 1, "explain": "To wait on C++ state or object properties, use `base::test::RunUntil()` with a lambda that checks the condition directly."}, {"rule": "TA-008", "prompt": "```cpp\nASSERT_TRUE(base::test::RunUntil([&]() {\n  return content::EvalJs(web_contents, \"window.ready\").ExtractBool();\n}));\n```\n\nWhat's wrong?", "choices": ["`EvalJs` spins its own run loop; don't nest run-loop operations inside `RunUntil`", "Nothing — `RunUntil` is designed for polling JS state, and `EvalJs` is synchronous", "It should use `ExecJs`, because `EvalJs(...).ExtractBool()` crashes on non-bool values", "The lambda should capture `web_contents` by value, since `RunUntil` may call it later"], "answer": 0, "explain": "Never call something that spins its own run loop (`EvalJs`, `ExecJs`, IPC that waits for a response) inside `RunUntil()`. Only direct C++ state checks, getters, and property checks are safe."}, {"rule": "TA-009", "prompt": "```cpp\nbase::RunLoop run_loop;\nbool result = false;\nservice->CheckPurchaseState(\n    base::BindLambdaForTesting([&](bool is_purchased) {\n      result = is_purchased;\n      run_loop.Quit();\n    }));\nrun_loop.Run();\nEXPECT_FALSE(result);\n```\n\nWhat will a reviewer ask for?", "choices": ["Nothing — `RunLoop` plus `BindLambdaForTesting` is the canonical callback-waiting pattern", "Replace `run_loop.Run()` with `RunUntilIdle()` so the test can't hang if the callback never fires", "Use `run_loop.QuitClosure()` instead of calling `Quit()` in the lambda", "Use `base::test::TestFuture<bool>`: pass `future.GetCallback()`, check `future.Get()`"], "answer": 3, "explain": "Always use `base::test::TestFuture` for `OnceCallback`-based operations; it's shorter and less error-prone. Reviewers flag `RunLoop` + `BindLambdaForTesting` + `Quit()` when `TestFuture` would work."}, {"rule": "TA-010", "prompt": "A browser test sends `Init()` asynchronously over the Solana provider Mojo interface, then needs to be sure it was processed before asserting. Which approach is precise and deterministic?", "choices": ["`base::PlatformThread::Sleep(base::Milliseconds(100))`, which covers Mojo's typical latency", "A sync call on the same interface, e.g. read `window.braveSolana.isConnected`", "Call `RunUntilIdle()` in both the browser and renderer processes to flush the Mojo pipe", "Send `Init()` twice so at least one is processed"], "answer": 1, "explain": "Mojo processes messages in order on a given interface. A synchronous call on that interface guarantees all earlier async messages on it have been handled, which is a precise alternative to polling."}, {"rule": "TA-011", "prompt": "`object_under_test.DoSomethingAsync(base::OnceClosure done)` takes a plain closure, and you need manual run-loop control that `TestFuture` doesn't give you. What's the accepted pattern?", "choices": ["Pass `base::DoNothing()` as `done`, then call `RunUntilIdle()` to drain the async work", "Poll with `RunUntil` and an `ExecJs` check that the page reflects the result", "Create a `base::RunLoop`, pass `run_loop.QuitClosure()`, then `run_loop.Run()`", "Sleep briefly with `PlatformThread::Sleep`, then check the result object's state"], "answer": 2, "explain": "When `TestFuture` doesn't fit, pass `run_loop.QuitClosure()` and call `run_loop.Run()`, which waits specifically for that closure to fire."}, {"rule": "TA-012", "prompt": "```cpp\nservice->UpdateSettings(new_settings);\nEXPECT_EQ(true, content::EvalJs(web_contents, \"isSettingEnabled()\"));\n```\n\n`UpdateSettings` is an async Mojo call, and the test is flaky. Best fix?", "choices": ["Wrap the `EvalJs` check in `base::test::RunUntil` so it retries until the setting applies", "Add `RunUntilIdle()` between the two lines so the Mojo message is flushed first", "Repeat the `EvalJs` check up to three times to absorb the Mojo round-trip latency", "Pass a `TestFuture` callback to `UpdateSettings`, wait on `future.Get()`, then `EvalJs`"], "answer": 3, "explain": "Don't call `EvalJs` right after an async Mojo operation; the message may not be processed yet. Synchronize on the Mojo response first, with a `TestFuture` or `RunUntil` on C++ state."}, {"rule": "TI-001", "prompt": "You need to test that clicking Pause while a navigation tool is still running behaves correctly. The real navigation tool finishes at unpredictable times. Best approach?", "choices": ["Use the real tool, but wait a short fixed delay so it's mid-run when you click Pause", "A `MockTool` whose `Execute` stores the callback; click Pause, then run it yourself", "Run the test 10 times in CI and accept it if the large majority of runs pass", "Test only the already-finished case, since the mid-run timing can't be controlled"], "answer": 1, "explain": "Prefer fakes over real dependencies. A mock that captures the callback lets you control exactly when work completes, so the test is deterministic, faster, and isolated from cascading failures."}, {"rule": "TI-002", "prompt": "A test reaches into a class with `EXPECT_EQ(object->private_state_, 42);`. The class has public `IsReady()` and `GetValue()` methods. What should the reviewer suggest?", "choices": ["Make `private_state_` public so the test can read it without friend declarations", "Add a `FRIEND_TEST` so accessing it is legal", "Keep it — checking the internal field is more precise than the public getters", "Assert via the public API: `IsReady()` and `GetValue() == 42`"], "answer": 3, "explain": "Test the API, not the implementation. Testing through public interfaces lets internals change without breaking tests, and gives other developers accurate usage examples."}, {"rule": "TI-003", "prompt": "A browser test checks the `Accept-Language` header on every request. The page loads subresources from several domains, and the test stores a single `std::string expected_header_`. It's flaky. Fix?", "choices": ["Keep a per-domain map of expected values, looked up by the request's `Host`", "Reset `expected_header_` after every request so stale values aren't reused", "Add a short delay before setting the next expected value so requests settle", "Only check the main-frame request, since subresources inherit its headers"], "answer": 0, "explain": "Subresource requests can arrive out of order, so a single global expected value races. Use per-domain (per-resource) expected values."}, {"rule": "TI-004", "prompt": "```cpp\nconst int kThrottleMs = 500;\nWaitForSelectorBlocked();  // may take 200-300ms\nNonBlockingDelay(base::Milliseconds(250));\n// expect still throttled...\n```\n\nThe test flakes. What's the underlying issue and fix?", "choices": ["The 250ms delay overshoots what's left of the window; reduce it to about 50ms instead", "Use `RunUntilIdle()` instead of `NonBlockingDelay` so no wall-clock time passes", "Polling eats into a timer that starts at fetch; use a far larger window, e.g. 2000ms", "Start the throttle timer manually at the beginning of the test, before any polling"], "answer": 2, "explain": "Throttle timers start when the fetch happens, not when your checks begin, and polling waits consume that window. Use throttle times much larger than the expected polling duration."}, {"rule": "TI-006", "prompt": "You've drafted a fix for a flaky test that waits for a DOM update after a renderer IPC. What should you do before finalizing it?", "choices": ["Search Chromium for tests with similar needs and reuse an established pattern", "Run it 50 times locally with `--gtest_repeat`, and ship it if every run is green", "Wrap it in a retry so CI reruns it automatically on an occasional failure", "Disable it on the platforms where it flakes, and file a bug to investigate"], "answer": 0, "explain": "Before fixing async/timing issues, search the Chromium codebase for similar scenarios and prefer established, event-driven Chromium patterns over novel solutions."}, {"rule": "TI-007", "prompt": "Your fix uses a MutationObserver to wait for the DOM to update, an approach copied from Chromium's `service_worker_internals_ui_browsertest.cc`. What should accompany it?", "choices": ["Nothing — a MutationObserver is self-explanatory to anyone reading the code", "A link to a Stack Overflow answer explaining how MutationObserver timing works", "A TODO to replace it with a simple fixed delay once the test is stable", "A comment or commit note pointing at the Chromium file it's copied from"], "answer": 3, "explain": "When you follow a Chromium pattern, include a reference to it in a code comment or the commit message, so readers can see the precedent."}, {"rule": "TI-008", "prompt": "A test contains:\n\n```cpp\ncontent::EvalJs(web_contents, \"window.solana.isConnected\");\n```\n\nWhat should the reviewer flag?", "choices": ["Use `ExecJs` instead, since the script's return value isn't needed here", "Check the result with `EXPECT_EQ(true, content::EvalJs(...))`", "Wrap it in `base::test::RunUntil` so it retries", "Nothing — `EvalJs` fails the test on JS exceptions automatically"], "answer": 1, "explain": "Always check `EvalJs` results with `EXPECT_TRUE`/`EXPECT_EQ`. An unchecked call swallows errors, so even a gibberish expression would \"pass\"."}, {"rule": "TI-009", "prompt": "`production.cc` defines `constexpr base::TimeDelta kCleanupDelay = base::Seconds(30);` and the unit test defines an identical copy so it can advance the mock clock. Better approach?", "choices": ["Hardcode `base::Seconds(30)` directly in the test so it reads self-contained", "Keep both copies, with a comment in each pointing to the other one", "Expose it once as `inline constexpr` in a shared header used by both", "Advance the mock clock by a large value like 1 hour, so the exact delay doesn't matter"], "answer": 2, "explain": "Don't duplicate constants between production and test code. Expose the value via a shared header so both always agree."}, {"rule": "TI-010", "prompt": "A unit test in `//brave/components/...` gets a settings map via `HostContentSettingsMapFactory::GetForProfile(profile)` from `chrome/browser/...`. What's the right fix?", "choices": ["Construct one directly via `base::MakeRefCounted<HostContentSettingsMap>(...)`", "Add the `//chrome/browser` dep with `nogncheck`, since it's only used in tests", "Move the component's test into `//brave/browser`, where profile factories are allowed", "Convert it into a browser test, which provides a real profile and its factories"], "answer": 0, "explain": "Component unit tests must not depend on `//chrome`. If you need objects normally created by Chrome infrastructure, create them manually in the test."}, {"rule": "TI-011", "prompt": "```cpp\nclass BraveTab {\n  FRIEND_TEST_ALL_PREFIXES(BraveTabTest, RenameBasic);\n  FRIEND_TEST_ALL_PREFIXES(BraveTabTest, RenameCancel);\n  FRIEND_TEST_ALL_PREFIXES(BraveTabTest, RenameSubmit);\n  raw_ptr<views::Textfield> rename_textfield_;\n};\n```\n\nAll three tests only need `rename_textfield_`. Preferred approach?", "choices": ["Add one more `FRIEND_TEST_ALL_PREFIXES` for each new test, as the class already does", "Make `rename_textfield_` public, since tests are its only outside users", "Add a `rename_textfield_for_testing()` accessor returning the textfield", "Declare the `BraveTabTest` fixture a `friend class` and forward accessors from it"], "answer": 2, "explain": "When tests need a single private member, provide a `*_for_testing()` accessor returning a reference, instead of proliferating `FRIEND_TEST` macros."}, {"rule": "TI-012", "prompt": "```cpp\nvoid SetUp() override { g_disable_stats_for_testing = true; }\nTEST_F(StatsTest, UpdaterDoesNotReachEndpoint) { ... }\n```\n\nWhat's the problem?", "choices": ["The global should also be reset in `TearDown()`, but otherwise the approach is sound", "The test name is too long and should describe the setup rather than the outcome", "Nothing — disabling stats is the simplest way to verify that no request is made", "It disables the code under test, so it proves nothing; use a mock server instead"], "answer": 3, "explain": "When using test-only controls (globals, mocks, feature overrides), verify the test still exercises the code path it claims to test. A test that disables the code under test proves nothing."}, {"rule": "TI-013", "prompt": "A fixture does `void SetUp() override { g_disable_auto_start = true; }` and has no `TearDown()`. What should be added?", "choices": ["`void TearDown() override { g_disable_auto_start = false; }`", "Nothing — gtest runs each test with freshly initialized globals", "Set it to `false` at the start of every other test that depends on it", "Make `g_disable_auto_start` `thread_local` so it can't leak between tests"], "answer": 0, "explain": "If `SetUp()` disables functionality via a global, re-enable it in `TearDown()` so state doesn't leak into other tests."}, {"rule": "TI-014", "prompt": "A test loops over 30 URLs and runs `EXPECT_EQ(result.status, Status::kSuccess);` for each. When it fails, CI shows only `Expected kSuccess, got kError`. Improvement?", "choices": ["Split it into 30 separate `TEST_F`s, one per URL, so the failing one is named", "Stream context into it: `<< \"Failed for URL: \" << url << \", code: \" << result.code`", "Replace `EXPECT_EQ` with `ASSERT_EQ` so it stops at the first failing URL", "Add `LOG(INFO) << url;` before each check so the log shows the last URL tried"], "answer": 1, "explain": "Include diagnostic state in assertions using `<<`, so failures can be debugged from the log without rerunning under a debugger."}, {"rule": "TI-015", "prompt": "A helper `VerifyTabCount(Browser*, int expected)` is called from 12 places in a browser test. When it fails, the output points only to the `EXPECT_EQ` line inside the helper. Fix?", "choices": ["Inline the helper at every call site so each failure points at its own line", "Add a `LOG(ERROR)` in the helper printing the expected and actual tab counts", "Add a `base::Location` param and use `SCOPED_TRACE(location.ToString())`", "Turn the helper into a macro so `__LINE__` expands at each call site instead"], "answer": 2, "explain": "Use `SCOPED_TRACE` with a `base::Location` defaulted to `Current()` in browser test helpers, so failure output shows the caller's file and line."}, {"rule": "TI-016", "prompt": "A PR adds a new AI tool handler that parses JSON arguments. Its tests cover only well-formed inputs. What should the reviewer request?", "choices": ["Nothing — the happy path is what real users hit, and the model emits valid JSON", "A browser test for the happy path too, so the full tool pipeline is exercised", "A fuzzer instead of unit tests", "Tests for malformed, empty, null, and out-of-range inputs"], "answer": 3, "explain": "Tool and handler implementations must have unit tests for bad/invalid input (malformed, empty, null, out-of-range), not just happy paths."}, {"rule": "TI-017", "prompt": "A refactor moves validation logic from `Parser` into a new `Validator` class. The author deletes an `EXPECT_FALSE(parser.Parse(bad_input))` check that no longer fits. Feedback?", "choices": ["Move that check into the `Validator` tests so coverage doesn't drop", "Fine — the refactor makes the check obsolete, since `Parser` no longer validates", "Keep the old check commented out in the `Parser` tests for future reference", "Leave it to a follow-up PR"], "answer": 0, "explain": "When refactoring removes a test check, move it to the appropriate new location rather than deleting it. Test coverage should never decrease during a refactor."}, {"rule": "TI-018", "prompt": "`GetRecentHistory()` is documented to return most-recent-first. The test checks `results.size() == 3u` and `ContainsUrl(results, ...)` for each URL. What's missing?", "choices": ["A check that no URL appears twice, e.g. by inserting all of them into a `std::set`", "Explicit order checks, e.g. `EXPECT_EQ(results[0].url, \"https://c.com\")`", "A check that `results` isn't empty before calling `ContainsUrl` on it", "Nothing — size plus `ContainsUrl` for each URL fully verifies the content"], "answer": 1, "explain": "When a function returns ordered data, assert the order explicitly, not just the contents."}, {"rule": "TI-020", "prompt": "A test validates a serialized request body:\n\n```cpp\nEXPECT_THAT(json_str, testing::HasSubstr(\"\\\"method\\\":\\\"chain_getBlockHash\\\"\"));\n```\n\nPreferred form?", "choices": ["Build a `base::Value::Dict` by hand with `Set(\"method\", ...)` calls and compare it", "Use `testing::MatchesRegex()` over the whole body so key order and spacing are flexible", "`EXPECT_EQ(actual, base::test::ParseJsonDict(R\"({\"method\":\"chain_getBlockHash\",\"id\":1})\"));`", "Compare raw strings: `EXPECT_EQ(json_str, R\"({\"method\":\"chain_getBlockHash\",\"id\":1})\")`"], "answer": 2, "explain": "Compare JSON with `base::test::ParseJsonDict()`. Never validate JSON with `HasSubstr`; it's fragile and doesn't check structure. Building dicts by hand is also discouraged."}, {"rule": "TI-021", "prompt": "A test for a failed title generation only checks `EXPECT_FALSE(result.has_value());`. On failure, the observer should never be told the title changed. What should be added?", "choices": ["`EXPECT_CALL(observer, OnConversationTitleChanged(_)).WillOnce(Return())`", "A second test for the success path", "Nothing — the error result is enough", "`EXPECT_CALL(observer, OnConversationTitleChanged(_)).Times(0);`"], "answer": 3, "explain": "On error/failure paths, explicitly verify that side effects which should NOT occur don't happen, e.g. with `.Times(0)`."}, {"rule": "TI-022", "prompt": "A deserialization test checks `title` and `url`, but the struct also has `favicon_url` and `description`. Which addition best meets the standard?", "choices": ["Assert every field, and add a test that malformed input fails", "Assert `favicon_url` only, since URL parsing is the field most likely to break", "Compare `ToString()` output to a golden string", "Nothing — secondary fields like `description` aren't worth dedicated assertions"], "answer": 0, "explain": "Serialization tests must verify ALL fields, including secondary ones like favicon URLs, and should also test deserializing invalid or malformed input."}, {"rule": "TI-023", "prompt": "A file has `TEST_F(MyTest, HandleTypeA)`, `HandleTypeB`, and `HandleTypeC`. Each is identical except for the input enum and the expected string. Preferred structure?", "choices": ["Keep separate tests; they're easier to filter and each failure names its case", "A table of `{name, type, expected}` cases with `SCOPED_TRACE(tc.name)`", "Merge them into one test with three back-to-back `EXPECT_EQ` checks", "Use a macro to stamp out the three tests so each still gets its own name"], "answer": 1, "explain": "For similar scenarios that differ only in inputs and outputs, use parameterized tests: a case table with `SCOPED_TRACE`, or `INSTANTIATE_TEST_SUITE_P` for larger suites."}, {"rule": "TI-024", "prompt": "Many tests repeat this pair of lines for every content block:\n\n```cpp\nEXPECT_TRUE(blocks[0]->is_text_content_block());\nEXPECT_EQ(blocks[0]->get_text_content_block()->text, \"hello\");\n```\n\nWhat should the reviewer suggest?", "choices": ["Nothing — explicit assertions at each site are more readable than helpers", "Use a macro expanding to both lines, so failures still report the caller's line", "Check only `is_text_content_block()`, and skip the repetitive field comparison", "Extract a helper like `VerifyTextBlock(*blocks[0], \"hello\")`"], "answer": 3, "explain": "Extract repeated assertion blocks into reusable helper functions, such as `VerifyTextBlock()` and `VerifyImageBlock()`."}, {"rule": "TI-025", "prompt": "```cpp\nEXPECT_EQ(map[entry->uuid.value_or(\"\")], expected_content);\n```\n\n`uuid` is a `std::optional<std::string>`. What's the better form?", "choices": ["`EXPECT_TRUE(entry->uuid.has_value());` followed by the same `value_or(\"\")` line", "Use `entry->uuid.value()` directly, which throws if it's empty", "`ASSERT_TRUE(entry->uuid.has_value());` then index with `*entry->uuid`", "`value_or(\"missing\")`, so a missing uuid yields a clearly named, failing lookup"], "answer": 2, "explain": "Use `ASSERT_TRUE(opt.has_value())` before accessing an optional in tests. A `value_or(\"\")` fallback hides bugs."}, {"rule": "TI-026", "prompt": "An action should be blocked while the page is loading and allowed afterwards. The only test is `ActionSucceeds`, which completes loading first and then expects success. What's missing?", "choices": ["A test that it's blocked while loading, alongside the after-loading test", "A browser test version of the same happy path, to exercise real page loading", "A test with a longer loading delay, so the success path is checked under load", "Nothing — the success path already exercises the loading guard implicitly"], "answer": 0, "explain": "Test both sides of a guard condition: that the behavior is blocked while the guard is active AND that it proceeds once the guard is released."}, {"rule": "TI-027", "prompt": "To test error recovery, a test directly sets an object's internal members into a combination that production code can never reach, then asserts recovery works. Feedback?", "choices": ["Good — extreme internal states make recovery tests more thorough than real ones", "Fine, as long as a comment explains which internal state is being forced", "Reach the scenario via production code paths; impossible states prove nothing", "Wrap the setup in `#if DCHECK_IS_ON()` so it never runs in release builds"], "answer": 2, "explain": "Don't construct states that can't occur in production. Follow the production code path to set up the scenario; impossible-state tests give false confidence."}, {"rule": "TI-028", "prompt": "`Fetch()` should be called exactly once during the test:\n\n```cpp\nEXPECT_CALL(mock, Fetch(_)).WillRepeatedly(Return(result));\n```\n\nWhat should change?", "choices": ["Nothing — `WillRepeatedly` is more robust", "Use `ON_CALL` instead of `EXPECT_CALL`", "Add `.Times(testing::AnyNumber())`", "Use `.WillOnce(Return(result))`"], "answer": 3, "explain": "When a mock method should be called exactly once, use `WillOnce`. `WillRepeatedly` hides bugs where it's called more times than expected."}, {"rule": "TI-029", "prompt": "A browser test for \"open link in new tab\" asserts only `EXPECT_TRUE(OpenNewTab(url));`. What should be added?", "choices": ["An `EXPECT_CALL` on a mock tab delegate verifying it was asked to open `url`", "Check the tab count went up by one and the active tab's URL is `url`", "A `RunUntilIdle()` after opening so the new tab has finished loading", "Nothing — `OpenNewTab` returns false whenever the tab fails to open"], "answer": 1, "explain": "Browser tests should verify observable side effects (the tab actually appeared, the URL actually loaded), not just return values. That catches integration issues unit tests miss."}, {"rule": "TI-030", "prompt": "A bug-fix PR corrects an off-by-one in tab restore. The author says existing tests pass, so no new test is needed. Response?", "choices": ["Add a test that fails without the fix and passes with it", "Agree — passing existing tests shows nothing regressed", "Ask for a manual QA note in the PR description covering the restore case", "A follow-up issue to add a test later is enough for a small off-by-one"], "answer": 0, "explain": "Every bug-fix PR should include a test reproducing the specific bug. It should fail without the fix and pass with it, guarding against regressions."}, {"rule": "TI-033", "prompt": "You fixed a flaky `FooTest.HandlesReload` and verified it with `--gtest_filter=FooTest.HandlesReload`. The file also has `FooTest` and `FooIncognitoTest` fixtures with other tests. What's next?", "choices": ["Ship it — the target test passes", "Run only the other `FooTest.*` tests", "Run every test in the file, across all fixtures", "Run the full browser_tests suite on one platform"], "answer": 2, "explain": "When fixing a test, run all tests in the same file across every fixture, not just the one you changed, to catch interactions between tests that share fixtures."}, {"rule": "TI-034", "prompt": "```cpp\nauto* item = model->GetItem(0);\nEXPECT_TRUE(item != nullptr);\nitem->DoSomething();\n```\n\nWhat's the issue?", "choices": ["Use `EXPECT_NE(item, nullptr)` so the failure message prints the pointer", "Use `ASSERT_TRUE`/`ASSERT_NE`, since the next line dereferences `item`", "Wrap `item->DoSomething()` in `if (item)` so a null item can't crash the test", "Nothing — gtest stops the test at the first failed expectation anyway"], "answer": 1, "explain": "Use fatal `ASSERT_*` for preconditions that later code depends on. A failing `EXPECT_*` keeps running and can crash on null or cause confusing secondary failures."}, {"rule": "TI-035", "prompt": "A database class uses `SEQUENCE_CHECKER(sequence_checker_)`. In mock-based tests it's constructed on one sequence and used on another, so the sequence checks fail. Fix?", "choices": ["Remove the sequence checker, since production only ever uses one sequence", "Construct the object on the same sequence it's used on in every test", "Wrap the checks in `#if !defined(UNIT_TEST)` so they only run in production", "Call `DETACH_FROM_SEQUENCE(sequence_checker_)` in the constructor"], "answer": 3, "explain": "Database classes with a `SEQUENCE_CHECKER` should call `DETACH_FROM_SEQUENCE` in their constructor, so the checker binds to whichever sequence first uses the object."}, {"rule": "TI-036", "prompt": "```cpp\nclass MyUtilsTest : public testing::Test {};\n\nTEST_F(MyUtilsTest, ParsesValidInput) {\n  EXPECT_EQ(Parse(\"abc\"), \"abc\");\n}\n```\n\nWhat should the reviewer suggest?", "choices": ["Drop the empty fixture and use `TEST(MyUtilsTest, ParsesValidInput)`", "Add an empty `SetUp()` override so using `TEST_F` is justified", "Switch to `TEST_P` so more inputs can be added later without restructuring", "Nothing — `TEST_F` is always preferred, since a fixture may be needed later"], "answer": 0, "explain": "If the fixture adds no members, `SetUp()`, or `TearDown()`, use plain `TEST()`. `TEST_F` is only needed when the fixture provides shared state."}, {"rule": "TI-037", "prompt": "A test server handler serves `/api/v1` and `return nullptr;` for everything else. A code change starts hitting `/api/v2`, and the test fails mysteriously much later. Better default branch?", "choices": ["Return a 404 response so the client sees a realistic error for unknown paths", "`LOG(WARNING) << request.relative_url << request.content;` then return `nullptr`", "`NOTREACHED() << \"Unhandled: \" << request.relative_url << request.content;`", "Return an empty 200 response so the code under test keeps going"], "answer": 2, "explain": "Make the default handler in mock servers/interceptors `NOTREACHED() << request.content`, so unhandled requests fail loudly and the message includes the body for debugging."}, {"rule": "TI-038", "prompt": "Which test name follows the standard?", "choices": ["`TEST_F(WalletServiceTest, TestSend)`", "`TEST_F(WalletServiceTest, WalletServiceSendTransactionTest1)`", "`TEST_F(WalletServiceTest, SendErr2)`", "`TEST_F(WalletServiceTest, SendFailsOnInsufficientBalance)`"], "answer": 3, "explain": "Test names should be long and descriptive enough to explain the scenario without reading the body. Don't trade clarity for shorter names."}, {"rule": "TI-039", "prompt": "A PR adds new ranking logic with several branches but no tests. The author says it's \"too hard to test because it calls the network directly; we'll add tests later.\" Best response?", "choices": ["Accept it — tests can land in a follow-up once the ranking logic stabilizes", "Ask for a refactor for testability (pure logic, injected deps), plus tests", "Ask for a browser test that exercises the ranking against the real network", "Accept it if overall project coverage stays above the 80% threshold"], "answer": 1, "explain": "Code that can be tested should be tested. If it's hard to test, suggest refactors that improve testability (pure functions, dependency injection, separating I/O) rather than accepting untested code."}, {"rule": "TI-039", "prompt": "A PR adds a settings toggle wired straight to a pref, with no other logic. A reviewer blocks it for lacking a dedicated test. Is that right?", "choices": ["Yes — every PR that changes user-visible behavior needs at least one new test", "Yes — coverage must reach 90%+ on touched lines, including UI wiring", "Only if the pref is synced, since sync makes the toggle's effects cross-device", "No — trivial UI with no meaningful logic doesn't need a dedicated test"], "answer": 3, "explain": "Use judgment: never require a dedicated test for trivial UI with no meaningful logic (like a toggle wired to a pref), or when the change follows an existing untested pattern."}, {"rule": "TI-040", "prompt": "You override `components/foo/foo_service.cc` via `chromium_src` and want test coverage. What's the recommended approach?", "choices": ["Override the upstream unittest in `chromium_src`, `#include` it, then add Brave `TEST_F`s", "Copy the upstream test file into brave and edit it to match the override", "Write only Brave-specific tests in a new standalone fixture, unrelated to upstream's tests", "Rely on upstream CI, since the upstream tests already exercise `foo_service.cc`"], "answer": 0, "explain": "Use the chromium_src include pattern: include the upstream test file so all upstream tests run against your override, then add Brave-specific tests reusing upstream fixtures."}, {"rule": "TI-041", "prompt": "A class's behavior depends on three `base::Feature` flags (`kFlagA`, `kFlagB`, `kFlagC`). How should you cover the interactions?", "choices": ["Write three tests, each enabling one flag, since each flag is independent", "Test with all flags on and with all flags off, the two extremes that matter", "A value-parameterized test over `testing::Range<size_t>(0, 1 << 3)`, one bit per flag", "Rely on the default flag states, and add a test whenever one of the defaults changes"], "answer": 2, "explain": "For multiple feature flags, use value-parameterized tests that cover all 2^N combinations, encoding each combination as a bitmask where bit `i` enables feature `i`."}, {"rule": "TI-042", "prompt": "Your PR flips `kMyCache` to enabled-by-default. You notice `MyCachingTest()` calls `feature_list_.InitAndEnableFeature(kMyCache)`, which is now \"redundant\". What should you do?", "choices": ["Remove it — the compiled-in default now enables `kMyCache`, so it's dead code", "Keep it pinned (or parameterize both states); don't rely on the default", "Remove it, and add a helper that simulates the old default's behavior", "Move it into `TearDown()` so it restores state after each test"], "answer": 1, "explain": "Tests must never rely on a `base::Feature`'s compiled-in default. Pin every flag the test depends on, or parameterize over both states, so a future default flip can't silently change coverage."}, {"rule": "TI-042", "prompt": "A parameterized fixture needs `ScopedFeatureList` set from `GetParam()`. Where should it be initialized?", "choices": ["At the end of `SetUp()`, after members are created, so `GetParam()` is valid", "In each `TEST_P` body, right before the code under test reads the flag value", "In `TearDown()`, so the overrides are scoped to a single test", "In the fixture constructor, before anything that reads the flag is constructed"], "answer": 3, "explain": "Initialize `ScopedFeatureList` in the fixture constructor, which runs before `SetUp()` and can already call `GetParam()`. That way nothing that reads the flag is constructed first."}, {"rule": "TI-043", "prompt": "You run `brave_browser_tests --gtest_filter='AIChatPDFOCRBrowserTest.*'` and get:\n\n```\nWARNING: No matching tests to run.\nSUCCESS: all tests passed.\nTests took 0 seconds.\n```\n\nWhat should you conclude?", "choices": ["Nothing ran; check `--gtest_list_tests`, the target may be compiled out", "The tests passed; the warning is cosmetic when the filter uses a wildcard", "The tests are flaky on this machine and gtest skipped them automatically", "The filter was ignored, so gtest ran and passed the full suite instead"], "answer": 0, "explain": "A filter that matches nothing still reports success and exits 0. Before trusting a pass, confirm the tests exist with `--gtest_list_tests` and look for `[ RUN ]`/`[ OK ]` lines with a non-zero duration."}, {"rule": "TI-043", "prompt": "`MyCachingTest` is instantiated with `INSTANTIATE_TEST_SUITE_P(All, MyCachingTest, testing::Bool(), ...)`. Which filter actually runs its tests?", "choices": ["`--gtest_filter='MyCachingTest.*'`", "`--gtest_filter='MyCachingTest/*'`", "`--gtest_filter='All/MyCachingTest.*'`", "`--gtest_filter='MyCachingTest.NotifiesWhenReady'`"], "answer": 2, "explain": "Parameterized suites need the instantiation prefix (`All/MyCachingTest.*`). A bare fixture-name filter matches nothing and still reports success."}, {"rule": "TJ-001", "prompt": "A browser test needs to wait until a `<div id=\"status\">` shows the text `\"Done\"`. Which approach does the standard prefer?", "choices": ["A C++ loop calling `EvalJs` on `innerText` every 10ms until it reads `\"Done\"`", "`EvalJs` a script with `setTimeout(..., 1000)` and then read `#status` text", "Sleep the test thread for a second so rendering settles, then check once", "`EvalJs` a Promise resolved by a `MutationObserver` once the text matches"], "answer": 3, "explain": "Prefer JavaScript event-driven patterns like `MutationObserver` over C++ polling for DOM changes — they're more deterministic, more efficient, and match Chromium's own pattern (`service_worker_internals_ui_browsertest.cc`)."}, {"rule": "TJ-002", "prompt": "A test must wait for `document.getElementById('foo')` to exist. A teammate wrote a C++ loop with `NonBlockingDelay(base::Milliseconds(10))`, an `EvalJs` check, and a 10s deadline that calls `FAIL()`. Is this acceptable?", "choices": ["No — C++ polling loops are never allowed in Brave tests; use JS events instead", "Yes — C++ polling is the fallback when event-driven JS doesn't fit, as here", "No — it should use a fixed sleep instead of a deadline to keep it deterministic", "Yes, but only if the `FAIL()` deadline is removed so the test can't flake"], "answer": 1, "explain": "Manual C++ polling is the fallback for cases like checking element existence or JS API readiness, where an event-driven JS pattern doesn't apply. Keep the deadline and `FAIL()` on timeout."}, {"rule": "TJ-003", "prompt": "Which `EvalJs` call follows the standard for test code inspecting the page?", "choices": ["`content::EvalJs(web_contents, \"...\", EXECUTE_SCRIPT_DEFAULT_OPTIONS, ISOLATED_WORLD_ID_BRAVE_INTERNAL)`", "`content::EvalJs(web_contents, \"document.getElementById('foo')\")` in the page's own main world", "`content::ExecJs(web_contents, \"window.__test = true\")` before every check, then `EvalJs` the result", "`content::EvalJs(web_contents, \"...\", content::EXECUTE_SCRIPT_NO_USER_GESTURE)` for every page check"], "answer": 0, "explain": "Evaluate test JavaScript in `ISOLATED_WORLD_ID_BRAVE_INTERNAL` so test code doesn't interfere with page scripts."}, {"rule": "TJ-004", "prompt": "A Solana provider test does:\n\n```cpp\nWaitForSolanaProviderBinding();\nEXPECT_TRUE(ExecJs(web_contents, \"window.braveSolana.on('connect', ...)\"));\n```\n\nIt flakes with `braveSolana.on is not a function`. Why, and what's the fix?", "choices": ["The binding wait is too short — call `WaitForSolanaProviderBinding()` twice in a row", "`ExecJs` runs before navigation finishes — wrap the call in a `setTimeout` to defer it a bit", "Mojo binds before the event emitter exists — poll until `braveSolana.on` is a function", "The provider is only injected in isolated worlds — run the script in the main world"], "answer": 2, "explain": "Waiting for the mojo binding doesn't guarantee renderer-side JS setup is done. Poll (with a deadline) until the JS API is actually ready before using it."}, {"rule": "TN-001", "prompt": "A test clicks a link to `#section2` (a fragment navigation) and needs to wait for it to commit. It currently uses `content::TestNavigationObserver`, which times out. What should be used?", "choices": ["`base::test::RunUntil()` polling `GetLastCommittedURL()` until it ends in `#section2`", "A `WebContentsObserver` quitting a `RunLoop` on same-document `DidFinishNavigation`", "`TestNavigationObserver` with a larger timeout, since fragment commits are slower", "`content::WaitForLoadStop(web_contents)`, which also covers same-document loads"], "answer": 1, "explain": "Standard `TestNavigationObserver` skips same-document navigations, and you should NOT use `RunUntil()` polling for them. Use a custom observer that quits on a same-document, non-error `DidFinishNavigation`."}, {"rule": "TN-002", "prompt": "A test needs a template URL to be registered for a host before continuing. Which approach is correct?", "choices": ["`ASSERT_TRUE(base::test::RunUntil([&] { return service->GetTemplateURLForHost(host); }))`", "`EvalJs` a script that does `setTimeout(() => {}, 1200)` to give the service time to register", "Sleep the test thread for 1200ms with `base::PlatformThread::Sleep` before checking", "Check once right after navigation; registration happens synchronously during commit"], "answer": 0, "explain": "Hardcoded JavaScript timeouts are unreliable. Wait for the actual condition in C++ with `base::test::RunUntil`."}, {"rule": "TN-003", "prompt": "A Speedreader test does:\n\n```cpp\nNavigateToPageSynchronously(url);\nEXPECT_TRUE(ExecJs(web_contents, \"document.querySelector('.distilled')...\"));\n```\n\nIt is flaky. What's missing?", "choices": ["A `WaitForLoadStop()` call after navigating, before running the script", "Nothing — `NavigateToPageSynchronously` already waits for distillation", "A `WaitDistilled()` call before interacting with distilled content", "Running the script in `ISOLATED_WORLD_ID_BRAVE_INTERNAL` so it sees the page"], "answer": 2, "explain": "`NavigateToPageSynchronously` only waits for load stop, not distillation. Always call `WaitDistilled()` before touching distilled elements."}, {"rule": "TUF-000", "prompt": "A test listed in `test/filters/generated/browser_tests-linux.filter` has been fixed upstream and no longer flakes. What do you do?", "choices": ["Delete its line from the generated filter file by hand and note why in the PR", "Add a note to the hand-written `browser_tests.filter` re-enabling it", "Re-run `update-upstream-flake-filters.py` to regenerate the generated files", "Nothing — generated filters are permanent once added, to avoid churn"], "answer": 2, "explain": "Generated filters come from a script that picks up upstream tests with ≥1% flake rate over 30 days, computed per config. Never hand-edit them; re-run the update script."}, {"rule": "TUF-001", "prompt": "An upstream test fails intermittently on Brave CI, and no Brave code is involved. A teammate opens a PR with a patch renaming it to `DISABLED_SignOut`. Best response?", "choices": ["Use an entry in a `test/filters/` file instead of a patch", "Approve — the `DISABLED_` prefix is the standard gtest mechanism for this", "Patch the upstream test's timing logic so the flake is fixed rather than hidden", "Add a `chromium_src` override of the test file that skips it"], "answer": 0, "explain": "Never patch upstream tests to disable flakes. Filter files are the preferred, trivially reversible mechanism. Only fix upstream test code when Brave's own overrides or patches cause the failure."}, {"rule": "TUF-002", "prompt": "`check-upstream-flake.py` reports **Stable upstream** (0.3% flake rate) for a test that keeps failing on Brave CI. What next?", "choices": ["Filter it anyway, noting the 0.3% upstream rate in the filter comment", "Re-run with `--days 60` until the rate crosses the 1% filtering threshold", "Filter it only in a sanitizer-specific filter file to limit its blast radius", "Look for `chromium_src/` overrides or `patches/` that cause the failure"], "answer": 3, "explain": "With an upstream flake rate below 1%, investigate Brave-specific causes before filtering. If a Brave override or patch is responsible, fix that code instead of hiding it."}, {"rule": "TUF-003", "prompt": "LUCI Analysis shows `SomeParameterizedTest/0` and `SomeParameterizedTest/2` are flaky upstream, while `/1` is stable. Which filter entries should you add?", "choices": ["`-SomeParameterizedTest/*`", "`-SomeParameterizedTest/0` and `-SomeParameterizedTest/2`", "`-SomeParameterizedTest/0` only, and wait to see whether `/2` recurs", "`-SomeParameterized*`"], "answer": 1, "explain": "Don't use wildcards that also suppress stable variants. Check each variant in LUCI and filter only the ones that are actually flaky."}, {"rule": "TUF-004", "prompt": "A test failed on Brave's Linux ASan bot. LUCI Analysis shows a 1.6% upstream flake rate that includes failures on non-sanitizer builds. Where should the filter go?", "choices": ["`browser_tests-linux-asan.filter`, since that's the only bot where Brave saw it fail", "Both `browser_tests-linux-asan.filter` and `browser_tests-linux-msan.filter`", "A broader file like `browser_tests.filter`, since it also fails without sanitizers", "Nowhere — at 1.6% the test is stable enough that it should be fixed, not filtered"], "answer": 2, "explain": "Make the filter as narrow as the evidence supports. When upstream data shows failures outside sanitizer builds, a sanitizer-specific file is too narrow, so use a broader filter file."}, {"rule": "TUF-005", "prompt": "Which comment should precede `-WebUIURLLoaderFactoryTest.RangeRequest/*` in a filter file?", "choices": ["`# Flaky on Brave CI; fails intermittently on the Linux and Windows bots.`", "`# Disabled after repeated CI failures on several bots; see the team Slack thread for details.`", "`# Known upstream flake (1.8%/30d, LUCI). Mojo data pipe race: completion before data flush.`", "`# TODO(someone): re-enable once upstream stabilizes range request handling.`"], "answer": 2, "explain": "Every filter entry needs a comment saying why it's disabled and what triggers the failure. Include the upstream flake rate with its lookback period, and why this file was chosen if that isn't obvious."}, {"rule": "TUF-006", "prompt": "Reviewing a filter file (SuiteA's two tests share the same Mojo race condition):\n\n```\n# Various flaky tests\n-SuiteA.Test1\n# Different issue\n-SuiteB.Test2\n-SuiteA.Test2\n```\n\nWhat should change?", "choices": ["Group shared-root-cause tests under one specific comment; blank line between sections", "Nothing — every entry already has a comment somewhere near it, which is all that's required", "Sort all entries alphabetically under a single `# Flaky tests` header for easier diffing", "Move each test into its own filter file so each can be re-enabled independently"], "answer": 0, "explain": "Group entries by root cause under a single comment section, and give distinct causes their own sections. Always leave a blank line before a new comment section."}, {"rule": "UV-001", "prompt": "```cpp\nAddChildView(new views::Label(u\"Hello\"));\n// later, to remove and destroy a child:\nparent->RemoveChildView(some_child);\n```\n\nWhich version follows the standard?", "choices": ["Call `some_child->SetVisible(false)` instead of removing it", "`AddChildView(std::make_unique<...>())`, then `RemoveChildView(child)` followed by `delete child;`", "`AddChildView(std::make_unique<...>())`; remove via `parent->RemoveChildViewT(some_child)`", "Keep `AddChildView(new ...)`; `RemoveChildView()` already deletes the child"], "answer": 2, "explain": "Use the `unique_ptr` overload of `AddChildView()`, and `RemoveChildViewT()` to remove-and-destroy: it returns a `unique_ptr`, making ownership explicit. Plain `RemoveChildView()` does not delete."}, {"rule": "UV-002", "prompt": "```cpp\nMyView::~MyView() {\n  if (tab_strip_model_) {\n    tab_strip_model_->RemoveObserver(this);\n  }\n}\nvoid MyView::OnTabStripModelDestroyed(TabStripModel* model) {\n  model->RemoveObserver(this);\n}\n```\n\n`MyView` inherits `TabStripModelObserver`. What should the reviewer say?", "choices": ["Move the `RemoveObserver` call into `Shutdown()` instead of the destructor", "Remove both calls; just null out `tab_strip_model_`", "Keep the destructor call but remove the one in `OnTabStripModelDestroyed`", "Correct as written — every `AddObserver` needs a matching `RemoveObserver`"], "answer": 1, "explain": "`~TabStripModelObserver` calls `RemoveObserver(this)` on every observed model, and `ModelDestroyed` removes it before `OnTabStripModelDestroyed`. Derived classes only clear their own state."}, {"rule": "UV-003", "prompt": "```cpp\nauto* my_view = static_cast<MyCustomView*>(some_view);\nmy_view->DoSomething();\n```\n\n`some_view` is a `views::View*` that may or may not be a `MyCustomView`. What's the best replacement?", "choices": ["Keep `static_cast` but add `DCHECK(some_view->GetClassName() == ...)`", "`reinterpret_cast<MyCustomView*>(some_view)` with a null check", "`views::AsViewClass<MyCustomView>(some_view)` + null check", "`dynamic_cast<MyCustomView*>(some_view)` with a null check"], "answer": 2, "explain": "RTTI is disabled, so `dynamic_cast` isn't available. `views::AsViewClass`/`IsViewClass` walk the `METADATA_HEADER` chain and return `nullptr` on mismatch (even for partially constructed views); `static_cast` gives UB."}, {"rule": "UV-004", "prompt": "A teammate adds a new bubble:\n\n```cpp\nclass MyBubble : public views::BubbleDialogDelegateView { ... };\n```\n\nWhat should they do instead?", "choices": ["Build a `ui::DialogModel` and show it via `BubbleDialogModelHost`", "Inherit from `views::WidgetDelegateView` and draw a bubble border", "Inherit from `views::DialogDelegateView` instead", "Keep it, but move business logic into a separate helper class"], "answer": 0, "explain": "`BubbleDialogDelegateView` is deprecated: merging delegate and view muddles ownership. Use a `ui::DialogModel` + `BubbleDialogModelHost` factory; the widget takes the host via `release()`."}, {"rule": "UV-005", "prompt": "You need a non-bubble modal dialog with OK/Cancel. Which approach follows Brave's standard?", "choices": ["Subclass `views::DialogDelegate` and `SetContentsView()` a separate View", "Subclass `views::View` and show it in a plain `views::Widget`", "Subclass `views::DialogDelegateView` and lay out children directly in it", "Subclass `views::BubbleDialogDelegateView` with no anchor view"], "answer": 0, "explain": "`DialogDelegateView` is deprecated. Inherit `DialogDelegate` alone, give it a separate contents `View`, and show it with `DialogDelegate::CreateDialogWidget()`."}, {"rule": "UV-006", "prompt": "```cpp\nvoid SidebarModel::FetchFaviconFromNetwork(const SidebarItem& item) {\n  image_fetcher_->FetchImage(item.url, ...);\n}\n```\n\nThis runs for every profile, including Private and Tor windows. What's the problem and fix?", "choices": ["Only Tor is affected; add an `IsTor()` check and keep fetching for Incognito", "No problem — favicons are public resources, so nothing leaks", "Set a Tor proxy on the `ImageFetcher` so requests are routed correctly", "It uses the system network context; skip if `profile_->IsOffTheRecord()`"], "answer": 3, "explain": "`ImageFetcherService` isn't profile-bound: off-the-record requests leave the profile's network partition and Tor requests bypass the proxy. Skip for OTR profiles and fall back to a default; use a `SimpleURLLoader` with the profile's `URLLoaderFactory` if needed."}, {"rule": "UV-007", "prompt": "A \"copy screenshot\" feature writes an image to the clipboard:\n\n```cpp\nui::ScopedClipboardWriter writer(ui::ClipboardBuffer::kCopyPaste);\nwriter.WriteImage(bitmap);\n```\n\nIt can run in Private and Tor windows. What should be added?", "choices": ["`if (profile->IsTor()) writer.MarkAsOffTheRecord();` — Incognito is fine", "`if (profile->IsOffTheRecord()) writer.MarkAsOffTheRecord();`", "Clear the clipboard when the private window closes", "`if (profile->IsOffTheRecord() || profile->IsTor()) writer.MarkAsOffTheRecord();`"], "answer": 1, "explain": "`MarkAsOffTheRecord()` keeps private content out of OS clipboard history and cloud sync. Tor profiles are off-the-record, so `IsOffTheRecord()` alone covers them."}];
